using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.IO;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;

namespace AiAgentDotfilesTests {
    public sealed class HardKillReviewedLoadLease : IDisposable {
        private const uint GENERIC_READ = 0x80000000;
        private const uint FILE_READ_ATTRIBUTES = 0x00000080;
        private const uint FILE_SHARE_READ = 0x00000001;
        private const uint FILE_SHARE_WRITE = 0x00000002;
        private const uint OPEN_EXISTING = 3;
        private const uint FILE_FLAG_BACKUP_SEMANTICS = 0x02000000;
        private const uint FILE_FLAG_OPEN_REPARSE_POINT = 0x00200000;
        private const uint FILE_ATTRIBUTE_DIRECTORY = 0x00000010;
        private const uint FILE_ATTRIBUTE_REPARSE_POINT = 0x00000400;
        private const int FILE_ATTRIBUTE_TAG_INFO_CLASS = 9;

        [StructLayout(LayoutKind.Sequential)]
        private struct FILE_ATTRIBUTE_TAG_INFO {
            public uint FileAttributes;
            public uint ReparseTag;
        }

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern SafeFileHandle CreateFileW(string fileName, uint desiredAccess, uint shareMode,
            IntPtr securityAttributes, uint creationDisposition, uint flagsAndAttributes, IntPtr templateFile);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool GetFileInformationByHandleEx(SafeFileHandle file, int fileInformationClass,
            out FILE_ATTRIBUTE_TAG_INFO fileInformation, uint bufferSize);

        private readonly List<SafeFileHandle> handles;
        private bool disposed;

        private HardKillReviewedLoadLease(List<SafeFileHandle> handles) {
            this.handles = handles;
        }

        private static string Extended(string path) {
            string full = Path.GetFullPath(path);
            if (full.StartsWith(@"\\?\", StringComparison.Ordinal)) return full;
            if (full.StartsWith(@"\\", StringComparison.Ordinal)) return @"\\?\UNC\" + full.Substring(2);
            return @"\\?\" + full;
        }

        private static SafeFileHandle OpenAndVerify(string path, bool directory) {
            uint access = directory ? FILE_READ_ATTRIBUTES : GENERIC_READ | FILE_READ_ATTRIBUTES;
            uint share = directory ? FILE_SHARE_READ | FILE_SHARE_WRITE : FILE_SHARE_READ;
            uint flags = FILE_FLAG_OPEN_REPARSE_POINT | (directory ? FILE_FLAG_BACKUP_SEMANTICS : 0u);
            SafeFileHandle handle = CreateFileW(Extended(path), access, share, IntPtr.Zero, OPEN_EXISTING, flags, IntPtr.Zero);
            if (handle.IsInvalid) {
                int error = Marshal.GetLastWin32Error();
                handle.Dispose();
                throw new Win32Exception(error, "Unable to acquire reviewed load lease: " + path);
            }
            FILE_ATTRIBUTE_TAG_INFO info;
            if (!GetFileInformationByHandleEx(handle, FILE_ATTRIBUTE_TAG_INFO_CLASS, out info, (uint)Marshal.SizeOf<FILE_ATTRIBUTE_TAG_INFO>())) {
                int error = Marshal.GetLastWin32Error();
                handle.Dispose();
                throw new Win32Exception(error, "Unable to inspect reviewed load lease: " + path);
            }
            bool actualDirectory = (info.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
            if (actualDirectory != directory || (info.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0) {
                handle.Dispose();
                throw new IOException("Reviewed load path type or reparse state is invalid: " + path);
            }
            return handle;
        }

        public static HardKillReviewedLoadLease Acquire(string repositoryRoot, string[] relativePaths) {
            if (String.IsNullOrWhiteSpace(repositoryRoot)) throw new ArgumentException("Repository root is required.", "repositoryRoot");
            if (relativePaths == null || relativePaths.Length == 0) throw new ArgumentException("Reviewed paths are required.", "relativePaths");
            string root = Path.GetFullPath(repositoryRoot);
            string prefix = root.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
            var files = new List<string>();
            var directories = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string relative in relativePaths) {
                if (String.IsNullOrWhiteSpace(relative) || Path.IsPathRooted(relative)) throw new ArgumentException("Reviewed relative path is invalid.", "relativePaths");
                string full = Path.GetFullPath(Path.Combine(root, relative.Replace('/', Path.DirectorySeparatorChar)));
                if (!full.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) throw new IOException("Reviewed path escapes repository root: " + relative);
                files.Add(full);
                DirectoryInfo parent = Directory.GetParent(full);
                while (parent != null) {
                    directories.Add(parent.FullName);
                    parent = parent.Parent;
                }
            }
            var directoryList = new List<string>(directories);
            directoryList.Sort((left, right) => left.Length != right.Length ? left.Length.CompareTo(right.Length) : StringComparer.OrdinalIgnoreCase.Compare(left, right));
            files.Sort(StringComparer.OrdinalIgnoreCase);
            var opened = new List<SafeFileHandle>();
            try {
                foreach (string directory in directoryList) opened.Add(OpenAndVerify(directory, true));
                foreach (string file in files) opened.Add(OpenAndVerify(file, false));
                return new HardKillReviewedLoadLease(opened);
            } catch {
                for (int index = opened.Count - 1; index >= 0; index--) opened[index].Dispose();
                throw;
            }
        }

        public void Dispose() {
            if (disposed) return;
            disposed = true;
            Exception first = null;
            for (int index = handles.Count - 1; index >= 0; index--) {
                try { handles[index].Dispose(); }
                catch (Exception error) { if (first == null) first = error; }
            }
            if (first != null) throw first;
        }
    }
}
