$script:hardKillReviewedLoadLease=$null
try{
    $script:hardKillReviewedLoadLease=[AiAgentDotfilesTests.HardKillReviewedLoadLease]::Acquire($RepoRoot,[string[]]@($script:hardKillReviewedLoadManifest.Keys))
    $reviewedRepoPrefix=$RepoRoot.TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar
    foreach($relativePath in $script:hardKillReviewedLoadManifest.Keys){
        $reviewedPath=[IO.Path]::GetFullPath([IO.Path]::Combine($RepoRoot,([string]$relativePath).Replace('/',[IO.Path]::DirectorySeparatorChar)))
        if(-not $reviewedPath.StartsWith($reviewedRepoPrefix,[StringComparison]::OrdinalIgnoreCase) -or -not[IO.File]::Exists($reviewedPath)){throw 'hard-kill reviewed load path is invalid'}
        $reviewedHash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([IO.File]::ReadAllBytes($reviewedPath))).ToLowerInvariant()
        if($reviewedHash -cne [string]$script:hardKillReviewedLoadManifest[$relativePath]){throw ('hard-kill reviewed load hash mismatch: '+$relativePath)}
    }
    . (Microsoft.PowerShell.Management\Join-Path $RepoRoot 'scripts/canonical-recovery-common.ps1')
    . (Microsoft.PowerShell.Management\Join-Path $RepoRoot 'tests/helpers/canonical-reviewed-recovery-engine.ps1')
    . (Microsoft.PowerShell.Management\Join-Path $RepoRoot 'tests/helpers/canonical-hard-kill-process-common.ps1')
    . (Microsoft.PowerShell.Management\Join-Path $RepoRoot 'tests/helpers/canonical-hard-kill-job-process.ps1')
}catch{
    $reviewedLoadPrimary=$_.Exception
    $reviewedLoadCleanup=$null
    if($script:hardKillReviewedLoadLease){
        try{$script:hardKillReviewedLoadLease.Dispose()}catch{$reviewedLoadCleanup=$_.Exception}
        finally{$script:hardKillReviewedLoadLease=$null}
    }
    if($reviewedLoadCleanup){throw [AggregateException]::new('hard-kill reviewed load primary/cleanup failure',[Exception[]]@($reviewedLoadPrimary,$reviewedLoadCleanup))}
    throw $reviewedLoadPrimary
}

if(-not('AiAgentDotfiles.HardKillLeaseProbe' -as [type])){
    Add-Type -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
namespace AiAgentDotfiles {
    public static class HardKillLeaseProbe {
        private const uint DELETE = 0x00010000;
        private const uint GENERIC_WRITE = 0x40000000;
        private const uint FILE_SHARE_READ = 0x1, FILE_SHARE_WRITE = 0x2, FILE_SHARE_DELETE = 0x4;
        private const uint OPEN_EXISTING = 3;
        private const uint FILE_FLAG_BACKUP_SEMANTICS = 0x02000000, FILE_FLAG_OPEN_REPARSE_POINT = 0x00200000;
        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern SafeFileHandle CreateFileW(string name, uint access, uint share, IntPtr security, uint creation, uint flags, IntPtr template);
        [DllImport("ntdll.dll")]
        private static extern int NtSuspendProcess(IntPtr processHandle);
        [DllImport("ntdll.dll")]
        private static extern int NtResumeProcess(IntPtr processHandle);
        private static string Extended(string path) {
            string full = System.IO.Path.GetFullPath(path);
            if (full.StartsWith(@"\\?\", StringComparison.Ordinal)) return full;
            if (full.StartsWith(@"\\", StringComparison.Ordinal)) return @"\\?\UNC\" + full.Substring(2);
            return @"\\?\" + full;
        }
        public static bool IsDeleteOpenBlocked(string directoryPath) {
            using (SafeFileHandle handle = CreateFileW(Extended(directoryPath), DELETE, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, IntPtr.Zero, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT, IntPtr.Zero)) {
                if (!handle.IsInvalid) return false;
                int error = Marshal.GetLastWin32Error();
                if (error == 32) return true;
                throw new Win32Exception(error, "Unable to probe canonical mutation parent lease: " + directoryPath);
            }
        }
        public static int ProbeWriteDeleteOpenError(string filePath) {
            using (SafeFileHandle handle = CreateFileW(Extended(filePath), GENERIC_WRITE | DELETE,
                FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, IntPtr.Zero, OPEN_EXISTING,
                FILE_FLAG_OPEN_REPARSE_POINT, IntPtr.Zero)) {
                if (!handle.IsInvalid) return 0;
                return Marshal.GetLastWin32Error();
            }
        }
        public static void Suspend(System.Diagnostics.Process process) {
            int status = NtSuspendProcess(process.Handle);
            if (status != 0) throw new InvalidOperationException("NtSuspendProcess failed with NTSTATUS 0x" + status.ToString("X8"));
        }
        public static void Resume(System.Diagnostics.Process process) {
            int status = NtResumeProcess(process.Handle);
            if (status != 0) throw new InvalidOperationException("NtResumeProcess failed with NTSTATUS 0x" + status.ToString("X8"));
        }
    }
    public sealed class HardKillDirectoryOplock : IDisposable {
        private const uint GENERIC_READ = 0x80000000;
        private const uint FILE_SHARE_READ = 0x1, FILE_SHARE_WRITE = 0x2, FILE_SHARE_DELETE = 0x4;
        private const uint OPEN_EXISTING = 3;
        private const uint FILE_FLAG_OVERLAPPED = 0x40000000, FILE_FLAG_BACKUP_SEMANTICS = 0x02000000, FILE_FLAG_OPEN_REPARSE_POINT = 0x00200000;
        private const uint FSCTL_REQUEST_OPLOCK = 0x00090240;
        private const uint OPLOCK_LEVEL_CACHE_READ = 0x1, OPLOCK_LEVEL_CACHE_HANDLE = 0x2, OPLOCK_LEVEL_CACHE_WRITE = 0x4;
        private const uint REQUEST_OPLOCK_INPUT_FLAG_REQUEST = 0x1;
        private const uint REQUEST_OPLOCK_OUTPUT_FLAG_ACK_REQUIRED = 0x1;
        private const int ERROR_IO_PENDING = 997;
        private const uint WAIT_OBJECT_0 = 0, WAIT_TIMEOUT = 258;
        [StructLayout(LayoutKind.Sequential)]
        private struct REQUEST_OPLOCK_INPUT_BUFFER {
            public ushort StructureVersion, StructureLength;
            public uint RequestedOplockLevel, Flags;
        }
        [StructLayout(LayoutKind.Sequential)]
        private struct REQUEST_OPLOCK_OUTPUT_BUFFER {
            public ushort StructureVersion, StructureLength;
            public uint OriginalOplockLevel, NewOplockLevel, Flags, AccessMode;
            public ushort ShareMode;
        }
        [StructLayout(LayoutKind.Sequential)]
        private struct OVERLAPPED {
            public IntPtr Internal, InternalHigh;
            public uint Offset, OffsetHigh;
            public IntPtr EventHandle;
        }
        [StructLayout(LayoutKind.Sequential)]
        private struct FILETIME {
            public uint Low, High;
        }
        [StructLayout(LayoutKind.Sequential)]
        private struct BY_HANDLE_FILE_INFORMATION {
            public uint FileAttributes;
            public FILETIME CreationTime, LastAccessTime, LastWriteTime;
            public uint VolumeSerialNumber, FileSizeHigh, FileSizeLow, NumberOfLinks, FileIndexHigh, FileIndexLow;
        }
        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern SafeFileHandle CreateFileW(string name, uint access, uint share, IntPtr security, uint creation, uint flags, IntPtr template);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern IntPtr CreateEventW(IntPtr security, bool manualReset, bool initialState, string name);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool DeviceIoControl(SafeFileHandle device, uint code, IntPtr input, uint inputSize, IntPtr output, uint outputSize, IntPtr bytesReturned, IntPtr overlapped);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool CancelIoEx(SafeFileHandle handle, IntPtr overlapped);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool GetFileInformationByHandle(SafeFileHandle handle, out BY_HANDLE_FILE_INFORMATION info);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern uint WaitForSingleObject(IntPtr handle, uint milliseconds);
        [DllImport("kernel32.dll")]
        private static extern bool CloseHandle(IntPtr handle);
        private SafeFileHandle handle;
        private IntPtr eventHandle, inputBuffer, outputBuffer, overlappedBuffer;
        private string openedIdentity;
        private uint requestedOplockLevel;
        private bool disposed;
        private static string Extended(string path) {
            string full = System.IO.Path.GetFullPath(path);
            if (full.StartsWith(@"\\?\", StringComparison.Ordinal)) return full;
            if (full.StartsWith(@"\\", StringComparison.Ordinal)) return @"\\?\UNC\" + full.Substring(2);
            return @"\\?\" + full;
        }
        private static string ReadIdentity(SafeFileHandle source) {
            BY_HANDLE_FILE_INFORMATION info;
            if (!GetFileInformationByHandle(source, out info)) throw new Win32Exception(Marshal.GetLastWin32Error(), "Unable to read hard-kill oplock identity.");
            ulong index = ((ulong)info.FileIndexHigh << 32) | info.FileIndexLow;
            return info.VolumeSerialNumber.ToString("x8") + ":" + index.ToString("x16");
        }
        private HardKillDirectoryOplock(string path, bool directory, uint oplockLevel) {
            try {
                if (directory && oplockLevel != (OPLOCK_LEVEL_CACHE_READ | OPLOCK_LEVEL_CACHE_HANDLE)) throw new ArgumentException("Directory hard-kill oplocks must use the R|H level.", "oplockLevel");
                uint openFlags = FILE_FLAG_OVERLAPPED | FILE_FLAG_OPEN_REPARSE_POINT | (directory ? FILE_FLAG_BACKUP_SEMANTICS : 0u);
                handle = CreateFileW(Extended(path), GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, IntPtr.Zero, OPEN_EXISTING, openFlags, IntPtr.Zero);
                if (handle.IsInvalid) throw new Win32Exception(Marshal.GetLastWin32Error(), "Unable to open path for hard-kill oplock: " + path);
                openedIdentity = ReadIdentity(handle);
                requestedOplockLevel = oplockLevel;
                eventHandle = CreateEventW(IntPtr.Zero, true, false, null);
