                inputBuffer = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(REQUEST_OPLOCK_INPUT_BUFFER)));
                outputBuffer = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(REQUEST_OPLOCK_OUTPUT_BUFFER)));
