            $left=if($statementIndex -gt 0){Get-HardKillAstTextCompact $statements[$statementIndex-1]}else{''}
            $right=if($statementIndex+1 -lt $statements.Count){Get-HardKillAstTextCompact $statements[$statementIndex+1]}else{''}
            if($left -cnotmatch [string]$expected.LeftPattern -or $right -cnotmatch [string]$expected.RightPattern){throw 'reach-physical-edge'}
