        if($engineHash -cne $ExpectedEngineSha256){throw 'behavior-engine-hash-mismatch'}
        . $enginePath
        $request=ConvertFrom-SemanticJson -Json ([IO.File]::ReadAllText($ContractProbeRequestPath))
        $fixture=New-SealedMutationBehaviorFixture -Request $request
        $action=Read-SealedMutationBehaviorControllerAction -Fixture $fixture -Request $request
        $rawCase=Invoke-SealedMutationBehaviorCase -Fixture $fixture -Request $request -Action $action
        $rows=@([ordered]@{RawRows=$rawCase.RawRows;Artifacts=$rawCase.Artifacts;RawFailure=$rawCase.RawFailure})
        $document=[ordered]@{Cases=$rows;RequestSha256=$ContractProbeRequestSha256;EngineSha256=$ExpectedEngineSha256;HostSha256=$ExpectedProbeHostSha256}
        $responseBytes=Get-SealedMutationBehaviorResponseBytes -Document $document -Request $request -Action $action
        Write-SealedMutationBehaviorResponse -Fixture $fixture -Bytes $responseBytes
        [IO.File]::WriteAllBytes($ContractProbeResultPath,(ConvertTo-SemanticJsonBytes -InputObject $document))
    } finally {
        if($null -ne $fixture){Close-SealedMutationBehaviorFixture -Fixture $fixture}
    }
}
if($ContractProbe){
    Invoke-SealedMutationContractProbe -ContractProbeRequestPath $ContractProbeRequestPath -ContractProbeRequestSha256 $ContractProbeRequestSha256 `
        -MutationEnginePath $MutationEnginePath -ExpectedEngineSha256 $ExpectedEngineSha256 -ExpectedProbeHostSha256 $ExpectedProbeHostSha256 `
        -ContractProbeResultPath $ContractProbeResultPath -ContractProbeScratchRoot $ContractProbeScratchRoot
    return
