        'engine-loader-missing'=@($loaderMissing,'probe-engine-loader-statement:4')
        'engine-loader-reordered'=@($loaderReordered,'probe-engine-loader-statement:3')
        'engine-loader-wrong-path'=@($loaderWrongPath,'probe-engine-loader-statement:4')
        'engine-loader-unbound-hash'=@($loaderUnboundHash,'probe-engine-loader-statement:2')
        'using-module-shadow'=@($usingModule,'probe-using-statement')
        'requires-module-shadow'=@($requiresModule,'probe-requires-module')
        'requires-assembly-load'=@($requiresAssembly,'probe-requires-assembly')
    }
    $baselineResult=Test-HardKillBehaviorProbeHostContract -HostSource $baseline;$cases=[Collections.Generic.List[object]]::new()
    foreach($name in $specs.Keys){
        $source=[string]$specs[$name][0];$expected=[string]$specs[$name][1];$tokens=$null;$errors=$null;$null=[Management.Automation.Language.Parser]::ParseInput($source,[ref]$tokens,[ref]$errors)
        $verdict=if(@($errors).Count -eq 0){Test-HardKillBehaviorProbeHostContract -HostSource $source}else{$null};$codes=@(if($verdict){@($verdict.ErrorCodes)}else{@('mutation-parse')})
        $cases.Add([pscustomobject]@{Name=$name;Changed=$source -cne $baseline;ParseValid=@($errors).Count -eq 0;Rejected=$null -ne $verdict -and -not $verdict.Valid;ExpectedErrorCode=$expected;RejectedForExpectedReason=$codes.Count -eq 1 -and $codes[0] -ceq $expected;ErrorCodes=$codes})
    }
    return [pscustomobject]@{
        Valid=$baselineResult.Valid -and $specs.Count -eq 31 -and $cases.Count -eq 31 -and @($cases|Where-Object{-not $_.Changed -or -not $_.ParseValid -or -not $_.Rejected -or -not $_.RejectedForExpectedReason}).Count -eq 0
        BaselineValid=$baselineResult.Valid;Cases=@($cases);ExpectedNames=@($specs.Keys)
    }
}
function Get-HardKillBehaviorExpectedFacts {
    param([Parameter(Mandatory)][string]$CaseName)
    $facts=[ordered]@{
        'selector-nonmatch-no-io'=@(@('TicketKind','null'),@('JournalReadCount','0'),@('StageRootAccessCount','0'))
        'selector-first-match-single-use-ticket'=@(@('MatchCount','1'),@('FinalState','Released'),@('DuplicateError','duplicate-match'),@('ForeignTicketError','foreign-ticket'),@('ConsumedTicketError','ticket-consumed'))
        'selector-prehandoff-failure-ownership'=@(@('StateTrace','Unmatched>Publishing>Failed'),@('MarkPublicationFailedCount','1'),@('WrapperLeaseResidue','0'),@('PrimaryOrder','primary-first'))
        'selector-posthandoff-timeout-ownership'=@(@('StateTrace','Unmatched>Publishing>Waiting>Failed'),@('MarkPublicationFailedCount','0'),@('CoordinatorFailureCount','1'),@('TicketReuseError','ticket-consumed'),@('WrapperLeaseResidue','0'),@('PrimaryOrder','primary-first'))
        'context-sealed-call-failure-cleanup'=@(@('ContextDisposeCount','1'),@('CoordinatorDisposeCount','1'),@('RootLeaseDisposeCount','1'),@('PrimaryOrder','primary-first'))
        'context-match-assertion-failure-cleanup'=@(@('ContextDisposeCount','1'),@('CoordinatorDisposeCount','1'),@('RootLeaseDisposeCount','1'),@('PrimaryOrder','primary-first'))
        'native-layout-x86-x64'=@(@('X86Layout','exact'),@('X64Layout','exact'),@('CurrentLayout','exact'))
        'native-secured-root-containment'=@(@('CreateInformation','2'),@('Dacl','protected'),@('UnauthorizedSid','denied'),@('RootReplacement','blocked'),@('ExtraChild','detected'))
        'native-forbidden-read-delete-bridge'=@(@('NtStatusHex','c0000043'),@('RetryCount','0'),@('HandleKind','none'),@('WriterIdentity','stable'))
        'native-reviewed-writer-bridge-seal'=@(@('Trace','CreateTempWriter>Write>FlushFileBuffers>RereadWriter>RenameWriterNoReplace>OpenReadBridgeShareAll>CloseWriter>OpenReadSealShareRead>CloseReadBridge>VerifyReadSeal'),@('IdentityRelation','all-equal'),@('Bytes','exact'))
        'native-seal-blocks-write-delete-rebind'=@(@('WriteWin32','32'),@('DeleteWin32','32'),@('RebindWin32','5'),@('CompatibleRead','same-identity'))
        'native-failure-matrix-zero-residue'=@(@('FailureMatrix','complete'),@('FailureHandleDelta','0'),@('KnownArtifactResidue','0'))
        'qpc-late-entry-no-refresh'=@(@('LateEntry','rejected'),@('TerminateJobObjectCallCount','0'),@('RelativeBudgetRefresh','absent'))
        'qpc-overflow-and-natural-exit-race'=@(@('Overflow','rejected'),@('NaturalExitReceipt','rejected'),@('ExitCodeMismatch','recorded'))
        'partial-preseal-rebind-fail-closed'=@(@('RebindAttempt','performed'),@('RebindBeforeSeal','succeeded'),@('SealIdentity','mismatch-rejected'),@('RuntimeProof','absent'),@('ForensicOriginal','preserved'))
        'partial-postseal-mutation-blocked'=@(@('SealBeforeAttack','true'),@('WriteWin32','32'),@('DeleteWin32','32'),@('RebindWin32','5'),@('Prefix','exact'))
        'differential-role-swap-rejected'=@(@('RawChains','validated'),@('ObservedRoleMap','cross-role'),@('RuntimeError','identity-role-swap'))
        'differential-stable-parent-recreate-rejected'=@(@('RawChains','validated'),@('StableParentIdentity','changed'),@('RuntimeError','stable-parent-identity-changed'))
        'rollback-stage-cleanup-failure-no-proof'=@(@('InjectedStage','cleanup'),@('CleanupError','observed'),@('RuntimeProof','absent'),@('PrimaryOrder','primary-first'))
        'preimage-stage-cleanup-failure-no-proof'=@(@('InjectedStage','cleanup'),@('CleanupError','observed'),@('RuntimeProof','absent'),@('PrimaryOrder','primary-first'))
    }
    if(-not $facts.Contains($CaseName)){return $null}
    return ,@($facts[$CaseName])
}
