        'selector-prehandoff-failure-ownership'=@('managed-token','read-action>typed-prehandoff-failure>publish-response')
        'selector-posthandoff-timeout-ownership'=@('managed-token','read-action>typed-posthandoff-timeout>publish-response')
        'context-sealed-call-failure-cleanup'=@('managed-token','read-action>sealed-call-failure>context-finally>publish-response')
