        'native-secured-root-containment'=@('native-resource','read-action>validate-secured-root>publish-response')
        'native-forbidden-read-delete-bridge'=@('native-live-handle','parent-open>read-action>forbidden-bridge>publish-response')
        'native-reviewed-writer-bridge-seal'=@('native-live-handle','parent-open>read-action>reviewed-seal>publish-response')
        'native-seal-blocks-write-delete-rebind'=@('native-live-handle','parent-open>read-action>mutation-probes>publish-response')
        'native-failure-matrix-zero-residue'=@('native-resource','read-action>native-failure-matrix>publish-response')
        'qpc-late-entry-no-refresh'=@('qpc-live-job','parent-qpc>read-action>late-entry>publish-response')
        'qpc-overflow-and-natural-exit-race'=@('qpc-live-job','parent-qpc>read-action>exit-race>publish-response')
        'partial-preseal-rebind-fail-closed'=@('partial-preseal-rebind','parent-rebind>read-action>identity-reject>publish-response')
        'partial-postseal-mutation-blocked'=@('partial-sealed-handle','parent-open>read-action>mutation-probes>publish-response')
        'differential-role-swap-rejected'=@('differential-held-artifacts','read-action>publish-raw-pair>parent-role-map>publish-response')
        'differential-stable-parent-recreate-rejected'=@('differential-held-artifacts','read-action>publish-raw-pair>parent-stable-identity>publish-response')
        'rollback-stage-cleanup-failure-no-proof'=@('cleanup-held-blocker','parent-blocker>read-action>cleanup-failure>proof-check>publish-response')
        'preimage-stage-cleanup-failure-no-proof'=@('cleanup-held-blocker','parent-blocker>read-action>cleanup-failure>proof-check>publish-response')
    }
    if(-not $specs.Contains($CaseName)){return $null}
    return [pscustomobject]@{Kind=[string]$specs[$CaseName][0];OperationSequence=[string]$specs[$CaseName][1]}
}
function Test-HardKillBehaviorCaseEvidence {
    param(
        [AllowNull()]$Case,
        [AllowNull()]$RequestCase,
        [AllowNull()]$ParentObservation,
        [Parameter(Mandatory)][string]$ExpectedPriorRowSha256
    )
    $caseKeys=@('Index','Name','CaseNonce','InputSha256','ActionSha256','PriorRowSha256','RawRows','Artifacts','RawFailure','RowSha256')
    $rowKeys=@('Ordinal','Operation','Result','ErrorCode','Identity','Length','RawSha256')
    $requestKeys=@('Index','Name','CaseNonce','InputSha256','AbsoluteDeadlineQpc','ReadyEventName','ContinueEventName','DoneEventName','ReleaseEventName','CaseRelativeDirectory','ChallengeRelativePath','ActionRelativePath','ResponseRelativePath','OracleKind','OperationSequence')
    $parentKeys=@('Index','CaseNonce','OracleKind','OperationSequence','AbsoluteDeadlineQpc','ReadyObserved','RootProcessAlive','JobActiveBefore','ParentQpcAtReady','ParentQpcAtContinue','StopwatchFrequency','ActionNonce','ActionSha256','ChallengeAttempted','ChallengeWin32Error','ChallengeIdentity','ChallengeLength','ChallengeRawSha256','ResponseObserved','ResponseIdentity','ResponseLength','ResponseRawSha256','ExpectedResponseRawSha256','PresealRebindAttempted','PresealOriginalIdentity','PresealReplacementIdentity','DifferentialArtifactsObserved','DifferentialIdentityRelation','ForensicObserved','ProofAbsentObserved','ForensicIdentity','ForensicLength','ForensicRawSha256','CleanupBlockerHeld')
    if(-not(Test-HardKillExactObjectKeys $Case $caseKeys) -or -not(Test-HardKillExactObjectKeys $RequestCase $requestKeys) -or -not(Test-HardKillExactObjectKeys $ParentObservation $parentKeys)){return $false}
    if($Case.Index -isnot [long] -or $RequestCase.Index -isnot [long] -or $Case.Index -ne $RequestCase.Index -or
        $Case.Name -isnot [string] -or $Case.Name -cne $RequestCase.Name -or $Case.CaseNonce -isnot [string] -or $Case.CaseNonce -cne $RequestCase.CaseNonce -or
        $Case.InputSha256 -isnot [string] -or $Case.InputSha256 -cne $RequestCase.InputSha256 -or $RequestCase.AbsoluteDeadlineQpc -isnot [string] -or
        $RequestCase.AbsoluteDeadlineQpc -cnotmatch '^[1-9][0-9]*$' -or $ParentObservation.AbsoluteDeadlineQpc -cne $RequestCase.AbsoluteDeadlineQpc -or
        $Case.ActionSha256 -isnot [string] -or $Case.ActionSha256 -cne $ParentObservation.ActionSha256 -or
        $Case.PriorRowSha256 -isnot [string] -or $Case.PriorRowSha256 -cne $ExpectedPriorRowSha256 -or $Case.RowSha256 -isnot [string] -or $Case.RowSha256 -cnotmatch '^[0-9a-f]{64}$') {return $false}
    if($null -ne $Case.RawFailure -and -not(Test-HardKillExactObjectKeys $Case.RawFailure @('Stage','Code','PrimaryOrdinal','CleanupCodes'))){return $false}
    $expectedFacts=Get-HardKillBehaviorExpectedFacts -CaseName $Case.Name;if($null -eq $expectedFacts){return $false}
    $rows=@($Case.RawRows);if($rows.Count -ne $expectedFacts.Count){return $false}
    for($index=0;$index -lt $rows.Count;$index++){
        $row=$rows[$index];$expected=$expectedFacts[$index]
        if(-not(Test-HardKillExactObjectKeys $row $rowKeys) -or $row.Ordinal -isnot [long] -or $row.Ordinal -ne $index -or
            $row.Operation -isnot [string] -or $row.Operation -cne [string]$expected[0] -or $row.Result -isnot [string] -or $row.Result -cne [string]$expected[1] -or
            $row.ErrorCode -isnot [string] -or $row.Identity -isnot [string] -or $row.Length -isnot [long] -or $row.Length -lt 0 -or
            $row.RawSha256 -isnot [string] -or ($row.RawSha256.Length -ne 0 -and $row.RawSha256 -cnotmatch '^[0-9a-f]{64}$')){return $false}
    }
    $oracle=Get-HardKillParentOracleSpec -CaseName $Case.Name
    if($null -eq $oracle -or $RequestCase.OracleKind -cne $oracle.Kind -or $RequestCase.OperationSequence -cne $oracle.OperationSequence -or
        $ParentObservation.OracleKind -cne $oracle.Kind -or $ParentObservation.OperationSequence -cne $oracle.OperationSequence -or
        $ParentObservation.Index -ne $RequestCase.Index -or $ParentObservation.CaseNonce -cne $RequestCase.CaseNonce -or
        -not $ParentObservation.ReadyObserved -or -not $ParentObservation.RootProcessAlive -or [long]$ParentObservation.JobActiveBefore -le 0 -or
        [long]$ParentObservation.ParentQpcAtReady -le 0 -or [long]$ParentObservation.ParentQpcAtContinue -lt [long]$ParentObservation.ParentQpcAtReady -or
        [long]$ParentObservation.StopwatchFrequency -ne [Diagnostics.Stopwatch]::Frequency -or -not $ParentObservation.ChallengeAttempted -or
        [int]$ParentObservation.ChallengeWin32Error -ne 32 -or [string]::IsNullOrWhiteSpace([string]$ParentObservation.ChallengeIdentity) -or
        [long]$ParentObservation.ChallengeLength -le 0 -or [string]$ParentObservation.ChallengeRawSha256 -cnotmatch '^[0-9a-f]{64}$' -or
        -not $ParentObservation.ResponseObserved -or $ParentObservation.ResponseIdentity -isnot [string] -or [string]::IsNullOrWhiteSpace($ParentObservation.ResponseIdentity) -or
        [long]$ParentObservation.ResponseLength -le 0 -or $ParentObservation.ResponseRawSha256 -cne $ParentObservation.ExpectedResponseRawSha256){return $false}
    $challengeArtifacts=@($Case.Artifacts|Where-Object{$_ -is [Collections.IDictionary] -and $_['Kind'] -ceq 'challenge'})
    $responseArtifacts=@($Case.Artifacts|Where-Object{$_ -is [Collections.IDictionary] -and $_['Kind'] -ceq 'response'})
    if($challengeArtifacts.Count -ne 1 -or $responseArtifacts.Count -ne 1){return $false}
    $artifact=$challengeArtifacts[0];$responseArtifact=$responseArtifacts[0]
    if(-not(Test-HardKillExactObjectKeys $artifact @('Kind','RelativePath','Identity','Length','RawSha256')) -or
        $artifact.RelativePath -cne $RequestCase.ChallengeRelativePath -or $artifact.Identity -cne $ParentObservation.ChallengeIdentity -or
        $artifact.Length -ne $ParentObservation.ChallengeLength -or $artifact.RawSha256 -cne $ParentObservation.ChallengeRawSha256 -or
        -not(Test-HardKillExactObjectKeys $responseArtifact @('Kind','RelativePath','Identity','Length','RawSha256')) -or
        $responseArtifact.RelativePath -cne $RequestCase.ResponseRelativePath -or $responseArtifact.Identity -cne $ParentObservation.ResponseIdentity -or
        $responseArtifact.Length -ne $ParentObservation.ResponseLength -or $responseArtifact.RawSha256 -cne $ParentObservation.ResponseRawSha256){return $false}
    switch($oracle.Kind){
        'qpc-live-job'{if([long]$ParentObservation.ParentQpcAtContinue -le [long]$ParentObservation.ParentQpcAtReady -or [long]$ParentObservation.JobActiveBefore -le 0){return $false}}
        'partial-preseal-rebind'{if(-not $ParentObservation.PresealRebindAttempted -or [string]::IsNullOrWhiteSpace($ParentObservation.PresealOriginalIdentity) -or [string]::IsNullOrWhiteSpace($ParentObservation.PresealReplacementIdentity) -or $ParentObservation.PresealOriginalIdentity -ceq $ParentObservation.PresealReplacementIdentity){return $false}}
        'differential-held-artifacts'{if(-not $ParentObservation.DifferentialArtifactsObserved -or $ParentObservation.DifferentialIdentityRelation -cnotin @('cross-role','stable-parent-changed')){return $false}}
        'cleanup-held-blocker'{if(-not $ParentObservation.CleanupBlockerHeld -or -not $ParentObservation.ForensicObserved -or -not $ParentObservation.ProofAbsentObserved){return $false}}
        default{if($ParentObservation.PresealRebindAttempted -or $ParentObservation.DifferentialArtifactsObserved -or $ParentObservation.CleanupBlockerHeld){return $false}}
    }
    $artifacts=@($Case.Artifacts)
    foreach($artifact in $artifacts){
        if(-not(Test-HardKillExactObjectKeys $artifact @('Kind','RelativePath','Identity','Length','RawSha256')) -or
            $artifact.Kind -isnot [string] -or $artifact.RelativePath -isnot [string] -or $artifact.RelativePath -match '(^|[\\/])\.\.([\\/]|$)' -or
            $artifact.Identity -isnot [string] -or [string]::IsNullOrWhiteSpace($artifact.Identity) -or $artifact.Length -isnot [long] -or $artifact.Length -le 0 -or
            $artifact.RawSha256 -isnot [string] -or $artifact.RawSha256 -cnotmatch '^[0-9a-f]{64}$'){return $false}
    }
    if($Case.Name -cin @('rollback-stage-cleanup-failure-no-proof','preimage-stage-cleanup-failure-no-proof')){
        $forensicArtifacts=@($artifacts|Where-Object{$_['Kind'] -ceq 'forensic'})
        if(-not $ParentObservation.ForensicObserved -or -not $ParentObservation.ProofAbsentObserved -or $forensicArtifacts.Count -ne 1 -or
            $forensicArtifacts[0].RelativePath -cne ($RequestCase.CaseRelativeDirectory+'/forensic.bin') -or
            $forensicArtifacts[0].Identity -cne $ParentObservation.ForensicIdentity -or $forensicArtifacts[0].Length -ne $ParentObservation.ForensicLength -or
            $forensicArtifacts[0].RawSha256 -cne $ParentObservation.ForensicRawSha256){return $false}
    }
    $expectedArtifactCount=2
    if($Case.Name -cin @('rollback-stage-cleanup-failure-no-proof','preimage-stage-cleanup-failure-no-proof')){$expectedArtifactCount++}
    if($artifacts.Count -ne $expectedArtifactCount){return $false}
    $rowDocument=[ordered]@{Index=$Case.Index;Name=$Case.Name;CaseNonce=$Case.CaseNonce;InputSha256=$Case.InputSha256;ActionSha256=$Case.ActionSha256;PriorRowSha256=$Case.PriorRowSha256;RawRows=@($Case.RawRows);Artifacts=@($Case.Artifacts);RawFailure=$Case.RawFailure}
    return (Get-HardKillSha256Hex (ConvertTo-SemanticJsonBytes -InputObject $rowDocument)) -ceq $Case.RowSha256
}
function Open-HardKillHeldFileEvidence {
    param([Parameter(Mandatory)][string]$Path)
    $full=[IO.Path]::GetFullPath($Path);$chain=$null;$capture=$null
    try{
        $parent=[IO.Path]::GetDirectoryName($full);$leaf=[IO.Path]::GetFileName($full)
        $chainReceiver=[AiAgentDotfiles.SealedOwnershipTransferReceiver]::new()
        Open-SafeDirectoryContainmentChain -Path $parent -OwnershipReceiver $chainReceiver
        $chain = $chainReceiver.GetDeliveredExact()
        $capture=[AiAgentDotfiles.NoFollowFile]::OpenAndHashChildRegularFile($chain[$chain.Count-1],$leaf)
        $bytes=[IO.File]::ReadAllBytes($full);$sha=Get-HardKillSha256Hex $bytes
        if($sha -cne [string]$capture.ReadResult.Sha256 -or $bytes.LongLength -ne [long]$capture.ReadResult.Length){throw 'held-file-byte-drift'}
        return [pscustomobject]@{Path=$full;Leaf=$leaf;ParentHandles=$chain;Capture=$capture;Bytes=$bytes;Sha256=$sha;Identity=[string]$capture.ReadResult.Identity;Length=[long]$capture.ReadResult.Length}
    }catch{
        if($capture){$capture.Dispose()};if($chain){Close-SafeDirectoryContainmentChain -Handles $chain};throw
    }
}
function Close-HardKillHeldFileEvidence {
    param([AllowNull()]$Evidence)
    if($null -eq $Evidence){return}
    $primary=$null
    try{if($Evidence.Capture){$Evidence.Capture.Dispose()}}catch{$primary=$_.Exception}
    try{if($Evidence.ParentHandles){Close-SafeDirectoryContainmentChain -Handles $Evidence.ParentHandles}}catch{if($null -eq $primary){$primary=$_.Exception}else{$primary=[AggregateException]::new('held-file cleanup failed',@($primary,$_.Exception))}}
    if($primary){throw $primary}
}
function Write-HardKillCreateNewBytes {
    param([Parameter(Mandatory)][string]$Path,[Parameter(Mandatory)][byte[]]$Bytes)
    $stream=$null
    try{
        $stream=[IO.FileStream]::new([IO.Path]::GetFullPath($Path),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read,4096,[IO.FileOptions]::WriteThrough)
        $stream.Write($Bytes,0,$Bytes.Length);$stream.Flush($true)
    }finally{if($stream){$stream.Dispose()}}
}
function Get-HardKillRemainingQpcMilliseconds {
    param([Parameter(Mandatory)][long]$AbsoluteDeadlineQpc)
    $now=[Diagnostics.Stopwatch]::GetTimestamp();$frequency=[long][Diagnostics.Stopwatch]::Frequency
    if($AbsoluteDeadlineQpc -le $now -or $frequency -le 0){return 0}
    $remainingTicks=[long]($AbsoluteDeadlineQpc-$now)
    $milliseconds=[Math]::Ceiling(([double]$remainingTicks*1000.0)/[double]$frequency)
    if($milliseconds -gt [int]::MaxValue){return [int]::MaxValue}
    return [int][Math]::Max(1.0,$milliseconds)
}
function New-HardKillBehaviorOracleFixture {
    param(
        [Parameter(Mandatory)][string]$CaseName,[Parameter(Mandatory)][long]$Index,[Parameter(Mandatory)][string]$CaseNonce,
