    switch -CaseSensitive -Exact ($Fixture.OracleKind) {
        'managed-token' { return Complete-HardKillManagedTokenOracleObservation -Fixture $Fixture -Process $Process -JobProcess $JobProcess -DeadlineQpc $DeadlineQpc }
