function Test-HardKillBehaviorOracleObservation {
    param([Parameter(Mandatory)]$Fixture,[Parameter(Mandatory)]$Observation)
    $spec=Get-HardKillParentOracleSpec -CaseName ([string]$Fixture.CaseName)
    return $null -ne $spec -and $Observation.Index -eq $Fixture.Index -and $Observation.CaseNonce -ceq $Fixture.CaseNonce -and
        $Observation.OracleKind -ceq $spec.Kind -and $Observation.OperationSequence -ceq $spec.OperationSequence -and
        $Observation.ReadyObserved -and $Observation.RootProcessAlive -and [long]$Observation.JobActiveBefore -gt 0 -and
        [long]$Observation.ParentQpcAtContinue -ge [long]$Observation.ParentQpcAtReady -and $Observation.ResponseObserved
}
function Close-HardKillBehaviorOracleFixture {
    param([AllowNull()]$Fixture)
    if($null -eq $Fixture -or $Fixture.Closed){return}
    if($Fixture.ResponseCapture){$Fixture.ResponseCapture.Dispose();$Fixture.ResponseCapture=$null}
    if($Fixture.ChallengeCapture){$Fixture.ChallengeCapture.Dispose();$Fixture.ChallengeCapture=$null}
    foreach($name in @('ReleaseEvent','DoneEvent','ContinueEvent','ReadyEvent')){if($Fixture.$name){$Fixture.$name.Dispose();$Fixture.$name=$null}}
    $Fixture.Closed=$true
}
