        if($definitions.Count -ne 1){return $null};return $definitions[0]
    }
    function Remove-DispatcherDefinition([string]$Source,[string]$Name){
        $definition=Get-DispatcherDefinition $Source $Name;if($null -eq $definition){return $null}
        return $Source.Remove($definition.Extent.StartOffset,$definition.Extent.EndOffset-$definition.Extent.StartOffset)
    }
    function Replace-InDispatcherDefinition([string]$Source,[string]$Name,[string]$Old,[string]$New){
