'@
    function Replace-Once([string]$Source,[string]$Old,[string]$New){$offset=$Source.IndexOf($Old,[StringComparison]::Ordinal);if($offset -lt 0 -or $Source.IndexOf($Old,$offset+$Old.Length,[StringComparison]::Ordinal) -ge 0){return $null};return $Source.Remove($offset,$Old.Length).Insert($offset,$New)}
    $dispatcherLine="function Invoke-SealedMutationBehaviorCase { param(`$Fixture,`$Request,`$Action) switch -CaseSensitive -Exact (`$Request.Name) {"
    $firstBranch="'selector-nonmatch-no-io' { return Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo -Fixture `$Fixture -Request `$Request -Action `$Action }"
    $firstHandler='function Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo { param($Fixture,$Request,$Action) return [AiAgentDotfilesTests.SealedMutationBehaviorCasePrimitives]::ExecuteSelectorNonmatchNoIo($Fixture,$Request,$Action) }'
    $secondHandler='function Invoke-SealedMutationBehaviorHandlerSelectorFirstMatchSingleUseTicket { param($Fixture,$Request,$Action) return [AiAgentDotfilesTests.SealedMutationBehaviorCasePrimitives]::ExecuteSelectorFirstMatchSingleUseTicket($Fixture,$Request,$Action) }'
    $mutants=[ordered]@{
        'missing-dispatcher'=(Replace-Once $baseline $dispatcherLine ($dispatcherLine.Replace('Invoke-SealedMutationBehaviorCase','Invoke-SealedMutationBehaviorCaseMissing')))
        'duplicate-dispatcher'=$baseline+"`n"+$dispatcherLine+"`ndefault { throw 'behavior-case-name' }`n}}`n"
        'selector-from-fixture'=(Replace-Once $baseline '($Request.Name)' '($Fixture.CaseName)')
        'missing-exact'=(Replace-Once $baseline 'switch -CaseSensitive -Exact' 'switch -CaseSensitive')
        'missing-case'=(Replace-Once $baseline $firstBranch '')
        'duplicate-case-label'=(Replace-Once $baseline "'selector-first-match-single-use-ticket'" "'selector-nonmatch-no-io'")
        'default-canned-return'=(Replace-Once $baseline "default { throw 'behavior-case-name' }" 'default { return [pscustomobject]@{} }')
        'wrong-handler'=(Replace-Once $baseline $firstBranch ($firstBranch.Replace('Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo','Invoke-SealedMutationBehaviorHandlerSelectorFirstMatchSingleUseTicket')))
        'dispatcher-action-swapped'=(Replace-Once $baseline $firstBranch ($firstBranch.Replace('-Action $Action','-Action $Request')))
        'missing-handler'=(Replace-Once $baseline $firstHandler '')
        'nested-handler'=(Replace-Once $baseline $firstHandler ('function Invoke-SealedMutationNestedCarrier {'+$firstHandler+'}'))
        'canned-handler'=(Replace-Once $baseline $firstHandler 'function Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo { param($Fixture,$Request,$Action) return [pscustomobject]@{} }')
        'unreachable-primitive'=(Replace-Once $baseline $firstHandler 'function Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo { param($Fixture,$Request,$Action) if($false){return [AiAgentDotfilesTests.SealedMutationBehaviorCasePrimitives]::ExecuteSelectorNonmatchNoIo($Fixture,$Request,$Action)};return [pscustomobject]@{} }')
        'shared-primitive-member'=(Replace-Once $baseline '::ExecuteSelectorFirstMatchSingleUseTicket($Fixture,$Request,$Action)' '::ExecuteSelectorNonmatchNoIo($Fixture,$Request,$Action)')
        'primitive-action-swapped'=(Replace-Once $baseline '::ExecuteSelectorNonmatchNoIo($Fixture,$Request,$Action)' '::ExecuteSelectorNonmatchNoIo($Fixture,$Request,$Request)')
        'alias-shadow'=$baseline+"`nSet-Alias Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo Get-Date`n"
        'computed-alias-shadow'=$baseline+"`n`$setter='Set-Alias';& `$setter Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo Get-Date`n"
        'case-insensitive-handler-shadow'=$baseline+"`n"+$secondHandler.Replace('Invoke-SealedMutationBehaviorHandlerSelectorFirstMatchSingleUseTicket','invoke-sealedmutationbehaviorhandlerselectorfirstmatchsingleuseticket')+"`n"
    }
    $expected=[ordered]@{
        'missing-dispatcher'='behavior-child-helper-missing:Invoke-SealedMutationBehaviorCase';'duplicate-dispatcher'='behavior-child-helper-missing:Invoke-SealedMutationBehaviorCase'
        'selector-from-fixture'='behavior-child-dispatcher-selector';'missing-exact'='behavior-child-dispatcher-selector';'missing-case'='behavior-child-dispatcher-label:selector-first-match-single-use-ticket'
        'duplicate-case-label'='behavior-child-dispatcher-label:selector-nonmatch-no-io';'default-canned-return'='behavior-child-dispatcher-default'
        'wrong-handler'='behavior-child-dispatcher-handler:selector-nonmatch-no-io';'dispatcher-action-swapped'='behavior-child-dispatcher-binding:selector-nonmatch-no-io:Action'
        'missing-handler'='behavior-child-handler-definition:Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo';'nested-handler'='behavior-child-handler-scope:Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo'
        'canned-handler'='behavior-child-handler-primitive:Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo';'unreachable-primitive'='behavior-child-handler-primitive:Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo'
        'shared-primitive-member'='behavior-child-handler-primitive:Invoke-SealedMutationBehaviorHandlerSelectorFirstMatchSingleUseTicket'
        'primitive-action-swapped'='behavior-child-handler-primitive-binding:Invoke-SealedMutationBehaviorHandlerSelectorNonmatchNoIo:Action'
        'alias-shadow'='behavior-child-shadow';'computed-alias-shadow'='behavior-child-shadow'
        'case-insensitive-handler-shadow'='behavior-child-handler-definition:Invoke-SealedMutationBehaviorHandlerSelectorFirstMatchSingleUseTicket'
    }
    $baselineResult=Test-HardKillBehaviorChildCapabilityContract -EngineSource $baseline;$cases=[Collections.Generic.List[object]]::new()
    foreach($name in $mutants.Keys){$source=[string]$mutants[$name];$tokens=$null;$errors=$null;$null=[Management.Automation.Language.Parser]::ParseInput($source,[ref]$tokens,[ref]$errors);$verdict=if(@($errors).Count -eq 0){Test-HardKillBehaviorChildCapabilityContract -EngineSource $source}else{$null};$codes=@(if($verdict){$verdict.ErrorCodes}else{'mutation-parse'});$reason=[string]$expected[$name];$cases.Add([pscustomobject]@{Name=$name;Changed=$source -cne $baseline;ParseValid=@($errors).Count -eq 0;Rejected=$null -ne $verdict -and -not $verdict.Valid;ExpectedErrorCode=$reason;RejectedForExpectedReason=$codes.Count -eq 1 -and $codes[0] -ceq $reason;ErrorCodes=$codes})}
    return [pscustomobject]@{Valid=$baselineResult.Valid -and $cases.Count -eq 18 -and @($cases|Where-Object{-not $_.Changed -or -not $_.ParseValid -or -not $_.Rejected -or -not $_.RejectedForExpectedReason}).Count -eq 0;Baseline=$baselineResult;Cases=@($cases);ExpectedNames=@($expected.Keys)}
}
function Test-HardKillBehaviorProbeHostCaseFlowContract {
    param([AllowEmptyString()][Parameter(Mandatory)][string]$HostSource)
    $result=[ordered]@{Valid=$false;ErrorCodes=@();FunctionCount=0;RouteCount=0;CaseLoopCount=0;CaseCount=0;DeadlineBindingCount=0;LifecycleCount=0;RowFieldCount=0;DocumentFieldCount=0}
    try{
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($HostSource,[ref]$tokens,[ref]$errors)
        if(@($errors).Count -ne 0){throw 'probe-case-flow-parse'}
        function Test-HostFlowAstExact([Management.Automation.Language.Ast]$Node,[string]$ExpectedSource){
            if($null -eq $Node){return $false}
            $actual=Get-HardKillTokenFingerprint -Source ([string]$Node.Extent.Text)
            $expected=Get-HardKillTokenFingerprint -Source $ExpectedSource
            return -not[string]::IsNullOrEmpty($actual) -and $actual -ceq $expected
        }
        if($null -eq $ast.ParamBlock){throw 'probe-case-flow-route-parameters'}
        $scriptAttributes=@($ast.ParamBlock.Attributes)
        if($scriptAttributes.Count -ne 1 -or $scriptAttributes[0] -isnot [Management.Automation.Language.AttributeAst] -or
            $scriptAttributes[0].TypeName.Name -cne 'CmdletBinding' -or $scriptAttributes[0].PositionalArguments.Count -ne 0 -or
            $scriptAttributes[0].NamedArguments.Count -ne 0){throw 'probe-case-flow-route-parameters'}
        $requiredParamBlockSource=@'
param(
    [switch]$ContractProbe,
    [string]$ContractProbeRequestPath,
    [string]$ContractProbeRequestSha256,
    [string]$MutationEnginePath,
    [string]$ExpectedEngineSha256,
    [string]$SealedInvocationFixturePath,
    [string]$SealedInvocationFixtureSha256,
    [string]$ExpectedProbeHostSha256,
    [string]$ContractProbeResultPath,
    [string]$ContractProbeScratchRoot,
    [Parameter(Mandatory)][string]$ToolchainRoot,
    [Parameter(Mandatory)][string]$FixtureRoot,
    [Parameter(Mandatory)][ValidatePattern('^[0-9a-f-]{36}$')][string]$TransactionId,
    [Parameter(Mandatory)][ValidateSet('parent','directory','directory-add','directory-delete','file','file-add')][string]$Kind,
    [Parameter(Mandatory)][string]$Checkpoint,
    [Parameter(Mandatory)][string]$MarkerPath,
    [string]$AfterPreimageStagePath,
    [ValidatePattern('^AiAgentDotfilesTests-AfterPreimage-[0-9a-f]{32}$')][string]$AfterPreimageStageEventName,
    [ValidateSet('committed','failed-restored')][string]$TerminalOutcome='committed'
)
'@
        if((Get-HardKillTokenFingerprint -Source ([string]$ast.ParamBlock.Extent.Text)) -cne
            (Get-HardKillTokenFingerprint -Source $requiredParamBlockSource)){throw 'probe-case-flow-route-parameters'}
        foreach($blockName in @('DynamicParamBlock','BeginBlock','ProcessBlock','CleanBlock')){$property=$ast.PSObject.Properties[$blockName];if($property -and $property.Value -and @($property.Value.Statements).Count){throw 'probe-case-flow-route-control'}}
        $rootTraps=@($ast.FindAll({param($node)$node -is [Management.Automation.Language.TrapStatementAst]},$true)|Where-Object{$null -eq (Get-NearestHardKillFunction $_)})
        if($rootTraps.Count -ne 0){throw 'probe-case-flow-route-control'}
        $requirements=$ast.ScriptRequirements
        $requiresDirectives=@($tokens|Where-Object{$_.Kind -eq [Management.Automation.Language.TokenKind]::Comment -and ([string]$_.Text) -imatch '^#requires(?:\s|$)'})
        if(@($ast.UsingStatements).Count -ne 0 -or $null -eq $requirements -or $requirements.RequiredPSVersion -ne [version]'7.0' -or
            @($requirements.RequiredPSEditions).Count -ne 0 -or @($requirements.RequiredModules).Count -ne 0 -or
            @($requirements.RequiredAssemblies).Count -ne 0 -or -not[string]::IsNullOrEmpty([string]$requirements.RequiredApplicationId) -or
            $requirements.IsElevationRequired -or $requiresDirectives.Count -ne 1 -or [string]$requiresDirectives[0].Text -cne '#requires -Version 7.0'){
            throw 'probe-case-flow-route-shadow'
        }

        $routeCommands=@($ast.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst] -and
            $node.GetCommandName() -ieq 'Invoke-SealedMutationContractProbe'},$true)|Where-Object{$null -eq (Get-NearestHardKillFunction $_)})
        if($routeCommands.Count -ne 1 -or $routeCommands[0].GetCommandName() -cne 'Invoke-SealedMutationContractProbe' -or
            $routeCommands[0].InvocationOperator -ne [Management.Automation.Language.TokenKind]::Unknown -or $routeCommands[0].Redirections.Count -ne 0){throw 'probe-case-flow-route'}
        $routePipeline=$routeCommands[0].Parent;$routeBlock=if($routePipeline){$routePipeline.Parent}else{$null};$routeIf=if($routeBlock){$routeBlock.Parent}else{$null}
        $routeText="if(`$ContractProbe){`nInvoke-SealedMutationContractProbe -ContractProbeRequestPath `$ContractProbeRequestPath -ContractProbeRequestSha256 `$ContractProbeRequestSha256 -MutationEnginePath `$MutationEnginePath -ExpectedEngineSha256 `$ExpectedEngineSha256 -ExpectedProbeHostSha256 `$ExpectedProbeHostSha256 -ContractProbeResultPath `$ContractProbeResultPath -ContractProbeScratchRoot `$ContractProbeScratchRoot`nreturn`n}"
        if($routePipeline -isnot [Management.Automation.Language.PipelineAst] -or $routeBlock -isnot [Management.Automation.Language.StatementBlockAst] -or
            $routeIf -isnot [Management.Automation.Language.IfStatementAst] -or -not[object]::ReferenceEquals($routeIf.Parent,$ast.EndBlock) -or
