        if($routeIndex -lt 0 -or @($rootStatements[0..($routeIndex-1)]|Where-Object{$_ -isnot [Management.Automation.Language.FunctionDefinitionAst]}).Count -ne 0){throw 'probe-case-flow-route-predecessor'}
        $criticalNames=@('Assert-SealedMutationBehaviorChildPrimitiveAuthority','New-SealedMutationBehaviorFixture','Read-SealedMutationBehaviorControllerAction',
            'Invoke-SealedMutationBehaviorCase','Get-SealedMutationBehaviorResponseBytes','Write-SealedMutationBehaviorResponse','Close-SealedMutationBehaviorFixture',
            'ConvertFrom-SemanticJson','ConvertTo-SemanticJsonBytes')
        $priorDefinitions=@($rootStatements[0..($routeIndex-1)]|Where-Object{$_ -is [Management.Automation.Language.FunctionDefinitionAst]})
