        foreach($blockName in @('DynamicParamBlock','BeginBlock','ProcessBlock','CleanBlock')){$property=$function.Body.PSObject.Properties[$blockName];if($property -and $property.Value -and @($property.Value.Statements).Count){throw 'probe-case-flow-scope'}}
        if(@($function.FindAll({param($node)$node -is [Management.Automation.Language.TrapStatementAst] -or $node -is [Management.Automation.Language.ScriptBlockExpressionAst]},$true)).Count -ne 0){throw 'probe-case-flow-control'}
        $statements=@($function.Body.EndBlock.Statements)
