        $result.CaseLoopCount=1;$result.CaseCount=20
        $abrupt=@($loop.FindAll({param($node)$node -is [Management.Automation.Language.ReturnStatementAst] -or $node -is [Management.Automation.Language.ExitStatementAst] -or
            $node -is [Management.Automation.Language.BreakStatementAst] -or $node -is [Management.Automation.Language.ContinueStatementAst] -or $node -is [Management.Automation.Language.TrapStatementAst]},$true))
        $loopStatements=@($loop.Body.Statements)
        if($abrupt.Count -ne 0 -or $loopStatements.Count -ne 3 -or -not(Test-HostFlowAstExact $loopStatements[0] '$fixture = $null') -or
            -not(Test-HostFlowAstExact $loopStatements[1] '$casePrimary = $null') -or $loopStatements[2] -isnot [Management.Automation.Language.TryStatementAst]){throw 'probe-case-flow-loop'}
        $innerTry=$loopStatements[2]
        if($innerTry.CatchClauses.Count -ne 1 -or $innerTry.CatchClauses[0].CatchTypes.Count -ne 0 -or $null -eq $innerTry.Finally -or $innerTry.CatchClauses[0].Body.Statements.Count -ne 1 -or
