            $dynamic=@($current.FindAll({param($node)$node -is [Management.Automation.Language.ScriptBlockExpressionAst] -or
                ($node -is [Management.Automation.Language.CommandAst] -and ($node.InvocationOperator -ne [Management.Automation.Language.TokenKind]::Unknown -or $null -eq $node.GetCommandName()))},$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$current)})
            if($dynamic.Count -ne 0){throw 'preimage-provenance-dynamic-or-unreviewed-call'}
            $commands=@($current.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$current)})
            foreach($command in $commands){
