                $callees=@($definitions|Where-Object{(([string]$_.Name -split ':')[-1]) -ieq $name})
                if($callees.Count -gt 1){throw 'preimage-provenance-dynamic-or-unreviewed-call'}
                if($callees.Count -eq 1){$queue.Enqueue($callees[0]);continue}
                if($name -cnotin $allowedLeafCommands){throw 'preimage-provenance-dynamic-or-unreviewed-call'}
            }
            $members=@($current.FindAll({param($node)$node -is [Management.Automation.Language.InvokeMemberExpressionAst]},$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$current)})
            foreach($member in $members){$name=[string]$member.Member.Value;if($name -cin $forbiddenMembers){$result.PartialForbiddenReachableCount++;throw 'preimage-provenance-partial-real-chain-reachable'};if($name -cnotin $allowedMembers){throw 'preimage-provenance-dynamic-or-unreviewed-call'}}
        }
        if((Get-HardKillTokenFingerprint -Source ([string]$partial.Extent.Text)) -cne (Get-HardKillTokenFingerprint -Source $partialSource)){
            throw 'preimage-provenance-partial-stage-binding'
        }
        $result.Valid=$true
    }catch{$result.ErrorCodes=@([string]$_.Exception.Message)}
    return [pscustomobject]$result
}
