        'AiAgentDotfilesTests.HardKillJobReapReceipt','AiAgentDotfilesTests.HardKillLiveTerminationReceipt',
        'AiAgentDotfilesTests.HardKillNaturalExitReceipt','AiAgentDotfilesTests.HardKillFailureCleanupReceipt',
        'AiAgentDotfilesTests.HardKillSealedMutationHostSession','AiAgentDotfilesTests.HardKillSealedMutationControllerScope'
    )
    $guardParts=@($typeNames|ForEach-Object{'$null -ne ('''+[string]$_+''' -as [type])'})
