    $addType='$script:hardKillSealedMutationTransportAuthorityTypes=Microsoft.PowerShell.Utility\Add-Type -Language CSharp -PassThru -TypeDefinition $hardKillSealedMutationTransportAuthoritySource -ErrorAction Stop'
    $baseline=$sourceAssignment+[Environment]::NewLine+$guard+[Environment]::NewLine+$addType
    $sourceSha=Get-HardKillSha256Hex ([Text.UTF8Encoding]::new($false).GetBytes(($authoritySource -replace "\r\n?",[string][char]10)))
    $mutants=[ordered]@{
        'source-missing'=$baseline.Replace($sourceAssignment,'')
        'source-duplicate'=$baseline+[Environment]::NewLine+$sourceAssignment
        'source-not-literal'=$baseline.Replace($sourceAssignment,'$hardKillSealedMutationTransportAuthoritySource=$env:TEMP')
        'preload-guard-missing'=$baseline.Replace($guard,'')
        'preload-guard-after-add-type'=$baseline.Replace($guard+[Environment]::NewLine+$addType,$addType+[Environment]::NewLine+$guard)
        'preload-guard-name-omitted'=$baseline.Replace($guard,$guard.Replace(' -or $null -ne (''AiAgentDotfilesTests.SealedJobQpcDeadlines'' -as [type])',''))
        'add-type-missing'=$baseline.Replace($addType,'')
