        'add-type-unqualified'=$baseline.Replace('Microsoft.PowerShell.Utility\Add-Type','Add-Type')
        'add-type-pass-thru-missing'=$baseline.Replace(' -PassThru','')
        'add-type-source-swapped'=$baseline.Replace('-TypeDefinition $hardKillSealedMutationTransportAuthoritySource','-TypeDefinition $otherSource')
        'registry-rebound'=$baseline+[Environment]::NewLine+'$script:hardKillSealedMutationTransportAuthorityTypes=@()'
        'source-body-canned'=$baseline.Replace('return "reviewed-native";','return null;')
        'source-body-unreachable'=$baseline.Replace('return "reviewed-native";','if(false){return "reviewed-native";}return null;')
        'source-type-missing'=$baseline.Replace('public sealed class SealedJobQpcDeadlines {}','')
        'source-extra-public-type'=$baseline.Replace('public sealed class HardKillSealedMutationControllerScope {}','public sealed class HardKillSealedMutationControllerScope {}'+[Environment]::NewLine+'public sealed class ExtraAuthorityType {}')
    }
    $expected=[ordered]@{
        'source-missing'='transport-authority-source-literal';'source-duplicate'='transport-authority-source-literal';'source-not-literal'='transport-authority-source-literal'
        'preload-guard-missing'='transport-authority-preexisting-guard-required';'preload-guard-after-add-type'='transport-authority-preexisting-guard-required';'preload-guard-name-omitted'='transport-authority-preexisting-guard-required'
        'add-type-missing'='transport-authority-controller-add-type-required';'add-type-duplicate'='transport-authority-controller-add-type-required';'add-type-unqualified'='transport-authority-controller-add-type-required'
        'add-type-pass-thru-missing'='transport-authority-controller-add-type-required';'add-type-source-swapped'='transport-authority-controller-add-type-required';'registry-rebound'='transport-authority-controller-add-type-required'
        'source-body-canned'='transport-authority-source-not-reviewed';'source-body-unreachable'='transport-authority-source-not-reviewed'
        'source-type-missing'='transport-authority-type-inventory';'source-extra-public-type'='transport-authority-type-inventory'
    }
    $baselineResult=Test-HardKillSealedMutationTransportAuthorityDefinitionContract -HelperSource $baseline -ReviewedSourceSha256 $sourceSha
    $cases=[Collections.Generic.List[object]]::new();$inventoryMatches=@($mutants.Keys).Count -eq @($expected.Keys).Count
    if($inventoryMatches){for($index=0;$index -lt @($expected.Keys).Count;$index++){if([string]@($mutants.Keys)[$index] -cne [string]@($expected.Keys)[$index]){$inventoryMatches=$false;break}}}
    foreach($name in $expected.Keys){
        $source=if($mutants.Contains($name)){[string]$mutants[$name]}else{''};$tokens=$null;$errors=$null
        $null=[Management.Automation.Language.Parser]::ParseInput($source,[ref]$tokens,[ref]$errors)
