        $codes=@(if($verdict){$verdict.ErrorCodes}else{'mutation-parse'});$reason=[string]$expected[$name]
        $cases.Add([pscustomobject]@{Name=$name;Constructed=-not[string]::IsNullOrEmpty($source);Changed=$source -cne $baseline;ParseValid=@($errors).Count -eq 0;Rejected=$null -ne $verdict -and -not $verdict.Valid;ExpectedErrorCode=$reason;RejectedForExpectedReason=$codes.Count -eq 1 -and $codes[0] -ceq $reason;ErrorCodes=$codes})
    }
    return [pscustomobject]@{Valid=$baselineResult.Valid -and $inventoryMatches -and $cases.Count -eq 16 -and @($cases|Where-Object{-not $_.Constructed -or -not $_.Changed -or -not $_.ParseValid -or -not $_.Rejected -or -not $_.RejectedForExpectedReason}).Count -eq 0;Baseline=$baselineResult;Cases=@($cases);ExpectedNames=@($expected.Keys)}
}
