                'after-file-replace'{[ordered]@{Kind='file';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileReplacePresent';CurrentState='PRESENT'};break}
                'before-file-add-move'{[ordered]@{Kind='file-add';RawCheckpoint='before-file-replace';Checkpoint='BeforeFileReplaceMove';Variant='FileMoveMissing';CurrentState='MISSING'};break}
                'after-file-add-move'{[ordered]@{Kind='file-add';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileMoveMissing';CurrentState='MISSING'};break}
                'rollback-file-before-replace'{[ordered]@{Kind='file';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileReplacePresent';CurrentState='PRESENT'};break}
                'rollback-file-after-replace'{[ordered]@{Kind='file';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileReplacePresent';CurrentState='PRESENT'};break}
                'rollback-file-add-before-new-to-staged'{[ordered]@{Kind='file-add';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileMoveMissing';CurrentState='MISSING'};break}
                'rollback-file-add-after-new-to-staged'{[ordered]@{Kind='file-add';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileMoveMissing';CurrentState='MISSING'};break}
                default{throw 'sealed mutation controller file case name is invalid'}
            }
            $armTargets=@($snapshot.State.Header.Targets|Where-Object{[string]$_.TargetId -ceq [string]$selector.SelectorArm.TargetId -and [long]$_.Order -eq [long]$selector.SelectorArm.TargetOrder})
            $preparedRecords=@($snapshot.State.Records|Where-Object{[string]$_.Phase -ceq 'FILE_PREPARED' -and [string]$_.Data.TargetId -ceq [string]$selector.SelectorArm.TargetId})
            if([string]$CaseDefinition.Kind -cne [string]$expectedFileBinding.Kind -or [string]$CaseDefinition.Checkpoint -cne [string]$expectedFileBinding.RawCheckpoint -or
                [string]$stage.Checkpoint -cne [string]$expectedFileBinding.Checkpoint -or [string]$stage.DeclaredPrimitiveVariant -cne [string]$expectedFileBinding.Variant -or
                [string]$stage.ActualBranchDiscriminator -cne [string]$expectedFileBinding.CurrentState -or
                $armTargets.Count -ne 1 -or [string]$armTargets[0].TargetKind -cne 'file' -or [string]$armTargets[0].Role -cne 'manifest' -or [string]$armTargets[0].Platform -cne 'Union' -or
                [string]$armTargets[0].Current.State -cne [string]$expectedFileBinding.CurrentState -or [string]$armTargets[0].Candidate.State -cne 'PRESENT' -or
                [string]$intentRecord.Data.TargetId -cne [string]$selector.SelectorArm.TargetId -or $preparedRecords.Count -ne 1 -or
                [long]$preparedRecords[0].Sequence -ne ([long]$selector.ExpectedIntentSequence-1) -or [string]$intentRecord.PreviousHash -cne (Get-SemanticJsonHash -InputObject $preparedRecords[0]) -or
                (Get-SemanticJsonHash -InputObject $intentRecord.Data) -cne (Get-SemanticJsonHash -InputObject $preparedRecords[0].Data)){
                throw 'sealed mutation controller file selector arm, case binding, or prepared intent is invalid'
            }
            $target=$armTargets[0];$missing=[ordered]@{State='MISSING'}
            $targetState=Get-CanonicalObservedPathState -Path ([string]$target.TargetPath) -ExpectedKind file
            $preimageState=Get-CanonicalObservedPathState -Path ([string]$target.PreimagePath) -ExpectedKind file
            $swapState=Get-CanonicalObservedPathState -Path ([string]$target.SwapOldPath) -ExpectedKind file
            $stagedState=Get-CanonicalObservedPathState -Path ([string]$target.StagedPath) -ExpectedKind file
            if([string]$stage.Checkpoint -ceq 'BeforeFileReplaceMove'){
                if(-not(Test-CanonicalObservedMatchesContractState -Actual $targetState -Contract $target.Current) -or
                    -not(Test-CanonicalObservedMatchesContractState -Actual $preimageState -Contract $target.Current) -or [string]$swapState.State -cne 'MISSING' -or
                    -not(Test-CanonicalObservedMatchesContractState -Actual $stagedState -Contract $target.Candidate) -or
                    ([string]$target.Current.State -ceq 'PRESENT' -and ([string]::IsNullOrWhiteSpace([string]$targetState.Identity) -or [string]::IsNullOrWhiteSpace([string]$preimageState.Identity))) -or
                    [string]::IsNullOrWhiteSpace([string]$stagedState.Identity)){
                    throw 'sealed mutation before-file observation did not precede the exact replace or move primitive'
                }
                $observedRecordData=New-CanonicalTargetRecordData -Target $target -TargetState $targetState -PreimageState $preimageState -SwapOldState $missing -StagedState $stagedState
                if((Get-SemanticJsonHash -InputObject $observedRecordData) -cne (Get-SemanticJsonHash -InputObject $intentRecord.Data)){throw 'sealed mutation before-file tuple differs from the durable intent'}
            }else{
                if(-not(Test-CanonicalObservedMatchesContractState -Actual $targetState -Contract $target.Candidate) -or
                    -not(Test-CanonicalObservedMatchesContractState -Actual $preimageState -Contract $target.Current) -or [string]$stagedState.State -cne 'MISSING' -or
                    ([string]$target.Current.State -ceq 'PRESENT' -and (-not(Test-CanonicalObservedMatchesContractState -Actual $swapState -Contract $target.Current) -or
                        [string]::IsNullOrWhiteSpace([string]$preimageState.Identity) -or [string]::IsNullOrWhiteSpace([string]$swapState.Identity))) -or
                    ([string]$target.Current.State -ceq 'MISSING' -and [string]$swapState.State -cne 'MISSING') -or [string]::IsNullOrWhiteSpace([string]$targetState.Identity)){
                    throw 'sealed mutation after-file observation did not follow the exact replace or move primitive'
                }
                $observedRecordData=New-CanonicalTargetRecordData -Target $target -TargetState $targetState -PreimageState $preimageState -SwapOldState $swapState -StagedState $missing
            }
            foreach($heldFileTuple in @(
                [ordered]@{Path=[string]$target.TargetPath;State=$targetState},
                [ordered]@{Path=[string]$target.PreimagePath;State=$preimageState},
                [ordered]@{Path=[string]$target.SwapOldPath;State=$swapState},
                [ordered]@{Path=[string]$target.StagedPath;State=$stagedState}
            )){
                if([string]$heldFileTuple.State.State -cne 'PRESENT'){continue}
                $heldFile=Open-HardKillHeldFileEvidence -Path ([string]$heldFileTuple.Path)
                $null=$fileEvidence.Add($heldFile)
                if([string]$heldFile.Identity -cne [string]$heldFileTuple.State.Identity -or [string]$heldFile.Sha256 -cne [string]$heldFileTuple.State.Hash){
                    throw 'sealed mutation file evidence differs from the independently observed tuple'
                }
            }
        }else{
            $armTargets=@($snapshot.State.Header.Targets|Where-Object{[string]$_.TargetId -ceq [string]$selector.SelectorArm.TargetId -and [long]$_.Order -eq [long]$selector.SelectorArm.TargetOrder})
            if($armTargets.Count -ne 1 -or [string]$stage.ActualBranchDiscriminator -cne 'PRESENT'){throw 'sealed mutation controller preimage selector arm is not one exact present target'}
            $target=$armTargets[0];$preimageWorkspaceRecords=@();$swapOldWorkspaceRecords=@()
            foreach($record in @($snapshot.State.Records)){
                if([string]$record.Phase -cin @('WORKSPACE_CREATE_INTENT','WORKSPACE_CREATED')){
                    if([string]$record.Data.WorkspaceRole -ceq 'preimage'){$preimageWorkspaceRecords=@($preimageWorkspaceRecords)+@($record)}
                    elseif([string]$record.Data.WorkspaceRole -ceq 'swap-old'){$swapOldWorkspaceRecords=@($swapOldWorkspaceRecords)+@($record)}
                }
            }
            if($preimageWorkspaceRecords.Count -ne 2 -or [long]$preimageWorkspaceRecords[0].Sequence -ne 1 -or [string]$preimageWorkspaceRecords[0].Phase -cne 'WORKSPACE_CREATE_INTENT' -or
                [long]$preimageWorkspaceRecords[1].Sequence -ne 2 -or [string]$preimageWorkspaceRecords[1].Phase -cne 'WORKSPACE_CREATED' -or [string]::IsNullOrWhiteSpace([string]$preimageWorkspaceRecords[1].Data.CreatedIdentity) -or
                $swapOldWorkspaceRecords.Count -ne 2 -or [long]$swapOldWorkspaceRecords[0].Sequence -ne 3 -or [string]$swapOldWorkspaceRecords[0].Phase -cne 'WORKSPACE_CREATE_INTENT' -or
                [long]$swapOldWorkspaceRecords[1].Sequence -ne 4 -or [string]$swapOldWorkspaceRecords[1].Phase -cne 'WORKSPACE_CREATED' -or [string]::IsNullOrWhiteSpace([string]$swapOldWorkspaceRecords[1].Data.CreatedIdentity)){
                throw 'sealed mutation controller preimage workspace evidence is incomplete'
            }
            $sourceEvidence=Open-HardKillHeldFileEvidence -Path ([string]$target.TargetPath)
            $sourceState=Get-CanonicalObservedPathState -Path ([string]$target.TargetPath) -ExpectedKind file
            if([string]$sourceEvidence.Identity -cne [string]$sourceState.Identity -or [string]$sourceEvidence.Sha256 -cne [string]$sourceState.Hash -or
                -not(Test-CanonicalObservedMatchesContractState -Actual $sourceState -Contract $target.Current)){throw 'sealed mutation controller preimage source differs from the target tuple'}
            if([string]$stage.Checkpoint -ceq 'PreimageReady'){
                $observedRecordData=[ordered]@{EvidenceKind='RealPreimageReady';Target=$target;PreimageWorkspaceIntent=$preimageWorkspaceRecords[0];PreimageWorkspaceCreated=$preimageWorkspaceRecords[1];SwapOldWorkspaceIntent=$swapOldWorkspaceRecords[0];SwapOldWorkspaceCreated=$swapOldWorkspaceRecords[1];SourceState=$sourceState}
            }elseif([string]$stage.Checkpoint -ceq 'RetainedPartialPreimage'){
                $partialEvidence=Open-HardKillHeldFileEvidence -Path ([string]$target.PreimagePath)
                $preimageState=Get-CanonicalObservedPathState -Path ([string]$target.PreimagePath) -ExpectedKind file
                $swapState=Get-CanonicalObservedPathState -Path ([string]$target.SwapOldPath)
                $stagedState=Get-CanonicalObservedPathState -Path ([string]$target.StagedPath) -ExpectedKind file
                $expectedIntentData=New-CanonicalTargetRecordData -Target $target -TargetState $sourceState -PreimageState ([ordered]@{State='MISSING'}) -SwapOldState ([ordered]@{State='MISSING'}) -StagedState $stagedState
                $strictPrefix=$partialEvidence.Length -gt 0 -and $partialEvidence.Length -eq ($sourceEvidence.Length-1)
                if($strictPrefix){for($byteIndex=0;$byteIndex -lt $partialEvidence.Bytes.Length;$byteIndex++){if($partialEvidence.Bytes[$byteIndex] -ne $sourceEvidence.Bytes[$byteIndex]){$strictPrefix=$false;break}}}
                if(-not $strictPrefix -or [string]$partialEvidence.Identity -cne [string]$preimageState.Identity -or [string]$partialEvidence.Sha256 -cne [string]$preimageState.Hash -or
                    [string]$partialEvidence.ParentHandles[-1].Info.Identity -cne [string]$preimageWorkspaceRecords[1].Data.CreatedIdentity -or
                    (Get-SemanticJsonHash -InputObject $intentRecord.Data) -cne (Get-SemanticJsonHash -InputObject $expectedIntentData) -or
                    [string]$swapState.State -cne 'MISSING' -or -not(Test-CanonicalObservedMatchesContractState -Actual $stagedState -Contract $target.Candidate)){throw 'sealed mutation controller retained partial tuple is invalid'}
                $observedRecordData=[ordered]@{EvidenceKind='SyntheticDirectRetainedPartialPreimage';Target=$target;PreimagePath=[IO.Path]::GetFullPath([string]$target.PreimagePath);PreimageWorkspaceIntent=$preimageWorkspaceRecords[0];PreimageWorkspaceCreated=$preimageWorkspaceRecords[1];SwapOldWorkspaceIntent=$swapOldWorkspaceRecords[0];SwapOldWorkspaceCreated=$swapOldWorkspaceRecords[1];PartialIdentity=[string]$partialEvidence.Identity;PartialLength=[long]$partialEvidence.Length;PartialRawSha256=[string]$partialEvidence.Sha256;SourceIdentity=[string]$sourceEvidence.Identity;SourceLength=[long]$sourceEvidence.Length;SourceRawSha256=[string]$sourceEvidence.Sha256}
            }else{throw 'sealed mutation controller received an unsupported preimage checkpoint'}
        }
        $evidenceTupleHash=Get-SemanticJsonHash -InputObject ([ordered]@{
            TransactionNamespace=[string]$selector.TransactionNamespace;Checkpoint=[string]$stage.Checkpoint;DeclaredVariant=[string]$stage.DeclaredPrimitiveVariant
            ActualBranchDiscriminator=[string]$stage.ActualBranchDiscriminator;SelectorArm=$stage.SelectorArm;ObservedRecordData=$observedRecordData
            IntentSequence=[long]$selector.ExpectedIntentSequence;IntentSemanticHash=(Get-SemanticJsonHash -InputObject $intentRecord)
            TailSequence=[long]$selector.ExpectedTailSequence;TailSemanticHash=(Get-SemanticJsonHash -InputObject $tailRecord);DerivedJournalHeadHash=[string]$snapshot.State.DerivedJournalHeadHash
        })
        if([string]$stage.EvidenceTupleHash -cne $evidenceTupleHash){throw 'sealed mutation controller stage evidence tuple differs from independent workspace reconstruction'}
        if([string]$stage.IntentPhase -cne [string]$intentRecord.Phase -or [long]$stage.IntentSequence -ne [long]$intentRecord.Sequence -or
            [string]$stage.IntentSemanticHash -cne (Get-SemanticJsonHash -InputObject $intentRecord) -or [string]$stage.IntentArtifactIdentity -cne [string]$intentLease.Info.Identity -or
            [long]$stage.IntentArtifactLength -ne [long]$intentLease.ReadResult.Length -or [string]$stage.IntentArtifactRawSha256 -cne [string]$intentLease.ReadResult.Sha256 -or
            [string]$stage.TailPhase -cne [string]$tailRecord.Phase -or [long]$stage.TailSequence -ne [long]$tailRecord.Sequence -or
            [string]$stage.TailSemanticHash -cne (Get-SemanticJsonHash -InputObject $tailRecord) -or [string]$stage.TailArtifactIdentity -cne [string]$tailLease.Info.Identity -or
            [long]$stage.TailArtifactLength -ne [long]$tailLease.ReadResult.Length -or [string]$stage.TailArtifactRawSha256 -cne [string]$tailLease.ReadResult.Sha256){throw 'sealed mutation controller stage record evidence differs from independent held journal captures'}
        Close-CanonicalJournalSnapshot -Snapshot $snapshot;$snapshot=$null
        return [pscustomobject]@{Stage=$stage;IntentLease=$intentLease;TailLease=$tailLease;SourceEvidence=$sourceEvidence;PartialEvidence=$partialEvidence;FileEvidence=@($fileEvidence);SharedLease=$shared;Closed=$false}
    }catch{
        if($snapshot){try{Close-CanonicalJournalSnapshot -Snapshot $snapshot}catch{}}
        foreach($heldFileEvidence in @($fileEvidence)){try{Close-HardKillHeldFileEvidence -Evidence $heldFileEvidence}catch{}}
        if($partialEvidence){try{Close-HardKillHeldFileEvidence -Evidence $partialEvidence}catch{}}
        if($sourceEvidence){try{Close-HardKillHeldFileEvidence -Evidence $sourceEvidence}catch{}}
        if($tailLease -and -not $shared){try{$tailLease.Dispose()}catch{}}
        if($intentLease){try{$intentLease.Dispose()}catch{}}
        throw
    }
}
function Close-HardKillSealedMutationJournalObservation {
    param($Observation)
    if($null -eq $Observation -or $Observation.Closed){return}
    $failures=[Collections.Generic.List[Exception]]::new()
    foreach($heldFileEvidence in @($Observation.FileEvidence)){try{Close-HardKillHeldFileEvidence -Evidence $heldFileEvidence}catch{$null=$failures.Add($_.Exception)}}
    if($Observation.PartialEvidence){try{Close-HardKillHeldFileEvidence -Evidence $Observation.PartialEvidence}catch{$null=$failures.Add($_.Exception)}}
    if($Observation.SourceEvidence){try{Close-HardKillHeldFileEvidence -Evidence $Observation.SourceEvidence}catch{$null=$failures.Add($_.Exception)}}
    if($Observation.TailLease -and -not $Observation.SharedLease){try{$Observation.TailLease.Dispose()}catch{$null=$failures.Add($_.Exception)}}
    if($Observation.IntentLease){try{$Observation.IntentLease.Dispose()}catch{$null=$failures.Add($_.Exception)}}
    $Observation.Closed=$true
    if($failures.Count -eq 1){throw $failures[0]};if($failures.Count -gt 1){throw [AggregateException]::new('sealed mutation journal observation cleanup',[Exception[]]$failures.ToArray())}
}
function Write-HardKillSealedMutationPostState {
    param($CaseDefinition,[AiAgentDotfilesTests.HardKillJobReapReceipt]$Receipt)
    $state=Read-CanonicalJournalDirectory -TransactionNamespace ([string]$CaseDefinition.Selector.TransactionNamespace) -AllowUnfinished
    $classification=Get-CanonicalTransactionRecoveryClassification -State $state -RepoRoot ([string]$CaseDefinition.RepoRoot)
    $document=[ordered]@{
        SchemaVersion=[long]1;ArtifactKind='sealed-mutation-controller-post-state';Checkpoint=[string]$CaseDefinition.Selector.Checkpoint
        TransactionId=[string]$CaseDefinition.Selector.TransactionId;TransactionNamespace=[string]$CaseDefinition.Selector.TransactionNamespace
        DerivedJournalHeadHash=[string]$state.DerivedJournalHeadHash;PendingCount=[long]@($state.PendingEntries).Count
        ClassificationStatus=[string]$classification.Status;AllowedAction=[string]$classification.AllowedAction;ClassificationExpectedOutcome=[string]$classification.ExpectedOutcome
        Pid=$Receipt.Pid.ToString([Globalization.CultureInfo]::InvariantCulture);RootCreationFileTimeTicks=$Receipt.RootCreationFileTimeTicks.ToString([Globalization.CultureInfo]::InvariantCulture)
        JobZeroQpcTicks=$Receipt.JobZeroQpcTicks.ToString([Globalization.CultureInfo]::InvariantCulture);ActiveAfter=[long]$Receipt.ActiveAfter;JobHandleClosed=[bool]$Receipt.JobHandleClosed;IdentityGone=[bool]$Receipt.IdentityGone
    }
    $bytes=ConvertTo-SemanticJsonBytes -InputObject $document
    $stream=[IO.File]::Open([string]$CaseDefinition.PostStatePath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
    try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}
}
function Invoke-HardKillSealedMutationControllerCase {
    param($HostPath,$EnginePath,$Case)
    [AiAgentDotfilesTests.HardKillSealedMutationControllerScope]$controllerScope=$null
    [AiAgentDotfilesTests.HardKillSealedMutationHostSession]$session=$null
    [AiAgentDotfilesTests.HardKillJobReapReceipt]$reapReceipt=$null
    $observation=$null;$journalObservation=$null;$postState=$null;$postStateDocument=$null;$observedJournalHeadHash='';$caseDefinition=$null;$reapMode='';$primary=$null
    $cleanupErrors=[Collections.Generic.List[Exception]]::new()
    try{
        $controllerScope=[AiAgentDotfilesTests.HardKillSealedMutationControllerScope]::Create($Case)
        $caseDefinition=$controllerScope.CaseDefinition
        $reapMode=[string]$controllerScope.ReapMode
        $caseHostArguments=@($caseDefinition.HostArguments)
        if($caseHostArguments.Count -ne 12 -or [string]$caseHostArguments[0] -cne '-ToolchainRoot' -or
            [string]$caseHostArguments[2] -cne '-FixtureRoot' -or [string]$caseHostArguments[4] -cne '-TransactionId' -or
            [string]$caseHostArguments[6] -cne '-Kind' -or [string]$caseHostArguments[8] -cne '-Checkpoint' -or
            [string]$caseHostArguments[10] -cne '-MarkerPath' -or [string]$caseHostArguments[5] -cne [string]$caseDefinition.Selector.TransactionId -or
            [string]$caseHostArguments[7] -cne [string]$caseDefinition.Kind -or [string]$caseHostArguments[9] -cne [string]$caseDefinition.Checkpoint){
            throw 'sealed mutation host wire arguments differ from the exact case definition'
        }
        $sealedHostPath=[IO.Path]::GetFullPath($HostPath);$sealedEnginePath=[IO.Path]::GetFullPath($EnginePath)
        $sealedHostDirectory=[IO.Path]::GetDirectoryName($sealedHostPath);$sealedEngineDirectory=[IO.Path]::GetDirectoryName($sealedEnginePath)
        $sealedHostTestsDirectory=[IO.Path]::GetDirectoryName($sealedHostDirectory);$sealedEngineTestsDirectory=[IO.Path]::GetDirectoryName($sealedEngineDirectory)
        $expectedHostArgumentToolchainRoot=[IO.Path]::GetFullPath([IO.Path]::Combine($sealedHostDirectory,'..','..'))
        $expectedEngineToolchainRoot=[IO.Path]::GetFullPath([IO.Path]::Combine($sealedEngineDirectory,'..','..'))
        $expectedHostArgumentFixtureRoot=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath([string]$controllerScope.InvocationFixturePath))
        $expectedHostArgumentMarkerPath=[IO.Path]::GetFullPath([IO.Path]::Combine($expectedHostArgumentFixtureRoot,'checkpoint.marker'))
        if([IO.Path]::GetFileName($sealedHostDirectory) -cne 'helpers' -or [IO.Path]::GetFileName($sealedEngineDirectory) -cne 'helpers' -or
            [IO.Path]::GetFileName($sealedHostTestsDirectory) -cne 'tests' -or [IO.Path]::GetFileName($sealedEngineTestsDirectory) -cne 'tests' -or
            $expectedHostArgumentToolchainRoot -cne $expectedEngineToolchainRoot -or [IO.Path]::GetFileName($sealedHostPath) -cne 'canonical-hard-kill-host.ps1' -or
            [IO.Path]::GetFileName($sealedEnginePath) -cne 'canonical-reviewed-mutation-engine.ps1' -or
            [IO.Path]::GetFullPath([string]$caseHostArguments[1]) -cne $expectedHostArgumentToolchainRoot -or
            [IO.Path]::GetFullPath([string]$caseHostArguments[3]) -cne $expectedHostArgumentFixtureRoot -or
            [IO.Path]::GetFullPath([string]$caseHostArguments[11]) -cne $expectedHostArgumentMarkerPath){
            throw 'sealed mutation host wire path arguments differ from the held host, engine, fixture, or marker roots'
        }
        if([string]$caseDefinition.Kind -ceq 'directory-delete'){
            $expectedDirectoryDeletionSelectorCheckpoint=switch -CaseSensitive ([string]$caseDefinition.Checkpoint){
                'before-directory-new-installed-record'{'BeforeDirectoryDeletionRecord';break}
                'after-directory-new-installed-record'{'AfterDirectoryDeletionRecord';break}
                default{throw 'sealed mutation directory-delete host wire checkpoint is invalid'}
            }
            $expectedDirectoryDeletionCaseName=if([string]$caseDefinition.Checkpoint -ceq 'before-directory-new-installed-record'){'directory-delete-before-installed-record'}else{'directory-delete-after-installed-record'}
            if([string]$caseDefinition.Selector.Checkpoint -cne $expectedDirectoryDeletionSelectorCheckpoint -or
                [string]$caseDefinition.Name -cne $expectedDirectoryDeletionCaseName){throw 'sealed mutation directory-delete host wire, typed checkpoint, or case name differs'}
        }
        if([string]$caseDefinition.Selector.Checkpoint -cin @('BeforeFileReplaceMove','AfterFileReplaceMove')){
            $expectedFileWireBinding=switch -CaseSensitive ([string]$caseDefinition.Name){
                'before-file-replace'{[ordered]@{Kind='file';RawCheckpoint='before-file-replace';Checkpoint='BeforeFileReplaceMove';Variant='FileReplacePresent'};break}
                'after-file-replace'{[ordered]@{Kind='file';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileReplacePresent'};break}
                'before-file-add-move'{[ordered]@{Kind='file-add';RawCheckpoint='before-file-replace';Checkpoint='BeforeFileReplaceMove';Variant='FileMoveMissing'};break}
                'after-file-add-move'{[ordered]@{Kind='file-add';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileMoveMissing'};break}
                'rollback-file-before-replace'{[ordered]@{Kind='file';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileReplacePresent'};break}
                'rollback-file-after-replace'{[ordered]@{Kind='file';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileReplacePresent'};break}
                'rollback-file-add-before-new-to-staged'{[ordered]@{Kind='file-add';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileMoveMissing'};break}
                'rollback-file-add-after-new-to-staged'{[ordered]@{Kind='file-add';RawCheckpoint='after-file-replace';Checkpoint='AfterFileReplaceMove';Variant='FileMoveMissing'};break}
                default{throw 'sealed mutation file host wire case name is invalid'}
            }
            if([string]$caseDefinition.Kind -cne [string]$expectedFileWireBinding.Kind -or [string]$caseDefinition.Checkpoint -cne [string]$expectedFileWireBinding.RawCheckpoint -or
                [string]$caseDefinition.Selector.Checkpoint -cne [string]$expectedFileWireBinding.Checkpoint -or [string]$caseDefinition.DeclaredVariant -cne [string]$expectedFileWireBinding.Variant){
                throw 'sealed mutation file host wire, typed checkpoint, variant, or case name differs'
            }
        }
        $failureCleanupAbsoluteCapQpcTicks=[long]$controllerScope.FailureCleanupAbsoluteCapQpcTicks
        $session=[AiAgentDotfilesTests.HardKillSealedMutationHostSession]::Acquire($HostPath,$EnginePath,$controllerScope)
        if($session.IsResumed){throw 'sealed mutation session was resumed before the controller acquired ownership'}
        if(-not[object]::ReferenceEquals($controllerScope.Deadlines,$session.Deadlines) -or $session.ReapMode -cne $reapMode -or
            [long]$session.FailureCleanupAbsoluteCapQpcTicks -ne $failureCleanupAbsoluteCapQpcTicks){throw 'sealed mutation session identity, mode, deadlines, or failure cap drifted during acquisition'}
        $expectedFailureCapQpcTicks=if($reapMode -ceq 'hard-kill'){$session.Deadlines.HardKillCumulativeReapDeadlineQpc}elseif($reapMode -ceq 'natural-release'){$session.Deadlines.NaturalReleaseCumulativeReapDeadlineQpc}else{throw 'sealed mutation controller scope returned an invalid reap mode'}
        if($failureCleanupAbsoluteCapQpcTicks -ne $expectedFailureCapQpcTicks){throw 'sealed mutation failure cap does not match the prelaunch case mode'}
        $session.Resume()
        if(-not $session.IsResumed){throw 'sealed mutation session did not enter the exact resumed state'}
        $observation=$controllerScope.Observe($session)
        $journalObservation=Open-HardKillSealedMutationJournalObservation -CaseDefinition $caseDefinition -StageObservation $observation -Session $session
        $observedJournalHeadHash=[string]$journalObservation.Stage.DerivedJournalHeadHash
        if($reapMode -ceq 'hard-kill'){
            $reapReceipt=[AiAgentDotfilesTests.HardKillLiveTerminationReceipt]$session.JobProcess.TerminateLiveAndConfirm([long]$session.ProcessId,[long]$session.RootCreationFileTimeTicks,$session.Deadlines)
        }elseif($reapMode -ceq 'natural-release'){
            Close-HardKillSealedMutationJournalObservation -Observation $journalObservation;$journalObservation=$null
            $released=$controllerScope.ReleaseForNaturalExit($session,$observation)
            if($released -isnot [bool] -or -not $released){throw 'sealed mutation natural-release signal receipt is invalid'}
            $reapReceipt=[AiAgentDotfilesTests.HardKillNaturalExitReceipt]$session.JobProcess.ConfirmNaturalExitAndClose([long]$session.ProcessId,[long]$session.RootCreationFileTimeTicks,$session.Deadlines)
        }else{throw 'sealed mutation controller scope returned an invalid reap mode'}
        $accepted=$session.AcceptReapReceipt($reapReceipt)
        if(-not[object]::ReferenceEquals($accepted,$reapReceipt)){throw 'sealed mutation session did not accept the exact nominal receipt'}
        if($journalObservation){Close-HardKillSealedMutationJournalObservation -Observation $journalObservation;$journalObservation=$null}
        Write-HardKillSealedMutationPostState -CaseDefinition $caseDefinition -Receipt $reapReceipt
        $postState=$controllerScope.ReadPostState($session,$observation,$reapReceipt)
        $postStateBytes=[byte[]]$postState['Bytes']
        $postStateText=[Text.UTF8Encoding]::new($false,$true).GetString($postStateBytes)
        $postStateDocument=ConvertFrom-SemanticJson -Json $postStateText
        $postStateKeys=@('SchemaVersion','ArtifactKind','Checkpoint','TransactionId','TransactionNamespace','DerivedJournalHeadHash','PendingCount','ClassificationStatus','AllowedAction','ClassificationExpectedOutcome','Pid','RootCreationFileTimeTicks','JobZeroQpcTicks','ActiveAfter','JobHandleClosed','IdentityGone')
        $canonicalPostStateBytes=ConvertTo-SemanticJsonBytes -InputObject $postStateDocument
        $postJournalState=Read-CanonicalJournalDirectory -TransactionNamespace ([string]$caseDefinition.Selector.TransactionNamespace) -AllowUnfinished
        $postClassification=Get-CanonicalTransactionRecoveryClassification -State $postJournalState -RepoRoot ([string]$caseDefinition.RepoRoot)
        $postRecords=@($postJournalState.Records);$postRecordHashes=@($postRecords|ForEach-Object{Get-SemanticJsonHash -InputObject $_})
