            },$true)|Where-Object{
                [object]::ReferenceEquals((Get-NearestHardKillFunction $_),$commandFunction) -and
                [object]::ReferenceEquals((Get-NearestTransportScriptBlock $_),$commandBlock) -and
                (Get-TransportCapabilityKey ([string]$_.VariablePath.UserPath) $capabilityFrame) -ceq $splatKey
            })
            if($interveningReferences.Count -ne 0){return New-StaticSplatResult $false $null}
            $interveningCommands=@($ast.FindAll({param($node)
