                $value=Get-TransportStaticHashtableValue $value.Child
            }
            if($value -isnot [Management.Automation.Language.HashtableAst]){return New-StaticSplatResult $false $null}
            return New-StaticSplatResult $true $value
        }
        function Get-TransportStaticHashtableValue([Management.Automation.Language.Ast]$Value){
            $current=$Value
            while($null -ne $current){
                if($current -is [Management.Automation.Language.PipelineAst]){
                    $elements=@($current.PipelineElements)
                    if($elements.Count -ne 1){return $null}
                    $current=$elements[0]
