                }
                if($current -is [Management.Automation.Language.CommandExpressionAst]){
                    $current=$current.Expression
                    continue
                }
                if($current -is [Management.Automation.Language.ParenExpressionAst]){
                    $elements=@($current.Pipeline.PipelineElements)
                    if($elements.Count -ne 1){return $null}
                    $current=$elements[0]
                    continue
                }
                break
            }
            return $current
        }
        function Get-TransportStaticStringConstant([Management.Automation.Language.Ast]$Value){
            $current=Get-TransportStaticHashtableValue $Value
