        function Get-TransportOutputVariableBindings([Management.Automation.Language.CommandAst]$Command){
            $rows=[Collections.Generic.List[object]]::new()
            $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $directKinds=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $leaf=Get-TransportCommandLeaf $Command
            $bindingCandidates=[Collections.Generic.List[object]]::new()
            foreach($parameter in @($Command.CommandElements|Where-Object{$_ -is [Management.Automation.Language.CommandParameterAst]})){
                $candidate=[string]$parameter.ParameterName;$kind=Get-TransportOutputBindingKind $candidate $leaf;$target=Get-TransportCommandParameterArgument $Command $parameter
                if([string]::IsNullOrEmpty($kind)){continue}
                if(-not $directKinds.Add($kind)){return [pscustomobject]@{Present=$true;Valid=$false;Rows=@()}}
                $bindingCandidates.Add([pscustomobject]@{Kind=$kind;Target=$target})
            }
            foreach($splat in @($Command.CommandElements|Where-Object{$_ -is [Management.Automation.Language.VariableExpressionAst] -and $_.Splatted})){
                $splatResolution=Get-TransportStaticSplatHashtable $Command $splat
                if(-not $splatResolution.Valid){return [pscustomobject]@{Present=$true;Valid=$false;Rows=@()}}
                $hashtable=$splatResolution.Hashtable
                foreach($pair in @($hashtable.KeyValuePairs)){
                    if($pair.Item1 -isnot [Management.Automation.Language.StringConstantExpressionAst]){return [pscustomobject]@{Present=$true;Valid=$false;Rows=@()}}
                    $candidate=[string]$pair.Item1.Value;$kind=Get-TransportOutputBindingKind $candidate $leaf
                    if(-not[string]::IsNullOrEmpty($kind)){
                        if($directKinds.Contains($kind)){continue}
                        $bindingCandidates.Add([pscustomobject]@{Kind=$kind;Target=(Get-TransportStaticStringConstant $pair.Item2)})
                    }
                }
            }
            foreach($bindingCandidate in @($bindingCandidates)){
                $kind=[string]$bindingCandidate.Kind;$target=$bindingCandidate.Target
                if(-not $seen.Add($kind)){return [pscustomobject]@{Present=$true;Valid=$false;Rows=@()}}
                if($target -isnot [Management.Automation.Language.StringConstantExpressionAst]){return [pscustomobject]@{Present=$true;Valid=$false;Rows=@()}}
                $rawTarget=[string]$target.Value;$append=$kind -ceq 'OutVariable' -and $rawTarget.StartsWith('+',[StringComparison]::Ordinal)
                $targetName=if($append){$rawTarget.Substring(1)}else{$rawTarget}
                if([string]::IsNullOrEmpty($targetName)){return [pscustomobject]@{Present=$true;Valid=$false;Rows=@()}}
                $rows.Add([pscustomobject]@{Target=$targetName;Append=$append;Kind=$kind;Mode=$(if($kind -ceq 'TeeVariable'){'PipelineInput'}else{'CommandOutput'})})
            }
            return [pscustomobject]@{Present=$rows.Count -ne 0;Valid=$true;Rows=@($rows)}
        }
