            $aliases=@{
                'db'='Debug';'ea'='ErrorAction';'ev'='ErrorVariable';'infa'='InformationAction';'iv'='InformationVariable';
                'ob'='OutBuffer';'ov'='OutVariable';'pv'='PipelineVariable';'proga'='ProgressAction';'vb'='Verbose';
                'wa'='WarningAction';'wv'='WarningVariable'
            }
            if($aliases.ContainsKey($Candidate)){return [string]$aliases[$Candidate]}
            $known=@('Debug','ErrorAction','ErrorVariable','InformationAction','InformationVariable','OutBuffer','OutVariable','PipelineVariable','ProgressAction','Verbose','WarningAction','WarningVariable','WhatIf','Confirm')
            $matches=@($known|Where-Object{$_.StartsWith($Candidate,[StringComparison]::OrdinalIgnoreCase)})
            return $(if($matches.Count -eq 1){[string]$matches[0]}else{''})
        }
        function Get-TransportStaticCallbackArguments([Management.Automation.Language.Ast]$Value){
            $current=Get-TransportStaticHashtableValue $Value
            if($current -is [Management.Automation.Language.ArrayLiteralAst]){
                $rows=[Collections.Generic.List[object]]::new()
                foreach($element in @($current.Elements)){
                    $nested=Get-TransportStaticCallbackArguments $element
                    if(-not $nested.Valid){return [pscustomobject]@{Valid=$false;Arguments=@()}}
                    foreach($argument in @($nested.Arguments)){$rows.Add($argument)}
                }
                return [pscustomobject]@{Valid=$rows.Count -ne 0;Arguments=@($rows)}
            }
            if($null -eq $current){return [pscustomobject]@{Valid=$false;Arguments=@()}}
            return [pscustomobject]@{Valid=$true;Arguments=@($current)}
        }
        function Get-TransportForEachCommandModel([Management.Automation.Language.CommandAst]$Command){
            if((Get-TransportCommandLeaf $Command) -notin @('foreach-object','%')){
                return [pscustomobject]@{Present=$false;Valid=$false;Callbacks=@();InputObjects=@()}
            }
            $callbacks=[Collections.Generic.List[object]]::new()
            $sequence=[Collections.Generic.List[object]]::new()
            $inputObjects=[Collections.Generic.List[object]]::new()
            $consumedOffsets=[Collections.Generic.HashSet[int]]::new()
            $seenSingletonRoles=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $seenDirectSequenceRoles=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $seenDirectRoles=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $seenSplatRoles=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $modelState=[pscustomobject]@{BeginBound=$false;EndBound=$false;ParallelBound=$false;FixedBegin=$null;FixedEnd=$null;FixedParallel=$null;DirectSequenceCount=0;SplatSequenceCount=0}
            function Test-ForEachStaticNull([Management.Automation.Language.Ast]$Value){
                $candidate=Get-TransportStaticHashtableValue $Value
                return ($candidate -is [Management.Automation.Language.VariableExpressionAst] -and
                    [string]$candidate.VariablePath.UserPath -ieq 'null') -or
                    ($candidate -is [Management.Automation.Language.ConstantExpressionAst] -and $null -eq $candidate.Value)
            }
            function Test-ForEachStaticFalse([Management.Automation.Language.Ast]$Value){
                $candidate=Get-TransportStaticHashtableValue $Value
                return ($candidate -is [Management.Automation.Language.VariableExpressionAst] -and
                    [string]$candidate.VariablePath.UserPath -ieq 'false') -or
                    ($candidate -is [Management.Automation.Language.ConstantExpressionAst] -and $candidate.Value -is [bool] -and -not[bool]$candidate.Value)
            }
            function Add-ForEachRole([string]$Role,[Management.Automation.Language.Ast]$Value,[int]$Offset,[bool]$FromSplat){
                if($Role -ceq 'InputObject'){
                    if(-not $seenSingletonRoles.Add($Role)){return $false}
                    $inputObjects.Add((Get-TransportStaticHashtableValue $Value))
                    return $null -ne $inputObjects[-1]
                }
                if($Role -in @('Begin','End','Parallel')){
                    if(-not $seenSingletonRoles.Add($Role)){return $false}
                    $isNull=Test-ForEachStaticNull $Value
                    if($Role -ceq 'Parallel' -and $isNull){return $false}
                    if($isNull){$argument=$null}
                    else{
                        $expanded=Get-TransportStaticCallbackArguments $Value
                        if(-not $expanded.Valid -or $expanded.Arguments.Count -ne 1){return $false}
                        $argument=$expanded.Arguments[0]
                    }
                    if($Role -ceq 'Begin'){$modelState.BeginBound=$true;$modelState.FixedBegin=$argument}
                    elseif($Role -ceq 'End'){$modelState.EndBound=$true;$modelState.FixedEnd=$argument}
                    else{$modelState.ParallelBound=$true;$modelState.FixedParallel=$argument}
                    return $true
                }
                if($Role -notin @('Process','RemainingScripts')){return $false}
                if(-not $FromSplat -and -not $seenDirectSequenceRoles.Add($Role)){return $false}
                $expanded=Get-TransportStaticCallbackArguments $Value
                if(-not $expanded.Valid){return $false}
                if(-not $FromSplat){$modelState.DirectSequenceCount++}
                foreach($argument in @($expanded.Arguments)){
                    $sequence.Add([pscustomobject]@{Argument=$argument})
                }
                return $true
            }
            foreach($parameter in @($Command.CommandElements|Where-Object{$_ -is [Management.Automation.Language.CommandParameterAst]})){
                $candidate=[string]$parameter.ParameterName
                $bindingKind=Get-TransportOutputBindingKind $candidate (Get-TransportCommandLeaf $Command)
                $role=if(-not[string]::IsNullOrEmpty($bindingKind)){$bindingKind}else{Get-TransportForEachParameterRole $candidate}
                if([string]::IsNullOrEmpty($role)){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                if(-not $seenDirectRoles.Add($role)){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                if($role -in @('WhatIf','Confirm')){
                    if($null -eq $parameter.Argument -or -not(Test-ForEachStaticFalse $parameter.Argument)){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                    continue
                }
                $isBareSwitch=$role -in @('Debug','Verbose','UseNewRunspace','AsJob') -and $null -eq $parameter.Argument
                $argument=if($isBareSwitch){$null}else{Get-TransportCommandParameterArgument $Command $parameter}
                if($null -ne $argument){$null=$consumedOffsets.Add([int]$argument.Extent.StartOffset)}
                if($role -in @('InputObject','Begin','Process','End','RemainingScripts','Parallel')){
                    if($null -eq $argument -or -not(Add-ForEachRole $role $argument ([int]$parameter.Extent.StartOffset) $false)){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                }elseif($role -in @('MemberName','UseNewRunspace','ThrottleLimit','TimeoutSeconds','AsJob')){
                    return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}
                }elseif($role -notin @('Debug','Verbose') -and $null -eq $argument){
                    return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}
                }
            }
            foreach($splat in @($Command.CommandElements|Where-Object{$_ -is [Management.Automation.Language.VariableExpressionAst] -and $_.Splatted})){
                $splatResolution=Get-TransportStaticSplatHashtable $Command $splat
                if(-not $splatResolution.Valid){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                $splatHasSequence=$false
                foreach($pair in @($splatResolution.Hashtable.KeyValuePairs)){
                    if($pair.Item1 -isnot [Management.Automation.Language.StringConstantExpressionAst]){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                    $candidate=[string]$pair.Item1.Value
                    $bindingKind=Get-TransportOutputBindingKind $candidate (Get-TransportCommandLeaf $Command)
                    $role=if(-not[string]::IsNullOrEmpty($bindingKind)){$bindingKind}else{Get-TransportForEachParameterRole $candidate}
                    if([string]::IsNullOrEmpty($role)){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                    if($seenDirectRoles.Contains($role)){continue}
                    if(-not $seenSplatRoles.Add($role)){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                    if($role -in @('WhatIf','Confirm')){
                        if(-not(Test-ForEachStaticFalse $pair.Item2)){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                        continue
                    }
                    if($role -in @('InputObject','Begin','Process','End','RemainingScripts','Parallel')){
                        if(-not(Add-ForEachRole $role $pair.Item2 ([int]$splat.Extent.StartOffset) $true)){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                        if($role -in @('Process','RemainingScripts')){$splatHasSequence=$true}
                    }elseif($role -in @('MemberName','UseNewRunspace','ThrottleLimit','TimeoutSeconds','AsJob')){
                        return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}
                    }
                }
                if($splatHasSequence){$modelState.SplatSequenceCount++}
            }
            $positional=[Collections.Generic.List[object]]::new()
            for($elementIndex=1;$elementIndex -lt $Command.CommandElements.Count;$elementIndex++){
                $element=$Command.CommandElements[$elementIndex]
                if($element -is [Management.Automation.Language.CommandParameterAst] -or
                    ($element -is [Management.Automation.Language.VariableExpressionAst] -and $element.Splatted) -or
                    $consumedOffsets.Contains([int]$element.Extent.StartOffset)){continue}
                $positional.Add($element)
            }
            foreach($positionalElement in @($positional)){
                $sequence.Add([pscustomobject]@{Argument=$positionalElement})
            }
            if($modelState.SplatSequenceCount -gt 1){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
            if($modelState.ParallelBound){
                if($modelState.BeginBound -or $modelState.EndBound -or $sequence.Count -ne 0){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                $callbacks.Add([pscustomobject]@{Role='Parallel';Argument=$modelState.FixedParallel})
            }else{
                if($sequence.Count -eq 0){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                $slots=[Collections.Generic.List[object]]::new()
                if($modelState.BeginBound){$slots.Add($modelState.FixedBegin)}
                foreach($sequenceRow in @($sequence)){$slots.Add($sequenceRow.Argument)}
                $processStart=if($slots.Count -gt 1){1}else{0}
                $processEndExclusive=$slots.Count
                $actualBegin=if($slots.Count -gt 1){$slots[0]}else{$null}
                $actualEnd=if($modelState.EndBound){$modelState.FixedEnd}else{$null}
                if(-not $modelState.EndBound -and $slots.Count -gt 2){$processEndExclusive--;$actualEnd=$slots[$slots.Count-1]}
                if($null -ne $actualBegin){$callbacks.Add([pscustomobject]@{Role='Begin';Argument=$actualBegin})}
                for($sequenceIndex=$processStart;$sequenceIndex -lt $processEndExclusive;$sequenceIndex++){
                    if($null -eq $slots[$sequenceIndex]){return [pscustomobject]@{Present=$true;Valid=$false;Callbacks=@();InputObjects=@()}}
                    $callbacks.Add([pscustomobject]@{Role='Process';Argument=$slots[$sequenceIndex]})
                }
                if($null -ne $actualEnd){$callbacks.Add([pscustomobject]@{Role='End';Argument=$actualEnd})}
            }
            return [pscustomobject]@{Present=$true;Valid=$callbacks.Count -ne 0;Callbacks=@($callbacks);InputObjects=@($inputObjects)}
        }
        function Get-TransportPipelineInputParameterNames([Management.Automation.Language.FunctionDefinitionAst]$Definition){
            $names=[Collections.Generic.List[string]]::new()
            if($Definition.IsFilter){foreach($automaticName in @('_','PSItem','input')){$names.Add($automaticName)}}
            if($null -eq $Definition.Body.ParamBlock){return [pscustomobject]@{Valid=$true;Names=@($names)}}
            foreach($parameter in @($Definition.Body.ParamBlock.Parameters)){
                $acceptsPipeline=$false
                foreach($attribute in @($parameter.Attributes|Where-Object{
                    [string]$_.TypeName.FullName -iin @('Parameter','ParameterAttribute','System.Management.Automation.ParameterAttribute')
                })){
                    foreach($namedArgument in @($attribute.NamedArguments|Where-Object{
                        [string]$_.ArgumentName -iin @('ValueFromPipeline','ValueFromPipelineByPropertyName')
                    })){
                        if($namedArgument.ExpressionOmitted){$acceptsPipeline=$true;continue}
                        $argumentValue=Get-TransportStaticHashtableValue $namedArgument.Argument
                        if($argumentValue -is [Management.Automation.Language.ConstantExpressionAst] -and $argumentValue.Value -is [bool]){
                            if([bool]$argumentValue.Value){$acceptsPipeline=$true};continue
                        }
                        if($argumentValue -is [Management.Automation.Language.VariableExpressionAst] -and
                            [string]$argumentValue.VariablePath.UserPath -iin @('true','false')){
                            if([string]$argumentValue.VariablePath.UserPath -ieq 'true'){$acceptsPipeline=$true};continue
                        }
                        return [pscustomobject]@{Valid=$false;Names=@()}
                    }
                }
                if($acceptsPipeline){$names.Add((([string]$parameter.Name.VariablePath.UserPath -split ':')[-1]))}
            }
            return [pscustomobject]@{Valid=$true;Names=@($names)}
        }
        function Test-TransportPipelineVariableBindingConflict(
            [Management.Automation.Language.CommandAst]$Command,
            [string]$Target,
            [ValidateSet('Top','Local')][string]$CapabilityFrame){
            $pipeline=$Command.Parent
            if($pipeline -isnot [Management.Automation.Language.PipelineAst]){return $true}
            $targetKey=Get-TransportCapabilityKey $Target $CapabilityFrame
            $matching=[Collections.Generic.List[object]]::new()
            foreach($pipelineElement in @($pipeline.PipelineElements)){
                if($pipelineElement -isnot [Management.Automation.Language.CommandAst]){continue}
                $bindings=Get-TransportOutputVariableBindings $pipelineElement
                if($bindings.Present -and -not $bindings.Valid){return $true}
                foreach($binding in @($bindings.Rows)){
                    if((Get-TransportCapabilityKey ([string]$binding.Target) $CapabilityFrame) -ceq $targetKey){
                        $null=$matching.Add($binding)
                    }
                }
            }
            return $matching.Count -ne 1 -or [string]$matching[0].Kind -cne 'PipelineVariable'
        }
        function Get-TransportPipelineCapabilitySources(
            [Management.Automation.Language.CommandAst]$Command,
            [ValidateSet('CommandOutput','PipelineInput')][string]$Mode){
            function New-TransportFlowResult([bool]$Valid,[object[]]$Sources){
                return [pscustomobject]@{Valid=$Valid;Sources=@($Sources)}
            }
            function Get-TransportWriteOutputPayloads([Management.Automation.Language.CommandAst]$WriteCommand){
                $payloads=[Collections.Generic.List[object]]::new()
                $consumed=[Collections.Generic.HashSet[int]]::new()
                $seenParameters=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                $directParameters=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                function Get-WriteOutputParameterRole([string]$Candidate){
                    $aliases=@{
                        'db'='Debug';'ea'='ErrorAction';'ev'='ErrorVariable';'infa'='InformationAction';'iv'='InformationVariable';
                        'ob'='OutBuffer';'ov'='OutVariable';'pv'='PipelineVariable';'proga'='ProgressAction';'vb'='Verbose';
                        'wa'='WarningAction';'wv'='WarningVariable'
                    }
                    if($aliases.ContainsKey($Candidate)){return [string]$aliases[$Candidate]}
                    $known=@('InputObject','NoEnumerate','Debug','ErrorAction','ErrorVariable','InformationAction','InformationVariable','OutBuffer','OutVariable','PipelineVariable','ProgressAction','Verbose','WarningAction','WarningVariable')
                    $matches=@($known|Where-Object{$_.StartsWith($Candidate,[StringComparison]::OrdinalIgnoreCase)})
                    return $(if($matches.Count -eq 1){[string]$matches[0]}else{''})
                }
                foreach($parameter in @($WriteCommand.CommandElements|Where-Object{$_ -is [Management.Automation.Language.CommandParameterAst]})){
                    $role=Get-WriteOutputParameterRole ([string]$parameter.ParameterName)
                    if([string]::IsNullOrEmpty($role) -or -not $seenParameters.Add($role)){return [pscustomobject]@{Valid=$false;Payloads=@()}}
                    $null=$directParameters.Add($role)
                    if($role -in @('NoEnumerate','Debug','Verbose')){continue}
                    $argument=Get-TransportCommandParameterArgument $WriteCommand $parameter
                    if($null -eq $argument){return [pscustomobject]@{Valid=$false;Payloads=@()}}
                    $null=$consumed.Add([int]$argument.Extent.StartOffset)
                    if($role -ceq 'InputObject'){
                        if($null -eq $argument){return [pscustomobject]@{Valid=$false;Payloads=@()}}
                        $payloads.Add($argument)
                    }
                }
                foreach($splat in @($WriteCommand.CommandElements|Where-Object{$_ -is [Management.Automation.Language.VariableExpressionAst] -and $_.Splatted})){
                    $splatResolution=Get-TransportStaticSplatHashtable $WriteCommand $splat
                    if(-not $splatResolution.Valid){return [pscustomobject]@{Valid=$false;Payloads=@()}}
                    $hashtable=$splatResolution.Hashtable
                    foreach($pair in @($hashtable.KeyValuePairs)){
                        if($pair.Item1 -isnot [Management.Automation.Language.StringConstantExpressionAst]){return [pscustomobject]@{Valid=$false;Payloads=@()}}
                        $role=Get-WriteOutputParameterRole ([string]$pair.Item1.Value)
                        if($directParameters.Contains($role)){continue}
                        if([string]::IsNullOrEmpty($role) -or -not $seenParameters.Add($role)){return [pscustomobject]@{Valid=$false;Payloads=@()}}
                        if($role -ceq 'InputObject'){
                            $value=Get-TransportStaticHashtableValue $pair.Item2
                            if($null -eq $value){return [pscustomobject]@{Valid=$false;Payloads=@()}}
                            $payloads.Add($value)
                        }
                    }
                }
                for($elementIndex=1;$elementIndex -lt $WriteCommand.CommandElements.Count;$elementIndex++){
                    $element=$WriteCommand.CommandElements[$elementIndex]
                    if($element -is [Management.Automation.Language.CommandParameterAst] -or
                        ($element -is [Management.Automation.Language.VariableExpressionAst] -and $element.Splatted) -or
                        $consumed.Contains([int]$element.Extent.StartOffset)){continue}
                    $payloads.Add($element)
                }
                return [pscustomobject]@{Valid=$true;Payloads=@($payloads)}
            }
            function Get-TransportCallbackPsVariableTarget([Management.Automation.Language.Ast]$Node){
                if($Node -isnot [Management.Automation.Language.MemberExpressionAst] -or
                    $Node -is [Management.Automation.Language.InvokeMemberExpressionAst] -or
                    $Node.Member -isnot [Management.Automation.Language.StringConstantExpressionAst] -or
                    [string]$Node.Member.Value -ine 'Value'){
                    return $null
                }
                $getter=$Node.Expression
                if($getter -is [Management.Automation.Language.CommandExpressionAst]){$getter=$getter.Expression}
                if($getter -is [Management.Automation.Language.ParenExpressionAst]){
                    $elements=@($getter.Pipeline.PipelineElements)
                    if($elements.Count -eq 1 -and $elements[0] -is [Management.Automation.Language.CommandAst]){
                        return Get-TransportGetVariableTarget $elements[0] $false
                    }
                }
                if($getter -isnot [Management.Automation.Language.InvokeMemberExpressionAst] -or $getter.Static -or
                    $getter.Member -isnot [Management.Automation.Language.StringConstantExpressionAst] -or
                    [string]$getter.Member.Value -ine 'Get' -or @($getter.Arguments).Count -ne 1){return $null}
                if((Get-HardKillAstTextCompact -Ast $getter.Expression) -ine '$ExecutionContext.SessionState.PSVariable'){return $null}
                if($getter.Arguments[0] -isnot [Management.Automation.Language.StringConstantExpressionAst]){return '__DYNAMIC__'}
                return [string]$getter.Arguments[0].Value
            }
            function Resolve-TransportCallbackVariable(
                [string]$Name,
                [Management.Automation.Language.Ast]$UseAst,
                [Management.Automation.Language.ScriptBlockAst]$CallbackBlock,
                [Collections.Generic.HashSet[string]]$InputNames,
                [object[]]$InputSources,
                [Collections.Generic.HashSet[string]]$Visiting){
                $capabilityKey=Get-TransportCapabilityKey $Name 'Local'
                $isLocalKey=$capabilityKey.IndexOf(':',[StringComparison]::Ordinal) -lt 0
                if($isLocalKey -and $InputNames.Contains($capabilityKey)){return New-TransportFlowResult $true $InputSources}
                if(-not $isLocalKey){
                    if(Test-TransportTopNameMayContainScriptBlock $Name ([int]$UseAst.Extent.StartOffset) $UseAst){return New-TransportFlowResult $true @($UseAst)}
                    return New-TransportFlowResult $true @()
                }
                $visitKey=('{0}|{1}' -f $capabilityKey,[int]$UseAst.Extent.StartOffset)
                if(-not $Visiting.Add($visitKey)){return New-TransportFlowResult $false @()}
                try{
                    $priorWrites=@($CallbackBlock.FindAll({param($node)
                        $node -is [Management.Automation.Language.AssignmentStatementAst] -and
                        $node.Left -is [Management.Automation.Language.VariableExpressionAst] -and
                        (Get-TransportCapabilityKey ([string]$node.Left.VariablePath.UserPath) 'Local') -ceq $capabilityKey -and
                        $node.Extent.StartOffset -lt $UseAst.Extent.StartOffset
                    },$true)|Where-Object{
                        [object]::ReferenceEquals((Get-NearestTransportScriptBlock $_),$CallbackBlock)
                    }|Sort-Object {$_.Extent.StartOffset} -Descending)
                    $writes=@($priorWrites|Where-Object{Test-TransportWriteDominatesUse $_ $UseAst $CallbackBlock})
                    if($writes.Count -eq 0){
                        if($priorWrites.Count -ne 0){return New-TransportFlowResult $false @()}
                        $parameterMatches=@($(if($null -ne $CallbackBlock.ParamBlock){$CallbackBlock.ParamBlock.Parameters}else{@()})|Where-Object{
                            (Get-TransportCapabilityKey ([string]$_.Name.VariablePath.UserPath) 'Local') -ceq $capabilityKey
                        })
                        if($parameterMatches.Count -ne 1){return New-TransportFlowResult $false @()}
                        if($null -eq $parameterMatches[0].DefaultValue){return New-TransportFlowResult $true @()}
                        return Resolve-TransportCallbackValue $parameterMatches[0].DefaultValue $CallbackBlock $InputNames $InputSources $Visiting
                    }
                    return Resolve-TransportCallbackValue $writes[0].Right $CallbackBlock $InputNames $InputSources $Visiting
                }finally{$null=$Visiting.Remove($visitKey)}
            }
            function Resolve-TransportCallbackValue(
                [Management.Automation.Language.Ast]$Node,
                [Management.Automation.Language.ScriptBlockAst]$CallbackBlock,
                [Collections.Generic.HashSet[string]]$InputNames,
                [object[]]$InputSources,
                [Collections.Generic.HashSet[string]]$Visiting){
                if($null -eq $Node){return New-TransportFlowResult $true @()}
                if($Node -is [Management.Automation.Language.CommandExpressionAst]){
                    return Resolve-TransportCallbackValue $Node.Expression $CallbackBlock $InputNames $InputSources $Visiting
                }
                if($Node -is [Management.Automation.Language.ParenExpressionAst]){
                    return Resolve-TransportCallbackPipeline $Node.Pipeline $CallbackBlock $InputNames $InputSources $Visiting
                }
                if($Node -is [Management.Automation.Language.PipelineAst]){
                    return Resolve-TransportCallbackPipeline $Node $CallbackBlock $InputNames $InputSources $Visiting
                }
                if($Node -is [Management.Automation.Language.ConvertExpressionAst]){
                    if([string]$Node.Type.TypeName.FullName -iin @('string','System.String')){return New-TransportFlowResult $true @($Node)}
                    return Resolve-TransportCallbackValue $Node.Child $CallbackBlock $InputNames $InputSources $Visiting
                }
                if($Node -is [Management.Automation.Language.ScriptBlockExpressionAst]){return New-TransportFlowResult $true @($Node)}
                if($Node -is [Management.Automation.Language.VariableExpressionAst]){
                    return Resolve-TransportCallbackVariable ([string]$Node.VariablePath.UserPath) $Node $CallbackBlock $InputNames $InputSources $Visiting
                }
                if($Node -is [Management.Automation.Language.MemberExpressionAst] -and $Node -isnot [Management.Automation.Language.InvokeMemberExpressionAst]){
                    $target=Get-TransportCallbackPsVariableTarget $Node
                    if($target -ceq '__DYNAMIC__'){return New-TransportFlowResult $false @()}
                    if($null -ne $target){return Resolve-TransportCallbackVariable $target $Node $CallbackBlock $InputNames $InputSources $Visiting}
                }
                if($Node -is [Management.Automation.Language.InvokeMemberExpressionAst]){
                    if($Node.Member -isnot [Management.Automation.Language.StringConstantExpressionAst]){return New-TransportFlowResult $false @()}
                    $member=[string]$Node.Member.Value
                    if($member -ieq 'GetNewClosure'){
                        return Resolve-TransportCallbackValue $Node.Expression $CallbackBlock $InputNames $InputSources $Visiting
                    }
                    if($member -ieq 'ToString'){return New-TransportFlowResult $true @($Node)}
                    $receiver=Resolve-TransportCallbackValue $Node.Expression $CallbackBlock $InputNames $InputSources $Visiting
                    if(-not $receiver.Valid){return $receiver}
                    foreach($inputSource in @($InputSources)){
                        if(@($receiver.Sources|Where-Object{[object]::ReferenceEquals($_,$inputSource)}).Count -ne 0){return New-TransportFlowResult $false @()}
                    }
                    return New-TransportFlowResult $true @($Node)
                }
                if($Node -is [Management.Automation.Language.CommandAst]){
                    $leaf=Get-TransportCommandLeaf $Node
                    if($leaf -in @('get-variable','gv')){
                        $target=Get-TransportGetVariableTarget $Node $true
                        if($target -ceq '__DYNAMIC__'){return New-TransportFlowResult $false @()}
                        if($null -ne $target){return Resolve-TransportCallbackVariable $target $Node $CallbackBlock $InputNames $InputSources $Visiting}
                    }
                    if($leaf -in @('write-output','write','echo')){
                        $payload=Get-TransportWriteOutputPayloads $Node
                        if(-not $payload.Valid){return New-TransportFlowResult $false @()}
                        $commandSources=[Collections.Generic.List[object]]::new()
                        foreach($payloadNode in @($payload.Payloads)){
                            $resolved=Resolve-TransportCallbackValue $payloadNode $CallbackBlock $InputNames $InputSources $Visiting
                            if(-not $resolved.Valid){return $resolved}
                            foreach($source in @($resolved.Sources)){$commandSources.Add($source)}
                        }
                        return New-TransportFlowResult $true @($commandSources)
                    }
                    $definitions=@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $leaf -and $_.Extent.StartOffset -lt $Node.Extent.StartOffset})
                    if($definitions.Count -gt 1){return New-TransportFlowResult $false @()}
                    if($definitions.Count -eq 1){
                        $binding=Get-TransportCommandArgumentBindings $Node $definitions[0]
                        if(-not $binding.Valid){return New-TransportFlowResult $false @()}
                        $capableParameters=[Collections.Generic.List[string]]::new();$boundSources=[Collections.Generic.List[object]]::new()
                        foreach($boundArgument in @($binding.Bindings)){
                            $resolvedArgument=Resolve-TransportCallbackValue $boundArgument.Value $CallbackBlock $InputNames $InputSources $Visiting
                            if(-not $resolvedArgument.Valid){return $resolvedArgument}
                            if($resolvedArgument.Sources.Count -ne 0){$capableParameters.Add([string]$boundArgument.Name)}
                            foreach($source in @($resolvedArgument.Sources)){$boundSources.Add($source)}
                        }
                        $definitionVisiting=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
                        $mayExpose=Test-TransportDefinitionMayExposeScriptBlock $definitions[0] $definitionVisiting ([int]$Node.Extent.StartOffset) @($capableParameters) $Node @(@($binding.Bindings)|ForEach-Object{[string]$_.Name})
                        if(-not $mayExpose){return New-TransportFlowResult $true @()}
                        $helperSources=[Collections.Generic.List[object]]::new()
                        foreach($source in @($boundSources)){$helperSources.Add($source)}
                        $helperSources.Add($Node)
                        return New-TransportFlowResult $true @($helperSources)
                    }
                    return New-TransportFlowResult $true @($Node)
                }
                $inputReads=@($Node.FindAll({param($child)
                    $child -is [Management.Automation.Language.VariableExpressionAst] -and
                    $InputNames.Contains((([string]$child.VariablePath.UserPath -split ':')[-1]))
                },$true))
                if($inputReads.Count -ne 0){return New-TransportFlowResult $true $InputSources}
                return New-TransportFlowResult $true @($Node)
            }
            function Resolve-TransportForEachOutput(
                [Management.Automation.Language.CommandAst]$ForEachCommand,
                [object[]]$InputSources){
                $model=Get-TransportForEachCommandModel $ForEachCommand
                if(-not $model.Valid){return New-TransportFlowResult $false @()}
                $effectiveInputSources=[Collections.Generic.List[object]]::new()
                foreach($source in @($InputSources)){$effectiveInputSources.Add($source)}
                if($model.InputObjects.Count -ne 0){
                    if($InputSources.Count -ne 0 -or $model.InputObjects.Count -ne 1){return New-TransportFlowResult $false @()}
                    $effectiveInputSources.Add($model.InputObjects[0])
                }
                $outputSources=[Collections.Generic.List[object]]::new()
                foreach($callbackRow in @($model.Callbacks)){
                    $callbackCandidate=$callbackRow.Argument
                    while($callbackCandidate -is [Management.Automation.Language.ParenExpressionAst] -or
                          $callbackCandidate -is [Management.Automation.Language.CommandExpressionAst]){
                        if($callbackCandidate -is [Management.Automation.Language.ParenExpressionAst]){
                            $callbackElements=@($callbackCandidate.Pipeline.PipelineElements)
                            if($callbackElements.Count -ne 1){return New-TransportFlowResult $false @()}
                            $callbackCandidate=$callbackElements[0]
                        }else{$callbackCandidate=$callbackCandidate.Expression}
                    }
                    if($callbackCandidate -isnot [Management.Automation.Language.ScriptBlockExpressionAst]){return New-TransportFlowResult $false @()}
                    $callbackBlock=$callbackCandidate.ScriptBlock
                    $inputNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                    foreach($inputName in @('_','PSItem','input')){$null=$inputNames.Add($inputName)}
                    $callbackInputSources=if([string]$callbackRow.Role -in @('Process','RemainingScripts','Parallel')){@($effectiveInputSources)}else{@()}
                    $outputPipelines=[Collections.Generic.List[object]]::new()
                    foreach($returnStatement in @($callbackBlock.FindAll({param($node)$node -is [Management.Automation.Language.ReturnStatementAst]},$true)|Where-Object{[object]::ReferenceEquals((Get-NearestTransportScriptBlock $_),$callbackBlock)})){
                        if($null -ne $returnStatement.Pipeline){$outputPipelines.Add($returnStatement.Pipeline)}
                    }
                    foreach($outputPipeline in @($callbackBlock.FindAll({param($node)
                        $node -is [Management.Automation.Language.PipelineAst] -and
                        ($node.Parent -is [Management.Automation.Language.NamedBlockAst] -or $node.Parent -is [Management.Automation.Language.StatementBlockAst])
                    },$true)|Where-Object{[object]::ReferenceEquals((Get-NearestTransportScriptBlock $_),$callbackBlock)})){$outputPipelines.Add($outputPipeline)}
                    foreach($outputPipeline in @($outputPipelines)){
                        $visiting=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                        $resolved=Resolve-TransportCallbackPipeline $outputPipeline $callbackBlock $inputNames $callbackInputSources $visiting
                        if(-not $resolved.Valid){return $resolved}
                        foreach($source in @($resolved.Sources)){$outputSources.Add($source)}
                    }
                }
                return New-TransportFlowResult $true @($outputSources)
            }
            function Resolve-TransportCallbackPipeline(
                [Management.Automation.Language.PipelineAst]$Pipeline,
                [Management.Automation.Language.ScriptBlockAst]$CallbackBlock,
                [Collections.Generic.HashSet[string]]$InputNames,
                [object[]]$InputSources,
                [Collections.Generic.HashSet[string]]$Visiting){
                $elements=@($Pipeline.PipelineElements)
                if($elements.Count -eq 0){return New-TransportFlowResult $true @()}
                $first=Resolve-TransportCallbackValue $elements[0] $CallbackBlock $InputNames $InputSources $Visiting
                if(-not $first.Valid){return $first}
                $current=@($first.Sources)
                for($pipelineIndex=1;$pipelineIndex -lt $elements.Count;$pipelineIndex++){
                    $element=$elements[$pipelineIndex]
                    if($element -isnot [Management.Automation.Language.CommandAst]){return New-TransportFlowResult $false @()}
                    $leaf=Get-TransportCommandLeaf $element
                    if(Test-TransportReviewedOutNullCommand $element){$current=@();continue}
                    if($leaf -eq 'out-null'){return New-TransportFlowResult $false @()}
                    if($leaf -in @('tee-object','where-object','?')){continue}
                    if($leaf -in @('foreach-object','%')){
                        $mapped=Resolve-TransportForEachOutput $element $current
                        if(-not $mapped.Valid){return $mapped}
                        $current=@($mapped.Sources);continue
                    }
                    if($leaf -in @('write-output','write','echo')){
                        $payload=Get-TransportWriteOutputPayloads $element
                        if(-not $payload.Valid){return New-TransportFlowResult $false @()}
                        if($payload.Payloads.Count -eq 0){continue}
                        $replacement=[Collections.Generic.List[object]]::new()
                        foreach($payloadNode in @($payload.Payloads)){
                            $resolved=Resolve-TransportCallbackValue $payloadNode $CallbackBlock $InputNames $InputSources $Visiting
                            if(-not $resolved.Valid){return $resolved}
                            foreach($source in @($resolved.Sources)){$replacement.Add($source)}
                        }
                        $current=@($replacement);continue
                    }
                    $definitions=@($callableDefinitions|Where-Object{
                        ((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $leaf -and $_.Extent.StartOffset -lt $element.Extent.StartOffset
                    })
                    if($definitions.Count -gt 1){return New-TransportFlowResult $false @()}
                    if($definitions.Count -eq 1){
                        $pipelineParameters=Get-TransportPipelineInputParameterNames $definitions[0]
                        if(-not $pipelineParameters.Valid){return New-TransportFlowResult $false @()}
                        $current=@([pscustomobject]@{
                            TransportFlowKind='CallableOutput'
                            Command=$element
                            Definition=$definitions[0]
                            PipelineInputs=@($current)
                            PipelineParameterNames=@($pipelineParameters.Names)
                        })
                    }else{$current=@($current)+@($element)}
                }
                return New-TransportFlowResult $true $current
            }
            $pipeline=$Command.Parent
            if($pipeline -isnot [Management.Automation.Language.PipelineAst]){return [pscustomobject]@{Valid=$false;Sources=@()}}
            $elements=@($pipeline.PipelineElements);$targetIndex=-1
            for($elementIndex=0;$elementIndex -lt $elements.Count;$elementIndex++){
                if([object]::ReferenceEquals($elements[$elementIndex],$Command)){$targetIndex=$elementIndex;break}
            }
            if($targetIndex -lt 0){return [pscustomobject]@{Valid=$false;Sources=@()}}
            $sources=[Collections.Generic.List[object]]::new()
            for($elementIndex=0;$elementIndex -le $targetIndex;$elementIndex++){
                if($elementIndex -eq $targetIndex -and $Mode -ceq 'PipelineInput'){
                    return [pscustomobject]@{Valid=$true;Sources=@($sources)}
                }
                $element=$elements[$elementIndex]
                $nextSources=[Collections.Generic.List[object]]::new()
                if($element -isnot [Management.Automation.Language.CommandAst]){
                    $nextSources.Add($element)
                }else{
                    $leaf=Get-TransportCommandLeaf $element
                    if(Test-TransportReviewedOutNullCommand $element){
                        $null=$null
                    }elseif($leaf -eq 'out-null'){
                        return [pscustomobject]@{Valid=$false;Sources=@()}
                    }elseif($leaf -in @('tee-object','where-object','?')){
                        foreach($source in @($sources)){$nextSources.Add($source)}
                    }elseif($leaf -in @('foreach-object','%')){
                        $mapped=Resolve-TransportForEachOutput $element @($sources)
                        if(-not $mapped.Valid){return $mapped}
                        foreach($source in @($mapped.Sources)){$nextSources.Add($source)}
                    }elseif($leaf -in @('write-output','write','echo')){
                        $payload=Get-TransportWriteOutputPayloads $element
                        if(-not $payload.Valid){return [pscustomobject]@{Valid=$false;Sources=@()}}
                        if($payload.Payloads.Count -eq 0){foreach($source in @($sources)){$nextSources.Add($source)}}
                        else{
                            foreach($payloadNode in @($payload.Payloads)){$nextSources.Add($payloadNode)}
                        }
                    }else{
                        $definitions=@($callableDefinitions|Where-Object{
                            ((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $leaf -and $_.Extent.StartOffset -lt $element.Extent.StartOffset
                        })
                        if($definitions.Count -gt 1){return [pscustomobject]@{Valid=$false;Sources=@()}}
                        if($definitions.Count -eq 1){
                            $pipelineParameters=Get-TransportPipelineInputParameterNames $definitions[0]
                            if(-not $pipelineParameters.Valid){return [pscustomobject]@{Valid=$false;Sources=@()}}
                            $nextSources.Add([pscustomobject]@{
                                TransportFlowKind='CallableOutput'
                                Command=$element
                                Definition=$definitions[0]
                                PipelineInputs=@($sources)
                                PipelineParameterNames=@($pipelineParameters.Names)
                            })
                        }else{$nextSources.Add($element)}
                    }
                }
                $sources=$nextSources
            }
            return [pscustomobject]@{Valid=$true;Sources=@($sources)}
        }
        function Get-TransportGetVariableTarget(
            [Management.Automation.Language.CommandAst]$Command,
            [bool]$RequireValueOnly){
            if((Get-TransportCommandLeaf $Command) -notin @('get-variable','gv')){return $null}
            $nameParameters=@($Command.CommandElements|Where-Object{
                $_ -is [Management.Automation.Language.CommandParameterAst] -and
                'Name'.StartsWith([string]$_.ParameterName,[StringComparison]::OrdinalIgnoreCase)
            })
            $valueOnlyParameters=@($Command.CommandElements|Where-Object{
                $_ -is [Management.Automation.Language.CommandParameterAst] -and
                'ValueOnly'.StartsWith([string]$_.ParameterName,[StringComparison]::OrdinalIgnoreCase)
            })
            if($RequireValueOnly -and $valueOnlyParameters.Count -ne 1){return '__DYNAMIC__'}
            if($nameParameters.Count -gt 1){return '__DYNAMIC__'}
            if($nameParameters.Count -eq 1){
                $target=Get-TransportCommandParameterArgument $Command $nameParameters[0]
            }else{
                $otherValueParameters=@($Command.CommandElements|Where-Object{
                    $_ -is [Management.Automation.Language.CommandParameterAst] -and
                    -not 'ValueOnly'.StartsWith([string]$_.ParameterName,[StringComparison]::OrdinalIgnoreCase)
                })
                if($otherValueParameters.Count -ne 0){return '__DYNAMIC__'}
                $plain=@($Command.CommandElements|Select-Object -Skip 1|Where-Object{$_ -isnot [Management.Automation.Language.CommandParameterAst]})
                if($plain.Count -ne 1){return '__DYNAMIC__'}
                $target=$plain[0]
            }
            if($target -isnot [Management.Automation.Language.StringConstantExpressionAst]){return '__DYNAMIC__'}
            return [string]$target.Value
        }
        function Get-TransportStatementOwner([Management.Automation.Language.Ast]$Node){
            $cursor=$Node
            while($null -ne $cursor -and $cursor.Parent -isnot [Management.Automation.Language.NamedBlockAst] -and
                $cursor.Parent -isnot [Management.Automation.Language.StatementBlockAst]){$cursor=$cursor.Parent}
            if($null -eq $cursor -or $null -eq $cursor.Parent){return $null}
            return [pscustomobject]@{Block=$cursor.Parent;Statement=$cursor}
        }
        function Get-TransportPipelineElementOwners([Management.Automation.Language.Ast]$Node){
            $owners=[Collections.Generic.List[object]]::new()
            $cursor=$Node
            while($null -ne $cursor -and $null -ne $cursor.Parent){
                if($cursor.Parent -is [Management.Automation.Language.PipelineAst]){
                    $null=$owners.Add([pscustomobject]@{Pipeline=$cursor.Parent;Element=$cursor})
                }
                $cursor=$cursor.Parent
            }
            return @($owners)
        }
        function Test-TransportWriteDominatesUse(
            [Management.Automation.Language.Ast]$WriteAst,
            [Management.Automation.Language.Ast]$UseAst,
            [Management.Automation.Language.ScriptBlockAst]$FallbackBoundary=$null,
            [int]$BeforeOffset=[int]::MaxValue){
            if($null -eq $WriteAst){return $false}
            if($null -ne $UseAst){
                if($WriteAst -is [Management.Automation.Language.PipelineAst]){
                    $useCursor=$UseAst
                    while($null -ne $useCursor){
                        if([object]::ReferenceEquals($useCursor,$WriteAst)){return $true}
                        $useCursor=$useCursor.Parent
                    }
                }
                foreach($writePipelineOwner in @(Get-TransportPipelineElementOwners $WriteAst)){
                    foreach($usePipelineOwner in @(Get-TransportPipelineElementOwners $UseAst)){
                        if(-not[object]::ReferenceEquals($writePipelineOwner.Pipeline,$usePipelineOwner.Pipeline)){continue}
                        $pipelineElements=@($writePipelineOwner.Pipeline.PipelineElements);$writeElementIndex=-1;$useElementIndex=-1
                        for($pipelineIndex=0;$pipelineIndex -lt $pipelineElements.Count;$pipelineIndex++){
                            if([object]::ReferenceEquals($pipelineElements[$pipelineIndex],$writePipelineOwner.Element)){$writeElementIndex=$pipelineIndex}
                            if([object]::ReferenceEquals($pipelineElements[$pipelineIndex],$usePipelineOwner.Element)){$useElementIndex=$pipelineIndex}
                        }
                        if($writeElementIndex -ge 0 -and $useElementIndex -gt $writeElementIndex){return $true}
                    }
                }
            }
            $writeOwner=Get-TransportStatementOwner $WriteAst
            if($null -eq $writeOwner){return $false}
            if($null -eq $UseAst){
                return $null -ne $FallbackBoundary -and [object]::ReferenceEquals($writeOwner.Block,$FallbackBoundary.EndBlock) -and
                    [int]$WriteAst.Extent.StartOffset -lt $BeforeOffset
            }
            $cursor=$UseAst
            while($null -ne $cursor){
                $useOwner=Get-TransportStatementOwner $cursor
                if($null -eq $useOwner){break}
                if([object]::ReferenceEquals($writeOwner.Block,$useOwner.Block)){
                    $statements=@($writeOwner.Block.Statements);$writeIndex=-1;$useIndex=-1
                    for($statementIndex=0;$statementIndex -lt $statements.Count;$statementIndex++){
                        if([object]::ReferenceEquals($statements[$statementIndex],$writeOwner.Statement)){$writeIndex=$statementIndex}
                        if([object]::ReferenceEquals($statements[$statementIndex],$useOwner.Statement)){$useIndex=$statementIndex}
                    }
                    return $writeIndex -ge 0 -and $useIndex -gt $writeIndex
                }
                $cursor=$useOwner.Block.Parent
            }
            return $false
        }
        function Get-TransportCommandArgumentBindings(
            [Management.Automation.Language.CommandAst]$Command,
            [Management.Automation.Language.FunctionDefinitionAst]$Definition){
            $parameters=@(if($null -ne $Definition.Body.ParamBlock){$Definition.Body.ParamBlock.Parameters})
            $parameterNames=@($parameters|ForEach-Object{[string]$_.Name.VariablePath.UserPath})
            $bindings=[Collections.Generic.List[object]]::new();$used=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $directNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);$splatNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);$consumedOffsets=[Collections.Generic.HashSet[int]]::new()
            function New-BindingFailure { return [pscustomobject]@{Valid=$false;Bindings=@();ParameterNames=$parameterNames} }
            function Get-DefinitionParameter([string]$Candidate){
                $matches=@($parameters|Where-Object{
                    $declaredName=[string]$_.Name.VariablePath.UserPath
                    $aliases=@($_.Attributes|Where-Object{$_.TypeName.FullName -ieq 'Alias'}|ForEach-Object{$_.PositionalArguments}|ForEach-Object{if($_ -is [Management.Automation.Language.StringConstantExpressionAst]){[string]$_.Value}})
                    $declaredName.StartsWith($Candidate,[StringComparison]::OrdinalIgnoreCase) -or @($aliases|Where-Object{$_.StartsWith($Candidate,[StringComparison]::OrdinalIgnoreCase)}).Count -ne 0
                })
                return $(if($matches.Count -eq 1){$matches[0]}else{$null})
            }
            function Get-CommonRole([string]$Candidate){
                $aliases=@{'db'='Debug';'ea'='ErrorAction';'ev'='ErrorVariable';'infa'='InformationAction';'iv'='InformationVariable';'ob'='OutBuffer';'ov'='OutVariable';'pv'='PipelineVariable';'proga'='ProgressAction';'vb'='Verbose';'wa'='WarningAction';'wv'='WarningVariable'}
                if($aliases.ContainsKey($Candidate)){return [string]$aliases[$Candidate]}
                $known=@('Debug','ErrorAction','ErrorVariable','InformationAction','InformationVariable','OutBuffer','OutVariable','PipelineVariable','ProgressAction','Verbose','WarningAction','WarningVariable','WhatIf','Confirm')
                $matches=@($known|Where-Object{$_.StartsWith($Candidate,[StringComparison]::OrdinalIgnoreCase)})
                return $(if($matches.Count -eq 1){[string]$matches[0]}else{''})
            }
            function Test-StaticFalse([Management.Automation.Language.Ast]$Value){
                $candidate=Get-TransportStaticHashtableValue $Value
                return ($candidate -is [Management.Automation.Language.VariableExpressionAst] -and [string]$candidate.VariablePath.UserPath -ieq 'false') -or ($candidate -is [Management.Automation.Language.ConstantExpressionAst] -and $candidate.Value -is [bool] -and -not[bool]$candidate.Value)
            }
            function Test-SupportsShouldProcess {
                if($null -eq $Definition.Body.ParamBlock){return $false}
                foreach($attribute in @($Definition.Body.ParamBlock.Attributes|Where-Object{[string]$_.TypeName.FullName -iin @('CmdletBinding','CmdletBindingAttribute','System.Management.Automation.CmdletBindingAttribute')})){
                    foreach($namedArgument in @($attribute.NamedArguments|Where-Object{[string]$_.ArgumentName -ieq 'SupportsShouldProcess'})){
                        if($namedArgument.ExpressionOmitted){return $true}
                        $value=Get-TransportStaticHashtableValue $namedArgument.Argument
                        if($value -is [Management.Automation.Language.VariableExpressionAst] -and [string]$value.VariablePath.UserPath -ieq 'true'){return $true}
                        if($value -is [Management.Automation.Language.ConstantExpressionAst] -and $value.Value -is [bool] -and [bool]$value.Value){return $true}
                    }
                }
                return $false
            }
            $supportsShouldProcess=Test-SupportsShouldProcess
            foreach($parameterElement in @($Command.CommandElements|Where-Object{$_ -is [Management.Automation.Language.CommandParameterAst]})){
                $candidate=[string]$parameterElement.ParameterName;$parameter=Get-DefinitionParameter $candidate
                if($null -ne $parameter){
                    $parameterName=[string]$parameter.Name.VariablePath.UserPath
                    if(-not $directNames.Add($parameterName)){return New-BindingFailure}
                    $argument=Get-TransportCommandParameterArgument $Command $parameterElement;if($null -eq $argument){return New-BindingFailure}
                    $null=$consumedOffsets.Add([int]$argument.Extent.StartOffset);$null=$used.Add($parameterName);$bindings.Add([pscustomobject]@{Name=$parameterName;Value=$argument});continue
                }
                $commonRole=Get-CommonRole $candidate
                if([string]::IsNullOrEmpty($commonRole) -or -not $directNames.Add(('__common__'+$commonRole))){return New-BindingFailure}
                if($commonRole -in @('Debug','Verbose')){continue}
                if($commonRole -in @('WhatIf','Confirm')){if(-not $supportsShouldProcess -or $null -eq $parameterElement.Argument -or -not(Test-StaticFalse $parameterElement.Argument)){return New-BindingFailure};continue}
                $commonArgument=Get-TransportCommandParameterArgument $Command $parameterElement;if($null -eq $commonArgument){return New-BindingFailure}
                $null=$consumedOffsets.Add([int]$commonArgument.Extent.StartOffset)
            }
            foreach($splat in @($Command.CommandElements|Where-Object{$_ -is [Management.Automation.Language.VariableExpressionAst] -and $_.Splatted})){
                $splatResolution=Get-TransportStaticSplatHashtable $Command $splat;if(-not $splatResolution.Valid){return New-BindingFailure}
                foreach($pair in @($splatResolution.Hashtable.KeyValuePairs)){
                    if($pair.Item1 -isnot [Management.Automation.Language.StringConstantExpressionAst]){return New-BindingFailure}
                    $candidate=[string]$pair.Item1.Value;$parameter=Get-DefinitionParameter $candidate
                    if($null -ne $parameter){
                        $parameterName=[string]$parameter.Name.VariablePath.UserPath;if($directNames.Contains($parameterName)){continue};if(-not $splatNames.Add($parameterName)){return New-BindingFailure}
                        $value=Get-TransportStaticHashtableValue $pair.Item2;if($null -eq $value){return New-BindingFailure};$null=$used.Add($parameterName);$bindings.Add([pscustomobject]@{Name=$parameterName;Value=$value});continue
                    }
                    $commonRole=Get-CommonRole $candidate;if([string]::IsNullOrEmpty($commonRole)){return New-BindingFailure};$commonKey='__common__'+$commonRole
                    if($directNames.Contains($commonKey)){continue};if(-not $splatNames.Add($commonKey)){return New-BindingFailure}
                    if($commonRole -in @('WhatIf','Confirm') -and (-not $supportsShouldProcess -or -not(Test-StaticFalse $pair.Item2))){return New-BindingFailure}
                }
            }
            $position=0
            for($elementIndex=1;$elementIndex -lt $Command.CommandElements.Count;$elementIndex++){
                $element=$Command.CommandElements[$elementIndex]
                if($element -is [Management.Automation.Language.CommandParameterAst] -or ($element -is [Management.Automation.Language.VariableExpressionAst] -and $element.Splatted) -or $consumedOffsets.Contains([int]$element.Extent.StartOffset)){continue}
                while($position -lt $parameters.Count -and $used.Contains([string]$parameters[$position].Name.VariablePath.UserPath)){$position++}
                if($position -ge $parameters.Count){return New-BindingFailure}
                $parameterName=[string]$parameters[$position].Name.VariablePath.UserPath;$position++;$null=$used.Add($parameterName);$bindings.Add([pscustomobject]@{Name=$parameterName;Value=$element})
            }
            return [pscustomobject]@{Valid=$true;Bindings=@($bindings);ParameterNames=$parameterNames}
        }
        function Test-TransportInlineNodeReachable(
            [Management.Automation.Language.Ast]$Node,
            [Management.Automation.Language.Ast]$Boundary){
            $cursor=$Node
            while($cursor -and -not[object]::ReferenceEquals($cursor,$Boundary)){
                if($cursor -is [Management.Automation.Language.FunctionDefinitionAst]){return $false}
                if($cursor -is [Management.Automation.Language.ScriptBlockAst] -and $cursor.Parent -is [Management.Automation.Language.ScriptBlockExpressionAst]){
                    $scriptExpression=$cursor.Parent;$consumer=$scriptExpression.Parent
                    while($consumer -and $consumer -isnot [Management.Automation.Language.CommandAst] -and
                        $consumer -isnot [Management.Automation.Language.InvokeMemberExpressionAst] -and
                        -not[object]::ReferenceEquals($consumer,$Boundary)){$consumer=$consumer.Parent}
                    if($consumer -is [Management.Automation.Language.CommandAst]){
                        $consumerLeaf=Get-TransportCommandLeaf $consumer
                        if($consumerLeaf -notin @('foreach-object','where-object','%','?')){return $false}
                        if($consumerLeaf -in @('foreach-object','%')){
                            $model=Get-TransportForEachCommandModel $consumer
                            if(-not $model.Valid){return $true}
                            $isCallback=$false
                            foreach($callbackRow in @($model.Callbacks)){
                                $callbackCursor=$scriptExpression
                                while($null -ne $callbackCursor -and -not[object]::ReferenceEquals($callbackCursor,$consumer)){
                                    if([object]::ReferenceEquals($callbackCursor,$callbackRow.Argument)){$isCallback=$true;break}
                                    $callbackCursor=$callbackCursor.Parent
                                }
                                if($isCallback){break}
                            }
                            if(-not $isCallback){return $false}
                        }
                    }elseif($consumer -is [Management.Automation.Language.InvokeMemberExpressionAst]){
                        if([string]$consumer.Member.Value -inotin @(
                            'Invoke','InvokeReturnAsIs','InvokeWithContext','ForEach','Where',
                            'Run','StartNew','QueueUserWorkItem','UnsafeQueueUserWorkItem')){return $false}
                    }else{return $false}
                    $cursor=$consumer
                    continue
                }
                $cursor=$cursor.Parent
            }
            return [object]::ReferenceEquals($cursor,$Boundary)
        }
        $protectedTransportNames=@(
            'preimageTransportStaticSatisfied','transportAuthorityDefinitionStaticSatisfied','transportAuthorityRuntimeStaticSatisfied',
