        $scriptBlockCapabilityFirstOffsets=@{}
        $scriptBlockCapabilityWrites=@{}
        function Get-TransportCapabilityKey(
            [string]$Name,
            [ValidateSet('Top','Local')][string]$Frame){
            $raw=[string]$Name
            if($raw -match '^(?i)Variable:[\\/]?(.+)$'){$raw=$Matches[1]}
            if($raw -match '^(?i)(script|global|local|private):(.+)$'){
                $scope=$Matches[1].ToLowerInvariant();$leaf=$Matches[2]
                if($Frame -ceq 'Top' -and $scope -in @('script','local','private')){return $leaf}
                if($Frame -ceq 'Local' -and $scope -in @('local','private')){return $leaf}
                return ('{0}:{1}' -f $scope,$leaf)
            }
            return (($raw -split ':')[-1])
        }
        function Get-TransportStorageRootName([Management.Automation.Language.Ast]$Node){
            $current=$Node
            while($null -ne $current){
                if($current -is [Management.Automation.Language.CommandExpressionAst]){$current=$current.Expression;continue}
                if($current -is [Management.Automation.Language.ConvertExpressionAst]){$current=$current.Child;continue}
                if($current -is [Management.Automation.Language.ParenExpressionAst]){
                    $elements=@($current.Pipeline.PipelineElements)
                    if($elements.Count -eq 1 -and $elements[0] -is [Management.Automation.Language.CommandExpressionAst]){$current=$elements[0].Expression;continue}
                    return ''
                }
                if($current -is [Management.Automation.Language.IndexExpressionAst]){$current=$current.Target;continue}
                if($current -is [Management.Automation.Language.MemberExpressionAst] -and $current -isnot [Management.Automation.Language.InvokeMemberExpressionAst]){$current=$current.Expression;continue}
                break
            }
            if($current -isnot [Management.Automation.Language.VariableExpressionAst]){return ''}
            return [string]$current.VariablePath.UserPath
        }
        function Set-TransportScriptBlockCapabilityWrite([string]$Name,[int]$Offset,[bool]$MayContain,[Management.Automation.Language.Ast]$WriteAst=$null){
            $leaf=Get-TransportCapabilityKey $Name 'Top'
            if([string]::IsNullOrEmpty($leaf)){return $false}
            if(-not $scriptBlockCapabilityWrites.ContainsKey($leaf)){
                $scriptBlockCapabilityWrites[$leaf]=[Collections.Generic.List[object]]::new()
            }
            $rows=[Collections.Generic.List[object]]$scriptBlockCapabilityWrites[$leaf]
            $existing=@($rows|Where-Object{[int]$_.Offset -eq $Offset})
            if($existing.Count -gt 1){throw 'preimage-transport-common-entry-launch-bypass'}
            if($existing.Count -eq 1){
                if([bool]$existing[0].MayContain -eq $MayContain){return $false}
                $existing[0].MayContain=$MayContain;$existing[0].WriteAst=$WriteAst
            }else{
                $rows.Add([pscustomobject]@{Offset=$Offset;MayContain=$MayContain;WriteAst=$WriteAst})
            }
            if($MayContain){
                $null=$scriptBlockCapabilityNames.Add($leaf)
                if(-not $scriptBlockCapabilityFirstOffsets.ContainsKey($leaf) -or $Offset -lt [int]$scriptBlockCapabilityFirstOffsets[$leaf]){
                    $scriptBlockCapabilityFirstOffsets[$leaf]=$Offset
                }
            }
            return $true
        }
        function Add-TransportScriptBlockCapability([string]$Name,[int]$Offset,[Management.Automation.Language.Ast]$WriteAst=$null){
            return Set-TransportScriptBlockCapabilityWrite $Name $Offset $true $WriteAst
        }
        function Test-TransportTopNameMayContainScriptBlock([string]$Name,[int]$BeforeOffset,[Management.Automation.Language.Ast]$UseAst=$null){
            $leaf=Get-TransportCapabilityKey $Name 'Top'
            if([string]::IsNullOrEmpty($leaf)){return $false}
            $candidateKeys=@($leaf)
            if([string]$Name -notmatch '^(?i)(script|global|local|private):' -and
                $leaf.IndexOf(':',[StringComparison]::Ordinal) -lt 0){$candidateKeys+=('global:{0}' -f $leaf)}
            foreach($candidateKey in $candidateKeys){
                if(-not $scriptBlockCapabilityWrites.ContainsKey($candidateKey)){continue}
                $prior=@($scriptBlockCapabilityWrites[$candidateKey]|Where-Object{[int]$_.Offset -lt $BeforeOffset}|Sort-Object {[int]$_.Offset} -Descending)
                foreach($write in $prior){
                    if([bool]$write.MayContain){return $true}
                    if([int]$write.Offset -eq [int]::MinValue -or
                        (Test-TransportWriteDominatesUse $write.WriteAst $UseAst $ast $BeforeOffset)){return $false}
                }
            }
            return $false
        }
        function Get-TransportTopPsVariableValueTarget([Management.Automation.Language.Ast]$Node){
            if($Node -isnot [Management.Automation.Language.MemberExpressionAst] -or
                $Node -is [Management.Automation.Language.InvokeMemberExpressionAst] -or
                $Node.Member -isnot [Management.Automation.Language.StringConstantExpressionAst] -or
                [string]$Node.Member.Value -ine 'Value'){
                return $null
            }
            $getter=$Node.Expression
            if($getter -is [Management.Automation.Language.CommandExpressionAst]){$getter=$getter.Expression}
            if($getter -is [Management.Automation.Language.ParenExpressionAst]){
                $elements=@($getter.Pipeline.PipelineElements)
                if($elements.Count -eq 1 -and $elements[0] -is [Management.Automation.Language.CommandAst]){
                    return Get-TransportGetVariableTarget $elements[0] $false
                }
            }
            if($getter -isnot [Management.Automation.Language.InvokeMemberExpressionAst] -or $getter.Static -or
                $getter.Member -isnot [Management.Automation.Language.StringConstantExpressionAst] -or
                [string]$getter.Member.Value -ine 'Get' -or @($getter.Arguments).Count -ne 1){
                return $null
            }
            $providerCompact=Get-HardKillAstTextCompact -Ast $getter.Expression
            $providerAlias=$getter.Expression -is [Management.Automation.Language.VariableExpressionAst] -and
                $psVariableProviderAliases.Contains((([string]$getter.Expression.VariablePath.UserPath -split ':')[-1]))
            if($providerCompact -ine '$ExecutionContext.SessionState.PSVariable' -and -not $providerAlias){return $null}
            if($getter.Arguments[0] -isnot [Management.Automation.Language.StringConstantExpressionAst]){return '__DYNAMIC__'}
            return [string]$getter.Arguments[0].Value
        }
        function Test-TransportTopValueMayContainScriptBlock(
            [object]$Node,
            [int]$BeforeOffset){
            if($null -eq $Node){return $false}
            if($Node -isnot [Management.Automation.Language.Ast] -and
                $null -ne $Node.PSObject.Properties['TransportFlowKind'] -and
                [string]$Node.TransportFlowKind -ceq 'CallableOutput'){
                $binding=Get-TransportCommandArgumentBindings $Node.Command $Node.Definition
                if(-not $binding.Valid){return $true}
                $capableParameters=[Collections.Generic.List[string]]::new()
                foreach($boundArgument in @($binding.Bindings)){
                    if(Test-TransportTopValueMayContainScriptBlock $boundArgument.Value ([int]$Node.Command.Extent.StartOffset)){$capableParameters.Add([string]$boundArgument.Name)}
                }
                $pipelineMayContain=$false
                foreach($pipelineInput in @($Node.PipelineInputs)){
                    if(Test-TransportTopValueMayContainScriptBlock $pipelineInput ([int]$Node.Command.Extent.StartOffset)){$pipelineMayContain=$true;break}
                }
                $pipelineCapableParameters=[Collections.Generic.List[string]]::new()
                $pipelineBoundParameters=[Collections.Generic.List[string]]::new()
                if(@($Node.PipelineInputs).Count -ne 0){
                    foreach($automaticName in @('_','PSItem','input')){$pipelineBoundParameters.Add($automaticName)}
                    foreach($parameterName in @($Node.PipelineParameterNames|Where-Object{[string]$_ -inotin @(@($binding.Bindings)|ForEach-Object{[string]$_.Name})})){$pipelineBoundParameters.Add([string]$parameterName)}
                }
                if($pipelineMayContain){
                    foreach($pipelineBoundParameter in @($pipelineBoundParameters)){$pipelineCapableParameters.Add([string]$pipelineBoundParameter)}
                }
                $boundNames=@(@($binding.Bindings)|ForEach-Object{[string]$_.Name})+@($Node.PipelineParameterNames)
                $visiting=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
                return Test-TransportDefinitionMayExposeScriptBlock $Node.Definition $visiting ([int]$Node.Command.Extent.StartOffset) @($capableParameters) $Node.Command @($boundNames) @($pipelineCapableParameters) @($pipelineBoundParameters)
            }
            if($Node -is [Management.Automation.Language.CommandExpressionAst]){return Test-TransportTopValueMayContainScriptBlock $Node.Expression $BeforeOffset}
            if($Node -is [Management.Automation.Language.ConvertExpressionAst]){
                if([string]$Node.Type.TypeName.FullName -iin @('scriptblock','System.Management.Automation.ScriptBlock')){return $true}
                return Test-TransportTopValueMayContainScriptBlock $Node.Child $BeforeOffset
            }
            if($Node -is [Management.Automation.Language.ScriptBlockExpressionAst]){return $true}
            if($Node -is [Management.Automation.Language.VariableExpressionAst]){
                return Test-TransportTopNameMayContainScriptBlock ([string]$Node.VariablePath.UserPath) $BeforeOffset $Node
            }
            if($Node -is [Management.Automation.Language.ParenExpressionAst]){
                return Test-TransportTopValueMayContainScriptBlock $Node.Pipeline $BeforeOffset
            }
            if($Node -is [Management.Automation.Language.PipelineAst]){
                $elements=@($Node.PipelineElements)
                if($elements.Count -eq 0){return $false}
                $last=$elements[-1]
                if(Test-TransportReviewedOutNullCommand $last){return $false}
                if($last -isnot [Management.Automation.Language.CommandAst]){return Test-TransportTopValueMayContainScriptBlock $last $BeforeOffset}
                $flow=Get-TransportPipelineCapabilitySources $last 'CommandOutput'
                if(-not $flow.Valid){return $true}
                foreach($source in @($flow.Sources)){if(Test-TransportTopValueMayContainScriptBlock $source $BeforeOffset){return $true}}
                return $false
            }
            if($Node -is [Management.Automation.Language.HashtableAst]){
                foreach($pair in @($Node.KeyValuePairs)){if(Test-TransportTopValueMayContainScriptBlock $pair.Item2 $BeforeOffset){return $true}}
                return $false
            }
            if($Node -is [Management.Automation.Language.ArrayLiteralAst]){
                foreach($element in @($Node.Elements)){if(Test-TransportTopValueMayContainScriptBlock $element $BeforeOffset){return $true}}
                return $false
            }
            if($Node -is [Management.Automation.Language.ArrayExpressionAst]){return Test-TransportTopValueMayContainScriptBlock $Node.SubExpression $BeforeOffset}
            if($Node -is [Management.Automation.Language.StatementBlockAst]){
                foreach($statement in @($Node.Statements)){if(Test-TransportTopValueMayContainScriptBlock $statement $BeforeOffset){return $true}}
                return $false
            }
            if($Node -is [Management.Automation.Language.IndexExpressionAst]){return Test-TransportTopValueMayContainScriptBlock $Node.Target $BeforeOffset}
            if($Node -is [Management.Automation.Language.MemberExpressionAst] -and $Node -isnot [Management.Automation.Language.InvokeMemberExpressionAst]){
                $variableTarget=Get-TransportTopPsVariableValueTarget $Node
                if($variableTarget -ceq '__DYNAMIC__'){return $true}
                if($null -ne $variableTarget){return Test-TransportTopNameMayContainScriptBlock $variableTarget $BeforeOffset $Node}
                return Test-TransportTopValueMayContainScriptBlock $Node.Expression $BeforeOffset
            }
            if($Node -is [Management.Automation.Language.InvokeMemberExpressionAst] -and
                $Node.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and [string]$Node.Member.Value -ieq 'GetNewClosure'){
                return Test-TransportTopValueMayContainScriptBlock $Node.Expression $BeforeOffset
            }
            if($Node -is [Management.Automation.Language.CommandAst]){
                $leaf=Get-TransportCommandLeaf $Node
                if($leaf -in @('get-variable','gv')){
                    $target=Get-TransportGetVariableTarget $Node $true
                    if($target -ceq '__DYNAMIC__'){return $true}
                    if($null -ne $target){return Test-TransportTopNameMayContainScriptBlock $target $BeforeOffset $Node}
                }
                if($leaf -in @('write-output','write','echo')){
                    foreach($element in @($Node.CommandElements|Select-Object -Skip 1)){
                        if($element -is [Management.Automation.Language.CommandParameterAst]){
                            if($null -ne $element.Argument -and (Test-TransportTopValueMayContainScriptBlock $element.Argument $BeforeOffset)){return $true}
                            continue
                        }
                        if(Test-TransportTopValueMayContainScriptBlock $element $BeforeOffset){return $true}
                    }
                }
            }
            return $false
        }
        foreach($aliasAssignment in $aliasAssignments){
            $aliasPath=[string]$aliasAssignment.Left.VariablePath.UserPath
            $aliasName=(($aliasPath -split ':')[-1])
            if($aliasName -ieq 'null'){continue}
            $assignmentMayContain=Test-TransportTopValueMayContainScriptBlock $aliasAssignment.Right ([int]$aliasAssignment.Extent.StartOffset)
            if($aliasAssignment.Operator -ne [Management.Automation.Language.TokenKind]::Equals -and
                (Test-TransportTopNameMayContainScriptBlock $aliasPath ([int]$aliasAssignment.Extent.StartOffset) $aliasAssignment)){$assignmentMayContain=$true}
            $null=Set-TransportScriptBlockCapabilityWrite $aliasPath ([int]$aliasAssignment.Extent.StartOffset) $assignmentMayContain $aliasAssignment
            if($aliasAssignment.Right -is [Management.Automation.Language.CommandExpressionAst] -and
                $aliasAssignment.Right.Expression -is [Management.Automation.Language.ScriptBlockExpressionAst]){continue}
            if(Test-TransportNameTainted $aliasName){continue}
            $rhsVariables=@($aliasAssignment.Right.FindAll({param($node)$node -is [Management.Automation.Language.VariableExpressionAst]},$true))
            $taintedRhs=@($rhsVariables|Where-Object{Test-TransportNameTainted ([string]$_.VariablePath.UserPath)}).Count -ne 0
            $launchInputRhs=@($rhsVariables|Where-Object{$taintedLaunchInputNames.Contains((([string]$_.VariablePath.UserPath -split ':')[-1]))}).Count -ne 0
            $rhsCommands=@($aliasAssignment.Right.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst] -and
                (((([string]$node.GetCommandName() -split '[\\/]')[-1] -split ':')[-1]) -iin @('Get-Variable','gv'))},$true))
            foreach($rhsCommand in $rhsCommands){
                $literal=@($rhsCommand.CommandElements|Select-Object -Skip 1|Where-Object{$_ -is [Management.Automation.Language.StringConstantExpressionAst]}|Select-Object -First 1)
                if($literal.Count -ne 1){$taintedRhs=$true}
                elseif(Test-TransportNameTainted ([string]$literal[0].Value)){
                    $taintedRhs=$true
                    if($taintedLaunchInputNames.Contains((([string]$literal[0].Value -split ':')[-1]))){$launchInputRhs=$true}
                }
            }
            $rhsCompact=Get-HardKillAstTextCompact -Ast $aliasAssignment.Right
            if($rhsCompact -match '^\[[^\]]+\]\$ExecutionContext\.SessionState\.PSVariable$' -or
                $rhsCompact -ieq '$ExecutionContext.SessionState.PSVariable' -or
                @($aliasAssignment.Right.FindAll({param($node)$node -is [Management.Automation.Language.VariableExpressionAst] -and
                    $psVariableProviderAliases.Contains((([string]$node.VariablePath.UserPath -split ':')[-1]))},$true)).Count -ne 0){
                $null=$psVariableProviderAliases.Add($aliasName)
            }
            foreach($taintedName in @($taintedTransportNames)){
                if($rhsCompact -match ('(?i)PSVariable\.Get\(["'']?{0}["'']?\)' -f [regex]::Escape($taintedName))){$taintedRhs=$true;break}
            }
            if($taintedRhs){$null=$taintedTransportNames.Add($aliasName);if($launchInputRhs){$null=$taintedLaunchInputNames.Add($aliasName)}}
        }
        $safeStopwatchVariables=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $preSectionAssignments=@($ast.FindAll({param($node)
            $node -is [Management.Automation.Language.AssignmentStatementAst] -and $node.Left -is [Management.Automation.Language.VariableExpressionAst]
        },$true)|Where-Object{
            $null -eq (Get-NearestHardKillFunction $_) -and [object]::ReferenceEquals((Get-NearestTransportScriptBlock $_),$ast) -and
            $_.Extent.StartOffset -lt $sectionIf.Extent.StartOffset
        })
        foreach($assignmentGroup in @($preSectionAssignments|Group-Object {(([string]$_.Left.VariablePath.UserPath -split ':')[-1]).ToLowerInvariant()})){
            if($assignmentGroup.Count -eq 1 -and (Get-HardKillAstTextCompact -Ast $assignmentGroup.Group[0].Right) -cin @('[Diagnostics.Stopwatch]::new()','[System.Diagnostics.Stopwatch]::new()')){
                $null=$safeStopwatchVariables.Add((([string]$assignmentGroup.Group[0].Left.VariablePath.UserPath -split ':')[-1]))
            }
        }
        function Test-TransportDangerousCommand([Management.Automation.Language.CommandAst]$Command){
            $name=[string]$Command.GetCommandName();$leaf=Get-TransportCommandLeaf $Command
            if($Command.InvocationOperator -ne [Management.Automation.Language.TokenKind]::Unknown){
                if($Profile -ceq 'Actual' -and (Get-HardKillAstTextCompact -Ast $Command) -cin $reviewedRootLoads){return $false}
                return $true
            }
            if([string]::IsNullOrEmpty($name)){return $true}
            if($leaf -in @('invoke-expression','iex','invoke-command','icm')){return $true}
            if($leaf -in @('invoke-hardkillsealedmutationcontrollercase','start-hardkillregisteredprocess','start-hardkilljobprocess','start-process','start','saps','start-job','sajb','start-threadjob','invoke-wmimethod','invoke-cimmethod','pwsh','pwsh.exe','powershell','powershell.exe','cmd','cmd.exe','wscript','wscript.exe','cscript','cscript.exe','mshta','mshta.exe','rundll32','rundll32.exe','regsvr32','regsvr32.exe','schtasks','schtasks.exe','wmic','wmic.exe')){return $true}
            if($name -match '(?i)(^[A-Z]:[\\/]|^[\\/]{1,2}|\.(exe|com|cmd|bat|ps1|vbs|js|wsf|msc|cpl|scr)$)'){return $true}
            return $false
        }
        function Test-TransportDangerousMember([Management.Automation.Language.InvokeMemberExpressionAst]$Member){
            if($Member.Member -isnot [Management.Automation.Language.StringConstantExpressionAst]){return $true}
            $memberName=[string]$Member.Member.Value;$expression=Get-HardKillAstTextCompact -Ast $Member.Expression;$compact=Get-HardKillAstTextCompact -Ast $Member
            if($memberName -iin @('InvokeMember','DynamicInvoke','CreateDelegate','InvokeScript','Kill')){return $true}
            if($Member.Static -and $Member.Expression -isnot [Management.Automation.Language.TypeExpressionAst]){return $true}
            if($Member.Static -and $Member.Expression -is [Management.Automation.Language.TypeExpressionAst] -and
                [string]$Member.Expression.TypeName.FullName -iin @('Environment','System.Environment') -and
                $memberName -iin @('Exit','FailFast')){return $true}
            if($Member.Static -and $Member.Expression -is [Management.Automation.Language.TypeExpressionAst] -and
                [string]$Member.Expression.TypeName.FullName -iin @('ScriptBlock','System.Management.Automation.ScriptBlock') -and
                $memberName -ieq 'Create'){return $true}
            if($Member.Static -and $memberName -ieq 'Start' -and $Member.Expression -is [Management.Automation.Language.TypeExpressionAst] -and
                [string]$Member.Expression.TypeName.FullName -iin @('Diagnostics.Process','System.Diagnostics.Process')){return $true}
            if($compact -match '(?i)(System\.Management\.Automation\.PowerShell|\[PowerShell\]|AddScript\(|WScript\.Shell|Shell\.Application|Win32_Process)' -and
                $memberName -iin @('Create','Start','Run','ShellExecute','CreateProcess','Invoke','BeginInvoke')){return $true}
            if(-not $Member.Static -and $memberName -ieq 'Invoke' -and $Member.Expression -is [Management.Automation.Language.InvokeMemberExpressionAst]){return $true}
            if(-not $Member.Static -and $memberName -ieq 'Start'){
                if($Member.Expression -is [Management.Automation.Language.VariableExpressionAst] -and
                    $safeStopwatchVariables.Contains((([string]$Member.Expression.VariablePath.UserPath -split ':')[-1]))){
                    $stopwatchName=(([string]$Member.Expression.VariablePath.UserPath -split ':')[-1])
                    $stopwatchWrites=@($ast.FindAll({param($node)
                        $node -is [Management.Automation.Language.AssignmentStatementAst] -and $node.Extent.StartOffset -lt $Member.Extent.StartOffset -and
                        @($node.Left.FindAll({param($child)$child -is [Management.Automation.Language.VariableExpressionAst] -and
                            (([string]$child.VariablePath.UserPath -split ':')[-1]) -ieq $stopwatchName},$true)).Count -ne 0
                    },$true)|Where-Object{$null -eq (Get-NearestHardKillFunction $_) -and [object]::ReferenceEquals((Get-NearestTransportScriptBlock $_),$ast)})
                    $stopwatchCommandWrites=@($ast.FindAll({param($node)
                        if($node -isnot [Management.Automation.Language.CommandAst] -or $node.Extent.StartOffset -ge $Member.Extent.StartOffset){return $false}
                        $commandLeaf=Get-TransportCommandLeaf $node
                        if($commandLeaf -notin @('set-variable','sv','new-variable','nv','set-item','si')){return $false}
                        return @($node.CommandElements|Where-Object{$_ -is [Management.Automation.Language.StringConstantExpressionAst] -and
                            (([string]$_.Value -split ':')[-1]) -ieq $stopwatchName}).Count -ne 0
                    },$true)|Where-Object{$null -eq (Get-NearestHardKillFunction $_) -and [object]::ReferenceEquals((Get-NearestTransportScriptBlock $_),$ast)})
                    if($stopwatchWrites.Count -eq 1 -and $stopwatchCommandWrites.Count -eq 0){return $false}
                }
                return $true
            }
            return -not $Member.Static -and $memberName -iin @('Run','ShellExecute','CreateProcess')
        }
        $callableDefinitions=@($ast.FindAll({param($node)$node -is [Management.Automation.Language.FunctionDefinitionAst]},$true)|Where-Object{
            [object]::ReferenceEquals($_.Parent,$ast.EndBlock) -and $_.Extent.StartOffset -lt $sectionIf.Extent.StartOffset
        })
        function Test-TransportExpressionContainsCallableResult([Management.Automation.Language.Ast]$Node){
            if($null -eq $Node){return $false}
            $commands=@($Node.FindAll({param($child)$child -is [Management.Automation.Language.CommandAst]},$true))
            foreach($command in $commands){
                $leaf=Get-TransportCommandLeaf $command
                if([string]::IsNullOrEmpty($leaf)){return $true}
                if(@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $leaf -and $_.Extent.StartOffset -lt $command.Extent.StartOffset}).Count -ne 0){return $true}
            }
            return $false
        }
        function Test-TransportDefinitionMayExposePsVariableProvider(
            [Management.Automation.Language.FunctionDefinitionAst]$Definition,
            [Collections.Generic.HashSet[int]]$Visiting){
            $key=[int]$Definition.Extent.StartOffset
            if(-not $Visiting.Add($key)){return $true}
            try{
                if(@($Definition.Body.FindAll({param($node)(Get-HardKillAstTextCompact -Ast $node) -ieq '$ExecutionContext.SessionState.PSVariable'},$true)).Count -ne 0){return $true}
                $calls=@($Definition.Body.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true)|Where-Object{
                    [object]::ReferenceEquals((Get-NearestHardKillFunction $_),$Definition)
                })
                foreach($call in $calls){
                    $leaf=Get-TransportCommandLeaf $call
                    $definitions=@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $leaf -and $_.Extent.StartOffset -lt $call.Extent.StartOffset})
                    if($definitions.Count -gt 1){return $true}
                    if($definitions.Count -eq 1 -and (Test-TransportDefinitionMayExposePsVariableProvider $definitions[0] $Visiting)){return $true}
                }
                return $false
            }finally{$null=$Visiting.Remove($key)}
        }
        function Test-TransportDefinitionMayExposeScriptBlock(
            [Management.Automation.Language.FunctionDefinitionAst]$Definition,
            [Collections.Generic.HashSet[string]]$Visiting,
            [int]$CallOffset=[int]::MaxValue,
            [string[]]$ScriptBlockParameterNames=@(),
            [Management.Automation.Language.Ast]$CallSiteAst=$null,
            [string[]]$BoundParameterNames=@(),
            [string[]]$PipelineScriptBlockParameterNames=@(),
            [string[]]$PipelineBoundParameterNames=@()){
            $key=('{0}|c:{1}|b:{2}|p:{3}|i:{4}' -f [int]$Definition.Extent.StartOffset,((@($ScriptBlockParameterNames)|Sort-Object)-join','),((@($BoundParameterNames)|Sort-Object)-join','),((@($PipelineScriptBlockParameterNames)|Sort-Object)-join','),((@($PipelineBoundParameterNames)|Sort-Object)-join','))
            if(-not $Visiting.Add($key)){return $true}
            try{
                $definitionWrites=@{}
                $definitionParameters=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                $definitionScriptBlockParameters=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                $definitionPipelineScriptBlockParameters=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                $definitionPipelineBoundParameters=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                foreach($scriptBlockParameterName in @($ScriptBlockParameterNames)){$null=$definitionScriptBlockParameters.Add((($scriptBlockParameterName -split ':')[-1]))}
                foreach($pipelineParameterName in @($PipelineScriptBlockParameterNames)){$null=$definitionPipelineScriptBlockParameters.Add((($pipelineParameterName -split ':')[-1]))}
                foreach($pipelineBoundName in @($PipelineBoundParameterNames)){$null=$definitionPipelineBoundParameters.Add((($pipelineBoundName -split ':')[-1]))}
                if($null -ne $Definition.Body.ParamBlock){
                    foreach($parameter in @($Definition.Body.ParamBlock.Parameters)){
                        $parameterName=(([string]$parameter.Name.VariablePath.UserPath -split ':')[-1])
                        $null=$definitionParameters.Add($parameterName)
                    }
                }
                function Set-DefinitionScriptBlockWrite([string]$Name,[int]$Offset,[bool]$MayContain,[Management.Automation.Language.Ast]$WriteAst=$null){
                    $leaf=Get-TransportCapabilityKey $Name 'Local'
                    if(-not $definitionWrites.ContainsKey($leaf)){$definitionWrites[$leaf]=[Collections.Generic.List[object]]::new()}
                    $rows=[Collections.Generic.List[object]]$definitionWrites[$leaf]
                    $existing=@($rows|Where-Object{[int]$_.Offset -eq $Offset})
                    if($existing.Count -eq 1){
                        if([bool]$existing[0].MayContain -eq $MayContain){return $false}
                        $existing[0].MayContain=$MayContain;$existing[0].WriteAst=$WriteAst
                    }elseif($existing.Count -eq 0){$rows.Add([pscustomobject]@{Offset=$Offset;MayContain=$MayContain;WriteAst=$WriteAst})}
                    else{return $true}
                    return $true
                }
                function Test-DefinitionNameMayExposeScriptBlock([string]$Name,[int]$BeforeOffset,[Management.Automation.Language.Ast]$UseAst=$null){
                    $leaf=Get-TransportCapabilityKey $Name 'Local'
                    if($definitionWrites.ContainsKey($leaf)){
                        $prior=@($definitionWrites[$leaf]|Where-Object{[int]$_.Offset -lt $BeforeOffset}|Sort-Object {[int]$_.Offset} -Descending)
                        foreach($write in $prior){
                            if([bool]$write.MayContain){return $true}
                            if(Test-TransportWriteDominatesUse $write.WriteAst $UseAst $Definition.Body $BeforeOffset){return $false}
                        }
                    }
                    $useCursor=$UseAst;$inBegin=$false
                    while($null -ne $useCursor -and -not[object]::ReferenceEquals($useCursor,$Definition.Body)){
                        if($null -ne $Definition.Body.BeginBlock -and [object]::ReferenceEquals($useCursor,$Definition.Body.BeginBlock)){$inBegin=$true;break}
                        $useCursor=$useCursor.Parent
                    }
                    if($definitionPipelineBoundParameters.Contains($leaf) -and -not $inBegin){return $definitionPipelineScriptBlockParameters.Contains($leaf)}
                    if($definitionScriptBlockParameters.Contains($leaf)){return $true}
                    if($definitionParameters.Contains($leaf)){return $false}
                    return Test-TransportTopNameMayContainScriptBlock $Name $CallOffset $CallSiteAst
                }
                function Test-DefinitionValueMayExposeScriptBlock([object]$Node,[int]$BeforeOffset){
                    if($null -eq $Node){return $false}
                    if($Node -isnot [Management.Automation.Language.Ast] -and
                        $null -ne $Node.PSObject.Properties['TransportFlowKind'] -and
                        [string]$Node.TransportFlowKind -ceq 'CallableOutput'){
                        $binding=Get-TransportCommandArgumentBindings $Node.Command $Node.Definition
                        if(-not $binding.Valid){return $true}
                        $capableParameters=[Collections.Generic.List[string]]::new()
                        foreach($boundArgument in @($binding.Bindings)){
                            if(Test-DefinitionValueMayExposeScriptBlock $boundArgument.Value ([int]$Node.Command.Extent.StartOffset)){$capableParameters.Add([string]$boundArgument.Name)}
                        }
                        $pipelineMayContain=$false
                        foreach($pipelineInput in @($Node.PipelineInputs)){
                            if(Test-DefinitionValueMayExposeScriptBlock $pipelineInput ([int]$Node.Command.Extent.StartOffset)){$pipelineMayContain=$true;break}
                        }
                        $pipelineCapableParameters=[Collections.Generic.List[string]]::new()
                        $pipelineBoundParameters=[Collections.Generic.List[string]]::new()
                        if(@($Node.PipelineInputs).Count -ne 0){
                            foreach($automaticName in @('_','PSItem','input')){$pipelineBoundParameters.Add($automaticName)}
                            foreach($parameterName in @($Node.PipelineParameterNames|Where-Object{[string]$_ -inotin @(@($binding.Bindings)|ForEach-Object{[string]$_.Name})})){$pipelineBoundParameters.Add([string]$parameterName)}
                        }
                        if($pipelineMayContain){
                            foreach($pipelineBoundParameter in @($pipelineBoundParameters)){$pipelineCapableParameters.Add([string]$pipelineBoundParameter)}
                        }
                        $boundNames=@(@($binding.Bindings)|ForEach-Object{[string]$_.Name})+@($Node.PipelineParameterNames)
                        return Test-TransportDefinitionMayExposeScriptBlock $Node.Definition $Visiting ([int]$Node.Command.Extent.StartOffset) @($capableParameters) $Node.Command @($boundNames) @($pipelineCapableParameters) @($pipelineBoundParameters)
                    }
                    if($Node -is [Management.Automation.Language.CommandExpressionAst]){return Test-DefinitionValueMayExposeScriptBlock $Node.Expression $BeforeOffset}
                    if($Node -is [Management.Automation.Language.ConvertExpressionAst]){
                        if([string]$Node.Type.TypeName.FullName -iin @('scriptblock','System.Management.Automation.ScriptBlock')){return $true}
                        return Test-DefinitionValueMayExposeScriptBlock $Node.Child $BeforeOffset
                    }
                    if($Node -is [Management.Automation.Language.ScriptBlockExpressionAst]){return $true}
                    if($Node -is [Management.Automation.Language.VariableExpressionAst]){return Test-DefinitionNameMayExposeScriptBlock ([string]$Node.VariablePath.UserPath) $BeforeOffset $Node}
                    if($Node -is [Management.Automation.Language.ParenExpressionAst]){
                        return Test-DefinitionValueMayExposeScriptBlock $Node.Pipeline $BeforeOffset
                    }
                    if($Node -is [Management.Automation.Language.PipelineAst]){
                        $elements=@($Node.PipelineElements)
                        if($elements.Count -eq 0){return $false}
                        $last=$elements[-1]
                        if(Test-TransportReviewedOutNullCommand $last){return $false}
                        if($last -isnot [Management.Automation.Language.CommandAst]){return Test-DefinitionValueMayExposeScriptBlock $last $BeforeOffset}
                        $flow=Get-TransportPipelineCapabilitySources $last 'CommandOutput'
                        if(-not $flow.Valid){return $true}
                        foreach($source in @($flow.Sources)){if(Test-DefinitionValueMayExposeScriptBlock $source $BeforeOffset){return $true}}
                        return $false
                    }
                    if($Node -is [Management.Automation.Language.HashtableAst]){
                        foreach($pair in @($Node.KeyValuePairs)){if(Test-DefinitionValueMayExposeScriptBlock $pair.Item2 $BeforeOffset){return $true}}
                        return $false
                    }
                    if($Node -is [Management.Automation.Language.ArrayLiteralAst]){
                        foreach($element in @($Node.Elements)){if(Test-DefinitionValueMayExposeScriptBlock $element $BeforeOffset){return $true}}
                        return $false
                    }
                    if($Node -is [Management.Automation.Language.ArrayExpressionAst]){return Test-DefinitionValueMayExposeScriptBlock $Node.SubExpression $BeforeOffset}
                    if($Node -is [Management.Automation.Language.StatementBlockAst]){
                        foreach($statement in @($Node.Statements)){if(Test-DefinitionValueMayExposeScriptBlock $statement $BeforeOffset){return $true}}
                        return $false
                    }
                    if($Node -is [Management.Automation.Language.IndexExpressionAst]){return Test-DefinitionValueMayExposeScriptBlock $Node.Target $BeforeOffset}
                    if($Node -is [Management.Automation.Language.MemberExpressionAst] -and $Node -isnot [Management.Automation.Language.InvokeMemberExpressionAst]){
                        if(Test-TransportExpressionContainsCallableResult $Node.Expression){return $true}
                        return Test-DefinitionValueMayExposeScriptBlock $Node.Expression $BeforeOffset
                    }
                    if($Node -is [Management.Automation.Language.InvokeMemberExpressionAst]){
                        if($Node.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and [string]$Node.Member.Value -ieq 'GetNewClosure'){
                            return Test-DefinitionValueMayExposeScriptBlock $Node.Expression $BeforeOffset
                        }
                        if(-not $Node.Static -and $Node.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and
                            [string]$Node.Member.Value -ieq 'Get' -and
                            (Get-HardKillAstTextCompact -Ast $Node.Expression) -ieq '$ExecutionContext.SessionState.PSVariable'){
                            if(@($Node.Arguments).Count -ne 1 -or $Node.Arguments[0] -isnot [Management.Automation.Language.StringConstantExpressionAst]){return $true}
                            return Test-DefinitionNameMayExposeScriptBlock ([string]$Node.Arguments[0].Value) $BeforeOffset $Node
                        }
                        return $false
                    }
                    if($Node -is [Management.Automation.Language.CommandAst]){
                        $leaf=Get-TransportCommandLeaf $Node
                        if($leaf -in @('get-variable','gv')){
                            $target=Get-TransportGetVariableTarget $Node $true
                            if($target -ceq '__DYNAMIC__'){return $true}
                            if($null -ne $target){return Test-DefinitionNameMayExposeScriptBlock $target $BeforeOffset $Node}
                        }
                        if($leaf -in @('write-output','write','echo')){
                            foreach($element in @($Node.CommandElements|Select-Object -Skip 1)){
                                if($element -is [Management.Automation.Language.CommandParameterAst]){
                                    if($null -ne $element.Argument -and (Test-DefinitionValueMayExposeScriptBlock $element.Argument $BeforeOffset)){return $true}
                                    continue
                                }
                                if(Test-DefinitionValueMayExposeScriptBlock $element $BeforeOffset){return $true}
                            }
                        }
                        $definitions=@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $leaf -and $_.Extent.StartOffset -lt $Node.Extent.StartOffset})
                        if($definitions.Count -gt 1){return $true}
                        if($definitions.Count -eq 1){
                            $binding=Get-TransportCommandArgumentBindings $Node $definitions[0]
                            if(-not $binding.Valid){return $true}
                            $capableParameters=[Collections.Generic.List[string]]::new()
                            foreach($boundArgument in @($binding.Bindings)){
                                if(Test-DefinitionValueMayExposeScriptBlock $boundArgument.Value ([int]$Node.Extent.StartOffset)){$capableParameters.Add([string]$boundArgument.Name)}
                            }
                            if(Test-TransportDefinitionMayExposeScriptBlock $definitions[0] $Visiting ([int]$Node.Extent.StartOffset) @($capableParameters) $Node @(@($binding.Bindings)|ForEach-Object{[string]$_.Name})){return $true}
                        }
                    }
                    return $false
                }
                if($null -ne $Definition.Body.ParamBlock){
                    foreach($parameter in @($Definition.Body.ParamBlock.Parameters)){
                        if([string]$parameter.Name.VariablePath.UserPath -inotin @($BoundParameterNames) -and $null -ne $parameter.DefaultValue -and
                            ($parameter.StaticType -eq [scriptblock] -or
                             (Test-DefinitionValueMayExposeScriptBlock $parameter.DefaultValue ([int]$parameter.Extent.StartOffset)))){
                            $null=$definitionScriptBlockParameters.Add((([string]$parameter.Name.VariablePath.UserPath -split ':')[-1]))
                        }
                    }
                }
                $assignments=@($Definition.Body.FindAll({param($node)
                    $node -is [Management.Automation.Language.AssignmentStatementAst] -and
                    $node.Left -is [Management.Automation.Language.VariableExpressionAst]
                },$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$Definition)}|Sort-Object {$_.Extent.StartOffset})
                $definitionProducerCommands=@($Definition.Body.FindAll({param($node)
                    $node -is [Management.Automation.Language.CommandAst] -and
                    ((Get-TransportCommandLeaf $node) -in @('set-variable','sv','new-variable','nv','set-item','si','new-item','ni','set-content','sc','add-content','ac') -or
                     (Get-TransportOutputVariableBindings $node).Present)
                },$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$Definition)}|Sort-Object {$_.Extent.StartOffset})
                $changed=$true
                while($changed){
                    $changed=$false
                    foreach($assignment in $assignments){
                        $name=[string]$assignment.Left.VariablePath.UserPath
                        $mayContain=Test-DefinitionValueMayExposeScriptBlock $assignment.Right ([int]$assignment.Extent.StartOffset)
                        if($assignment.Operator -ne [Management.Automation.Language.TokenKind]::Equals -and
                            (Test-DefinitionNameMayExposeScriptBlock $name ([int]$assignment.Extent.StartOffset) $assignment)){$mayContain=$true}
                        if(Set-DefinitionScriptBlockWrite $name ([int]$assignment.Extent.StartOffset) $mayContain $assignment){$changed=$true}
                    }
                    foreach($producerCommand in $definitionProducerCommands){
                        $producerLeaf=Get-TransportCommandLeaf $producerCommand
                        $outputBindings=Get-TransportOutputVariableBindings $producerCommand
                        if($outputBindings.Present){
                            if(-not $outputBindings.Valid){return $true}
                            foreach($outputBinding in @($outputBindings.Rows)){
                                $flow=Get-TransportPipelineCapabilitySources $producerCommand ([string]$outputBinding.Mode)
                                if(-not $flow.Valid){return $true}
                                $bindingMayContain=$false
                                foreach($source in @($flow.Sources)){
                                    if(Test-DefinitionValueMayExposeScriptBlock $source ([int]$producerCommand.Extent.StartOffset)){$bindingMayContain=$true;break}
                                }
                                if([string]$outputBinding.Kind -ceq 'OutVariable' -and $outputBinding.Append -and
                                    (Test-DefinitionNameMayExposeScriptBlock ([string]$outputBinding.Target) ([int]$producerCommand.Extent.StartOffset) $producerCommand)){$bindingMayContain=$true}
                                if($bindingMayContain -and [string]$outputBinding.Target -match '(?i)^(script|global):'){return $true}
                                if(Set-DefinitionScriptBlockWrite ([string]$outputBinding.Target) ([int]$producerCommand.Extent.StartOffset) $bindingMayContain $producerCommand){$changed=$true}
                                if([string]$outputBinding.Kind -ceq 'PipelineVariable'){
                                    $bindingPipeline=$producerCommand.Parent
                                    if($bindingPipeline -isnot [Management.Automation.Language.PipelineAst] -or
                                        (Test-TransportPipelineVariableBindingConflict $producerCommand ([string]$outputBinding.Target) 'Local')){return $true}
                                    if(Set-DefinitionScriptBlockWrite ([string]$outputBinding.Target) ([int]$bindingPipeline.Extent.StartOffset-1) $false $bindingPipeline){$changed=$true}
                                    if(Set-DefinitionScriptBlockWrite ([string]$outputBinding.Target) ([int]$bindingPipeline.Extent.EndOffset) $false $bindingPipeline){$changed=$true}
                                }
                            }
                            continue
                        }
                        $nameParameters=@($producerCommand.CommandElements|Where-Object{
                            if($_ -isnot [Management.Automation.Language.CommandParameterAst]){return $false}
                            $candidate=[string]$_.ParameterName
                            return @('Name','Path','LiteralPath'|Where-Object{$_.StartsWith($candidate,[StringComparison]::OrdinalIgnoreCase)}).Count -eq 1
                        })
                        $valueParameters=@($producerCommand.CommandElements|Where-Object{$_ -is [Management.Automation.Language.CommandParameterAst] -and 'Value'.StartsWith([string]$_.ParameterName,[StringComparison]::OrdinalIgnoreCase)})
                        $producerName=$null;$producerValue=$null
                        if($nameParameters.Count -eq 1 -and $valueParameters.Count -eq 1){
                            $producerName=Get-TransportCommandParameterArgument $producerCommand $nameParameters[0]
                            $producerValue=Get-TransportCommandParameterArgument $producerCommand $valueParameters[0]
                        }elseif($nameParameters.Count -eq 0 -and $valueParameters.Count -eq 0){
                            $plainProducerElements=@($producerCommand.CommandElements|Select-Object -Skip 1|Where-Object{$_ -isnot [Management.Automation.Language.CommandParameterAst]})
                            if($plainProducerElements.Count -ge 2){$producerName=$plainProducerElements[0];$producerValue=$plainProducerElements[1]}
                        }
                        if($producerName -isnot [Management.Automation.Language.StringConstantExpressionAst] -or $null -eq $producerValue){
                            if(@($producerCommand.CommandElements|Select-Object -Skip 1|Where-Object{Test-DefinitionValueMayExposeScriptBlock $_ ([int]$producerCommand.Extent.StartOffset)}).Count -ne 0){return $true}
                            continue
                        }
                        $producerTarget=[string]$producerName.Value
                        if($producerLeaf -notin @('set-variable','sv','new-variable','nv') -and $producerTarget -notmatch '(?i)^variable:'){continue}
                        $producerMayContain=Test-DefinitionValueMayExposeScriptBlock $producerValue ([int]$producerCommand.Extent.StartOffset)
                        if($producerLeaf -in @('add-content','ac') -and
                            (Test-DefinitionNameMayExposeScriptBlock $producerTarget ([int]$producerCommand.Extent.StartOffset) $producerCommand)){$producerMayContain=$true}
                        if(Set-DefinitionScriptBlockWrite $producerTarget ([int]$producerCommand.Extent.StartOffset) $producerMayContain $producerCommand){$changed=$true}
                    }
                }
                $returns=@($Definition.Body.FindAll({param($node)$node -is [Management.Automation.Language.ReturnStatementAst]},$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$Definition)})
                foreach($returnStatement in $returns){
                    if($null -ne $returnStatement.Pipeline -and (Test-DefinitionValueMayExposeScriptBlock $returnStatement.Pipeline ([int]$returnStatement.Extent.StartOffset))){return $true}
                }
                $implicitOutputs=@($Definition.Body.FindAll({param($node)
                    $node -is [Management.Automation.Language.PipelineAst] -and
                    ($node.Parent -is [Management.Automation.Language.NamedBlockAst] -or $node.Parent -is [Management.Automation.Language.StatementBlockAst])
                },$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$Definition)})
                foreach($output in $implicitOutputs){
                    if(Test-DefinitionValueMayExposeScriptBlock $output ([int]$output.Extent.StartOffset)){return $true}
                }
                return $false
            }finally{$null=$Visiting.Remove($key)}
        }
        function Test-TransportTopCommandOutputMayContainScriptBlock([Management.Automation.Language.CommandAst]$Command){
            if(Test-TransportTopValueMayContainScriptBlock $Command ([int]$Command.Extent.StartOffset)){return $true}
            $leaf=Get-TransportCommandLeaf $Command
            $definitions=@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $leaf -and $_.Extent.StartOffset -lt $Command.Extent.StartOffset})
            if($definitions.Count -gt 1){return $true}
            if($definitions.Count -eq 1){
                $binding=Get-TransportCommandArgumentBindings $Command $definitions[0]
                if(-not $binding.Valid){return $true}
                $capableParameters=[Collections.Generic.List[string]]::new()
                foreach($boundArgument in @($binding.Bindings)){
                    if(Test-TransportTopValueMayContainScriptBlock $boundArgument.Value ([int]$Command.Extent.StartOffset)){$capableParameters.Add([string]$boundArgument.Name)}
                }
                $visiting=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
                return Test-TransportDefinitionMayExposeScriptBlock $definitions[0] $visiting ([int]$Command.Extent.StartOffset) @($capableParameters) $Command @(@($binding.Bindings)|ForEach-Object{[string]$_.Name})
            }
            return $false
        }
        foreach($aliasAssignment in $aliasAssignments){
            $aliasName=(([string]$aliasAssignment.Left.VariablePath.UserPath -split ':')[-1])
            if($taintedTransportNames.Contains($aliasName)){continue}
            $rhsCommand=@($aliasAssignment.Right.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true)|Select-Object -First 1)
            if($rhsCommand.Count -ne 1){continue}
            $rhsLeaf=Get-TransportCommandLeaf $rhsCommand[0]
            $rhsDefinition=@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $rhsLeaf -and $_.Extent.StartOffset -lt $rhsCommand[0].Extent.StartOffset})
            if($rhsDefinition.Count -ne 1){continue}
            $returnedVariables=@($rhsDefinition[0].Body.FindAll({param($node)
                $node -is [Management.Automation.Language.VariableExpressionAst] -and
                $taintedTransportNames.Contains((([string]$node.VariablePath.UserPath -split ':')[-1]))
            },$true))
            if($returnedVariables.Count -ne 0){
                $null=$taintedTransportNames.Add($aliasName)
                if(@($returnedVariables|Where-Object{$taintedLaunchInputNames.Contains((([string]$_.VariablePath.UserPath -split ':')[-1]))}).Count -ne 0){$null=$taintedLaunchInputNames.Add($aliasName)}
            }
            $providerVisiting=[Collections.Generic.HashSet[int]]::new()
            if(Test-TransportDefinitionMayExposePsVariableProvider $rhsDefinition[0] $providerVisiting){
                $null=$psVariableProviderAliases.Add($aliasName)
            }
        }
        function Update-TransportTopScriptBlockAssignments {
            $scriptBlockChanged=$true
            while($scriptBlockChanged){
                $scriptBlockChanged=$false
                foreach($aliasAssignment in $aliasAssignments){
                    $aliasName=(([string]$aliasAssignment.Left.VariablePath.UserPath -split ':')[-1])
                    $mayContainScriptBlock=Test-TransportTopValueMayContainScriptBlock $aliasAssignment.Right ([int]$aliasAssignment.Extent.StartOffset)
                    if($aliasAssignment.Operator -ne [Management.Automation.Language.TokenKind]::Equals -and
                        (Test-TransportTopNameMayContainScriptBlock $aliasName ([int]$aliasAssignment.Extent.StartOffset) $aliasAssignment)){$mayContainScriptBlock=$true}
                    if(-not $mayContainScriptBlock){
                        $rhsCommand=$null
                        if($aliasAssignment.Right -is [Management.Automation.Language.PipelineAst]){
                            $pipelineElements=@($aliasAssignment.Right.PipelineElements)
                            if($pipelineElements.Count -eq 1 -and $pipelineElements[0] -is [Management.Automation.Language.CommandAst]){$rhsCommand=$pipelineElements[0]}
                        }
                        if($null -ne $rhsCommand){
                            $rhsLeaf=Get-TransportCommandLeaf $rhsCommand
                            $rhsDefinitions=@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $rhsLeaf -and $_.Extent.StartOffset -lt $rhsCommand.Extent.StartOffset})
                            if($rhsDefinitions.Count -gt 1){$mayContainScriptBlock=$true}
                            elseif($rhsDefinitions.Count -eq 1){
                                $binding=Get-TransportCommandArgumentBindings $rhsCommand $rhsDefinitions[0]
                                if(-not $binding.Valid){$mayContainScriptBlock=$true}
                                else{
                                    $capableParameters=[Collections.Generic.List[string]]::new()
                                    foreach($boundArgument in @($binding.Bindings)){
                                        if(Test-TransportTopValueMayContainScriptBlock $boundArgument.Value ([int]$rhsCommand.Extent.StartOffset)){$capableParameters.Add([string]$boundArgument.Name)}
                                    }
                                    $scriptBlockVisiting=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
                                    $mayContainScriptBlock=Test-TransportDefinitionMayExposeScriptBlock $rhsDefinitions[0] $scriptBlockVisiting ([int]$rhsCommand.Extent.StartOffset) @($capableParameters) $rhsCommand @(@($binding.Bindings)|ForEach-Object{[string]$_.Name})
                                }
                            }
                        }
                    }
                    if(Set-TransportScriptBlockCapabilityWrite $aliasName ([int]$aliasAssignment.Extent.StartOffset) $mayContainScriptBlock $aliasAssignment){$scriptBlockChanged=$true}
                }
            }
        }
        $null=Update-TransportTopScriptBlockAssignments
        function Get-TransportTopCommandArgument(
            [Management.Automation.Language.CommandAst]$Command,
            [Management.Automation.Language.CommandParameterAst]$Parameter){
            if($null -ne $Parameter.Argument){return $Parameter.Argument}
            $parameterIndex=[Array]::IndexOf(@($Command.CommandElements),$Parameter)
            if($parameterIndex -ge 0 -and $parameterIndex+1 -lt $Command.CommandElements.Count -and
                $Command.CommandElements[$parameterIndex+1] -isnot [Management.Automation.Language.CommandParameterAst]){return $Command.CommandElements[$parameterIndex+1]}
            return $null
        }
        $topScriptBlockVariableProducers=@($ast.FindAll({param($node)
            $node -is [Management.Automation.Language.CommandAst] -and
            ((Get-TransportCommandLeaf $node) -in @('set-variable','sv','new-variable','nv','set-item','si','new-item','ni','set-content','sc','add-content','ac') -or
             (Get-TransportOutputVariableBindings $node).Present)
        },$true)|Where-Object{
            $null -eq (Get-NearestHardKillFunction $_) -and [object]::ReferenceEquals((Get-NearestTransportScriptBlock $_),$ast) -and
            $_.Extent.StartOffset -lt $sectionIf.Extent.EndOffset
        }|Sort-Object {$_.Extent.StartOffset})
        foreach($producerCommand in $topScriptBlockVariableProducers){
            $producerLeaf=Get-TransportCommandLeaf $producerCommand
            $outputBindings=Get-TransportOutputVariableBindings $producerCommand
            if($outputBindings.Present){
                if(-not $outputBindings.Valid){throw 'preimage-transport-common-entry-launch-bypass'}
                foreach($outputBinding in @($outputBindings.Rows)){
                    $flow=Get-TransportPipelineCapabilitySources $producerCommand ([string]$outputBinding.Mode)
                    if(-not $flow.Valid){throw 'preimage-transport-common-entry-launch-bypass'}
                    $bindingMayContain=$false
                    foreach($source in @($flow.Sources)){
                        if($source -is [Management.Automation.Language.CommandAst]){
                            if(Test-TransportTopCommandOutputMayContainScriptBlock $source){$bindingMayContain=$true;break}
                        }elseif(Test-TransportTopValueMayContainScriptBlock $source ([int]$producerCommand.Extent.StartOffset)){$bindingMayContain=$true;break}
                    }
                    if([string]$outputBinding.Kind -ceq 'OutVariable' -and $outputBinding.Append -and
                        (Test-TransportTopNameMayContainScriptBlock ([string]$outputBinding.Target) ([int]$producerCommand.Extent.StartOffset) $producerCommand)){$bindingMayContain=$true}
                    $null=Set-TransportScriptBlockCapabilityWrite ([string]$outputBinding.Target) ([int]$producerCommand.Extent.StartOffset) $bindingMayContain $producerCommand
                    if([string]$outputBinding.Kind -ceq 'PipelineVariable'){
                        $bindingPipeline=$producerCommand.Parent
                        if($bindingPipeline -isnot [Management.Automation.Language.PipelineAst] -or
                            (Test-TransportPipelineVariableBindingConflict $producerCommand ([string]$outputBinding.Target) 'Top')){
                            throw 'preimage-transport-common-entry-launch-bypass'
                        }
                        $null=Set-TransportScriptBlockCapabilityWrite ([string]$outputBinding.Target) ([int]$bindingPipeline.Extent.StartOffset-1) $false $bindingPipeline
                        $null=Set-TransportScriptBlockCapabilityWrite ([string]$outputBinding.Target) ([int]$bindingPipeline.Extent.EndOffset) $false $bindingPipeline
                    }
                }
                continue
            }
            $nameParameters=@($producerCommand.CommandElements|Where-Object{
                if($_ -isnot [Management.Automation.Language.CommandParameterAst]){return $false}
                $candidate=[string]$_.ParameterName
                return @('Name','Path','LiteralPath'|Where-Object{$_.StartsWith($candidate,[StringComparison]::OrdinalIgnoreCase)}).Count -eq 1
            })
            $valueParameters=@($producerCommand.CommandElements|Where-Object{$_ -is [Management.Automation.Language.CommandParameterAst] -and 'Value'.StartsWith([string]$_.ParameterName,[StringComparison]::OrdinalIgnoreCase)})
            if($nameParameters.Count -eq 1 -and $valueParameters.Count -eq 1){
                $producerName=Get-TransportTopCommandArgument $producerCommand $nameParameters[0]
                $producerValue=Get-TransportTopCommandArgument $producerCommand $valueParameters[0]
            }elseif($nameParameters.Count -eq 0 -and $valueParameters.Count -eq 0){
                $plainProducerElements=@($producerCommand.CommandElements|Select-Object -Skip 1|Where-Object{$_ -isnot [Management.Automation.Language.CommandParameterAst]})
                if($plainProducerElements.Count -lt 2){continue}
                $producerName=$plainProducerElements[0];$producerValue=$plainProducerElements[1]
            }else{continue}
            if($producerName -isnot [Management.Automation.Language.StringConstantExpressionAst] -or $null -eq $producerValue){continue}
            $producerTarget=[string]$producerName.Value
            if($producerLeaf -notin @('set-variable','sv','new-variable','nv') -and $producerTarget -notmatch '(?i)^variable:'){continue}
            $producerMayContainScriptBlock=Test-TransportTopValueMayContainScriptBlock $producerValue ([int]$producerCommand.Extent.StartOffset)
            if($producerLeaf -in @('add-content','ac') -and
                (Test-TransportTopNameMayContainScriptBlock $producerTarget ([int]$producerCommand.Extent.StartOffset) $producerCommand)){$producerMayContainScriptBlock=$true}
            $null=Set-TransportScriptBlockCapabilityWrite $producerTarget ([int]$producerCommand.Extent.StartOffset) $producerMayContainScriptBlock $producerCommand
        }
        $null=Update-TransportTopScriptBlockAssignments
        $safeSyntheticExternalCommands=@(
            'add-member','foreach-object','get-variable','out-null','set-variable','where-object','write-output','tee-object',
            'invoke-expression','iex','invoke-command','icm','import-module','new-module','set-alias','new-alias','remove-alias','import-alias','sal','nal','ral','ipal',
            'set-item','new-item','remove-item','clear-item','move-item','copy-item','rename-item','si','ni','ri','cli','mi','cpi','rni',
            'new-variable','remove-variable','clear-variable','sv','nv','rv','clv','set-content','add-content','clear-content','sc','ac','clc',
            'set-itemproperty','new-itemproperty','remove-itemproperty','rename-itemproperty','copy-itemproperty','move-itemproperty','clear-itemproperty','sp','np','rp','rnp','cp','mp','clp')
        $visitedTransportDefinitions=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        function Get-TransportUnwrappedExpression([Management.Automation.Language.Ast]$Node){
            $current=$Node
            while($null -ne $current){
                if($current -is [Management.Automation.Language.CommandExpressionAst]){$current=$current.Expression;continue}
                if($current -is [Management.Automation.Language.ConvertExpressionAst]){$current=$current.Child;continue}
                if($current -is [Management.Automation.Language.ParenExpressionAst]){
                    $elements=@($current.Pipeline.PipelineElements)
                    if($elements.Count -eq 1 -and $elements[0] -is [Management.Automation.Language.CommandExpressionAst]){$current=$elements[0].Expression;continue}
                }
                break
            }
            return $current
        }
        function Resolve-TransportScriptBlockValue(
            [Management.Automation.Language.Ast]$Value,
            [int]$BeforeOffset,
            [Collections.Generic.HashSet[string]]$Resolving){
            $candidate=Get-TransportUnwrappedExpression $Value
            if($candidate -is [Management.Automation.Language.ScriptBlockExpressionAst]){return $candidate.ScriptBlock}
            if($candidate -is [Management.Automation.Language.InvokeMemberExpressionAst] -and -not $candidate.Static -and
                $candidate.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and
                [string]$candidate.Member.Value -ceq 'GetNewClosure' -and @($candidate.Arguments).Count -eq 0){
                return Resolve-TransportScriptBlockValue $candidate.Expression $BeforeOffset $Resolving
            }
            return $null
        }
        function Test-TransportReachableRegion(
            [Management.Automation.Language.Ast]$Boundary,
            [int]$DefinitionCutoff,
            [string[]]$TaintedNames,
            [string[]]$PsVariableProviderNames=@(),
            [string[]]$ScriptBlockNames=@(),
            [Management.Automation.Language.Ast]$InvocationAst=$null,
            [ValidateSet('Top','Local')][string]$CapabilityFrame='Top',
            [string[]]$PipelineScriptBlockNames=@(),
            [string[]]$PipelineBoundParameterNames=@()){
            $binding=$null
            $regionTaint=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $incomingRegionTaint=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $regionLocalTaint=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            foreach($taintedName in @($TaintedNames)){
                $taintedLeaf=(($taintedName -split ':')[-1])
                $null=$incomingRegionTaint.Add($taintedLeaf)
                $null=$regionTaint.Add($taintedLeaf)
            }
            foreach($ambientName in @($taintedTransportNames)){$null=$regionTaint.Add((($ambientName -split ':')[-1]))}
            if($CapabilityFrame -ceq 'Top'){
                foreach($topTaintedName in @($topRegionTaint)){$null=$regionTaint.Add($topTaintedName)}
            }
            $regionPsVariableAliases=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            foreach($providerAlias in @($psVariableProviderAliases)){$null=$regionPsVariableAliases.Add($providerAlias)}
            foreach($providerName in @($PsVariableProviderNames)){$null=$regionPsVariableAliases.Add((($providerName -split ':')[-1]))}
            if($CapabilityFrame -ceq 'Top'){
                foreach($topProviderName in @($topRegionPsVariableProviders)){$null=$regionPsVariableAliases.Add($topProviderName)}
            }
            $regionScriptBlockNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $regionScriptBlockWrites=@{}
            $regionPipelineScriptBlockNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            foreach($pipelineScriptBlockName in @($PipelineScriptBlockNames)){
                $null=$regionPipelineScriptBlockNames.Add((Get-TransportCapabilityKey $pipelineScriptBlockName $CapabilityFrame))
            }
            $regionPipelineBoundParameterNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            foreach($pipelineBoundName in @($PipelineBoundParameterNames)){
                $null=$regionPipelineBoundParameterNames.Add((Get-TransportCapabilityKey $pipelineBoundName $CapabilityFrame))
            }
            $boundaryParameterNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            if($Boundary -is [Management.Automation.Language.ScriptBlockAst] -and $null -ne $Boundary.ParamBlock){
                foreach($boundaryParameter in @($Boundary.ParamBlock.Parameters)){
                    $null=$boundaryParameterNames.Add((([string]$boundaryParameter.Name.VariablePath.UserPath -split ':')[-1]))
                }
            }
            function Set-RegionScriptBlockWrite([string]$Name,[int]$Offset,[bool]$MayContain,[Management.Automation.Language.Ast]$WriteAst=$null){
                $leaf=Get-TransportCapabilityKey $Name $CapabilityFrame
                if([string]::IsNullOrEmpty($leaf)){return $false}
                if(-not $regionScriptBlockWrites.ContainsKey($leaf)){$regionScriptBlockWrites[$leaf]=[Collections.Generic.List[object]]::new()}
                $rows=[Collections.Generic.List[object]]$regionScriptBlockWrites[$leaf]
                $existing=@($rows|Where-Object{[int]$_.Offset -eq $Offset})
                if($existing.Count -gt 1){throw 'preimage-transport-common-entry-launch-bypass'}
                if($existing.Count -eq 1){
                    if([bool]$existing[0].MayContain -eq $MayContain){return $false}
                    $existing[0].MayContain=$MayContain;$existing[0].WriteAst=$WriteAst
                }
                else{$rows.Add([pscustomobject]@{Offset=$Offset;MayContain=$MayContain;WriteAst=$WriteAst})}
                if($MayContain){$null=$regionScriptBlockNames.Add($leaf)}
                return $true
            }
            function Publish-RegionNonLocalScriptBlockCapability(
                [string]$Name,
                [bool]$MayContain,
                [Management.Automation.Language.Ast]$WriteAst){
                if(-not $MayContain -or [string]::IsNullOrEmpty($Name) -or $Name -notmatch '(?i)^(script|global):'){return}
                $publishAst=if($CapabilityFrame -ceq 'Local' -and $null -ne $InvocationAst){$InvocationAst}else{$WriteAst}
                $publishOffset=if($null -ne $publishAst){[int]$publishAst.Extent.StartOffset}else{$DefinitionCutoff}
                $null=Set-TransportScriptBlockCapabilityWrite $Name $publishOffset $true $publishAst
            }
            function Test-RegionNameMayContainScriptBlock([string]$Name,[int]$BeforeOffset,[Management.Automation.Language.Ast]$UseAst=$null){
                $leaf=Get-TransportCapabilityKey $Name $CapabilityFrame
                if([string]::IsNullOrEmpty($leaf)){return $false}
                $useCursor=$UseAst;$inBegin=$false
                while($null -ne $useCursor -and -not[object]::ReferenceEquals($useCursor,$Boundary)){
                    if($Boundary -is [Management.Automation.Language.ScriptBlockAst] -and $null -ne $Boundary.BeginBlock -and
                        [object]::ReferenceEquals($useCursor,$Boundary.BeginBlock)){$inBegin=$true;break}
                    $useCursor=$useCursor.Parent
                }
                $pipelineBound=$regionPipelineBoundParameterNames.Contains($leaf) -and -not $inBegin
                $pipelineMayContain=$pipelineBound -and $regionPipelineScriptBlockNames.Contains($leaf)
                if($regionScriptBlockWrites.ContainsKey($leaf)){
                    $prior=@($regionScriptBlockWrites[$leaf]|Where-Object{[int]$_.Offset -lt $BeforeOffset}|Sort-Object {[int]$_.Offset} -Descending)
                    foreach($write in $prior){
                        if([int]$write.Offset -eq [int]::MinValue){if($pipelineBound){return $pipelineMayContain};return [bool]$write.MayContain}
                        if([bool]$write.MayContain){return $true}
                        if(
                        (Test-TransportWriteDominatesUse $write.WriteAst $UseAst $(if($Boundary -is [Management.Automation.Language.ScriptBlockAst]){$Boundary}else{$null}) $BeforeOffset)){return $false}
                    }
                }
                if($pipelineBound){return $pipelineMayContain}
                if($isInvokedScriptBlock){return $false}
                return Test-TransportTopNameMayContainScriptBlock $Name $DefinitionCutoff $UseAst
            }
            function Get-RegionActiveScriptBlockNames([int]$BeforeOffset,[Management.Automation.Language.Ast]$UseAst=$null){
                $active=[Collections.Generic.List[string]]::new()
                foreach($name in @($regionScriptBlockWrites.Keys|Sort-Object)){
                    if(Test-RegionNameMayContainScriptBlock $name $BeforeOffset $UseAst){$null=$active.Add([string]$name)}
                }
                return @($active)
            }
            $incomingScriptBlockNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            foreach($scriptBlockName in @($ScriptBlockNames)){$null=$incomingScriptBlockNames.Add((Get-TransportCapabilityKey $scriptBlockName $CapabilityFrame))}
            $regionEntryCutoff=if($Boundary -is [Management.Automation.Language.ScriptBlockAst]){$DefinitionCutoff}else{[int]$Boundary.Extent.StartOffset}
            $regionEntryUseAst=if($null -ne $InvocationAst){$InvocationAst}else{$Boundary}
            $isInvokedScriptBlock=$Boundary -is [Management.Automation.Language.ScriptBlockAst] -and
                $Boundary.Parent -is [Management.Automation.Language.ScriptBlockExpressionAst] -and $null -ne $InvocationAst
            if(-not $isInvokedScriptBlock){
                foreach($scriptBlockName in @($scriptBlockCapabilityWrites.Keys)){
                    $leaf=(($scriptBlockName -split ':')[-1])
                    if(-not $boundaryParameterNames.Contains($leaf) -and
                        (Test-TransportTopNameMayContainScriptBlock $scriptBlockName $regionEntryCutoff $regionEntryUseAst)){
                        $null=Set-RegionScriptBlockWrite $scriptBlockName ([int]::MinValue) $true
                        if([string]$scriptBlockName -notmatch '^(?i)(script|global):'){
                            $null=Set-RegionScriptBlockWrite ('script:{0}' -f $leaf) ([int]::MinValue) $true
                        }
                    }
                }
            }
            foreach($scriptBlockName in @($incomingScriptBlockNames)){
                if(-not $boundaryParameterNames.Contains($scriptBlockName)){$null=Set-RegionScriptBlockWrite $scriptBlockName ([int]::MinValue) $true}
            }
            $regionPsVariableObjects=@{}
            if($CapabilityFrame -ceq 'Top'){
                foreach($topObjectName in @($topRegionPsVariableObjects.Keys)){$regionPsVariableObjects[$topObjectName]=$topRegionPsVariableObjects[$topObjectName]}
            }
            function Test-RegionPsVariableProvider([Management.Automation.Language.Ast]$Node){
                $candidate=Get-TransportUnwrappedExpression $Node
                if((Get-HardKillAstTextCompact -Ast $candidate) -ieq '$ExecutionContext.SessionState.PSVariable'){return $true}
                $storageRoot=Get-TransportStorageRootName $candidate
                if(-not[string]::IsNullOrEmpty($storageRoot)){return $regionPsVariableAliases.Contains((Get-TransportCapabilityKey $storageRoot $CapabilityFrame))}
                return $false
            }
            function Get-RegionDirectPsVariableObjectTarget([Management.Automation.Language.Ast]$Node){
                $candidate=Get-TransportUnwrappedExpression $Node
                if($candidate -is [Management.Automation.Language.VariableExpressionAst]){
                    $objectKey=Get-TransportCapabilityKey ([string]$candidate.VariablePath.UserPath) $CapabilityFrame
                    if($regionPsVariableObjects.ContainsKey($objectKey)){return [string]$regionPsVariableObjects[$objectKey]}
                }
                if($candidate -is [Management.Automation.Language.InvokeMemberExpressionAst] -and -not $candidate.Static -and
                    $candidate.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and
                    [string]$candidate.Member.Value -ieq 'Get' -and (Test-RegionPsVariableProvider $candidate.Expression)){
                    if(@($candidate.Arguments).Count -ne 1 -or $candidate.Arguments[0] -isnot [Management.Automation.Language.StringConstantExpressionAst]){return '__DYNAMIC__'}
                    return [string]$candidate.Arguments[0].Value
                }
                if($candidate -is [Management.Automation.Language.ParenExpressionAst]){
                    $elements=@($candidate.Pipeline.PipelineElements)
                    if($elements.Count -eq 1 -and $elements[0] -is [Management.Automation.Language.CommandAst]){
                        return Get-TransportGetVariableTarget $elements[0] $false
                    }
                }
                return $null
            }
            function Test-RegionAstTainted([Management.Automation.Language.Ast]$Node){
                if(@($Node.FindAll({param($child)$child -is [Management.Automation.Language.VariableExpressionAst] -and
                    $regionTaint.Contains((([string]$child.VariablePath.UserPath -split ':')[-1]))},$true)).Count -ne 0){return $true}
                $variableTarget=Get-RegionPsVariableTarget $Node
                return $variableTarget -ceq '__DYNAMIC__' -or ($null -ne $variableTarget -and $regionTaint.Contains((($variableTarget -split ':')[-1])))
            }
            function Test-RegionMayContainScriptBlock([object]$Node,[int]$BeforeOffset=[int]::MaxValue){
                if($null -eq $Node){return $false}
                if($Node -isnot [Management.Automation.Language.Ast] -and
                    $null -ne $Node.PSObject.Properties['TransportFlowKind'] -and
                    [string]$Node.TransportFlowKind -ceq 'CallableOutput'){
                    $binding=Get-TransportCommandArgumentBindings $Node.Command $Node.Definition
                    if(-not $binding.Valid){return $true}
                    $capableParameters=[Collections.Generic.List[string]]::new()
                    foreach($boundArgument in @($binding.Bindings)){
                        if(Test-RegionMayContainScriptBlock $boundArgument.Value ([int]$Node.Command.Extent.StartOffset)){$capableParameters.Add([string]$boundArgument.Name)}
                    }
                    $pipelineMayContain=$false
                    foreach($pipelineInput in @($Node.PipelineInputs)){
                        if(Test-RegionMayContainScriptBlock $pipelineInput ([int]$Node.Command.Extent.StartOffset)){$pipelineMayContain=$true;break}
                    }
                    $pipelineCapableParameters=[Collections.Generic.List[string]]::new()
                    $pipelineBoundParameters=[Collections.Generic.List[string]]::new()
                    if(@($Node.PipelineInputs).Count -ne 0){
                        foreach($automaticName in @('_','PSItem','input')){$pipelineBoundParameters.Add($automaticName)}
                        foreach($parameterName in @($Node.PipelineParameterNames|Where-Object{[string]$_ -inotin @(@($binding.Bindings)|ForEach-Object{[string]$_.Name})})){$pipelineBoundParameters.Add([string]$parameterName)}
                    }
                    if($pipelineMayContain){
                        foreach($pipelineBoundParameter in @($pipelineBoundParameters)){$pipelineCapableParameters.Add([string]$pipelineBoundParameter)}
                    }
                    $boundNames=@(@($binding.Bindings)|ForEach-Object{[string]$_.Name})+@($Node.PipelineParameterNames)
                    $flowVisiting=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
                    return Test-TransportDefinitionMayExposeScriptBlock $Node.Definition $flowVisiting ([int]$Node.Command.Extent.StartOffset) @($capableParameters) $Node.Command @($boundNames) @($pipelineCapableParameters) @($pipelineBoundParameters)
                }
                if($Node -is [Management.Automation.Language.CommandExpressionAst]){return Test-RegionMayContainScriptBlock $Node.Expression $BeforeOffset}
                if($Node -is [Management.Automation.Language.ConvertExpressionAst]){
                    if([string]$Node.Type.TypeName.FullName -iin @('scriptblock','System.Management.Automation.ScriptBlock')){return $true}
                    return Test-RegionMayContainScriptBlock $Node.Child $BeforeOffset
                }
                if($Node -is [Management.Automation.Language.ScriptBlockExpressionAst]){return $true}
                if($Node -is [Management.Automation.Language.VariableExpressionAst]){
                    $objectTarget=Get-RegionDirectPsVariableObjectTarget $Node
                    if($null -ne $objectTarget){
                        if($objectTarget -ceq '__DYNAMIC__'){return $true}
                        return Test-RegionNameMayContainScriptBlock $objectTarget $BeforeOffset $Node
                    }
                    return Test-RegionNameMayContainScriptBlock ([string]$Node.VariablePath.UserPath) $BeforeOffset $Node
                }
                if($Node -is [Management.Automation.Language.ParenExpressionAst]){
                    return Test-RegionMayContainScriptBlock $Node.Pipeline $BeforeOffset
                }
                if($Node -is [Management.Automation.Language.PipelineAst]){
                    $elements=@($Node.PipelineElements)
                    if($elements.Count -eq 0){return $false}
                    $last=$elements[-1]
                    if(Test-TransportReviewedOutNullCommand $last){return $false}
                    if($last -isnot [Management.Automation.Language.CommandAst]){return Test-RegionMayContainScriptBlock $last $BeforeOffset}
                    $flow=Get-TransportPipelineCapabilitySources $last 'CommandOutput'
                    if(-not $flow.Valid){return $true}
                    foreach($source in @($flow.Sources)){if(Test-RegionMayContainScriptBlock $source $BeforeOffset){return $true}}
                    return $false
                }
                if($Node -is [Management.Automation.Language.HashtableAst]){
                    foreach($pair in @($Node.KeyValuePairs)){if(Test-RegionMayContainScriptBlock $pair.Item2 $BeforeOffset){return $true}}
                    return $false
                }
                if($Node -is [Management.Automation.Language.ArrayLiteralAst]){
                    foreach($element in @($Node.Elements)){if(Test-RegionMayContainScriptBlock $element $BeforeOffset){return $true}}
                    return $false
                }
                if($Node -is [Management.Automation.Language.ArrayExpressionAst]){return Test-RegionMayContainScriptBlock $Node.SubExpression $BeforeOffset}
                if($Node -is [Management.Automation.Language.StatementBlockAst]){
                    foreach($statement in @($Node.Statements)){if(Test-RegionMayContainScriptBlock $statement $BeforeOffset){return $true}}
                    return $false
                }
                if($Node -is [Management.Automation.Language.IndexExpressionAst]){return Test-RegionMayContainScriptBlock $Node.Target $BeforeOffset}
                if($Node -is [Management.Automation.Language.MemberExpressionAst] -and $Node -isnot [Management.Automation.Language.InvokeMemberExpressionAst]){
                    if(Test-TransportExpressionContainsCallableResult $Node.Expression){return $true}
                    $memberName=if($Node.Member -is [Management.Automation.Language.StringConstantExpressionAst]){[string]$Node.Member.Value}else{''}
                    $objectTarget=Get-RegionDirectPsVariableObjectTarget $Node.Expression
                    if($null -ne $objectTarget -and $memberName -ieq 'Name'){return $false}
                    if($Node.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and [string]$Node.Member.Value -ieq 'Value'){
                        $valueExpression=Get-TransportUnwrappedExpression $Node.Expression
                        if($null -ne $objectTarget){
                            if($objectTarget -ceq '__DYNAMIC__'){return $true}
                            return Test-RegionNameMayContainScriptBlock $objectTarget $BeforeOffset $Node
                        }
                        if($valueExpression -is [Management.Automation.Language.VariableExpressionAst]){
                            $objectName=(([string]$valueExpression.VariablePath.UserPath -split ':')[-1])
                            if($regionPsVariableObjects.ContainsKey($objectName)){
                                $target=[string]$regionPsVariableObjects[$objectName]
                                if($target -ceq '__DYNAMIC__'){return $true}
                                return Test-RegionNameMayContainScriptBlock $target $BeforeOffset $Node
                            }
                        }
                        if($valueExpression -is [Management.Automation.Language.InvokeMemberExpressionAst] -and -not $valueExpression.Static -and
                            $valueExpression.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and [string]$valueExpression.Member.Value -ieq 'Get' -and
                            (Test-RegionPsVariableProvider $valueExpression.Expression)){
                            if(@($valueExpression.Arguments).Count -ne 1 -or $valueExpression.Arguments[0] -isnot [Management.Automation.Language.StringConstantExpressionAst]){return $true}
                            return Test-RegionNameMayContainScriptBlock ([string]$valueExpression.Arguments[0].Value) $BeforeOffset $Node
                        }
                        if($valueExpression -is [Management.Automation.Language.ParenExpressionAst]){
                            $valueElements=@($valueExpression.Pipeline.PipelineElements)
                            if($valueElements.Count -eq 1 -and $valueElements[0] -is [Management.Automation.Language.CommandAst]){
                                $target=Get-TransportGetVariableTarget $valueElements[0] $false
                                if($target -ceq '__DYNAMIC__'){return $true}
                                if($null -ne $target){return Test-RegionNameMayContainScriptBlock $target $BeforeOffset $Node}
                            }
                        }
                    }
                    return Test-RegionMayContainScriptBlock $Node.Expression $BeforeOffset
                }
                if($Node -is [Management.Automation.Language.InvokeMemberExpressionAst]){
                    if($Node.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and [string]$Node.Member.Value -ieq 'GetNewClosure'){
                        return Test-RegionMayContainScriptBlock $Node.Expression $BeforeOffset
                    }
                    if(-not $Node.Static -and $Node.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and
                        [string]$Node.Member.Value -ieq 'Get' -and (Test-RegionPsVariableProvider $Node.Expression)){
                        if(@($Node.Arguments).Count -ne 1 -or $Node.Arguments[0] -isnot [Management.Automation.Language.StringConstantExpressionAst]){return $true}
                        return Test-RegionNameMayContainScriptBlock ([string]$Node.Arguments[0].Value) $BeforeOffset $Node
                    }
                    return $false
                }
                if($Node -is [Management.Automation.Language.CommandAst]){
                    $scriptLeaf=Get-TransportCommandLeaf $Node
                    if($scriptLeaf -in @('get-variable','gv')){
                        $target=Get-TransportGetVariableTarget $Node $true
                        if($target -ceq '__DYNAMIC__'){return $true}
                        if($null -ne $target){return Test-RegionNameMayContainScriptBlock $target $BeforeOffset $Node}
                    }
                    if($scriptLeaf -in @('write-output','write','echo')){
                        foreach($element in @($Node.CommandElements|Select-Object -Skip 1)){
                            if($element -is [Management.Automation.Language.CommandParameterAst]){
                                if($null -ne $element.Argument -and (Test-RegionMayContainScriptBlock $element.Argument $BeforeOffset)){return $true}
                                continue
                            }
                            if(Test-RegionMayContainScriptBlock $element $BeforeOffset){return $true}
                        }
                    }
                    $scriptDefinitions=@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $scriptLeaf -and $_.Extent.StartOffset -lt $Node.Extent.StartOffset})
                    if($scriptDefinitions.Count -gt 1){return $true}
                    if($scriptDefinitions.Count -eq 1){
                        $binding=Get-TransportCommandArgumentBindings $Node $scriptDefinitions[0]
                        if(-not $binding.Valid){return $true}
                        $capableParameters=[Collections.Generic.List[string]]::new()
                        foreach($boundArgument in @($binding.Bindings)){
                            if(Test-RegionMayContainScriptBlock $boundArgument.Value ([int]$Node.Extent.StartOffset)){$capableParameters.Add([string]$boundArgument.Name)}
                        }
                        $scriptVisiting=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
                        if(Test-TransportDefinitionMayExposeScriptBlock $scriptDefinitions[0] $scriptVisiting ([int]$Node.Extent.StartOffset) @($capableParameters) $Node @(@($binding.Bindings)|ForEach-Object{[string]$_.Name})){return $true}
                    }
                }
                return $false
            }
            function Test-RegionReceiverMayContainScriptBlock([Management.Automation.Language.Ast]$Node,[int]$BeforeOffset=[int]::MaxValue){
                return Test-RegionMayContainScriptBlock $Node $BeforeOffset
            }
            function Test-RegionRefExpression([Management.Automation.Language.Ast]$Node){
                if($null -eq $Node){return $false}
                return @($Node.FindAll({param($child)
                    $child -is [Management.Automation.Language.ConvertExpressionAst] -and
                    [string]$child.Type.TypeName.FullName -ieq 'ref'
                },$true)).Count -ne 0
            }
            if($Boundary -is [Management.Automation.Language.ScriptBlockAst] -and $null -ne $Boundary.ParamBlock){
                foreach($regionParameter in @($Boundary.ParamBlock.Parameters)){
                    $parameterName=(([string]$regionParameter.Name.VariablePath.UserPath -split ':')[-1])
                    $parameterMayContain=$incomingScriptBlockNames.Contains($parameterName) -or
                        ($null -ne $regionParameter.DefaultValue -and
                         ($regionParameter.StaticType -eq [scriptblock] -or
                          (Test-RegionMayContainScriptBlock $regionParameter.DefaultValue ([int]$regionParameter.Extent.StartOffset))))
                    $null=Set-RegionScriptBlockWrite $parameterName ([int]::MinValue) $parameterMayContain
                }
            }
            function Throw-RegionTaintedWrite([string]$Target){
                $leaf=(($Target -split ':')[-1])
                if($taintedLaunchInputNames.Contains($leaf)){throw 'preimage-transport-launch-input-provenance'}
                if($leaf -ieq 'cases'){throw 'preimage-transport-cases-provenance'}
                if($leaf -ieq 'reviewedMutationEnginePath'){throw 'preimage-transport-engine-provenance'}
                throw 'preimage-transport-owner-shadow'
            }
            function Get-RegionParameterArgument([Management.Automation.Language.CommandAst]$Command,[Management.Automation.Language.CommandParameterAst]$Parameter){
                if($null -ne $Parameter.Argument){return $Parameter.Argument}
                $parameterIndex=[Array]::IndexOf(@($Command.CommandElements),$Parameter)
                if($parameterIndex -ge 0 -and $parameterIndex+1 -lt $Command.CommandElements.Count -and
                    $Command.CommandElements[$parameterIndex+1] -isnot [Management.Automation.Language.CommandParameterAst]){return $Command.CommandElements[$parameterIndex+1]}
                return $null
            }
            function Get-RegionCommonParameterRole([string]$Candidate){
                if([string]::IsNullOrEmpty($Candidate)){return ''}
                $aliases=@{'db'='Debug';'ea'='ErrorAction';'ev'='ErrorVariable';'infa'='InformationAction';'iv'='InformationVariable';'ob'='OutBuffer';'ov'='OutVariable';'pv'='PipelineVariable';'proga'='ProgressAction';'vb'='Verbose';'wa'='WarningAction';'wv'='WarningVariable'}
                if($aliases.ContainsKey($Candidate)){return [string]$aliases[$Candidate]}
                $known=@('Debug','ErrorAction','ErrorVariable','InformationAction','InformationVariable','OutBuffer','OutVariable','PipelineVariable','ProgressAction','Verbose','WarningAction','WarningVariable','WhatIf','Confirm')
                $roleMatches=@($known|Where-Object{$_.StartsWith($Candidate,[StringComparison]::OrdinalIgnoreCase)})
                return $(if($roleMatches.Count -eq 1){[string]$roleMatches[0]}else{''})
            }
            function Test-RegionSupportsShouldProcess([Management.Automation.Language.FunctionDefinitionAst]$Definition){
                if($null -eq $Definition.Body.ParamBlock){return $false}
                foreach($attribute in @($Definition.Body.ParamBlock.Attributes|Where-Object{[string]$_.TypeName.FullName -iin @('CmdletBinding','CmdletBindingAttribute','System.Management.Automation.CmdletBindingAttribute')})){
                    foreach($namedArgument in @($attribute.NamedArguments|Where-Object{[string]$_.ArgumentName -ieq 'SupportsShouldProcess'})){
                        if($namedArgument.ExpressionOmitted){return $true}
                        $value=Get-TransportStaticHashtableValue $namedArgument.Argument
                        if($value -is [Management.Automation.Language.VariableExpressionAst] -and [string]$value.VariablePath.UserPath -ieq 'true'){return $true}
                        if($value -is [Management.Automation.Language.ConstantExpressionAst] -and $value.Value -is [bool] -and [bool]$value.Value){return $true}
                    }
                }
                return $false
            }
            function Get-RegionLiteralTarget([Management.Automation.Language.CommandAst]$Command){
                $expectsValue=$false
                for($targetIndex=1;$targetIndex -lt $Command.CommandElements.Count;$targetIndex++){
                    $targetElement=$Command.CommandElements[$targetIndex]
                    if($targetElement -is [Management.Automation.Language.CommandParameterAst]){
                        if($targetElement.ParameterName -iin @('Name','Path','LiteralPath','Variable')){
                            $attached=Get-RegionParameterArgument $Command $targetElement
                            if($null -ne $attached){if($attached -is [Management.Automation.Language.StringConstantExpressionAst]){return [string]$attached.Value};return ''}
                            $expectsValue=$true
                        }
                        continue
                    }
                    if($expectsValue -or $targetIndex -eq 1){if($targetElement -is [Management.Automation.Language.StringConstantExpressionAst]){return [string]$targetElement.Value};return ''}
                }
                return ''
            }
            function Get-RegionPsVariableTarget([Management.Automation.Language.Ast]$Node){
                $storageRoot=Get-TransportStorageRootName $Node
                if(-not[string]::IsNullOrEmpty($storageRoot)){
                    $storageLeaf=(($storageRoot -split ':')[-1])
                    if($regionPsVariableObjects.ContainsKey($storageLeaf)){return [string]$regionPsVariableObjects[$storageLeaf]}
                }
                $memberCalls=@($Node.FindAll({param($child)
                    $child -is [Management.Automation.Language.InvokeMemberExpressionAst] -and -not $child.Static -and
                    $child.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and [string]$child.Member.Value -ieq 'Get'
                },$true))
                foreach($memberCall in $memberCalls){
                    $providerCompact=Get-HardKillAstTextCompact -Ast $memberCall.Expression
                    $providerAliasMatch=Test-RegionPsVariableProvider $memberCall.Expression
                    if($providerCompact -ieq '$ExecutionContext.SessionState.PSVariable' -or $providerAliasMatch){
                        if(@($memberCall.Arguments).Count -ne 1 -or $memberCall.Arguments[0] -isnot [Management.Automation.Language.StringConstantExpressionAst]){return '__DYNAMIC__'}
                        return [string]$memberCall.Arguments[0].Value
                    }
                }
                $getCommands=@($Node.FindAll({param($child)$child -is [Management.Automation.Language.CommandAst] -and
                    (Get-TransportCommandLeaf $child) -in @('get-variable','gv')},$true))
                if($getCommands.Count -ne 0){
                    if($getCommands.Count -ne 1){return '__DYNAMIC__'}
                    $target=Get-RegionLiteralTarget $getCommands[0]
                    return $(if([string]::IsNullOrEmpty($target)){'__DYNAMIC__'}else{$target})
                }
                if($Node -is [Management.Automation.Language.VariableExpressionAst]){
                    $objectName=(([string]$Node.VariablePath.UserPath -split ':')[-1])
                    if($regionPsVariableObjects.ContainsKey($objectName)){return [string]$regionPsVariableObjects[$objectName]}
                }
                if($Node -is [Management.Automation.Language.MemberExpressionAst] -and
                    $Node.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and [string]$Node.Member.Value -ieq 'Value' -and
                    $null -ne $Node.Expression){
                    $objectExpression=Get-TransportUnwrappedExpression $Node.Expression
                    if($objectExpression -is [Management.Automation.Language.VariableExpressionAst]){
                        $objectName=(([string]$objectExpression.VariablePath.UserPath -split ':')[-1])
                        if($regionPsVariableObjects.ContainsKey($objectName)){return [string]$regionPsVariableObjects[$objectName]}
                    }
                }
                return $null
            }
            $regionAssignments=@($Boundary.FindAll({param($node)$node -is [Management.Automation.Language.AssignmentStatementAst]},$true)|Where-Object{Test-TransportInlineNodeReachable $_ $Boundary}|Sort-Object {$_.Extent.StartOffset})
            foreach($regionAssignment in $regionAssignments){
                if($regionAssignment.Left -is [Management.Automation.Language.VariableExpressionAst]){
                    $drivePath=[string]$regionAssignment.Left.VariablePath.UserPath;$driveLeaf=(($drivePath -split ':')[-1])
                    if($drivePath -match '(?i)^(Function|Alias):' -and $driveLeaf -iin @('Invoke-HardKillSealedMutationControllerCase','Start-HardKillRegisteredProcess','Set-TestProgress','Where-Object')){
                        throw 'preimage-transport-owner-shadow'
                    }
                    $localPath=[string]$regionAssignment.Left.VariablePath.UserPath
                    $localName=(($localPath -split ':')[-1])
                    if($localName -ieq 'null'){continue}
                    $isSafeLocalAmbientShadow=$CapabilityFrame -ceq 'Local' -and $localPath -notmatch '(?i)^(script|global):' -and
                        -not $boundaryParameterNames.Contains($localName) -and -not $incomingRegionTaint.Contains($localName) -and
                        -not $regionLocalTaint.Contains($localName) -and -not(Test-RegionAstTainted $regionAssignment.Right)
                    if($isSafeLocalAmbientShadow){$null=$regionTaint.Remove($localName)}
                    if($regionTaint.Contains($localName) -and -not $approvedTransportAssignmentOffsets.Contains([int]$regionAssignment.Extent.StartOffset)){
                        if($taintedLaunchInputNames.Contains($localName)){throw 'preimage-transport-launch-input-provenance'}
                        if($localName -ieq 'cases'){throw 'preimage-transport-cases-provenance'}
                        if($localName -ieq 'reviewedMutationEnginePath'){throw 'preimage-transport-engine-provenance'}
                        throw 'preimage-transport-owner-shadow'
                    }
                    if(-not $regionTaint.Contains($localName) -and (Test-RegionAstTainted $regionAssignment.Right)){
                        $null=$regionTaint.Add($localName)
                        if($CapabilityFrame -ceq 'Local'){$null=$regionLocalTaint.Add($localName)}
                        if($CapabilityFrame -ceq 'Top'){$null=$topRegionTaint.Add($localName)}
                    }
                    $mayContainScriptBlock=Test-RegionMayContainScriptBlock $regionAssignment.Right ([int]$regionAssignment.Extent.StartOffset)
                    if($regionAssignment.Operator -ne [Management.Automation.Language.TokenKind]::Equals -and
                        (Test-RegionNameMayContainScriptBlock $localPath ([int]$regionAssignment.Extent.StartOffset) $regionAssignment)){$mayContainScriptBlock=$true}
                    Publish-RegionNonLocalScriptBlockCapability $localPath $mayContainScriptBlock $regionAssignment
                    $null=Set-RegionScriptBlockWrite $localPath ([int]$regionAssignment.Extent.StartOffset) $mayContainScriptBlock $regionAssignment
                    $rhsCompact=Get-HardKillAstTextCompact -Ast $regionAssignment.Right
                    $directProvider=Test-RegionPsVariableProvider $regionAssignment.Right
                    $providerReferences=@($regionAssignment.Right.FindAll({param($child)
                        $isProvider=(Get-HardKillAstTextCompact -Ast $child) -ieq '$ExecutionContext.SessionState.PSVariable' -or
                            ($child -is [Management.Automation.Language.VariableExpressionAst] -and
                             $regionPsVariableAliases.Contains((([string]$child.VariablePath.UserPath -split ':')[-1])))
                        if(-not $isProvider){return $false}
                        $parent=$child.Parent
                        return -not($parent -is [Management.Automation.Language.InvokeMemberExpressionAst] -and
                            -not $parent.Static -and $parent.Member -is [Management.Automation.Language.StringConstantExpressionAst] -and
                            [string]$parent.Member.Value -ieq 'Get' -and [object]::ReferenceEquals($parent.Expression,$child))
                    },$true))
                    if($directProvider){
                        $null=$regionPsVariableAliases.Add($localName)
                        if($CapabilityFrame -ceq 'Top'){$null=$topRegionPsVariableProviders.Add($localName)}
                    }elseif($providerReferences.Count -ne 0){
                        throw 'preimage-transport-owner-shadow'
                    }else{
                        $rhsCommands=@($regionAssignment.Right.FindAll({param($child)$child -is [Management.Automation.Language.CommandAst]},$true))
                        if($rhsCommands.Count -eq 1){
                            $rhsLeaf=Get-TransportCommandLeaf $rhsCommands[0]
                            $rhsDefinitions=@($callableDefinitions|Where-Object{((([string]$_.Name -split ':')[-1]).ToLowerInvariant()) -ceq $rhsLeaf -and $_.Extent.StartOffset -lt $DefinitionCutoff})
                            $providerArgumentCount=@($rhsCommands[0].CommandElements|Select-Object -Skip 1|Where-Object{Test-RegionPsVariableProvider $_}).Count
                            if($providerArgumentCount -ne 0 -or ($rhsDefinitions.Count -eq 1 -and
                                @($rhsDefinitions[0].Body.FindAll({param($child)(Get-HardKillAstTextCompact -Ast $child) -ieq '$ExecutionContext.SessionState.PSVariable'},$true)).Count -ne 0)){
                                $null=$regionPsVariableAliases.Add($localName)
                            }
                        }
                    }
                    $variableTarget=Get-RegionPsVariableTarget $regionAssignment.Right
                    if($null -ne $variableTarget){
                        $regionPsVariableObjects[$localName]=$variableTarget
                        if($CapabilityFrame -ceq 'Top'){$topRegionPsVariableObjects[$localName]=$variableTarget}
                    }
                }else{
                    if(Test-RegionMayContainScriptBlock $regionAssignment.Right ([int]$regionAssignment.Extent.StartOffset)){
                        return $true
                    }
                    $indirectTarget=Get-RegionPsVariableTarget $regionAssignment.Left
                    if($null -ne $indirectTarget){
                    if($indirectTarget -ceq '__DYNAMIC__'){throw 'preimage-transport-owner-shadow'}
                        if($regionTaint.Contains((($indirectTarget -split ':')[-1]))){Throw-RegionTaintedWrite $indirectTarget}
                    }
                    if(Test-RegionAstTainted $regionAssignment.Left){
                        $launchInputReferences=@($regionAssignment.Left.FindAll({param($child)$child -is [Management.Automation.Language.VariableExpressionAst] -and
                            $taintedLaunchInputNames.Contains((([string]$child.VariablePath.UserPath -split ':')[-1]))},$true))
                        if($launchInputReferences.Count -ne 0){throw 'preimage-transport-launch-input-provenance'}
                        throw 'preimage-transport-owner-shadow'
                    }
                    $storageRoot=Get-TransportStorageRootName $regionAssignment.Left
                    $rhsTainted=Test-RegionAstTainted $regionAssignment.Right
                    $rhsProvider=Test-RegionPsVariableProvider $regionAssignment.Right
                    $rhsVariableTarget=Get-RegionPsVariableTarget $regionAssignment.Right
                    if(($rhsTainted -or $rhsProvider -or $null -ne $rhsVariableTarget) -and [string]::IsNullOrEmpty($storageRoot)){return $true}
                    if(-not[string]::IsNullOrEmpty($storageRoot)){
                        $storageKey=Get-TransportCapabilityKey $storageRoot $CapabilityFrame
                        if($rhsTainted){
                            $null=$regionTaint.Add($storageKey)
                            if($CapabilityFrame -ceq 'Top'){$null=$topRegionTaint.Add($storageKey)}
                        }
                        if($rhsProvider){
                            $null=$regionPsVariableAliases.Add($storageKey)
                            if($CapabilityFrame -ceq 'Top'){$null=$topRegionPsVariableProviders.Add($storageKey)}
                        }
                        if($null -ne $rhsVariableTarget){
                            $regionPsVariableObjects[$storageKey]=$rhsVariableTarget
                            if($CapabilityFrame -ceq 'Top'){$topRegionPsVariableObjects[$storageKey]=$rhsVariableTarget}
                        }
                    }
                }
            }
            $splattedCapabilityCommands=@($Boundary.FindAll({param($node)
                $node -is [Management.Automation.Language.CommandAst] -and
                @($node.CommandElements|Where-Object{$_ -is [Management.Automation.Language.VariableExpressionAst] -and $_.Splatted}).Count -ne 0
            },$true)|Where-Object{Test-TransportInlineNodeReachable $_ $Boundary})
            foreach($splattedCapabilityCommand in $splattedCapabilityCommands){
                $splattedLeaf=Get-TransportCommandLeaf $splattedCapabilityCommand
                if($splattedLeaf -in @('foreach-object','%')){
                    if(-not(Get-TransportForEachCommandModel $splattedCapabilityCommand).Valid){return $true}
                    continue
                }
                $splattedBindings=Get-TransportOutputVariableBindings $splattedCapabilityCommand
                if($splattedBindings.Present){if(-not $splattedBindings.Valid){return $true};continue}
                if(Test-RegionMayContainScriptBlock $splattedCapabilityCommand ([int]$splattedCapabilityCommand.Extent.StartOffset)){return $true}
            }
            $scriptBlockProducerCommands=@($Boundary.FindAll({param($node)
                $node -is [Management.Automation.Language.CommandAst] -and
                ((Get-TransportCommandLeaf $node) -in @('set-variable','sv','new-variable','nv','set-item','si','new-item','ni','set-content','sc','add-content','ac') -or
                 (Get-TransportOutputVariableBindings $node).Present)
            },$true)|Where-Object{Test-TransportInlineNodeReachable $_ $Boundary})
            foreach($producerCommand in $scriptBlockProducerCommands){
                $producerLeaf=Get-TransportCommandLeaf $producerCommand
                $outputBindings=Get-TransportOutputVariableBindings $producerCommand
                if($outputBindings.Present){
                    if(-not $outputBindings.Valid){return $true}
                    foreach($outputBinding in @($outputBindings.Rows)){
                        $flow=Get-TransportPipelineCapabilitySources $producerCommand ([string]$outputBinding.Mode)
                        if(-not $flow.Valid){return $true}
                        $bindingMayContain=$false
                        foreach($source in @($flow.Sources)){
                            if(Test-RegionMayContainScriptBlock $source ([int]$producerCommand.Extent.StartOffset)){$bindingMayContain=$true;break}
                        }
                        if([string]$outputBinding.Kind -ceq 'OutVariable' -and $outputBinding.Append -and
                            (Test-RegionNameMayContainScriptBlock ([string]$outputBinding.Target) ([int]$producerCommand.Extent.StartOffset) $producerCommand)){$bindingMayContain=$true}
                        Publish-RegionNonLocalScriptBlockCapability ([string]$outputBinding.Target) $bindingMayContain $producerCommand
                        $null=Set-RegionScriptBlockWrite ([string]$outputBinding.Target) ([int]$producerCommand.Extent.StartOffset) $bindingMayContain $producerCommand
                        if([string]$outputBinding.Kind -ceq 'PipelineVariable'){
                            $bindingPipeline=$producerCommand.Parent
                            if($bindingPipeline -isnot [Management.Automation.Language.PipelineAst] -or
                                (Test-TransportPipelineVariableBindingConflict $producerCommand ([string]$outputBinding.Target) $CapabilityFrame)){return $true}
                            $null=Set-RegionScriptBlockWrite ([string]$outputBinding.Target) ([int]$bindingPipeline.Extent.StartOffset-1) $false $bindingPipeline
                            $null=Set-RegionScriptBlockWrite ([string]$outputBinding.Target) ([int]$bindingPipeline.Extent.EndOffset) $false $bindingPipeline
                        }
                    }
                    continue
                }
                $valueParameters=@($producerCommand.CommandElements|Where-Object{
                    $_ -is [Management.Automation.Language.CommandParameterAst] -and
                    'Value'.StartsWith([string]$_.ParameterName,[StringComparison]::OrdinalIgnoreCase)
                })
                if($valueParameters.Count -gt 1){return $true}
                if($valueParameters.Count -eq 1){
                    $producerValue=Get-RegionParameterArgument $producerCommand $valueParameters[0]
                }else{
                    $plainProducerElements=@($producerCommand.CommandElements|Select-Object -Skip 1|Where-Object{$_ -isnot [Management.Automation.Language.CommandParameterAst]})
                    $producerValue=if($plainProducerElements.Count -ge 2){$plainProducerElements[1]}else{$null}
                }
                $producerTarget=Get-RegionLiteralTarget $producerCommand
                if($producerLeaf -notin @('set-variable','sv','new-variable','nv') -and $producerTarget -notmatch '(?i)^variable:'){continue}
                if([string]::IsNullOrEmpty($producerTarget) -and $null -ne $producerValue -and
                    (Test-RegionMayContainScriptBlock $producerValue ([int]$producerCommand.Extent.StartOffset))){return $true}
                if(-not[string]::IsNullOrEmpty($producerTarget)){
                    $producerCapabilityName=$producerTarget
                    if($producerCapabilityName -match '^(?i)Variable:[\\/]?(.+)$'){$producerCapabilityName=$Matches[1]}
                    $producerMayContain=$null -ne $producerValue -and (Test-RegionMayContainScriptBlock $producerValue ([int]$producerCommand.Extent.StartOffset))
                    if($producerLeaf -in @('add-content','ac') -and
                        (Test-RegionNameMayContainScriptBlock $producerTarget ([int]$producerCommand.Extent.StartOffset) $producerCommand)){$producerMayContain=$true}
                    $scopeParameters=@($producerCommand.CommandElements|Where-Object{
                        $_ -is [Management.Automation.Language.CommandParameterAst] -and
                        'Scope'.StartsWith([string]$_.ParameterName,[StringComparison]::OrdinalIgnoreCase)
                    })
                    if($scopeParameters.Count -gt 1){return $true}
                    $producerScope=''
                    if($scopeParameters.Count -eq 1){
                        $scopeArgument=Get-RegionParameterArgument $producerCommand $scopeParameters[0]
                        if($scopeArgument -isnot [Management.Automation.Language.StringConstantExpressionAst]){if($producerMayContain){return $true}}
                        else{$producerScope=[string]$scopeArgument.Value}
                    }
                    $publishedCapabilityName=$producerCapabilityName
                    if($producerCapabilityName -notmatch '(?i)^(script|global):' -and
                        -not[string]::IsNullOrEmpty($producerScope) -and $producerScope -inotin @('Local','Private','0')){
                        if($producerScope -inotin @('Script','Global')){if($producerMayContain){return $true}}
                        else{$publishedCapabilityName=('{0}:{1}' -f $producerScope.ToLowerInvariant(),$producerCapabilityName)}
                    }
                    Publish-RegionNonLocalScriptBlockCapability $publishedCapabilityName $producerMayContain $producerCommand
                    $null=Set-RegionScriptBlockWrite $producerCapabilityName ([int]$producerCommand.Extent.StartOffset) $producerMayContain $producerCommand
                }
            }
            $regionScriptBlockChanged=$true
            while($regionScriptBlockChanged){
                $regionScriptBlockChanged=$false
                foreach($regionAssignment in $regionAssignments){
                    if($regionAssignment.Left -isnot [Management.Automation.Language.VariableExpressionAst]){continue}
                    $localName=[string]$regionAssignment.Left.VariablePath.UserPath
                    $mayContainScriptBlock=Test-RegionMayContainScriptBlock $regionAssignment.Right ([int]$regionAssignment.Extent.StartOffset)
                    if($regionAssignment.Operator -ne [Management.Automation.Language.TokenKind]::Equals -and
                        (Test-RegionNameMayContainScriptBlock $localName ([int]$regionAssignment.Extent.StartOffset) $regionAssignment)){$mayContainScriptBlock=$true}
                    if(Set-RegionScriptBlockWrite $localName ([int]$regionAssignment.Extent.StartOffset) $mayContainScriptBlock $regionAssignment){$regionScriptBlockChanged=$true}
                }
            }
            $reachableAbrupt=@($Boundary.FindAll({param($node)
                $node -is [Management.Automation.Language.ExitStatementAst]
            },$true)|Where-Object{Test-TransportInlineNodeReachable $_ $Boundary})
            if($reachableAbrupt.Count -ne 0){return $true}
            $reachableMembers=@($Boundary.FindAll({param($node)$node -is [Management.Automation.Language.InvokeMemberExpressionAst]},$true)|Where-Object{Test-TransportInlineNodeReachable $_ $Boundary})
            foreach($member in $reachableMembers){
                if(Test-TransportDangerousMember $member){return $true}
                if(-not $member.Static -and [string]$member.Member.Value -iin @('Invoke','InvokeReturnAsIs','InvokeWithContext','BeginInvoke')){
                    $resolving=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                    $callbackBlock=Resolve-TransportScriptBlockValue $member.Expression ([int]$member.Extent.StartOffset) $resolving
                    if($null -eq $callbackBlock -or (Test-TransportReachableRegion $callbackBlock $DefinitionCutoff @($regionTaint) @($regionPsVariableAliases) @(Get-RegionActiveScriptBlockNames ([int]$member.Extent.StartOffset) $member) $member $CapabilityFrame)){return $true}
                }elseif(-not $member.Static -and [string]$member.Member.Value -iin @('ForEach','Where')){
                    if(@($member.Arguments).Count -eq 0){return $true}
                    $resolving=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                    $callbackBlock=Resolve-TransportScriptBlockValue $member.Arguments[0] ([int]$member.Extent.StartOffset) $resolving
                    if($null -eq $callbackBlock -or (Test-TransportReachableRegion $callbackBlock $DefinitionCutoff @($regionTaint) @($regionPsVariableAliases) @(Get-RegionActiveScriptBlockNames ([int]$member.Extent.StartOffset) $member) $member $CapabilityFrame)){return $true}
                }elseif(
                    ($member.Static -and $member.Expression -is [Management.Automation.Language.TypeExpressionAst] -and
                     [string]$member.Expression.TypeName.FullName -iin @('Task','Threading.Tasks.Task','System.Threading.Tasks.Task','ThreadPool','Threading.ThreadPool','System.Threading.ThreadPool') -and
                     [string]$member.Member.Value -iin @('Run','QueueUserWorkItem','UnsafeQueueUserWorkItem')) -or
                    (-not $member.Static -and [string]$member.Member.Value -ceq 'StartNew')){
                    if(@($member.Arguments).Count -eq 0){return $true}
                    $resolving=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                    $callbackBlock=Resolve-TransportScriptBlockValue $member.Arguments[0] ([int]$member.Extent.StartOffset) $resolving
                    if($null -eq $callbackBlock -or (Test-TransportReachableRegion $callbackBlock $DefinitionCutoff @($regionTaint) @($regionPsVariableAliases) @(Get-RegionActiveScriptBlockNames ([int]$member.Extent.StartOffset) $member) $member $CapabilityFrame)){return $true}
                }elseif(
                    (-not $member.Static -and [string]$member.Member.Value -iin @('ContinueWith','Register','DoCallBack')) -or
                    ($member.Static -and $member.Expression -is [Management.Automation.Language.TypeExpressionAst] -and
                     [string]$member.Expression.TypeName.FullName -iin @('Threading.Timer','System.Threading.Timer') -and [string]$member.Member.Value -ceq 'new') -or
                    ($member.Static -and $member.Expression -is [Management.Automation.Language.TypeExpressionAst] -and
                     [string]$member.Expression.TypeName.FullName -iin @('ThreadPool','Threading.ThreadPool','System.Threading.ThreadPool') -and
                     [string]$member.Member.Value -iin @('RegisterWaitForSingleObject','UnsafeRegisterWaitForSingleObject'))){
                    $callbackIndex=if([string]$member.Member.Value -iin @('RegisterWaitForSingleObject','UnsafeRegisterWaitForSingleObject')){1}else{0}
                    if(@($member.Arguments).Count -le $callbackIndex){return $true}
                    $resolving=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                    $callbackBlock=Resolve-TransportScriptBlockValue $member.Arguments[$callbackIndex] ([int]$member.Extent.StartOffset) $resolving
                    if($null -eq $callbackBlock -or (Test-TransportReachableRegion $callbackBlock $DefinitionCutoff @($regionTaint) @($regionPsVariableAliases) @(Get-RegionActiveScriptBlockNames ([int]$member.Extent.StartOffset) $member) $member $CapabilityFrame)){return $true}
                }
                foreach($directCallbackArgument in @($member.Arguments)){
                    $resolving=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                    $directCallbackBlock=Resolve-TransportScriptBlockValue $directCallbackArgument ([int]$member.Extent.StartOffset) $resolving
                    if($null -ne $directCallbackBlock){
                        if(Test-TransportReachableRegion $directCallbackBlock $DefinitionCutoff @($regionTaint) @($regionPsVariableAliases) @(Get-RegionActiveScriptBlockNames ([int]$member.Extent.StartOffset) $member) $member $CapabilityFrame){return $true}
                    }else{
                        $directCallbackCapability=@(Test-RegionMayContainScriptBlock $directCallbackArgument ([int]$member.Extent.StartOffset))
                        if($directCallbackCapability.Count -ne 1 -or [bool]$directCallbackCapability[0]){return $true}
                    }
                }
                $receiverResolving=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                $isScalarToString=[string]$member.Member.Value -ieq 'ToString' -and @($member.Arguments|Where-Object{$null -ne $_}).Count -eq 0
                $directReceiverBlock=if($isScalarToString){$null}else{Resolve-TransportScriptBlockValue $member.Expression ([int]$member.Extent.StartOffset) $receiverResolving}
                if($null -ne $directReceiverBlock){
                    if(Test-TransportReachableRegion $directReceiverBlock $DefinitionCutoff @($regionTaint) @($regionPsVariableAliases) @(Get-RegionActiveScriptBlockNames ([int]$member.Extent.StartOffset) $member) $member $CapabilityFrame){return $true}
                }elseif(-not $isScalarToString -and
                    (Test-RegionReceiverMayContainScriptBlock $member.Expression ([int]$member.Extent.StartOffset))){return $true}
                $providerCompact=Get-HardKillAstTextCompact -Ast $member.Expression
                $providerAliasMatch=Test-RegionPsVariableProvider $member.Expression
                if(-not $member.Static -and [string]$member.Member.Value -iin @('Set','Remove') -and
                    ($providerCompact -ieq '$ExecutionContext.SessionState.PSVariable' -or $providerAliasMatch)){
                    if(@($member.Arguments).Count -lt 1 -or $member.Arguments[0] -isnot [Management.Automation.Language.StringConstantExpressionAst]){throw 'preimage-transport-owner-shadow'}
                    $providerTarget=[string]$member.Arguments[0].Value
                    if($regionTaint.Contains((($providerTarget -split ':')[-1]))){Throw-RegionTaintedWrite $providerTarget}
                }
                if([string]$member.Member.Value -iin @('SetValue','Add','Clear','Remove','Insert','RemoveAt') -and (Test-RegionAstTainted $member.Expression)){
                    throw 'preimage-transport-owner-shadow'
                }
            }
            $reachableCommands=@($Boundary.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true)|Where-Object{Test-TransportInlineNodeReachable $_ $Boundary})
            foreach($command in $reachableCommands){
                if(Test-TransportDangerousCommand $command){return $true}
                $leaf=Get-TransportCommandLeaf $command
                if([string]::IsNullOrEmpty($leaf)){return $true}
                if($leaf -in @('foreach-object','%')){
                    $model=Get-TransportForEachCommandModel $command
                    if(-not $model.Valid){return $true}
                    $inputFlow=Get-TransportPipelineCapabilitySources $command 'PipelineInput'
                    if(-not $inputFlow.Valid){return $true}
                    $callbackInputSources=[Collections.Generic.List[object]]::new()
                    foreach($source in @($inputFlow.Sources)){$callbackInputSources.Add($source)}
                    if($model.InputObjects.Count -ne 0){
                        if($callbackInputSources.Count -ne 0 -or $model.InputObjects.Count -ne 1){return $true}
                        $callbackInputSources.Add($model.InputObjects[0])
                    }
                    $inputMayContainScriptBlock=$false
                    foreach($source in @($callbackInputSources)){
                        if(Test-RegionMayContainScriptBlock $source ([int]$command.Extent.StartOffset)){$inputMayContainScriptBlock=$true;break}
                    }
                    foreach($callbackRow in @($model.Callbacks)){
                        $resolving=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                        $callbackBlock=Resolve-TransportScriptBlockValue $callbackRow.Argument ([int]$command.Extent.StartOffset) $resolving
                        $incomingNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                        foreach($activeName in @(Get-RegionActiveScriptBlockNames ([int]$command.Extent.StartOffset) $command)){$null=$incomingNames.Add($activeName)}
                        if($inputMayContainScriptBlock -and [string]$callbackRow.Role -in @('Process','RemainingScripts','Parallel')){
                            foreach($automaticInputName in @('_','PSItem','input')){$null=$incomingNames.Add($automaticInputName)}
                        }
                        if($null -eq $callbackBlock -or (Test-TransportReachableRegion $callbackBlock $DefinitionCutoff @($regionTaint) @($regionPsVariableAliases) @($incomingNames) $command $CapabilityFrame)){return $true}
                    }
                }elseif($leaf -in @('where-object','?')){
                    if(@($command.CommandElements|Where-Object{$_ -is [Management.Automation.Language.VariableExpressionAst] -and $_.Splatted}).Count -ne 0){return $true}
                    $callbackArguments=[Collections.Generic.List[Management.Automation.Language.Ast]]::new()
                    $consumedOffsets=[Collections.Generic.HashSet[int]]::new()
