            if($candidate.Length -ge 2 -and 'pipelinevariable'.StartsWith($candidate,[StringComparison]::OrdinalIgnoreCase)){return $true}
            if($candidate.Length -ge 6 -and 'errorvariable'.StartsWith($candidate,[StringComparison]::OrdinalIgnoreCase)){return $true}
            if($candidate.Length -ge 8 -and 'warningvariable'.StartsWith($candidate,[StringComparison]::OrdinalIgnoreCase)){return $true}
            if($candidate.Length -ge 12 -and 'informationvariable'.StartsWith($candidate,[StringComparison]::OrdinalIgnoreCase)){return $true}
