        $sessionStateMutators=@($ast.FindAll({param($node)
            $node -is [Management.Automation.Language.InvokeMemberExpressionAst] -and [string]$node.Member.Value -iin @('Set','Remove') -and
            (Get-HardKillAstTextCompact -Ast $node.Expression) -ieq '$ExecutionContext.SessionState.PSVariable'
