            (Get-HardKillAstTextCompact -Ast $_) -match '(?i)(RepoRoot|hostArguments|recoveryArguments|stdout|stderr|recoveryOut|recoveryErr|pwshExecutablePath|env:(PATH|PATHEXT|PSModulePath)|SetEnvironmentVariable\(''(PATH|PATHEXT|PSModulePath)'')'
