            (([string]$node.Left.VariablePath.UserPath -split ':')[-1]) -ceq 'cases'
        },$true)|Sort-Object {$_.Extent.StartOffset})
        $goldCaseAssignments=@($goldSectionBlock.FindAll({param($node)
