            $goldProducer=@($goldAst.FindAll({param($node)$node -is [Management.Automation.Language.AssignmentStatementAst] -and (Get-HardKillAstTextCompact -Ast $node.Left) -ceq ('$'+$producerName)},$true)|Where-Object{$null -eq (Get-NearestHardKillFunction $_)})
            if($producer.Count -ne 1 -or $goldProducer.Count -ne 1 -or -not($producer[0] -in @($sectionBlock.Statements)) -or
