        $statements=@($forwardLoop.Body.Statements);$goldStatements=@($goldForwardLoop.Body.Statements);$selectedIndex=[Array]::IndexOf($statements,$selectedIf);$goldSelectedIndex=[Array]::IndexOf($goldStatements,$goldSelectedIf)
