            $node -is [Management.Automation.Language.InvokeMemberExpressionAst] -and [string]$node.Member.Value -ieq 'Start' -and $node.Static -and
            $node.Expression -is [Management.Automation.Language.TypeExpressionAst] -and [string]$node.Expression.TypeName.FullName -iin @('Diagnostics.Process','System.Diagnostics.Process')
        },$true))
