        if($launchCommands.Count -ne 2 -or $launchMembers.Count -ne 0 -or $registeredLaunches.Count -ne 2){throw 'preimage-transport-launch-inventory'}
        $launcherCutoff=[Math]::Min($normalLaunches[0].Extent.StartOffset,$recoveryLaunches[0].Extent.StartOffset)
