}
function Test-HardKillPreimageControllerTransportContractMutations {
    param([AllowEmptyString()][Parameter(Mandatory)][string]$ActualControllerSource)
    $baseline=@'
[CmdletBinding()]
param(
    [ValidateSet('all','primitives','setup','process','rollback')][string]$Section='all',
    [string]$CasePattern='*'
)
function Start-HardKillRegisteredProcess { param($FilePath,$ArgumentList,$RedirectStandardOutputPath,$RedirectStandardErrorPath) }
function Invoke-HardKillSealedMutationControllerCase {
    param($HostPath,$EnginePath,$Case)
    [AiAgentDotfilesTests.HardKillSealedMutationControllerScope]$controllerScope=$null
    [AiAgentDotfilesTests.HardKillSealedMutationHostSession]$session=$null
    [AiAgentDotfilesTests.HardKillJobReapReceipt]$reapReceipt=$null
