    function Replace-Once([string]$Source,[string]$Old,[string]$New){$offset=$Source.IndexOf($Old,[StringComparison]::Ordinal);if($offset-lt0-or$Source.IndexOf($Old,$offset+$Old.Length,[StringComparison]::Ordinal)-ge0){return $null};return $Source.Remove($offset,$Old.Length).Insert($offset,$New)}
    function Get-ActualPreludeMutationShape([string]$Source){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors)
        if(@($errors).Count -ne 0){return $null}
        $rootStatements=@($ast.EndBlock.Statements)
        $mainTries=@($rootStatements|Where-Object{$_ -is [Management.Automation.Language.TryStatementAst] -and @($_.CatchClauses).Count -eq 1 -and $null -ne $_.Finally})
        if($mainTries.Count -ne 1){return $null}
        $mainTryIndex=[Array]::IndexOf($rootStatements,$mainTries[0])
        if($mainTryIndex -le 0){return $null}
        $prelude=@($rootStatements[0..($mainTryIndex-1)]|Where-Object{$_ -isnot [Management.Automation.Language.FunctionDefinitionAst]})
        return [pscustomobject]@{Ast=$ast;MainTry=$mainTries[0];Prelude=$prelude}
    }
    function Replace-ActualPreludeRow([string]$Source,[int]$Index,[string]$NewText,[bool]$InsertBefore=$false){
        $shape=Get-ActualPreludeMutationShape $Source
        if($null -eq $shape -or $Index -lt 0 -or $Index -ge $shape.Prelude.Count){return $null}
        $row=$shape.Prelude[$Index]
        if($InsertBefore){return $Source.Insert($row.Extent.StartOffset,$NewText+"`n")}
        return $Source.Remove($row.Extent.StartOffset,$row.Extent.EndOffset-$row.Extent.StartOffset).Insert($row.Extent.StartOffset,$NewText)
    }
    function Swap-ActualPreludeRows([string]$Source,[int]$First,[int]$Second){
        $shape=Get-ActualPreludeMutationShape $Source
        if($null -eq $shape -or $First -lt 0 -or $Second -ne $First+1 -or $Second -ge $shape.Prelude.Count){return $null}
        $firstRow=$shape.Prelude[$First];$secondRow=$shape.Prelude[$Second]
        $replacement=([string]$secondRow.Extent.Text)+"`n"+([string]$firstRow.Extent.Text)
        return $Source.Remove($firstRow.Extent.StartOffset,$secondRow.Extent.EndOffset-$firstRow.Extent.StartOffset).Insert($firstRow.Extent.StartOffset,$replacement)
    }
    function Insert-ActualMainBodyStatement([string]$Source,[string]$Statement){
        $shape=Get-ActualPreludeMutationShape $Source
        if($null -eq $shape -or @($shape.MainTry.Body.Statements).Count -eq 0){return $null}
        $first=$shape.MainTry.Body.Statements[0]
        return $Source.Insert($first.Extent.EndOffset,"`n    "+$Statement)
    }
