    function Remove-Owner([string]$Source){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);$owner=@($ast.FindAll({param($node)$node-is[Management.Automation.Language.FunctionDefinitionAst]-and$node.Name-ceq'Invoke-HardKillSealedMutationControllerCase'},$true));if(@($errors).Count-ne0-or$owner.Count-ne1){return $null};return $Source.Remove($owner[0].Extent.StartOffset,$owner[0].Extent.EndOffset-$owner[0].Extent.StartOffset)}
