        $mainTry=$mainTries[0]
        $members=@($function.FindAll({param($node)$node -is [Management.Automation.Language.InvokeMemberExpressionAst]},$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$function)})
        $begin=@($members|Where-Object{[string]$_.Member.Value -ceq 'BeginReadWriteFile'});$wait=@($members|Where-Object{[string]$_.Member.Value -ceq 'WaitForBreak'});$ack=@($members|Where-Object{[string]$_.Member.Value -ceq 'IsAcknowledgedSelfMutationBreak'})
        $stageSet=@($members|Where-Object{[string]$_.Member.Value -ceq 'Set' -and (Get-HardKillAstTextCompact -Ast $_.Expression) -ceq '$StageEvent'})
        $eagerDispose=@($members|Where-Object{[string]$_.Member.Value -ceq 'Dispose' -and (Get-HardKillAstTextCompact -Ast $_.Expression) -cin @('$sourceFirst','$headerGate','$sourceCopy','$intentGate')})
        $lengthReads=@($function.FindAll({param($node)$node -is [Management.Automation.Language.MemberExpressionAst] -and [string]$node.Member.Value -ceq 'Length' -and (Get-HardKillAstTextCompact -Ast $node.Expression) -ceq '$preimageInfo'},$true))
        $commands=@($function.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$function)})
