        $result.BeginCount=$begin.Count;$result.WaitCount=$wait.Count;$result.AckCount=$ack.Count;$result.HandoffDisposeCount=$eagerDispose.Count;$result.StageReleaseCount=$stageSet.Count;$result.PreimageLengthReadCount=$lengthReads.Count
