        $expectedSource=@'
function Wait-HardKillAfterPreimageCheckpoint {
    param(
        [Parameter(Mandatory)]$Process,
        [Parameter(Mandatory)][string]$TransactionNamespace,
        [Parameter(Mandatory)][string]$RepoRoot,
        [Parameter(Mandatory)][string]$TransactionId,
        [Parameter(Mandatory)][string]$StagePath,
        [Parameter(Mandatory)]$StageEvent,
        [int]$TimeoutSeconds=300
    )
    $deadline=[DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
    $stage=$null;$sourceFirst=$null;$headerGate=$null;$sourceCopy=$null;$intentGate=$null;$armEvidence=$null;$released=$false
    try{
        while([DateTime]::UtcNow -lt $deadline -and $null -eq $stage){$Process.Refresh();if($Process.HasExited){return $false};$stage=Read-HardKillAfterPreimageStartStage -StagePath $StagePath -TransactionId $TransactionId -TransactionNamespace $TransactionNamespace;if($null -eq $stage){Start-Sleep -Milliseconds 20}}
        if($null -eq $stage){return $false}
        $sourceFirst=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetPath)
        if([string]$sourceFirst.Identity -cne [string]$stage.TargetIdentity){throw 'after-preimage first source R|W oplock identity differs from the typed stage'}
        $null=$StageEvent.Set();$released=$true
        if(-not $sourceFirst.WaitForBreak(300000) -or -not $sourceFirst.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage source observation did not reach its exact first R|W break'}
        $headerPath=Join-Path $TransactionNamespace 'header.json';$headerIdentity=[string][AiAgentDotfiles.NoFollowFile]::Inspect($headerPath).Identity
        $headerGate=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile($headerPath)
        if([string]$headerGate.Identity -cne $headerIdentity){throw 'after-preimage header gate identity changed before its R|W oplock was armed'}
        $sourceFirst.Dispose();$sourceFirst=$null
        if(-not $headerGate.WaitForBreak(300000) -or -not $headerGate.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage PREIMAGE_COPY_INTENT append did not reach its held header read'}
        $sourceCopy=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetPath)
        if([string]$sourceCopy.Identity -cne [string]$stage.TargetIdentity){throw 'after-preimage copy source identity changed before its second R|W oplock was armed'}
        $headerGate.Dispose();$headerGate=$null
        if(-not $sourceCopy.WaitForBreak(300000) -or -not $sourceCopy.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage real preimage copy did not reach its exact source R|W break'}
        $armEvidence=Open-HardKillAfterPreimageIntentEvidence -TransactionNamespace $TransactionNamespace -Stage $stage
        $intentGate=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$armEvidence.IntentPath)
        if([string]$intentGate.Identity -cne [string]$armEvidence.IntentIdentity){throw 'after-preimage intent identity changed before its R|W oplock was armed'}
        $sourceCopy.Dispose();$sourceCopy=$null
        if(-not $intentGate.WaitForBreak(300000) -or -not $intentGate.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage FILE_PREPARED append did not reach its exact held intent read'}
        $null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label 'hard-kill after-preimage requester'
        $intentGate.Dispose();$intentGate=$null
        $preimageInfo=[AiAgentDotfiles.NoFollowFile]::Inspect([IO.Path]::GetFullPath([string]$armEvidence.Target.PreimagePath));$armEvidence|Add-Member -NotePropertyName PreimageIdentity -NotePropertyValue ([string]$preimageInfo.Identity)
        if(-not(Test-HardKillAfterPreimagePostReapState -TransactionNamespace $TransactionNamespace -RepoRoot $RepoRoot -ArmEvidence $armEvidence)){throw 'hard-kill after-preimage post-reap tuple differs from its exact abandon boundary'}
        return $true
    }finally{
        $cleanupFailure=$null
        try{$null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label 'hard-kill after-preimage cleanup'}catch{$cleanupFailure=$_}
        if($null -eq $cleanupFailure){
            foreach($held in @($intentGate,$sourceCopy,$headerGate,$sourceFirst)){if($held){try{$held.Dispose()}catch{if($null -eq $cleanupFailure){$cleanupFailure=$_}}}}
            if(-not $released){try{$null=$StageEvent.Set()}catch{if($null -eq $cleanupFailure){$cleanupFailure=$_}}}
        }
        if($cleanupFailure){throw $cleanupFailure}
    }
}
'@
        if((Get-HardKillTokenFingerprint -Source ([string]$function.Extent.Text)) -cne (Get-HardKillTokenFingerprint -Source $expectedSource)){throw 'after-preimage-ladder-fingerprint'}
        $result.Valid=$true
    }catch{$result.ErrorCodes=@([string]$_.Exception.Message)}
    return [pscustomobject]$result
}
function Test-HardKillAfterPreimageCheckpointLadderContractMutations {
    param([Parameter(Mandatory)][string]$ControllerSource)
    function Replace-InLadder([string]$Source,[string]$Old,[string]$New){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);if(@($errors).Count -ne 0){return $null};$function=@($ast.FindAll({param($node)$node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -ceq 'Wait-HardKillAfterPreimageCheckpoint'},$true));if($function.Count -ne 1){return $null};$start=$function[0].Extent.StartOffset;$length=$function[0].Extent.EndOffset-$start;$offset=$Source.IndexOf($Old,$start,$length,[StringComparison]::Ordinal);if($offset -lt 0 -or $Source.IndexOf($Old,$offset+$Old.Length,$function[0].Extent.EndOffset-($offset+$Old.Length),[StringComparison]::Ordinal) -ge 0){return $null};return $Source.Remove($offset,$Old.Length).Insert($offset,$New)}
    $sourceGate="if(-not `$sourceFirst.WaitForBreak(300000) -or -not `$sourceFirst.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage source observation did not reach its exact first R|W break'}"
    $headerGate="if(-not `$headerGate.WaitForBreak(300000) -or -not `$headerGate.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage PREIMAGE_COPY_INTENT append did not reach its held header read'}"
    $copyGate="if(-not `$sourceCopy.WaitForBreak(300000) -or -not `$sourceCopy.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage real preimage copy did not reach its exact source R|W break'}"
    $intentGate="if(-not `$intentGate.WaitForBreak(300000) -or -not `$intentGate.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage FILE_PREPARED append did not reach its exact held intent read'}"
    $sourceAcquire='$sourceFirst=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetPath)';$headerAcquire='$headerGate=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile($headerPath)';$copyAcquire='$sourceCopy=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetPath)';$intentAcquire='$intentGate=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$armEvidence.IntentPath)'
    $sourceRelease='$sourceFirst.Dispose();$sourceFirst=$null';$headerRelease='$headerGate.Dispose();$headerGate=$null';$copyRelease='$sourceCopy.Dispose();$sourceCopy=$null';$intentRelease='$intentGate.Dispose();$intentGate=$null';$requester='$null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label ''hard-kill after-preimage requester'''
    $mutants=[ordered]@{
        'ladder-duplicate-source-gate'=Replace-InLadder $ControllerSource $sourceGate ($sourceGate+';'+$sourceGate)
        'ladder-source-acquire-argument'=Replace-InLadder $ControllerSource $sourceAcquire '$sourceFirst=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetIdentity)'
        'ladder-source-wait-receiver'=Replace-InLadder $ControllerSource $sourceGate ($sourceGate.Replace('$sourceFirst.WaitForBreak','$headerGate.WaitForBreak'))
        'ladder-header-acquire-argument'=Replace-InLadder $ControllerSource $headerAcquire '$headerGate=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetPath)'
        'ladder-header-wait-budget'=Replace-InLadder $ControllerSource $headerGate ($headerGate.Replace('WaitForBreak(300000)','WaitForBreak(299999)'))
        'ladder-copy-acquire-argument'=Replace-InLadder $ControllerSource $copyAcquire '$sourceCopy=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile($headerPath)'
        'ladder-copy-ack-receiver'=Replace-InLadder $ControllerSource $copyGate ($copyGate.Replace('$sourceCopy.IsAcknowledgedSelfMutationBreak','$headerGate.IsAcknowledgedSelfMutationBreak'))
        'ladder-intent-acquire-argument'=Replace-InLadder $ControllerSource $intentAcquire '$intentGate=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetPath)'
        'ladder-intent-ack-removed'=Replace-InLadder $ControllerSource $intentGate ($intentGate.Replace('$intentGate.IsAcknowledgedSelfMutationBreak()','$false'))
        'ladder-copy-gate-dead-branch'=Replace-InLadder $ControllerSource $copyGate ('if($false){'+$copyGate+'}')
        'ladder-header-before-source-release'=Replace-InLadder $ControllerSource ($sourceRelease+"`n        "+$headerGate) ($headerGate+"`n        "+$sourceRelease)
        'ladder-requester-after-intent-release'=Replace-InLadder $ControllerSource ($requester+"`n        "+$intentRelease) ($intentRelease+"`n        "+$requester)
        'ladder-header-release-removed'=Replace-InLadder $ControllerSource $headerRelease '$headerGate=$null'
        'ladder-finally-copy-omitted'=Replace-InLadder $ControllerSource '@($intentGate,$sourceCopy,$headerGate,$sourceFirst)' '@($intentGate,$headerGate,$sourceFirst)'
        'ladder-release-fallback-removed'=Replace-InLadder $ControllerSource 'if(-not $released){try{$null=$StageEvent.Set()}catch{if($null -eq $cleanupFailure){$cleanupFailure=$_}}}' '$null=$released'
        'ladder-preimage-length-read'=Replace-InLadder $ControllerSource '$armEvidence|Add-Member -NotePropertyName PreimageIdentity' '$null=$preimageInfo.Length;$armEvidence|Add-Member -NotePropertyName PreimageIdentity'
    }
    $expected=[ordered]@{
        'ladder-duplicate-source-gate'='after-preimage-ladder-cardinality';'ladder-source-acquire-argument'='after-preimage-ladder-fingerprint';'ladder-source-wait-receiver'='after-preimage-ladder-fingerprint';'ladder-header-acquire-argument'='after-preimage-ladder-fingerprint';'ladder-header-wait-budget'='after-preimage-ladder-fingerprint';'ladder-copy-acquire-argument'='after-preimage-ladder-fingerprint';'ladder-copy-ack-receiver'='after-preimage-ladder-fingerprint';'ladder-intent-acquire-argument'='after-preimage-ladder-fingerprint';'ladder-intent-ack-removed'='after-preimage-ladder-cardinality';'ladder-copy-gate-dead-branch'='after-preimage-ladder-fingerprint';'ladder-header-before-source-release'='after-preimage-ladder-fingerprint';'ladder-requester-after-intent-release'='after-preimage-ladder-fingerprint';'ladder-header-release-removed'='after-preimage-ladder-cardinality';'ladder-finally-copy-omitted'='after-preimage-ladder-cardinality';'ladder-release-fallback-removed'='after-preimage-ladder-cardinality';'ladder-preimage-length-read'='after-preimage-ladder-post-reap'
    }
    $baseline=Test-HardKillAfterPreimageCheckpointLadderContract -ControllerSource $ControllerSource;$cases=[Collections.Generic.List[object]]::new()
    foreach($name in $expected.Keys){$constructed=$mutants.Contains($name) -and $mutants[$name] -is [string] -and -not[string]::IsNullOrEmpty([string]$mutants[$name]);$source=if($constructed){[string]$mutants[$name]}else{''};$tokens=$null;$errors=$null;$null=[Management.Automation.Language.Parser]::ParseInput($source,[ref]$tokens,[ref]$errors);$verdict=if($constructed -and @($errors).Count -eq 0){Test-HardKillAfterPreimageCheckpointLadderContract -ControllerSource $source}else{$null};$codes=@(if($verdict){$verdict.ErrorCodes}else{'mutation-parse'});$reason=[string]$expected[$name];$cases.Add([pscustomobject]@{Name=$name;Constructed=$constructed;Changed=$constructed -and $source -cne $ControllerSource;ParseValid=$constructed -and @($errors).Count -eq 0;Rejected=$null -ne $verdict -and -not $verdict.Valid;ExpectedErrorCode=$reason;RejectedForExpectedReason=$codes.Count -eq 1 -and $codes[0] -ceq $reason;ErrorCodes=$codes})}
    return [pscustomobject]@{Valid=$baseline.Valid -and $cases.Count -eq 16 -and @($cases|Where-Object{-not $_.Constructed -or -not $_.Changed -or -not $_.ParseValid -or -not $_.Rejected -or -not $_.RejectedForExpectedReason}).Count -eq 0;Baseline=$baseline;Cases=@($cases);ExpectedNames=@($expected.Keys)}
}
function Test-HardKillBehaviorOracleDriverValidatorMutations {
    param([Parameter(Mandatory)][string]$ControllerSource)
    function Replace-OracleFunctionText {
        param([string]$Source,[string]$FunctionName,[string]$Old,[string]$New)
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors)
        if(@($errors).Count -ne 0){return $null};$function=Get-HardKillFunctionAst -Ast $ast -Name $FunctionName;if($null -eq $function){return $null}
        $start=$function.Extent.StartOffset;$length=$function.Extent.EndOffset-$start;$index=$Source.IndexOf($Old,$start,$length,[StringComparison]::Ordinal)
        if($index -lt 0 -or $Source.IndexOf($Old,$index+$Old.Length,($function.Extent.EndOffset-($index+$Old.Length)),[StringComparison]::Ordinal) -ge 0){return $null}
        return $Source.Remove($index,$Old.Length).Insert($index,$New)
    }
    $mutants=[ordered]@{}
    $mutants['oracle-from-child-argument']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' '-JobProcess $process.HardKillJobProcess -DeadlineQpc $oracleDeadlineQpc' '-JobProcess $process.HardKillJobProcess -DeadlineQpc $oracleDeadlineQpc -RawCase $rawCase'
    $mutants['action-leaks-expected-verdict']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' '-Process $process -ActionNonce $actionNonce' "-Process `$process -ActionNonce `$actionNonce -ExpectedVerdict 'pass'"
    $mutants['continue-before-action']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' '$actionNonce=[Guid]::NewGuid().ToString(''N'');$action=Invoke-HardKillBehaviorOracleAction' 'if(-not $fixture.ContinueEvent.Set()){throw ''early-continue''};$actionNonce=[Guid]::NewGuid().ToString(''N'');$action=Invoke-HardKillBehaviorOracleAction'
    $mutants['complete-before-done']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' 'if($remaining -le 0 -or -not $fixture.DoneEvent.WaitOne($remaining)){throw "behavior-done-timeout:$($row.Name)"}' '$observation=Complete-HardKillBehaviorOracleObservation -Fixture $fixture -Process $process -JobProcess $process.HardKillJobProcess -DeadlineQpc $oracleDeadlineQpc;if($remaining -le 0 -or -not $fixture.DoneEvent.WaitOne($remaining)){throw "behavior-done-timeout:$($row.Name)"}'
    $mutants['complete-after-exit']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' '$observation=Complete-HardKillBehaviorOracleObservation -Fixture $fixture' '$null=$process.WaitForExit(0);$observation=Complete-HardKillBehaviorOracleObservation -Fixture $fixture'
    $finalCaseRow="'differential-role-swap-rejected','differential-stable-parent-recreate-rejected','rollback-stage-cleanup-failure-no-proof','preimage-stage-cleanup-failure-no-proof'"
    $mutants['missing-case']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $finalCaseRow "'differential-role-swap-rejected','differential-stable-parent-recreate-rejected','rollback-stage-cleanup-failure-no-proof'"
    $mutants['duplicate-case']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $finalCaseRow "'differential-role-swap-rejected','differential-stable-parent-recreate-rejected','rollback-stage-cleanup-failure-no-proof','rollback-stage-cleanup-failure-no-proof'"
    $mutants['extra-oracle-key']=Replace-OracleFunctionText $ControllerSource 'Get-HardKillParentOracleSpec' "@('managed-token','read-action>typed-nonmatch>publish-response')" "@('managed-token','read-action>typed-nonmatch>publish-response','ExpectedVerdict')"
    $mutants['spec-kind-remapped']=Replace-OracleFunctionText $ControllerSource 'Get-HardKillParentOracleSpec' "'selector-nonmatch-no-io'=@('managed-token','read-action>typed-nonmatch>publish-response')" "'selector-nonmatch-no-io'=@('native-resource','read-action>typed-nonmatch>publish-response')"
    $mutants['fixture-kind-constant']=Replace-OracleFunctionText $ControllerSource 'New-HardKillBehaviorOracleFixture' 'OracleKind=$spec.Kind;OperationSequence=$spec.OperationSequence' "OracleKind='managed-token';OperationSequence=`$spec.OperationSequence"
    $mutants['fixture-spec-call-forged']=Replace-OracleFunctionText $ControllerSource 'New-HardKillBehaviorOracleFixture' '$spec=Get-HardKillParentOracleSpec -CaseName $CaseName' "`$spec=[pscustomobject]@{Kind='managed-token';OperationSequence='forged'}"
    $mutants['close-before-observation']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' '$observation=Complete-HardKillBehaviorOracleObservation -Fixture $fixture' 'Close-HardKillBehaviorOracleFixture -Fixture $fixture;$observation=Complete-HardKillBehaviorOracleObservation -Fixture $fixture'
    $driverClose='foreach($event in @($eventRows)){Close-HardKillBehaviorOracleFixture -Fixture $event}'
    $withoutPostExitClose=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $driverClose ''
    $mutants['close-not-finally']=if($null -ne $withoutPostExitClose){Replace-OracleFunctionText $withoutPostExitClose 'Invoke-HardKillBehaviorProbe' "if(`$remaining -le 0 -or -not `$process.WaitForExit(`$remaining)){throw 'behavior-probe-timeout'}" ($driverClose+";if(`$remaining -le 0 -or -not `$process.WaitForExit(`$remaining)){throw 'behavior-probe-timeout'}")}else{$null}
    $releaseGuard='if(-not $fixture.ReleaseEvent.Set()){throw "behavior-release-signal:$($row.Name)"}'
    $testGuard='if(-not(Test-HardKillBehaviorOracleObservation -Fixture $fixture -Observation $observation)){throw "behavior-oracle-observation:$($row.Name)"}'
    $withoutRelease=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $releaseGuard ''
    $mutants['release-before-test']=if($null -ne $withoutRelease){Replace-OracleFunctionText $withoutRelease 'Invoke-HardKillBehaviorProbe' $testGuard ($releaseGuard+';'+$testGuard)}else{$null}
    $mutants['release-unchecked']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $releaseGuard '$null=$fixture.ReleaseEvent.Set()'
    $mutants['release-missing']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $releaseGuard 'Out-Null'
    $mutants['ready-infinite-wait']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' '$fixture.ReadyEvent.WaitOne($remaining)' '$fixture.ReadyEvent.WaitOne(-1)'
    $mutants['exit-infinite-wait']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' '$process.WaitForExit($remaining)' '$process.WaitForExit(-1)'
    $doneGuard='if($remaining -le 0 -or -not $fixture.DoneEvent.WaitOne($remaining)){throw "behavior-done-timeout:$($row.Name)"}'
    $mutants['done-wall-clock-refresh']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $doneGuard ('$remaining=[int]([DateTime]::UtcNow.AddMilliseconds(1)-[DateTime]::UtcNow).TotalMilliseconds;'+$doneGuard)
    $mutants['deadline-reassigned']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $doneGuard ('$oracleDeadlineQpc=[Diagnostics.Stopwatch]::GetTimestamp();'+$doneGuard)
    $mutants['remaining-overwritten']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $doneGuard ('$remaining=[int]::MaxValue;'+$doneGuard)
    $mutants['test-dead-branch']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $testGuard ('if($false){'+$testGuard+'}')
    $requestDeadlinePrefix='$requestCase=[ordered]@{Index=[long]$index;Name=$name;CaseNonce=$caseNonce;InputSha256=$inputSha;AbsoluteDeadlineQpc=$oracleDeadlineQpc.ToString([Globalization.CultureInfo]::InvariantCulture);ReadyEventName'
    $mutants['request-deadline-omitted']=Replace-OracleFunctionText $ControllerSource 'Invoke-HardKillBehaviorProbe' $requestDeadlinePrefix '$requestCase=[ordered]@{Index=[long]$index;Name=$name;CaseNonce=$caseNonce;InputSha256=$inputSha;ReadyEventName'
    $expectedErrors=[ordered]@{
        'oracle-from-child-argument'='oracle-driver-call-arguments:Complete-HardKillBehaviorOracleObservation'
        'action-leaks-expected-verdict'='oracle-driver-call-arguments:Invoke-HardKillBehaviorOracleAction'
        'continue-before-action'='oracle-driver-event-cardinality'
        'complete-before-done'='oracle-driver-call-cardinality:Complete-HardKillBehaviorOracleObservation'
        'complete-after-exit'='oracle-driver-complete-after-exit'
        'missing-case'='oracle-driver-case-inventory'
        'duplicate-case'='oracle-driver-case-inventory'
        'extra-oracle-key'='oracle-spec-value:selector-nonmatch-no-io'
        'spec-kind-remapped'='oracle-spec-kind:selector-nonmatch-no-io'
        'fixture-kind-constant'='oracle-fixture-spec-binding'
        'fixture-spec-call-forged'='oracle-fixture-spec-call'
        'close-before-observation'='oracle-driver-call-cardinality:Close-HardKillBehaviorOracleFixture'
        'close-not-finally'='oracle-driver-lifecycle-order'
        'release-before-test'='oracle-driver-lifecycle-order'
        'release-unchecked'='oracle-driver-release-unchecked'
        'release-missing'='oracle-driver-release-cardinality'
        'ready-infinite-wait'='oracle-driver-deadline-binding:wait'
        'exit-infinite-wait'='oracle-driver-deadline-binding:wait'
        'done-wall-clock-refresh'='oracle-driver-deadline-cardinality'
        'deadline-reassigned'='oracle-driver-deadline-cardinality'
        'remaining-overwritten'='oracle-driver-deadline-cardinality'
        'test-dead-branch'='oracle-driver-success-path-shape'
        'request-deadline-omitted'='oracle-driver-request-deadline'
    }
    $cases=[Collections.Generic.List[object]]::new()
    foreach($entry in $mutants.GetEnumerator()){
        $parseValid=$false;$rejected=$false;$errors=@('mutation-not-applied')
        if($null -ne $entry.Value -and $entry.Value -cne $ControllerSource){$tokens=$null;$parseErrors=$null;$null=[Management.Automation.Language.Parser]::ParseInput($entry.Value,[ref]$tokens,[ref]$parseErrors);$parseValid=@($parseErrors).Count -eq 0;if($parseValid){$verdict=Test-HardKillBehaviorOracleDriverContract -ControllerSource $entry.Value;$rejected=-not $verdict.Valid;$errors=@($verdict.ErrorCodes)}}
        $expected=[string]$expectedErrors[[string]$entry.Key]
        $cases.Add([pscustomobject]@{Name=[string]$entry.Key;Changed=$null -ne $entry.Value -and $entry.Value -cne $ControllerSource;ParseValid=$parseValid;Rejected=$rejected;ExpectedErrorCode=$expected;RejectedForExpectedReason=$errors.Count -eq 1 -and $errors[0] -ceq $expected;ErrorCodes=$errors})
    }
    $baseline=Test-HardKillBehaviorOracleDriverContract -ControllerSource $ControllerSource
    return [pscustomobject]@{Valid=$baseline.Valid -and $cases.Count -eq 23 -and @(Compare-Object @($expectedErrors.Keys) @($cases.Name) -CaseSensitive).Count -eq 0 -and @($cases|Where-Object{-not $_.Changed -or -not $_.ParseValid -or -not $_.Rejected -or -not $_.RejectedForExpectedReason}).Count -eq 0;Baseline=$baseline;Cases=@($cases)}
}
function Get-HardKillBehaviorProbeInventory {
    param([Parameter(Mandatory)]$ProbeRootHandle,[Parameter(Mandatory)]$CaseDataHandle,[Parameter(Mandatory)]$CaseRows)
    $caseInventory=[Collections.Generic.List[object]]::new()
    foreach($row in @($CaseRows)){
        $caseInventory.Add([pscustomobject]@{Leaf=[string]$row.DirectoryLeaf;Identity=[string]$row.DirectoryIdentity;Children=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($row.DirectoryHandle)|Sort-Object)})
    }
    return [pscustomobject]@{
        RootChildren=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($ProbeRootHandle)|Sort-Object)
        CaseDataChildren=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($CaseDataHandle)|Sort-Object)
        Cases=@($caseInventory)
    }
}
function Test-HardKillBehaviorCleanupAuthorityWiringContract {
    param([Parameter(Mandatory)][string]$ControllerSource)
    $result=[ordered]@{Valid=$false;ErrorCodes=@()}
    try{
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($ControllerSource,[ref]$tokens,[ref]$errors)
        if(@($errors).Count -ne 0){throw 'authority-wiring-parse'}
        $invoke=Get-HardKillFunctionAst -Ast $ast -Name 'Invoke-HardKillBehaviorProbe'
        if($null -eq $invoke){throw 'authority-wiring-invoke-missing'}
        $sessionAssignments=@($invoke.FindAll({param($node)
            $node -is [Management.Automation.Language.AssignmentStatementAst] -and (Get-HardKillAstTextCompact $node.Left) -ceq '$cleanupSession' -and
            @($node.Right.FindAll({param($child)$child -is [Management.Automation.Language.InvokeMemberExpressionAst] -and
                (Get-HardKillAstTextCompact $child.Expression) -ceq '[AiAgentDotfilesTests.HardKillBehaviorCleanupSession]' -and $child.Member.Value -ceq 'Begin'},$true)).Count -eq 1
        },$true))
        $tokenAssignments=@($invoke.FindAll({param($node)$node -is [Management.Automation.Language.AssignmentStatementAst] -and
            (Get-HardKillAstTextCompact $node.Left) -ceq '$pendingToken' -and (Get-HardKillAstTextCompact $node.Right) -ceq '$cleanupSession.PendingToken'},$true))
        $requiredMethods=@('AcquireAndEnrollHeldFile','AcquireAndEnrollDirectoryChain','AbortBeforeRoot')
        $authorityCalls=@($invoke.FindAll({param($node)$node -is [Management.Automation.Language.InvokeMemberExpressionAst] -and
            (Get-HardKillAstTextCompact $node.Expression) -ceq '$cleanupSession'},$true))
        $actualMethods=@($authorityCalls|ForEach-Object{[string]$_.Member.Value}|Where-Object{$_ -cin $requiredMethods}|Sort-Object -Unique)
        $heldCalls=@($authorityCalls|Where-Object{[string]$_.Member.Value -ceq 'AcquireAndEnrollHeldFile'})
        $heldAssignments=@($invoke.FindAll({param($node)
            $node -is [Management.Automation.Language.AssignmentStatementAst] -and
            (Get-HardKillAstTextCompact $node.Left) -cin @('$engineEvidence','$hostEvidence') -and
            $node.Right -is [Management.Automation.Language.CommandExpressionAst] -and
            $node.Right.Expression -is [Management.Automation.Language.InvokeMemberExpressionAst] -and
            (Get-HardKillAstTextCompact $node.Right.Expression.Expression) -ceq '$cleanupSession' -and
            [string]$node.Right.Expression.Member.Value -ceq 'AcquireAndEnrollHeldFile'
        },$true))
        $heldBindingsValid=$heldCalls.Count -eq 2 -and $heldAssignments.Count -eq 2
        foreach($binding in @(
            [pscustomobject]@{Variable='$engineEvidence';Path='$EnginePath'},
            [pscustomobject]@{Variable='$hostEvidence';Path='$ProbeHostPath'}
        )){
            $assignment=@($heldAssignments|Where-Object{(Get-HardKillAstTextCompact $_.Left) -ceq $binding.Variable})
            if($assignment.Count -ne 1){$heldBindingsValid=$false;continue}
            $call=$assignment[0].Right.Expression
            if(@($call.Arguments).Count -ne 2 -or
                $call.Arguments[0] -isnot [Management.Automation.Language.ConvertExpressionAst] -or
                $call.Arguments[0].Type.TypeName.FullName -cne 'AiAgentDotfilesTests.HardKillBehaviorAcquire' -or
                $call.Arguments[1] -isnot [Management.Automation.Language.ConvertExpressionAst] -or
                $call.Arguments[1].Type.TypeName.FullName -cne 'AiAgentDotfilesTests.HardKillBehaviorRelease'){$heldBindingsValid=$false;continue}
            $acquireCommands=@($call.Arguments[0].FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true))
            $releaseCommands=@($call.Arguments[1].FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true))
            $expectedAcquire=Get-HardKillTokenFingerprint ("[AiAgentDotfilesTests.HardKillBehaviorAcquire]{Open-HardKillHeldFileEvidence -Path $($binding.Path)}")
            $expectedRelease=Get-HardKillTokenFingerprint '[AiAgentDotfilesTests.HardKillBehaviorRelease]{param($evidence) Close-HardKillBehaviorHeldEvidenceFailStop -Evidence $evidence}'
            if($acquireCommands.Count -ne 1 -or $acquireCommands[0].GetCommandName() -cne 'Open-HardKillHeldFileEvidence' -or
                $releaseCommands.Count -ne 1 -or $releaseCommands[0].GetCommandName() -cne 'Close-HardKillBehaviorHeldEvidenceFailStop' -or
                (Get-HardKillTokenFingerprint ([string]$call.Arguments[0].Extent.Text)) -cne $expectedAcquire -or
                (Get-HardKillTokenFingerprint ([string]$call.Arguments[1].Extent.Text)) -cne $expectedRelease){$heldBindingsValid=$false}
        }
        $rootCalls=@($authorityCalls|Where-Object{[string]$_.Member.Value -ceq 'AcquireAndEnrollDirectoryChain'})
        $rootAssignments=@($invoke.FindAll({param($node)
            $node -is [Management.Automation.Language.AssignmentStatementAst] -and
            (Get-HardKillAstTextCompact $node.Left) -ceq '$probeRootHandles' -and
            $node.Right -is [Management.Automation.Language.CommandExpressionAst] -and
            $node.Right.Expression -is [Management.Automation.Language.InvokeMemberExpressionAst] -and
            (Get-HardKillAstTextCompact $node.Right.Expression.Expression) -ceq '$cleanupSession' -and
            [string]$node.Right.Expression.Member.Value -ceq 'AcquireAndEnrollDirectoryChain'
        },$true))
        $rootBindingValid=$rootCalls.Count -eq 1 -and $rootAssignments.Count -eq 1
        if($rootBindingValid){
            $rootCall=$rootAssignments[0].Right.Expression
            $expectedAcquire=Get-HardKillTokenFingerprint '[AiAgentDotfilesTests.HardKillBehaviorAcquire]{$probeRootChainReceiver=[AiAgentDotfiles.SealedOwnershipTransferReceiver]::new();Open-SafeDirectoryContainmentChain -Path $probeRoot -OwnershipReceiver $probeRootChainReceiver;$probeRootChainReceiver.GetDeliveredExact()}'
            $expectedRelease=Get-HardKillTokenFingerprint '[AiAgentDotfilesTests.HardKillBehaviorRelease]{param($handles) Close-SafeDirectoryContainmentChain -Handles $handles}'
            if(@($rootCall.Arguments).Count -ne 2 -or
                $rootCall.Arguments[0] -isnot [Management.Automation.Language.ConvertExpressionAst] -or
                $rootCall.Arguments[0].Type.TypeName.FullName -cne 'AiAgentDotfilesTests.HardKillBehaviorAcquire' -or
                $rootCall.Arguments[1] -isnot [Management.Automation.Language.ConvertExpressionAst] -or
                $rootCall.Arguments[1].Type.TypeName.FullName -cne 'AiAgentDotfilesTests.HardKillBehaviorRelease' -or
                (Get-HardKillTokenFingerprint ([string]$rootCall.Arguments[0].Extent.Text)) -cne $expectedAcquire -or
                (Get-HardKillTokenFingerprint ([string]$rootCall.Arguments[1].Extent.Text)) -cne $expectedRelease){$rootBindingValid=$false}
        }
        $abortCalls=@($authorityCalls|Where-Object{[string]$_.Member.Value -ceq 'AbortBeforeRoot'})
        $abortAssignments=@($invoke.FindAll({param($node)
            $node -is [Management.Automation.Language.AssignmentStatementAst] -and (Get-HardKillAstTextCompact $node.Left) -ceq '$preRootAbortReceipt' -and
            $node.Right -is [Management.Automation.Language.CommandExpressionAst] -and
            $node.Right.Expression -is [Management.Automation.Language.InvokeMemberExpressionAst] -and
            (Get-HardKillAstTextCompact $node.Right.Expression.Expression) -ceq '$cleanupSession' -and
            [string]$node.Right.Expression.Member.Value -ceq 'AbortBeforeRoot'
        },$true))
        $abortGuarded=$false
        if($abortAssignments.Count -eq 1 -and $abortCalls.Count -eq 1 -and [object]::ReferenceEquals($abortAssignments[0].Right.Expression,$abortCalls[0])){
            $abortOwner=$abortAssignments[0].Parent
            while($null -ne $abortOwner -and $abortOwner -isnot [Management.Automation.Language.IfStatementAst]){$abortOwner=$abortOwner.Parent}
            if($abortOwner -is [Management.Automation.Language.IfStatementAst] -and $abortOwner.Clauses.Count -eq 1 -and $null -eq $abortOwner.ElseClause){
                $expectedAbortGuard=Get-HardKillTokenFingerprint '-not $probeRootCreated -and $null -ne $cleanupSession -and $null -ne $pendingToken -and $null -ne $primaryException -and $null -eq $process -and $launchedPid -eq 0'
                $abortGuarded=(Get-HardKillTokenFingerprint ([string]$abortOwner.Clauses[0].Item1.Extent.Text)) -ceq $expectedAbortGuard
            }
        }
        $heldOpenCommands=@($invoke.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst] -and $node.GetCommandName() -ceq 'Open-HardKillHeldFileEvidence'},$true))
        $heldCloseCommands=@($invoke.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst] -and $node.GetCommandName() -ceq 'Close-HardKillBehaviorHeldEvidenceFailStop'},$true))
        if($sessionAssignments.Count -ne 1 -or $tokenAssignments.Count -ne 1 -or
            @(Compare-Object $requiredMethods $actualMethods -CaseSensitive).Count -ne 0 -or $authorityCalls.Count -ne 4 -or
            -not $heldBindingsValid -or $heldOpenCommands.Count -ne 2 -or $heldCloseCommands.Count -ne 2 -or
            -not $rootBindingValid -or
            $abortCalls.Count -ne 1 -or $abortAssignments.Count -ne 1 -or -not $abortGuarded){throw 'authority-wiring-acquire-and-enroll'}
        $firstHeldOffset=@($heldAssignments|Sort-Object {$_.Extent.StartOffset})[0].Extent.StartOffset
        if($sessionAssignments[0].Extent.StartOffset -ge $tokenAssignments[0].Extent.StartOffset -or
            $tokenAssignments[0].Extent.StartOffset -ge $firstHeldOffset){throw 'authority-wiring-session-before-token'}
        $result.Valid=$true
    }catch{$result.ErrorCodes=@($_.Exception.Message)}
    return [pscustomobject]$result
}
function Test-HardKillBehaviorCleanupAuthorityPreflight {
    param([Parameter(Mandatory)][string]$ControllerPath)
    $result=[ordered]@{Valid=$false;SourcePath='';SourceSha256='';AuthoritySourceSha256='';ContractVersion='';Error='behavior-cleanup-authority-implementation-required'}
    try{
        $path=[IO.Path]::GetFullPath($ControllerPath)
        $result.SourcePath=$path
        if($path -cne [IO.Path]::GetFullPath($PSCommandPath) -or -not[IO.File]::Exists($path)){return [pscustomobject]$result}
        $bytes=[IO.File]::ReadAllBytes($path);$result.SourceSha256=Get-HardKillSha256Hex $bytes
        $source=[Text.UTF8Encoding]::new($false,$true).GetString($bytes)
        $tokens=$null;$errors=$null;$controllerAst=[Management.Automation.Language.Parser]::ParseInput($source,[ref]$tokens,[ref]$errors)
        if(@($errors).Count -ne 0 -or $source.IndexOf('HardKillBehaviorCleanupSession',[StringComparison]::Ordinal) -lt 0 -or
            $source.IndexOf('HardKillBehaviorCleanupPendingToken',[StringComparison]::Ordinal) -lt 0 -or
            $source.IndexOf('HardKillBehaviorCleanupReceipt',[StringComparison]::Ordinal) -lt 0 -or
            $source.IndexOf('canonical-hard-kill-cleanup-authority-v1',[StringComparison]::Ordinal) -lt 0){return [pscustomobject]$result}
        $alternateHelperRefs=@($controllerAst.FindAll({param($node)$node -is [Management.Automation.Language.StringConstantExpressionAst] -and
            [string]$node.Value -match 'canonical-hard-kill-behavior-cleanup-session\.ps1'},$true))
        if($alternateHelperRefs.Count -ne 0){$result.Error='behavior-cleanup-authority-alternate-helper-forbidden';return [pscustomobject]$result}
        $authorityDefinitions=[Collections.Generic.List[object]]::new()
        foreach($command in @($controllerAst.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst] -and $node.GetCommandName() -ceq 'Microsoft.PowerShell.Utility\Add-Type'},$true))){
            $elements=@($command.CommandElements);$definition=$null
            for($index=1;$index -lt $elements.Count-1;$index++){
                if($elements[$index] -is [Management.Automation.Language.CommandParameterAst] -and $elements[$index].ParameterName -ceq 'TypeDefinition' -and
                    $elements[$index+1] -is [Management.Automation.Language.StringConstantExpressionAst]){$definition=[string]$elements[$index+1].Value;break}
            }
            if($null -ne $definition -and $definition.IndexOf('HardKillBehaviorCleanupSession',[StringComparison]::Ordinal) -ge 0 -and
                $definition.IndexOf('HardKillBehaviorCleanupPendingToken',[StringComparison]::Ordinal) -ge 0 -and
                $definition.IndexOf('HardKillBehaviorCleanupReceipt',[StringComparison]::Ordinal) -ge 0 -and
                $definition.IndexOf('canonical-hard-kill-cleanup-authority-v1',[StringComparison]::Ordinal) -ge 0){
                $passThru=@($elements|Where-Object{$_ -is [Management.Automation.Language.CommandParameterAst] -and $_.ParameterName -ceq 'PassThru'})
                $owner=[Management.Automation.Language.Ast]$command
                while($null -ne $owner -and $owner -isnot [Management.Automation.Language.AssignmentStatementAst]){$owner=$owner.Parent}
                $authorityDefinitions.Add([pscustomobject]@{Command=$command;Source=$definition;PassThruCount=$passThru.Count;Assignment=$owner})
            }
        }
        $authorityRegistryAssignments=@($controllerAst.FindAll({param($node)
            $node -is [Management.Automation.Language.AssignmentStatementAst] -and
            (Get-HardKillAstTextCompact $node.Left) -ceq '$script:hardKillBehaviorCleanupAuthorityTypes'
        },$true))
        if($authorityDefinitions.Count -ne 1 -or $authorityDefinitions[0].PassThruCount -ne 1 -or
            $authorityDefinitions[0].Assignment -isnot [Management.Automation.Language.AssignmentStatementAst] -or
            (Get-HardKillAstTextCompact $authorityDefinitions[0].Assignment.Left) -cne '$script:hardKillBehaviorCleanupAuthorityTypes' -or
            $authorityDefinitions[0].Assignment.Right -isnot [Management.Automation.Language.PipelineAst] -or
            @($authorityDefinitions[0].Assignment.Right.PipelineElements).Count -ne 1 -or
            -not[object]::ReferenceEquals($authorityDefinitions[0].Assignment.Right.PipelineElements[0],$authorityDefinitions[0].Command) -or
            @($authorityDefinitions[0].Command.Redirections).Count -ne 0 -or
            $authorityDefinitions[0].Assignment.Parent -isnot [Management.Automation.Language.NamedBlockAst] -or
            $authorityDefinitions[0].Assignment.Parent.Parent -isnot [Management.Automation.Language.ScriptBlockAst] -or
            $null -ne $authorityDefinitions[0].Assignment.Parent.Parent.Parent -or $authorityRegistryAssignments.Count -ne 1 -or
            -not[object]::ReferenceEquals($authorityDefinitions[0].Assignment,$authorityRegistryAssignments[0])){
            $result.Error='behavior-cleanup-authority-controller-add-type-required';return [pscustomobject]$result
        }
        if(([string]$authorityDefinitions[0].Source).IndexOf('public HardKillBehaviorCleanupReceipt(',[StringComparison]::Ordinal) -ge 0){
            $result.Error='behavior-cleanup-authority-public-receipt-forbidden';return [pscustomobject]$result
        }
        $result.AuthoritySourceSha256=Get-HardKillSha256Hex ([Text.Encoding]::UTF8.GetBytes([string]$authorityDefinitions[0].Source))
        $reviewedAuthoritySourceSha256='871b7a00e797e06566008e45a94bd769f00964e84d81e550d5cf13c34b48de98'
        if($result.AuthoritySourceSha256 -cne $reviewedAuthoritySourceSha256){$result.Error='behavior-cleanup-authority-source-not-reviewed';return [pscustomobject]$result}
        $sessionType='AiAgentDotfilesTests.HardKillBehaviorCleanupSession' -as [type]
        $tokenType='AiAgentDotfilesTests.HardKillBehaviorCleanupPendingToken' -as [type]
        $receiptType='AiAgentDotfilesTests.HardKillBehaviorCleanupReceipt' -as [type]
        if($null -eq $sessionType -or $null -eq $tokenType -or $null -eq $receiptType -or -not $sessionType.IsSealed -or -not $tokenType.IsSealed -or -not $receiptType.IsSealed -or
            $sessionType.Assembly -ne $tokenType.Assembly -or $sessionType.Assembly -ne $receiptType.Assembly -or
            @($sessionType.GetConstructors([Reflection.BindingFlags]'Public,Instance')).Count -ne 0 -or
            @($tokenType.GetConstructors([Reflection.BindingFlags]'Public,Instance')).Count -ne 0 -or
            @($receiptType.GetConstructors([Reflection.BindingFlags]'Public,Instance')).Count -ne 0 -or
            @($receiptType.GetMethods([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|Where-Object{$_.ReturnType -eq $receiptType}).Count -ne 0){return [pscustomobject]$result}
        $registeredAuthorityTypes=@($script:hardKillBehaviorCleanupAuthorityTypes)
        if(@($registeredAuthorityTypes|Where-Object{[object]::ReferenceEquals($_,$sessionType)}).Count -ne 1 -or
            @($registeredAuthorityTypes|Where-Object{[object]::ReferenceEquals($_,$tokenType)}).Count -ne 1 -or
            @($registeredAuthorityTypes|Where-Object{[object]::ReferenceEquals($_,$receiptType)}).Count -ne 1 -or
            @($registeredAuthorityTypes|Where-Object{$_.Assembly -ne $sessionType.Assembly}).Count -ne 0){return [pscustomobject]$result}
        $versionProperty=$sessionType.GetProperty('ContractVersion',[Reflection.BindingFlags]'Public,Static')
        $apiProperty=$sessionType.GetProperty('ContractApiDigest',[Reflection.BindingFlags]'Public,Static')
        if($null -eq $versionProperty -or $null -eq $apiProperty -or -not $versionProperty.CanRead -or -not $apiProperty.CanRead){return [pscustomobject]$result}
        $result.ContractVersion=[string]$versionProperty.GetValue($null)
        if($result.ContractVersion -cne 'canonical-hard-kill-cleanup-authority-v1' -or $null -eq $apiProperty -or -not $apiProperty.CanRead){return [pscustomobject]$result}
        $begin=@($sessionType.GetMethods([Reflection.BindingFlags]'Public,Static')|Where-Object{$_.Name -ceq 'Begin'})
        $complete=@($sessionType.GetMethods([Reflection.BindingFlags]'Public,Instance')|Where-Object{$_.Name -ceq 'Complete' -and $_.ReturnType -eq $receiptType})
        $requiredInstanceMethods=@('AcquireAndEnrollHeldFile','AcquireAndEnrollDirectoryChain','AcquireAndEnrollEvent','AcquireAndEnrollFileCapture','StartAndEnrollProcess','AbortBeforeRoot','RecordDeleteReceipt','RecordAbsence','MarkRootAbsent','MarkLeasesClosed','Complete')
        $actualInstanceMethods=@($sessionType.GetMethods([Reflection.BindingFlags]'Public,Instance,DeclaredOnly')|Where-Object{-not $_.IsSpecialName}|ForEach-Object{$_.Name}|Sort-Object -Unique)
        $actualStaticMethods=@($sessionType.GetMethods([Reflection.BindingFlags]'Public,Static,DeclaredOnly')|Where-Object{-not $_.IsSpecialName}|ForEach-Object{$_.Name}|Sort-Object -Unique)
        $actualSessionSpecialMethods=@($sessionType.GetMethods([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|Where-Object{$_.IsSpecialName}|ForEach-Object{$_.Name}|Sort-Object -Unique)
        $actualSessionProperties=@($sessionType.GetProperties([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|ForEach-Object{$_.Name}|Sort-Object -Unique)
        $actualTokenMethods=@($tokenType.GetMethods([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|Where-Object{-not $_.IsSpecialName})
        $actualTokenSpecialMethods=@($tokenType.GetMethods([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|Where-Object{$_.IsSpecialName}|ForEach-Object{$_.Name}|Sort-Object -Unique)
        $actualTokenProperties=@($tokenType.GetProperties([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly'))
        $actualReceiptMethods=@($receiptType.GetMethods([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|Where-Object{-not $_.IsSpecialName})
        $actualReceiptSpecialMethods=@($receiptType.GetMethods([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|Where-Object{$_.IsSpecialName}|ForEach-Object{$_.Name}|Sort-Object -Unique)
        $actualReceiptProperties=@($receiptType.GetProperties([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|ForEach-Object{$_.Name}|Sort-Object -Unique)
        $publicFields=@(@($sessionType,$tokenType,$receiptType)|ForEach-Object{@($_.GetFields([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly'))})
        $publicEvents=@(@($sessionType,$tokenType,$receiptType)|ForEach-Object{@($_.GetEvents([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly'))})
        $pendingTokenProperty=$sessionType.GetProperty('PendingToken',[Reflection.BindingFlags]'Public,Instance')
        $receiptPaths=$receiptType.GetProperty('DeletedRelativePaths',[Reflection.BindingFlags]'Public,Instance')
        $receiptBooleanProperties=@(@('RootAbsent','LeasesClosed','DeleteReceiptsValidated')|ForEach-Object{
            $receiptType.GetProperty($_,[Reflection.BindingFlags]'Public,Instance')
        })
        if($begin.Count -ne 1 -or $begin[0].ReturnType -ne $sessionType -or $complete.Count -ne 1 -or
            @(Compare-Object $requiredInstanceMethods $actualInstanceMethods -CaseSensitive).Count -ne 0 -or
            @(Compare-Object @('Begin') $actualStaticMethods -CaseSensitive).Count -ne 0 -or
            @(Compare-Object @('get_ContractApiDigest','get_ContractVersion','get_PendingToken') $actualSessionSpecialMethods -CaseSensitive).Count -ne 0 -or
            @(Compare-Object @('ContractApiDigest','ContractVersion','PendingToken') $actualSessionProperties -CaseSensitive).Count -ne 0 -or
            $actualTokenMethods.Count -ne 0 -or $actualTokenSpecialMethods.Count -ne 0 -or $actualTokenProperties.Count -ne 0 -or $actualReceiptMethods.Count -ne 0 -or
            @(Compare-Object @('get_DeleteReceiptsValidated','get_DeletedRelativePaths','get_LeasesClosed','get_RootAbsent') $actualReceiptSpecialMethods -CaseSensitive).Count -ne 0 -or
            @(Compare-Object @('DeleteReceiptsValidated','DeletedRelativePaths','LeasesClosed','RootAbsent') $actualReceiptProperties -CaseSensitive).Count -ne 0 -or
            $publicFields.Count -ne 0 -or $publicEvents.Count -ne 0 -or
            $receiptBooleanProperties.Count -ne 3 -or @($receiptBooleanProperties|Where-Object{
                $null -eq $_ -or -not $_.CanRead -or $_.CanWrite -or $_.PropertyType -ne [bool] -or $_.GetMethod.IsStatic
            }).Count -ne 0 -or
            $null -eq $pendingTokenProperty -or -not $pendingTokenProperty.CanRead -or $pendingTokenProperty.CanWrite -or $pendingTokenProperty.PropertyType -ne $tokenType -or
            $null -eq $receiptPaths -or
            $receiptPaths.CanWrite -or -not $receiptPaths.PropertyType.IsGenericType -or
            $receiptPaths.PropertyType.GetGenericTypeDefinition() -ne [Collections.Generic.IReadOnlyList``1] -or
            $receiptPaths.PropertyType.GetGenericArguments().Count -ne 1 -or $receiptPaths.PropertyType.GetGenericArguments()[0] -ne [string]){
            return [pscustomobject]$result
        }
        $apiRows=@($sessionType.GetMethods([Reflection.BindingFlags]'Public,Static,Instance,DeclaredOnly')|ForEach-Object{
            '{0}|{1}|{2}|{3}' -f $_.Name,$_.IsStatic,$_.ReturnType.FullName,(@($_.GetParameters()|ForEach-Object{$_.ParameterType.FullName}) -join ',')
        }|Sort-Object)
        $apiDigest=Get-HardKillSha256Hex ([Text.Encoding]::UTF8.GetBytes(($apiRows -join "`n")))
        $reviewedAuthorityApiDigest='91a0c74bd0640a58c7d7e7624481623254b49099ed349c8948bf93f05ce567b7'
        if($apiDigest -cne $reviewedAuthorityApiDigest -or [string]$apiProperty.GetValue($null) -cne $reviewedAuthorityApiDigest){return [pscustomobject]$result}
        $wiring=Test-HardKillBehaviorCleanupAuthorityWiringContract -ControllerSource ([IO.File]::ReadAllText($PSCommandPath))
        if(-not $wiring.Valid){$result.Error='behavior-cleanup-authority-driver-wiring-required';return [pscustomobject]$result}
        $result.Valid=$true;$result.Error=''
    }catch{$result.Error='behavior-cleanup-authority-preflight: '+$_.Exception.Message}
    return [pscustomobject]$result
}
function Remove-HardKillBehaviorRegularFileExact {
    param([Parameter(Mandatory)]$Parent,[Parameter(Mandatory)][string]$Leaf,[Parameter(Mandatory)][string]$ExpectedIdentity,
        [Parameter(Mandatory)][uint32]$ExpectedLinkCount,[Parameter(Mandatory)][long]$ExpectedLength,[Parameter(Mandatory)][int]$ExpectedAttributes,
        [Parameter(Mandatory)][string]$RelativePath,[Parameter(Mandatory)]$CleanupJournal,[Parameter(Mandatory)]$CleanupSession)
    $deleteReceipt=[AiAgentDotfiles.NoFollowFile]::DeleteChildRegularFileIfIdentity($Parent,$Leaf,$ExpectedIdentity)
    if($deleteReceipt -isnot [AiAgentDotfiles.FileIdentityInfo]){throw "behavior-cleanup-delete-receipt-type:regular:$RelativePath"}
    if([string]$deleteReceipt.Identity -cne $ExpectedIdentity -or [uint32]$deleteReceipt.LinkCount -ne $ExpectedLinkCount -or
        [long]$deleteReceipt.Length -ne $ExpectedLength -or [int]$deleteReceipt.Attributes -ne $ExpectedAttributes -or
        $deleteReceipt.IsDirectory -or $deleteReceipt.IsReparsePoint -or $ExpectedLinkCount -ne 1){
        throw "behavior-cleanup-delete-receipt-mismatch:regular:$RelativePath"
    }
    $CleanupSession.RecordDeleteReceipt($RelativePath)
    $mutationRow=[pscustomobject]@{Ordinal=[long]$CleanupJournal.MutationRows.Count;Kind='RegularFile';RelativePath=$RelativePath;State='ReceiptValidated';ExpectedIdentity=$ExpectedIdentity;ObservedIdentity=[string]$deleteReceipt.Identity;LinkCount=[long]$deleteReceipt.LinkCount;Length=[long]$deleteReceipt.Length;Attributes=[long][int]$deleteReceipt.Attributes}
    $CleanupJournal.MutationRows.Add($mutationRow)
    $replacement=[AiAgentDotfiles.NoFollowFile]::TryInspectChild($Parent,$Leaf)
    if($null -ne $replacement){throw "behavior-cleanup-delete-absence-failed:regular:$RelativePath"}
    $CleanupSession.RecordAbsence($RelativePath)
    $mutationRow.State='AbsenceProven'
    $CleanupJournal.DeletedRelativePaths.Add($RelativePath)
}
