function Close-HardKillBehaviorHeldEvidenceFailStop {
    param([AllowNull()]$Evidence)
    if($null -eq $Evidence){return}
    if($Evidence.Capture){$Evidence.Capture.Dispose();$Evidence.Capture=$null}
    if($Evidence.ParentHandles){Close-SafeDirectoryContainmentChain -Handles $Evidence.ParentHandles;$Evidence.ParentHandles=$null}
}
function Invoke-HardKillBehaviorProbeCleanupAfterReap {
    param(
        [Parameter(Mandatory)]$CleanupSession,[Parameter(Mandatory)]$PendingToken,[Parameter(Mandatory)]$EventRows,[Parameter(Mandatory)]$OwnedFileRows,
        [AllowNull()]$EngineEvidence,[AllowNull()]$HostEvidence,[Parameter(Mandatory)]$CaseRows,[Parameter(Mandatory)]$CaseDataHandle,
        [Parameter(Mandatory)][string]$CaseDataIdentity,[Parameter(Mandatory)][uint32]$CaseDataLinkCount,[Parameter(Mandatory)][long]$CaseDataLength,[Parameter(Mandatory)][int]$CaseDataAttributes,
        [Parameter(Mandatory)]$ProbeRootHandle,[Parameter(Mandatory)]$ProbeParentHandle,[Parameter(Mandatory)]$ProbeRootHandles,
        [Parameter(Mandatory)][string]$ProbeRootLeaf,[Parameter(Mandatory)][string]$ProbeRootIdentity,[Parameter(Mandatory)][uint32]$ProbeRootLinkCount,
        [Parameter(Mandatory)][long]$ProbeRootLength,[Parameter(Mandatory)][int]$ProbeRootAttributes,
        [Parameter(Mandatory)]$CleanupJournal
    )
    if($CleanupSession.GetType().FullName -cne 'AiAgentDotfilesTests.HardKillBehaviorCleanupSession'){throw 'behavior-cleanup-authority-session-type'}
    if($null -eq $PendingToken.RegistryToken -or
        @($script:forensicRoots|Where-Object{[object]::ReferenceEquals($_,$PendingToken.RegistryToken)}).Count -ne 1){throw 'behavior-cleanup-pending-token-ownership'}
    for($caseIndex=0;$caseIndex -lt $CaseRows.Count;$caseIndex++){
        $row=$CaseRows[$caseIndex]
        $fixture=$EventRows[$caseIndex]
        Close-HardKillBehaviorOracleFixture -Fixture $fixture
        $EventRows[$caseIndex]=$null;$row.OracleFixture=$null
        $CleanupJournal.OwnershipRows.Add([pscustomobject]@{Kind='OracleFixture';RelativePath="case-data/$($row.DirectoryLeaf)";State='Closed'})
        foreach($file in @($row.FileRows)){
            if($file.Capture){$file.Capture.Dispose();$file.Capture=$null;$file.CaptureState='Closed';$CleanupJournal.OwnershipRows.Add([pscustomobject]@{Kind='FileCapture';RelativePath="case-data/$($row.DirectoryLeaf)/$($file.Leaf)";State='Closed'})}
            Remove-HardKillBehaviorRegularFileExact -Parent $row.DirectoryHandle -Leaf ([string]$file.Leaf) -ExpectedIdentity ([string]$file.Identity) `
                -ExpectedLinkCount ([uint32]$file.LinkCount) -ExpectedLength ([long]$file.Length) -ExpectedAttributes ([int]$file.Attributes) `
                -RelativePath ("case-data/$($row.DirectoryLeaf)/$($file.Leaf)") -CleanupJournal $CleanupJournal -CleanupSession $CleanupSession
        }
        if($row.DirectoryHandle){$row.DirectoryHandle.Dispose();$row.DirectoryHandle=$null}
        $CleanupJournal.OwnershipRows.Add([pscustomobject]@{Kind='DirectoryHandle';RelativePath="case-data/$($row.DirectoryLeaf)";State='Closed'})
        Remove-HardKillBehaviorEmptyDirectoryExact -Parent $CaseDataHandle -Leaf ([string]$row.DirectoryLeaf) -ExpectedIdentity ([string]$row.DirectoryIdentity) `
            -ExpectedLinkCount ([uint32]$row.DirectoryLinkCount) -ExpectedLength ([long]$row.DirectoryLength) -ExpectedAttributes ([int]$row.DirectoryAttributes) `
            -RelativePath ("case-data/$($row.DirectoryLeaf)") -CleanupJournal $CleanupJournal -CleanupSession $CleanupSession
    }
    foreach($file in @($OwnedFileRows|Where-Object{$_.Kind -ceq 'root'})){
        if($file.Capture){$file.Capture.Dispose();$file.Capture=$null;$file.CaptureState='Closed';$CleanupJournal.OwnershipRows.Add([pscustomobject]@{Kind='FileCapture';RelativePath=[string]$file.Leaf;State='Closed'})}
        Remove-HardKillBehaviorRegularFileExact -Parent $ProbeRootHandle -Leaf ([string]$file.Leaf) -ExpectedIdentity ([string]$file.Identity) `
            -ExpectedLinkCount ([uint32]$file.LinkCount) -ExpectedLength ([long]$file.Length) -ExpectedAttributes ([int]$file.Attributes) `
            -RelativePath ([string]$file.Leaf) -CleanupJournal $CleanupJournal -CleanupSession $CleanupSession
    }
    $CaseDataHandle.Dispose();$PendingToken.CaseDataHandle=$null
    $CleanupJournal.OwnershipRows.Add([pscustomobject]@{Kind='DirectoryHandle';RelativePath='case-data';State='Closed'})
    Remove-HardKillBehaviorEmptyDirectoryExact -Parent $ProbeRootHandle -Leaf 'case-data' -ExpectedIdentity $CaseDataIdentity `
        -ExpectedLinkCount $CaseDataLinkCount -ExpectedLength $CaseDataLength -ExpectedAttributes $CaseDataAttributes -RelativePath 'case-data' -CleanupJournal $CleanupJournal -CleanupSession $CleanupSession
    $ProbeRootHandle.Dispose();$PendingToken.ProbeRootHandle=$null
    $CleanupJournal.OwnershipRows.Add([pscustomobject]@{Kind='DirectoryHandle';RelativePath='.';State='Closed'})
    Remove-HardKillBehaviorEmptyDirectoryExact -Parent $ProbeParentHandle -Leaf $ProbeRootLeaf -ExpectedIdentity $ProbeRootIdentity `
        -ExpectedLinkCount $ProbeRootLinkCount -ExpectedLength $ProbeRootLength -ExpectedAttributes $ProbeRootAttributes -RelativePath '.' -CleanupJournal $CleanupJournal -CleanupSession $CleanupSession
    $rootInspection=[AiAgentDotfiles.NoFollowFile]::TryInspectChild($ProbeParentHandle,$ProbeRootLeaf)
    if($null -ne $rootInspection){throw 'behavior-cleanup-root-inspection-still-present'}
    $CleanupSession.MarkRootAbsent()
    Close-HardKillBehaviorHeldEvidenceFailStop -Evidence $EngineEvidence;$PendingToken.EngineEvidence=$null
    Close-HardKillBehaviorHeldEvidenceFailStop -Evidence $HostEvidence;$PendingToken.HostEvidence=$null
    Close-SafeDirectoryContainmentChain -Handles $ProbeRootHandles
    $PendingToken.ProbeRootHandles=$null;$PendingToken.ProbeParentHandle=$null
    $CleanupSession.MarkLeasesClosed()
    return $CleanupSession.Complete()
}
function Set-HardKillBehaviorPendingCleanupToken {
    param([Parameter(Mandatory)]$Token,[Parameter(Mandatory)][Collections.IDictionary]$Values)
    $registryToken=$Token.PSObject.Properties['RegistryToken']
    if($null -eq $registryToken -or $null -eq $registryToken.Value -or
        @($script:forensicRoots|Where-Object{[object]::ReferenceEquals($_,$registryToken.Value)}).Count -ne 1){throw 'behavior-pending-cleanup-token-not-registered'}
    foreach($key in $Values.Keys){
        $property=$Token.PSObject.Properties[[string]$key]
        if($null -eq $property){throw "behavior-pending-cleanup-token-field:$key"}
        $property.Value=$Values[$key]
    }
}
function Test-HardKillBehaviorCleanupBarrierContract {
    param([Parameter(Mandatory)][string]$ControllerSource,[Parameter(Mandatory)][string]$RepositoryRoot)
    $result=[ordered]@{
        Valid=$false;AuthorityScaffold=$false;PendingTokenScaffold=$false;LegacyReapPinned=$false;DeleteEvidencePinned=$false
        CleanupAuthorityReturnPinned=$false;ControllerPreflightBeforeResources=$false;TrustClosurePinned=$false;ScriptHeaderPinned=$false;SelfDefinitionPinned=$false;FunctionInventoryPinned=$false
        ExternalTrustPinned=$false;RootBindingPinned=$false
        MainExecutionPinned=$false;OuterForensicGuardPinned=$false;PrimaryFirstPinned=$false;ErrorCodes=@()
    }
    try{
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($ControllerSource,[ref]$tokens,[ref]$errors)
        if(@($errors).Count -ne 0){throw 'cleanup-contract-parse'}
        $requirements=$ast.ScriptRequirements
        $requiresDirectives=@($tokens|Where-Object{$_.Kind -eq [Management.Automation.Language.TokenKind]::Comment -and ([string]$_.Text) -imatch '^#requires(?:\s|$)'})
        if(@($ast.UsingStatements).Count -ne 0 -or $null -eq $requirements -or $requirements.RequiredPSVersion -ne [version]'7.0' -or
            @($requirements.RequiredPSEditions).Count -ne 0 -or @($requirements.RequiredModules).Count -ne 0 -or
            @($requirements.RequiredAssemblies).Count -ne 0 -or -not[string]::IsNullOrEmpty([string]$requirements.RequiredApplicationId) -or
            $requirements.IsElevationRequired -or $requiresDirectives.Count -ne 1 -or [string]$requiresDirectives[0].Text -cne '#requires -Version 7.0'){
            throw 'cleanup-script-header'
        }
        $orderedTopStatements=@($ast.EndBlock.Statements|Sort-Object {$_.Extent.StartOffset})
        if($orderedTopStatements.Count -eq 0){throw 'cleanup-script-header'}
        $headerSource=$ControllerSource.Substring(0,[int]$orderedTopStatements[0].Extent.StartOffset) -replace "`r`n?","`n"
        $headerDigest=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($headerSource))).ToLowerInvariant()
        if($headerDigest -cne '5a18f64c9626948fbd3a5c801fe2efc34aea9cb57f164eacd7ab71aebe4e4ffe'){throw 'cleanup-script-header'}
        $result.ScriptHeaderPinned=$true
        function Get-ReviewedExtentSha256([Management.Automation.Language.Ast]$Node){
            $normalized=[string]$Node.Extent.Text -replace "`r`n?","`n"
            if($Node -is [Management.Automation.Language.FunctionDefinitionAst] -and
                $Node.Name -ceq 'Test-HardKillPreimageControllerTransportContract'){
                $surfacePattern='(?m)(\$reviewedActualControllerSurfaceSha\s*=\s*'')[0-9a-f]{64}('')'
                $surfaceMatches=[regex]::Matches($normalized,$surfacePattern,[Text.RegularExpressions.RegexOptions]::CultureInvariant)
                if($surfaceMatches.Count -ne 1){throw 'cleanup-trust-closure'}
                $normalized=[regex]::Replace($normalized,$surfacePattern,('${1}'+('0'*64)+'${2}'),[Text.RegularExpressions.RegexOptions]::CultureInvariant)
            }
            return [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($normalized))).ToLowerInvariant()
