function Test-HardKillBehaviorCleanupBarrierContractMutations {
    param([Parameter(Mandatory)][string]$ControllerSource,[Parameter(Mandatory)][string]$RepositoryRoot)
    function Replace-Unique([string]$Source,[string]$Old,[string]$New){
        $offset=$Source.IndexOf($Old,[StringComparison]::Ordinal)
        if($offset -lt 0 -or $Source.IndexOf($Old,$offset+$Old.Length,[StringComparison]::Ordinal) -ge 0){return $null}
        return $Source.Substring(0,$offset)+$New+$Source.Substring($offset+$Old.Length)
    }
    function Replace-InFunction([string]$Source,[string]$FunctionName,[string]$Old,[string]$New){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);if(@($errors).Count){return $null}
        $function=Get-HardKillFunctionAst -Ast $ast -Name $FunctionName;if($null -eq $function){return $null}
        $text=[string]$function.Extent.Text;$relative=$text.IndexOf($Old,[StringComparison]::Ordinal)
        if($relative -lt 0 -or $text.IndexOf($Old,$relative+$Old.Length,[StringComparison]::Ordinal) -ge 0){return $null}
        $start=[int]$function.Extent.StartOffset+$relative
        return $Source.Substring(0,$start)+$New+$Source.Substring($start+$Old.Length)
    }
    function Replace-InScriptParameter([string]$Source,[string]$ParameterName,[string]$Old,[string]$New){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);if(@($errors).Count -or $null -eq $ast.ParamBlock){return $null}
        $parameter=@($ast.ParamBlock.Parameters|Where-Object{$_.Name.VariablePath.UserPath -ceq $ParameterName});if($parameter.Count -ne 1){return $null}
        return Replace-InAstExtent $Source $parameter[0] $Old $New
    }
    function Replace-InAstExtent([string]$Source,[Management.Automation.Language.Ast]$Node,[string]$Old,[string]$New){
        if($null -eq $Node){return $null}
        $text=[string]$Node.Extent.Text;$relative=$text.IndexOf($Old,[StringComparison]::Ordinal)
        if($relative -lt 0 -or $text.IndexOf($Old,$relative+$Old.Length,[StringComparison]::Ordinal) -ge 0){return $null}
        $start=[int]$Node.Extent.StartOffset+$relative
        return $Source.Substring(0,$start)+$New+$Source.Substring($start+$Old.Length)
    }
    function Replace-InAddType([string]$Source,[string]$Old,[string]$New){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);if(@($errors).Count){return $null}
        $commands=@($ast.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst] -and $node.GetCommandName() -ceq 'Add-Type'},$true))
        if($commands.Count -ne 1){return $null}
        return Replace-InAstExtent $Source $commands[0] $Old $New
    }
    function Replace-InOuterFinally([string]$Source,[string]$Old,[string]$New){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);if(@($errors).Count){return $null}
        $main=@($ast.EndBlock.Statements|Where-Object{
            $_ -is [Management.Automation.Language.TryStatementAst] -and
            $_.CatchClauses.Count -eq 1 -and
            $null -ne $_.Finally
        });if($main.Count -ne 1){return $null}
        return Replace-InAstExtent $Source $main[0].Finally $Old $New
    }
    function Insert-InMainTryStart([string]$Source,[string]$Text){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);if(@($errors).Count){return $null}
        $main=@($ast.EndBlock.Statements|Where-Object{
            $_ -is [Management.Automation.Language.TryStatementAst] -and
            $_.CatchClauses.Count -eq 1 -and
            $null -ne $_.Finally
        });if($main.Count -ne 1){return $null}
        $offset=[int]$main[0].Body.Extent.StartOffset+1
        return $Source.Substring(0,$offset)+$Text+$Source.Substring($offset)
    }
    function Insert-BeforeTopLevelFunction([string]$Source,[string]$FunctionName,[string]$Text){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);if(@($errors).Count){return $null}
        $matches=@($ast.EndBlock.Statements|Where-Object{$_ -is [Management.Automation.Language.FunctionDefinitionAst] -and $_.Name -ceq $FunctionName})
        if($matches.Count -ne 1){return $null}
        $offset=[int]$matches[0].Extent.StartOffset
        return $Source.Substring(0,$offset)+$Text+$Source.Substring($offset)
    }
    function Replace-InTerminalStatement([string]$Source,[string]$Old,[string]$New){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($Source,[ref]$tokens,[ref]$errors);if(@($errors).Count){return $null}
        $main=@($ast.EndBlock.Statements|Where-Object{
            $_ -is [Management.Automation.Language.TryStatementAst] -and
            $_.CatchClauses.Count -eq 1 -and
            $null -ne $_.Finally
        });if($main.Count -ne 1){return $null}
        $matches=@($ast.EndBlock.Statements|Where-Object{$_.Extent.StartOffset -gt $main[0].Extent.EndOffset -and $_.Extent.Text.IndexOf($Old,[StringComparison]::Ordinal) -ge 0})
        if($matches.Count -ne 1){return $null}
        return Replace-InAstExtent $Source $matches[0] $Old $New
    }

