function Invoke-HardKillBehaviorProbe {
    param(
        [Parameter(Mandatory)][string]$EnginePath,[Parameter(Mandatory)][string]$ProbeHostPath,
        [Parameter(Mandatory)][string[]]$ExpectedCases,[Parameter(Mandatory)][string]$ScratchParent,
        [Parameter(Mandatory)][string]$ControllerSource
    )
    $oracleCaseNames=@(
        'selector-nonmatch-no-io','selector-first-match-single-use-ticket','selector-prehandoff-failure-ownership','selector-posthandoff-timeout-ownership',
        'context-sealed-call-failure-cleanup','context-match-assertion-failure-cleanup','native-layout-x86-x64','native-secured-root-containment',
        'native-forbidden-read-delete-bridge','native-reviewed-writer-bridge-seal','native-seal-blocks-write-delete-rebind','native-failure-matrix-zero-residue',
        'qpc-late-entry-no-refresh','qpc-overflow-and-natural-exit-race','partial-preseal-rebind-fail-closed','partial-postseal-mutation-blocked',
        'differential-role-swap-rejected','differential-stable-parent-recreate-rejected','rollback-stage-cleanup-failure-no-proof','preimage-stage-cleanup-failure-no-proof'
    )
    $state=[ordered]@{
        Valid=$false;CaseNames=@();PassedCases=@();FailedCases=@($ExpectedCases);ParentObservations=@();Residue=0;RootAbsent=$true
        ProbeContractValid=$false;ValidatorSelfTest=$false;ParentOracleAuthority=$false;AuthorityBackedCleanup=$false
        LaunchAttempted=$false;LaunchedPid=0;CleanupErrors=@();ForensicRoot='';Error='missing-probe'
    }
    if(@(Compare-Object $oracleCaseNames $ExpectedCases -CaseSensitive).Count -ne 0){$state.Error='behavior-oracle-case-set';return [pscustomobject]$state}
    $parentOracleAuthority=Test-HardKillParentOraclePrimitiveAuthorityPreflight -ControllerSource $ControllerSource
    $state.ParentOracleAuthority=$parentOracleAuthority.Valid
    if(-not $parentOracleAuthority.Valid){$state.Error=[string]$parentOracleAuthority.Error;return [pscustomobject]$state}
    $validator=Test-HardKillBehaviorProbeValidatorMutations
    $heldChildPrimitiveStatic=Test-HardKillBehaviorChildPrimitiveAuthorityContractMutations
    $heldChildCapabilityStatic=Test-HardKillBehaviorChildCapabilityContractMutations
    $heldHostCaseFlowStatic=Test-HardKillBehaviorProbeHostCaseFlowContractMutations
    $state.ValidatorSelfTest=$validator.Valid -and $heldChildPrimitiveStatic.Valid -and $heldChildCapabilityStatic.Valid -and $heldHostCaseFlowStatic.Valid
    if(-not $state.ValidatorSelfTest){$state.Error='behavior-prelaunch-static-contract';return [pscustomobject]$state}
    $cleanupAuthority=Test-HardKillBehaviorCleanupAuthorityPreflight -ControllerPath $PSCommandPath
    $state.AuthorityBackedCleanup=$cleanupAuthority.Valid
    if(-not $cleanupAuthority.Valid){$state.Error=[string]$cleanupAuthority.Error;return [pscustomobject]$state}
    if(-not[IO.File]::Exists([IO.Path]::GetFullPath($EnginePath)) -or -not[IO.File]::Exists([IO.Path]::GetFullPath($ProbeHostPath))){return [pscustomobject]$state}
    $cleanupErrors=[Collections.Generic.List[Exception]]::new();$ownedFileRows=[Collections.Generic.List[object]]::new();$caseRows=[Collections.Generic.List[object]]::new()
    $eventRows=[Collections.Generic.List[object]]::new();$parentObservations=[Collections.Generic.List[object]]::new()
    $engineEvidence=$null;$hostEvidence=$null;$probeRootHandles=$null;$probeRootHandle=$null;$probeParentHandle=$null;$caseDataHandle=$null;$cleanupSession=$null
    $requestCapture=$null;$resultCapture=$null;$stdoutCapture=$null;$stderrCapture=$null;$process=$null;$probeRoot=$null
    $primaryException=$null;$reapConfirmed=$false;$validationSucceeded=$false;$probeRootCreated=$false;$preRootAbortReceipt=$null
    $terminalCleanupReceipt=$null;$terminalCleanupKind=''
    $launchedPid=0;$launchedRawCreation=0L;$rootInventoryBefore=@()
    $cleanupJournal=[pscustomobject]@{
        MutationRows=[Collections.Generic.List[object]]::new()
        OwnershipRows=[Collections.Generic.List[object]]::new()
        DeletedRelativePaths=[Collections.Generic.List[string]]::new()
    }
    $cleanupSession=[AiAgentDotfilesTests.HardKillBehaviorCleanupSession]::Begin()
    $pendingToken=$cleanupSession.PendingToken
    $cleanupState=[pscustomobject][ordered]@{
        RegistryToken=$pendingToken;State='Pending';Root=$null;Process=$null;ReapConfirmed=$false;InventoryAtCleanupStart=$null
        DeletedRelativePaths=@();EventRows=$null;OwnedFileRows=$null;EngineEvidence=$null;HostEvidence=$null;CaseRows=$null
        CaseDataHandle=$null;ProbeRootHandle=$null;ProbeParentHandle=$null;ProbeRootHandles=$null;CleanupJournal=$null
        CleanupReceipt=$null;Failures=[Exception[]]@()
    }
    try{
        $script:forensicRoots.Add($pendingToken)
        if(@($script:forensicRoots|Where-Object{[object]::ReferenceEquals($_,$pendingToken)}).Count -ne 1){throw 'behavior-pending-cleanup-token-registration'}
    }catch{
        $state.Error='behavior-pending-cleanup-token-registration: '+$_.Exception.Message
        $state.CleanupErrors=@($_.Exception.Message)
        return [pscustomobject]$state
    }
    try{
        $engineEvidence=$cleanupSession.AcquireAndEnrollHeldFile(
            [AiAgentDotfilesTests.HardKillBehaviorAcquire]{Open-HardKillHeldFileEvidence -Path $EnginePath},
            [AiAgentDotfilesTests.HardKillBehaviorRelease]{param($evidence) Close-HardKillBehaviorHeldEvidenceFailStop -Evidence $evidence})
        $hostEvidence=$cleanupSession.AcquireAndEnrollHeldFile(
            [AiAgentDotfilesTests.HardKillBehaviorAcquire]{Open-HardKillHeldFileEvidence -Path $ProbeHostPath},
            [AiAgentDotfilesTests.HardKillBehaviorRelease]{param($evidence) Close-HardKillBehaviorHeldEvidenceFailStop -Evidence $evidence})
        $utf8=[Text.UTF8Encoding]::new($false,$true);$engineSource=$utf8.GetString($engineEvidence.Bytes);$hostSource=$utf8.GetString($hostEvidence.Bytes)
        $engineTokens=$null;$engineErrors=$null;$null=[Management.Automation.Language.Parser]::ParseInput($engineSource,[ref]$engineTokens,[ref]$engineErrors)
        if(@($engineErrors).Count -ne 0){throw 'behavior-engine-parse'}
        $heldChildPrimitiveAuthority=Test-HardKillBehaviorChildPrimitiveAuthorityPreflight -EngineSource $engineSource
        if(-not $heldChildPrimitiveAuthority.Valid){throw ('behavior-child-primitive-authority:'+[string]$heldChildPrimitiveAuthority.Error)}
        $heldChildCapability=Test-HardKillBehaviorChildCapabilityContract -EngineSource $engineSource
        if(-not $heldChildCapability.Valid){throw ('behavior-child-capability:'+(@($heldChildCapability.ErrorCodes)-join','))}
        $probeContract=Test-HardKillBehaviorProbeHostCaseFlowContract -HostSource $hostSource;$state.ProbeContractValid=$probeContract.Valid
        if(-not $probeContract.Valid){throw ('behavior-probe-contract:'+(@($probeContract.ErrorCodes)-join','))}
        $heldPreimageProvenance=Test-HardKillPreimageProvenanceContract -HostSource $hostSource
        if(-not $heldPreimageProvenance.Valid){throw ('behavior-preimage-provenance:'+(@($heldPreimageProvenance.ErrorCodes)-join','))}

        $scratchFull=[IO.Path]::GetFullPath($ScratchParent);$probeRoot=Join-Path $scratchFull ('sealed-contract-probe-'+[Guid]::NewGuid().ToString('N'))
        Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{Root=$probeRoot})
        if([IO.Path]::GetRelativePath($scratchFull,$probeRoot).StartsWith('..',[StringComparison]::Ordinal)){throw 'behavior-probe-root-escape'}
        $null=[IO.Directory]::CreateDirectory($probeRoot);$probeRootCreated=$true;$state.RootAbsent=$false
        $probeRootHandles=$cleanupSession.AcquireAndEnrollDirectoryChain(
            [AiAgentDotfilesTests.HardKillBehaviorAcquire]{$probeRootChainReceiver=[AiAgentDotfiles.SealedOwnershipTransferReceiver]::new();Open-SafeDirectoryContainmentChain -Path $probeRoot -OwnershipReceiver $probeRootChainReceiver;$probeRootChainReceiver.GetDeliveredExact()},
            [AiAgentDotfilesTests.HardKillBehaviorRelease]{param($handles) Close-SafeDirectoryContainmentChain -Handles $handles})
        if($probeRootHandles.Count -lt 2){throw 'behavior-probe-root-containment'}
        $probeRootHandle=$probeRootHandles[$probeRootHandles.Count-1];$probeParentHandle=$probeRootHandles[$probeRootHandles.Count-2]
        Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{ProbeRootHandles=$probeRootHandles;ProbeRootHandle=$probeRootHandle;ProbeParentHandle=$probeParentHandle})
        $probeRootIdentity=[string]$probeRootHandle.Info.Identity;$probeRootLinkCount=[uint32]$probeRootHandle.Info.LinkCount;$probeRootLength=[long]$probeRootHandle.Info.Length;$probeRootAttributes=[int]$probeRootHandle.Info.Attributes;$probeRootLeaf=[IO.Path]::GetFileName($probeRoot)
        $caseDataPath=Join-Path $probeRoot 'case-data';$null=[IO.Directory]::CreateDirectory($caseDataPath)
        $caseDataHandle=[AiAgentDotfiles.NoFollowFile]::HoldChildDirectory($probeRootHandle,'case-data');$caseDataIdentity=[string]$caseDataHandle.Info.Identity;$caseDataLinkCount=[uint32]$caseDataHandle.Info.LinkCount;$caseDataLength=[long]$caseDataHandle.Info.Length;$caseDataAttributes=[int]$caseDataHandle.Info.Attributes
        Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{CaseDataHandle=$caseDataHandle})

        $controllerNonce=[Guid]::NewGuid().ToString('N');$probeNonce=[Guid]::NewGuid().ToString('N');$requestCases=[Collections.Generic.List[object]]::new()
        $oracleEpochQpc=[Diagnostics.Stopwatch]::GetTimestamp();$oracleDeadlineQpc=[long]($oracleEpochQpc+([long][Diagnostics.Stopwatch]::Frequency*420L))
        for($index=0;$index -lt $ExpectedCases.Count;$index++){
            $name=[string]$ExpectedCases[$index];$caseNonce=[Guid]::NewGuid().ToString('N');$directoryLeaf=('{0:D2}-{1}' -f $index,$caseNonce)
            $directoryPath=Join-Path $caseDataPath $directoryLeaf;$null=[IO.Directory]::CreateDirectory($directoryPath)
            $directoryHandle=[AiAgentDotfiles.NoFollowFile]::HoldChildDirectory($caseDataHandle,$directoryLeaf)
            $readyName="Local\ai-agent-dotfiles-sealed-ready-$probeNonce-$index";$continueName="Local\ai-agent-dotfiles-sealed-continue-$probeNonce-$index"
            $doneName="Local\ai-agent-dotfiles-sealed-done-$probeNonce-$index";$releaseName="Local\ai-agent-dotfiles-sealed-release-$probeNonce-$index"
            $readyCreated=$false;$continueCreated=$false;$doneCreated=$false;$releaseCreated=$false
            $ready=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$readyName,[ref]$readyCreated)
            $continue=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$continueName,[ref]$continueCreated)
            $done=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$doneName,[ref]$doneCreated)
            $release=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$releaseName,[ref]$releaseCreated)
            if(-not $readyCreated -or -not $continueCreated -or -not $doneCreated -or -not $releaseCreated -or
                $ready.WaitOne(0) -or $continue.WaitOne(0) -or $done.WaitOne(0) -or $release.WaitOne(0)){throw 'behavior-probe-event-collision'}
            $oracle=Get-HardKillParentOracleSpec -CaseName $name
            $caseBase=[ordered]@{
                Index=[long]$index;Name=$name;CaseNonce=$caseNonce;AbsoluteDeadlineQpc=$oracleDeadlineQpc.ToString([Globalization.CultureInfo]::InvariantCulture);ReadyEventName=$readyName;ContinueEventName=$continueName;DoneEventName=$doneName;ReleaseEventName=$releaseName
                CaseRelativeDirectory="case-data/$directoryLeaf";ChallengeRelativePath="case-data/$directoryLeaf/challenge.bin";ActionRelativePath="case-data/$directoryLeaf/action.json";ResponseRelativePath="case-data/$directoryLeaf/response.json"
                OracleKind=$oracle.Kind;OperationSequence=$oracle.OperationSequence
            }
            $inputSha=Get-HardKillSha256Hex (ConvertTo-SemanticJsonBytes -InputObject $caseBase)
            $requestCase=[ordered]@{Index=[long]$index;Name=$name;CaseNonce=$caseNonce;InputSha256=$inputSha;AbsoluteDeadlineQpc=$oracleDeadlineQpc.ToString([Globalization.CultureInfo]::InvariantCulture);ReadyEventName=$readyName;ContinueEventName=$continueName;DoneEventName=$doneName;ReleaseEventName=$releaseName;CaseRelativeDirectory=$caseBase.CaseRelativeDirectory;ChallengeRelativePath=$caseBase.ChallengeRelativePath;ActionRelativePath=$caseBase.ActionRelativePath;ResponseRelativePath=$caseBase.ResponseRelativePath;OracleKind=$oracle.Kind;OperationSequence=$oracle.OperationSequence}
            $oracleFixture=New-HardKillBehaviorOracleFixture -CaseName $name -Index $index -CaseNonce $caseNonce -RequestCase $requestCase -CaseDirectoryHandle $directoryHandle -CaseDirectoryPath $directoryPath -ReadyEvent $ready -ContinueEvent $continue -DoneEvent $done -ReleaseEvent $release -AbsoluteDeadlineQpc $oracleDeadlineQpc
            $eventRows.Add($oracleFixture);$requestCases.Add($requestCase);$caseRows.Add([pscustomobject]@{Index=$index;Name=$name;Request=$requestCase;DirectoryLeaf=$directoryLeaf;DirectoryHandle=$directoryHandle;DirectoryIdentity=[string]$directoryHandle.Info.Identity;DirectoryLinkCount=[uint32]$directoryHandle.Info.LinkCount;DirectoryLength=[long]$directoryHandle.Info.Length;DirectoryAttributes=[int]$directoryHandle.Info.Attributes;OracleFixture=$oracleFixture;FileRows=[Collections.Generic.List[object]]::new()})
        }
        $requestDocument=[ordered]@{SchemaVersion=1;ArtifactKind='sealed-mutation-contract-request';ControllerNonce=$controllerNonce;ProbeNonce=$probeNonce;EngineRawSha256=$engineEvidence.Sha256;ProbeHostRawSha256=$hostEvidence.Sha256;Cases=@($requestCases)}
        $requestBytes=ConvertTo-SemanticJsonBytes -InputObject $requestDocument;$requestSha=Get-HardKillSha256Hex $requestBytes
        $requestPath=Join-Path $probeRoot 'request.json';$resultPath=Join-Path $probeRoot 'result.json';$stdoutPath=Join-Path $probeRoot 'stdout.txt';$stderrPath=Join-Path $probeRoot 'stderr.txt'
        Write-HardKillCreateNewBytes -Path $requestPath -Bytes $requestBytes
        $requestCapture=[AiAgentDotfiles.NoFollowFile]::OpenAndHashChildRegularFile($probeRootHandle,'request.json')
        if([string]$requestCapture.ReadResult.Sha256 -cne $requestSha){throw 'behavior-request-capture-drift'}
        $ownedFileRows.Add([pscustomobject]@{Parent=$probeRootHandle;Leaf='request.json';Capture=$requestCapture;CaptureState='Live';Identity=[string]$requestCapture.Info.Identity;LinkCount=[uint32]$requestCapture.Info.LinkCount;Length=[long]$requestCapture.Info.Length;Attributes=[int]$requestCapture.Info.Attributes;Kind='root'});$requestCapture=$null

        $state.LaunchAttempted=$true
        $process=Start-HardKillRegisteredProcess -FilePath ([IO.Path]::Combine($PSHOME,'pwsh.exe')) -ArgumentList @(
            '-NoProfile','-File',$hostEvidence.Path,'-ContractProbe','-MutationEnginePath',$engineEvidence.Path,
            '-ContractProbeRequestPath',$requestPath,'-ContractProbeRequestSha256',$requestSha,
            '-ExpectedEngineSha256',$engineEvidence.Sha256,'-ExpectedProbeHostSha256',$hostEvidence.Sha256,
            '-ContractProbeResultPath',$resultPath,'-ContractProbeScratchRoot',$caseDataPath,
            '-ToolchainRoot',$probeRoot,'-FixtureRoot',$probeRoot,'-TransactionId',([Guid]::NewGuid().ToString()),
            '-Kind','directory','-Checkpoint','contract-probe','-MarkerPath',(Join-Path $probeRoot 'contract-probe.marker')
        ) -RedirectStandardOutputPath $stdoutPath -RedirectStandardErrorPath $stderrPath
        Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{Process=$process})
        $launchedPid=[int]$process.Id;$state.LaunchedPid=$launchedPid;$launchedRawCreation=[long]$process.HardKillJobProcess.RootCreationFileTimeTicks
        for($index=0;$index -lt $caseRows.Count;$index++){
            $row=$caseRows[$index];$fixture=$row.OracleFixture;$remaining=Get-HardKillRemainingQpcMilliseconds -AbsoluteDeadlineQpc $oracleDeadlineQpc
            if($remaining -le 0 -or -not $fixture.ReadyEvent.WaitOne($remaining)){throw "behavior-ready-timeout:$($row.Name)"}
            $actionNonce=[Guid]::NewGuid().ToString('N');$action=Invoke-HardKillBehaviorOracleAction -Fixture $fixture -Process $process -ActionNonce $actionNonce
            $fixture.ParentQpcAtReady=[long]$action.ParentQpcAtReady;$fixture.JobActiveBefore=[long]$action.JobActiveBefore;$fixture.ChallengeWin32Error=[long]$action.ChallengeWin32Error
            $actionCapture=[AiAgentDotfiles.NoFollowFile]::CreateAndSealChildRegularFile($row.DirectoryHandle,'action.json',$action.Bytes)
            $fileRow=[pscustomobject]@{Parent=$row.DirectoryHandle;Leaf='action.json';Capture=$actionCapture;CaptureState='Live';Identity=[string]$actionCapture.Info.Identity;LinkCount=[uint32]$actionCapture.Info.LinkCount;Length=[long]$actionCapture.Info.Length;Attributes=[int]$actionCapture.Info.Attributes;Kind='case'};$row.FileRows.Add($fileRow);$ownedFileRows.Add($fileRow)
            if(-not $fixture.ContinueEvent.Set()){throw "behavior-continue-signal:$($row.Name)"}
            $remaining=Get-HardKillRemainingQpcMilliseconds -AbsoluteDeadlineQpc $oracleDeadlineQpc
            if($remaining -le 0 -or -not $fixture.DoneEvent.WaitOne($remaining)){throw "behavior-done-timeout:$($row.Name)"}
            $observation=Complete-HardKillBehaviorOracleObservation -Fixture $fixture -Process $process -JobProcess $process.HardKillJobProcess -DeadlineQpc $oracleDeadlineQpc
            if(-not(Test-HardKillBehaviorOracleObservation -Fixture $fixture -Observation $observation)){throw "behavior-oracle-observation:$($row.Name)"}
            if(-not $fixture.ReleaseEvent.Set()){throw "behavior-release-signal:$($row.Name)"}
            $challengeInfo=[AiAgentDotfiles.NoFollowFile]::InspectChild($row.DirectoryHandle,'challenge.bin')
            $responseInfo=[AiAgentDotfiles.NoFollowFile]::InspectChild($row.DirectoryHandle,'response.json')
            $row.FileRows.Add([pscustomobject]@{Parent=$row.DirectoryHandle;Leaf='challenge.bin';Capture=$null;CaptureState='Closed';Identity=[string]$challengeInfo.Identity;LinkCount=[uint32]$challengeInfo.LinkCount;Length=[long]$challengeInfo.Length;Attributes=[int]$challengeInfo.Attributes;Kind='case'})
            $row.FileRows.Add([pscustomobject]@{Parent=$row.DirectoryHandle;Leaf='response.json';Capture=$null;CaptureState='Closed';Identity=[string]$responseInfo.Identity;LinkCount=[uint32]$responseInfo.LinkCount;Length=[long]$responseInfo.Length;Attributes=[int]$responseInfo.Attributes;Kind='case'})
            $parentObservations.Add($observation)
        }
        $remaining=Get-HardKillRemainingQpcMilliseconds -AbsoluteDeadlineQpc $oracleDeadlineQpc
        if($remaining -le 0 -or -not $process.WaitForExit($remaining)){throw 'behavior-probe-timeout'}
        foreach($event in @($eventRows)){Close-HardKillBehaviorOracleFixture -Fixture $event}
        $exitCode=[int]$process.ExitCode
        $normalReapReceipt=Confirm-HardKillRegisteredProcessReaped -Process $process -Label 'sealed mutation behavioral probe'
        if($normalReapReceipt -isnot [bool] -or -not $normalReapReceipt){throw 'behavior-probe-reap-receipt-invalid'}
        $reapConfirmed=$true;$process=$null
        Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{Process=$null;ReapConfirmed=$true})
        if($exitCode -ne 0){throw "behavior-probe-exit:$exitCode"}

        foreach($leaf in @('result.json','stdout.txt','stderr.txt')){
            $capture=[AiAgentDotfiles.NoFollowFile]::OpenAndHashChildRegularFile($probeRootHandle,$leaf)
            $fileRow=[pscustomobject]@{Parent=$probeRootHandle;Leaf=$leaf;Capture=$capture;CaptureState='Live';Identity=[string]$capture.Info.Identity;LinkCount=[uint32]$capture.Info.LinkCount;Length=[long]$capture.Info.Length;Attributes=[int]$capture.Info.Attributes;Kind='root'}
            $ownedFileRows.Add($fileRow)
            switch($leaf){'result.json'{$resultCapture=$capture};'stdout.txt'{$stdoutCapture=$capture};'stderr.txt'{$stderrCapture=$capture}}
        }
        $stderrBytes=[IO.File]::ReadAllBytes($stderrPath);if($stderrBytes.Length -ne 0){throw 'behavior-probe-stderr'}
        $resultBytes=[IO.File]::ReadAllBytes($resultPath)
        if((Get-HardKillSha256Hex $resultBytes) -cne [string]$resultCapture.ReadResult.Sha256 -or $resultBytes.LongLength -ne [long]$resultCapture.ReadResult.Length){throw 'behavior-result-capture-drift'}
        $resultText=$utf8.GetString($resultBytes);$document=ConvertFrom-SemanticJson -Json $resultText
        if([Convert]::ToBase64String($resultBytes) -cne [Convert]::ToBase64String((ConvertTo-SemanticJsonBytes -InputObject $document))){throw 'behavior-result-noncanonical'}
        $topKeys=@('SchemaVersion','ArtifactKind','RequestSha256','EngineRawSha256','ProbeHostRawSha256','HostIdentity','Cases','EvidenceInventorySha256','HashChainTailSha256','RawFailure')
        if(-not(Test-HardKillExactObjectKeys $document $topKeys) -or $document.SchemaVersion -isnot [long] -or $document.SchemaVersion -ne 1 -or
            $document.ArtifactKind -isnot [string] -or $document.ArtifactKind -cne 'sealed-mutation-contract-raw-evidence' -or
            $document.RequestSha256 -cne $requestSha -or $document.EngineRawSha256 -cne $engineEvidence.Sha256 -or $document.ProbeHostRawSha256 -cne $hostEvidence.Sha256 -or $null -ne $document.RawFailure){throw 'behavior-result-top-contract'}
        if(-not(Test-HardKillExactObjectKeys $document.HostIdentity @('Pid','RootCreationFileTimeTicks')) -or $document.HostIdentity.Pid -isnot [long] -or
            $document.HostIdentity.Pid -ne $launchedPid -or $document.HostIdentity.RootCreationFileTimeTicks -isnot [string] -or
            $document.HostIdentity.RootCreationFileTimeTicks -cne $launchedRawCreation.ToString([Globalization.CultureInfo]::InvariantCulture)){throw 'behavior-result-host-identity'}

        foreach($index in @(0..($caseRows.Count-1))){
            $row=$caseRows[$index]
            if($row.Name -cin @('rollback-stage-cleanup-failure-no-proof','preimage-stage-cleanup-failure-no-proof')){
                $children=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($row.DirectoryHandle)|Sort-Object)
                $forensicCapture=[AiAgentDotfiles.NoFollowFile]::OpenAndHashChildRegularFile($row.DirectoryHandle,'forensic.bin')
                $fileRow=[pscustomobject]@{Parent=$row.DirectoryHandle;Leaf='forensic.bin';Capture=$forensicCapture;CaptureState='Live';Identity=[string]$forensicCapture.Info.Identity;LinkCount=[uint32]$forensicCapture.Info.LinkCount;Length=[long]$forensicCapture.Info.Length;Attributes=[int]$forensicCapture.Info.Attributes;Kind='case'}
                $row.FileRows.Add($fileRow);$ownedFileRows.Add($fileRow)
                $parentObservations[$index]|Add-Member -NotePropertyName ForensicObserved -NotePropertyValue $true -Force
                $parentObservations[$index]|Add-Member -NotePropertyName ProofAbsentObserved -NotePropertyValue ('proof.json' -cnotin $children) -Force
                $parentObservations[$index]|Add-Member -NotePropertyName ForensicIdentity -NotePropertyValue ([string]$forensicCapture.ReadResult.Identity) -Force
                $parentObservations[$index]|Add-Member -NotePropertyName ForensicLength -NotePropertyValue ([long]$forensicCapture.ReadResult.Length) -Force
                $parentObservations[$index]|Add-Member -NotePropertyName ForensicRawSha256 -NotePropertyValue ([string]$forensicCapture.ReadResult.Sha256) -Force
                $parentObservations[$index].CleanupBlockerHeld=$true
            }else{
                $parentObservations[$index]|Add-Member -NotePropertyName ForensicObserved -NotePropertyValue $false -Force
                $parentObservations[$index]|Add-Member -NotePropertyName ProofAbsentObserved -NotePropertyValue $false -Force
                $parentObservations[$index]|Add-Member -NotePropertyName ForensicIdentity -NotePropertyValue '' -Force
                $parentObservations[$index]|Add-Member -NotePropertyName ForensicLength -NotePropertyValue 0L -Force
                $parentObservations[$index]|Add-Member -NotePropertyName ForensicRawSha256 -NotePropertyValue '' -Force
            }
        }
        $cases=@($document.Cases);if($cases.Count -ne $ExpectedCases.Count){throw 'behavior-result-case-count'}
        $passed=[Collections.Generic.List[string]]::new();$prior=('0'*64);$inventoryRows=[Collections.Generic.List[object]]::new()
        for($index=0;$index -lt $cases.Count;$index++){
            $case=$cases[$index];$requestCase=$requestCases[$index];$observation=$parentObservations[$index]
            if(Test-HardKillBehaviorCaseEvidence -Case $case -RequestCase $requestCase -ParentObservation $observation -ExpectedPriorRowSha256 $prior){$passed.Add([string]$requestCase.Name)}
            $prior=if($case -is [Collections.IDictionary] -and $case.Contains('RowSha256') -and $case.RowSha256 -is [string]){[string]$case.RowSha256}else{''}
            $inventoryRows.Add([ordered]@{Index=[long]$index;Name=[string]$requestCase.Name;Artifacts=@($case.Artifacts)})
        }
        $names=@($cases|ForEach-Object{if($_ -is [Collections.IDictionary] -and $_['Name'] -is [string]){[string]$_['Name']}else{''}})
        $inventorySha=Get-HardKillSha256Hex (ConvertTo-SemanticJsonBytes -InputObject @($inventoryRows))
        if(@(Compare-Object $ExpectedCases $names -CaseSensitive).Count -ne 0 -or $document.EvidenceInventorySha256 -cne $inventorySha -or $document.HashChainTailSha256 -cne $prior){throw 'behavior-result-chain'}
        $rootInventoryBefore=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($probeRootHandle)|Sort-Object)
        if(@(Compare-Object @('case-data','request.json','result.json','stderr.txt','stdout.txt') $rootInventoryBefore -CaseSensitive).Count -ne 0){throw 'behavior-root-inventory'}
        $caseDirectoryInventory=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($caseDataHandle)|Sort-Object)
        $expectedDirectories=@($caseRows|ForEach-Object{$_.DirectoryLeaf}|Sort-Object)
        if(@(Compare-Object $expectedDirectories $caseDirectoryInventory -CaseSensitive).Count -ne 0){throw 'behavior-case-directory-inventory'}
        foreach($row in $caseRows){
            $expectedLeaves=@('action.json','challenge.bin','response.json');if($row.Name -cin @('rollback-stage-cleanup-failure-no-proof','preimage-stage-cleanup-failure-no-proof')){$expectedLeaves+='forensic.bin'}
            $actualLeaves=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($row.DirectoryHandle)|Sort-Object)
            if(@(Compare-Object @($expectedLeaves|Sort-Object) $actualLeaves -CaseSensitive).Count -ne 0){throw "behavior-case-inventory:$($row.Name)"}
        }
        $failed=@($ExpectedCases|Where-Object{$_ -cnotin @($passed)});$validationSucceeded=$failed.Count -eq 0
        if(-not $validationSucceeded){throw 'behavior-parent-verdict-failed'}
        $state.CaseNames=$names;$state.PassedCases=@($passed);$state.FailedCases=$failed;$state.ParentObservations=@($parentObservations);$state.Error=''
    }catch{
        if($null -eq $primaryException){$primaryException=$_.Exception}
        $state.Error=$primaryException.Message
    }finally{
        $forensicInventory=$null;$cleanupReceipt=$null;$cleanupMutationAllowed=$false
        if(-not $probeRootCreated -and $null -ne $cleanupSession -and $null -ne $pendingToken -and $null -ne $primaryException -and $null -eq $process -and $launchedPid -eq 0){
            try{
                $preRootAbortReceipt=$cleanupSession.AbortBeforeRoot()
                if($preRootAbortReceipt -isnot [AiAgentDotfilesTests.HardKillBehaviorCleanupReceipt] -or -not $preRootAbortReceipt.RootAbsent -or
                    -not $preRootAbortReceipt.LeasesClosed -or -not $preRootAbortReceipt.DeleteReceiptsValidated -or
                    @($preRootAbortReceipt.DeletedRelativePaths).Count -ne 0 -or
                    @($script:forensicRoots|Where-Object{[object]::ReferenceEquals($_,$pendingToken)}).Count -ne 1){
                    throw 'behavior-pre-root-abort-receipt-invalid'
                }
                $cleanupReceipt=$preRootAbortReceipt;$terminalCleanupReceipt=$preRootAbortReceipt;$terminalCleanupKind='PreRootAbort'
            }catch{$cleanupErrors.Add([InvalidOperationException]::new('behavior-pre-root-abort-failed',$_.Exception))}
        }
        if($process -and -not $reapConfirmed){
            try{
                $cleanupReapReceipt=Confirm-HardKillRegisteredProcessReaped -Process $process -Label 'sealed mutation behavioral probe cleanup'
                if($cleanupReapReceipt -isnot [bool] -or -not $cleanupReapReceipt){throw 'behavior-probe-cleanup-reap-receipt-invalid'}
                $reapConfirmed=$true;$process=$null
                Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{Process=$null;ReapConfirmed=$true})
            }catch{$cleanupErrors.Add([InvalidOperationException]::new('behavior-probe-cleanup-reap-failed',$_.Exception))}
        }
        if($launchedPid -gt 0 -and -not $reapConfirmed -and $cleanupErrors.Count -eq 0){
            $cleanupErrors.Add([InvalidOperationException]::new('behavior-process-reap-not-confirmed'))
        }
        if($reapConfirmed -and $validationSucceeded -and $cleanupErrors.Count -eq 0){
            try{
                $forensicInventory=Get-HardKillBehaviorProbeInventory -ProbeRootHandle $probeRootHandle -CaseDataHandle $caseDataHandle -CaseRows $caseRows
                Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{InventoryAtCleanupStart=$forensicInventory})
                $cleanupMutationAllowed=$true
            }catch{$cleanupErrors.Add([InvalidOperationException]::new('behavior-probe-cleanup-inventory-failed',$_.Exception))}
        }
        if($cleanupMutationAllowed -and $validationSucceeded){
            try{
                $cleanupReceipt=Invoke-HardKillBehaviorProbeCleanupAfterReap -CleanupSession $cleanupSession -PendingToken $cleanupState -EventRows $eventRows -OwnedFileRows $ownedFileRows `
                    -EngineEvidence $engineEvidence -HostEvidence $hostEvidence -CaseRows $caseRows -CaseDataHandle $caseDataHandle -CaseDataIdentity $caseDataIdentity `
                    -CaseDataLinkCount $caseDataLinkCount -CaseDataLength $caseDataLength -CaseDataAttributes $caseDataAttributes `
                    -ProbeRootHandle $probeRootHandle -ProbeParentHandle $probeParentHandle -ProbeRootHandles $probeRootHandles -ProbeRootLeaf $probeRootLeaf `
                    -ProbeRootIdentity $probeRootIdentity -ProbeRootLinkCount $probeRootLinkCount -ProbeRootLength $probeRootLength -ProbeRootAttributes $probeRootAttributes -CleanupJournal $cleanupJournal
                if($cleanupReceipt -isnot [AiAgentDotfilesTests.HardKillBehaviorCleanupReceipt] -or -not $cleanupReceipt.RootAbsent -or
                    -not $cleanupReceipt.LeasesClosed -or -not $cleanupReceipt.DeleteReceiptsValidated){throw 'behavior-cleanup-receipt-invalid'}
                if(@(Compare-Object @($cleanupJournal.DeletedRelativePaths) @($cleanupReceipt.DeletedRelativePaths) -CaseSensitive).Count -ne 0){throw 'behavior-cleanup-receipt-paths'}
                Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{
                    State='CleanupReceiptValidated';Process=$null;ReapConfirmed=$true;DeletedRelativePaths=@($cleanupReceipt.DeletedRelativePaths)
                    EventRows=$null;OwnedFileRows=$null;EngineEvidence=$null;HostEvidence=$null;CaseRows=$null;CaseDataHandle=$null
                    ProbeRootHandle=$null;ProbeParentHandle=$null;ProbeRootHandles=$null;CleanupReceipt=$cleanupReceipt
                })
                $terminalCleanupReceipt=$cleanupReceipt;$terminalCleanupKind='FullCleanup'
            }catch{
                $cleanupMutationAllowed=$false
                $cleanupErrors.Add([InvalidOperationException]::new(('behavior-probe-cleanup-failed: '+$_.Exception.Message),$_.Exception))
            }
        }
        if($null -ne $terminalCleanupReceipt){
            try{
                if(@($script:forensicRoots|Where-Object{[object]::ReferenceEquals($_,$pendingToken)}).Count -ne 1){throw 'behavior-pending-cleanup-token-release-ownership'}
                $tokenRemoved=$script:forensicRoots.Remove($pendingToken)
                if($tokenRemoved -isnot [bool] -or -not $tokenRemoved -or
                    @($script:forensicRoots|Where-Object{[object]::ReferenceEquals($_,$pendingToken)}).Count -ne 0){
                    throw 'behavior-pending-cleanup-token-remove-failed'
                }
                if($terminalCleanupKind -ceq 'FullCleanup'){
                    $probeRootHandles=$null;$probeRootHandle=$null;$probeParentHandle=$null;$caseDataHandle=$null
                }elseif($terminalCleanupKind -cne 'PreRootAbort'){
                    throw 'behavior-pending-cleanup-terminal-kind'
                }
                $engineEvidence=$null;$hostEvidence=$null;$state.RootAbsent=$true;$state.ForensicRoot='';$state.Residue=0
            }catch{
                $cleanupErrors.Add([InvalidOperationException]::new((if($terminalCleanupKind -ceq 'PreRootAbort'){'behavior-pre-root-abort-failed'}else{'behavior-probe-cleanup-failed'}),$_.Exception))
            }
        }
        if(@($script:forensicRoots|Where-Object{[object]::ReferenceEquals($_,$pendingToken)}).Count -eq 1){
            $orderedFailures=[Collections.Generic.List[Exception]]::new()
            if($null -ne $primaryException){$orderedFailures.Add($primaryException)}
            foreach($cleanupError in $cleanupErrors){$orderedFailures.Add($cleanupError)}
            if($probeRootCreated){
                try{
                    Set-HardKillBehaviorPendingCleanupToken -Token $cleanupState -Values ([ordered]@{
                        State='Forensic';Root=$probeRoot;Process=$process;ReapConfirmed=$reapConfirmed;InventoryAtCleanupStart=$forensicInventory
                        DeletedRelativePaths=@($cleanupJournal.DeletedRelativePaths);EventRows=$eventRows;OwnedFileRows=$ownedFileRows
                        EngineEvidence=$engineEvidence;HostEvidence=$hostEvidence;CaseRows=$caseRows;CaseDataHandle=$caseDataHandle
                        ProbeRootHandle=$probeRootHandle;ProbeParentHandle=$probeParentHandle;ProbeRootHandles=$probeRootHandles
                        CleanupJournal=$cleanupJournal;CleanupReceipt=$cleanupReceipt;Failures=[Exception[]]$orderedFailures.ToArray()
                    })
                }catch{$cleanupErrors.Add([InvalidOperationException]::new('behavior-pending-cleanup-token-update-failed',$_.Exception))}
                $state.RootAbsent=$false;$state.ForensicRoot=$probeRoot
                $state.Residue=if($forensicInventory){@($forensicInventory.RootChildren).Count}else{-1}
            }else{
                $state.RootAbsent=$true;$state.ForensicRoot=''
                $state.Residue=-1
            }
        }
        $allFailures=[Collections.Generic.List[Exception]]::new()
        if($null -ne $primaryException){$allFailures.Add($primaryException)}
        foreach($cleanupError in $cleanupErrors){$allFailures.Add($cleanupError)}
        if($allFailures.Count -gt 0){$validationSucceeded=$false;$state.Error=(@($allFailures|ForEach-Object{$_.Message}) -join ' | ')}
        $state.CleanupErrors=@($cleanupErrors|ForEach-Object{$_.Message})
        $state.Valid=$validationSucceeded -and $reapConfirmed -and $state.RootAbsent -and $cleanupErrors.Count -eq 0
        if(-not $state.Valid -and @($state.PassedCases).Count -eq 0){$state.FailedCases=@($ExpectedCases)}
    }
    return [pscustomobject]$state
}
function Get-HardKillStructuralSha256 {
    param([AllowNull()][Management.Automation.Language.Ast]$Ast)
    if($null -eq $Ast){return ''}
    return [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData(
        [Text.Encoding]::UTF8.GetBytes((Get-HardKillStructuralProjection $Ast))
    )).ToLowerInvariant()
}
function Test-HardKillProductionClosureSourceMap {
    param(
        [Parameter(Mandatory)][Collections.IDictionary]$SourceByRelativePath,
        [Parameter(Mandatory)][string[]]$OwnedRelativePaths,
        [Parameter(Mandatory)][string[]]$Roots,
        [Parameter(Mandatory)][string[]]$AllowedBoundaryIds,
        [Parameter(Mandatory)][object[]]$ExceptionManifest,
        [Parameter(Mandatory)][string[]]$AllowedLeafCommandNames,
        [Parameter(Mandatory)][ValidatePattern('^[0-9a-f]{64}$')][string]$ExpectedClosureDigest
    )
    $violations=[Collections.Generic.List[string]]::new();$definitionsByName=@{};$definitionsById=@{};$asts=@{}
    foreach($relativePath in @($SourceByRelativePath.Keys|Sort-Object)){
        $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput([string]$SourceByRelativePath[$relativePath],[ref]$tokens,[ref]$errors)
        if(@($errors).Count -ne 0){$violations.Add("parse:$relativePath");continue}
        $asts[$relativePath]=$ast
        foreach($definition in @($ast.FindAll({param($node)$node -is [Management.Automation.Language.FunctionDefinitionAst]},$true))){
            $id="$relativePath::$($definition.Name)";$definitionsById[$id]=[pscustomobject]@{Id=$id;Path=$relativePath;Name=$definition.Name;Ast=$definition;Owned=$relativePath -cin $OwnedRelativePaths}
            if(-not $definitionsByName.ContainsKey($definition.Name)){$definitionsByName[$definition.Name]=[Collections.Generic.List[object]]::new()}
            $definitionsByName[$definition.Name].Add($definitionsById[$id])
        }
    }
    $queue=[Collections.Generic.Queue[object]]::new()
    foreach($rootName in $Roots){
        $allMatches=@(if($definitionsByName.ContainsKey($rootName)){$definitionsByName[$rootName]})
        $matches=@($allMatches|Where-Object{$_.Owned})
        if($allMatches.Count -ne 1 -or $matches.Count -ne 1){$violations.Add("root-cardinality:$rootName")}else{$queue.Enqueue($matches[0])}
    }
    $seen=@{};$edges=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$boundaries=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    while($queue.Count -gt 0){
        $current=$queue.Dequeue();if($seen.ContainsKey($current.Id)){continue};$seen[$current.Id]=$current
        $ownedDuplicates=@($definitionsByName[$current.Name]|Where-Object{$_.Owned})
        if($ownedDuplicates.Count -ne 1){$violations.Add("ambiguous-owned:$($current.Name)");continue}
        if($null -ne $current.Ast.Body.ParamBlock){
            foreach($parameter in @($current.Ast.Body.ParamBlock.Parameters)){
                if($parameter.StaticType -eq [scriptblock]){$violations.Add("scriptblock-parameter:$($current.Id):$(Get-HardKillStructuralSha256 $parameter)")}
            }
        }
        foreach($command in @($current.Ast.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$current.Ast)})){
            if($command.InvocationOperator -in @([Management.Automation.Language.TokenKind]::Ampersand,[Management.Automation.Language.TokenKind]::Dot) -and
                ($command.CommandElements.Count -eq 0 -or $command.CommandElements[0] -isnot [Management.Automation.Language.StringConstantExpressionAst])){
                $violations.Add("dynamic-command-invocation:$($current.Id):$(Get-HardKillStructuralSha256 $command)");continue
            }
            $callee=$command.GetCommandName()
            if([string]::IsNullOrWhiteSpace($callee)){$violations.Add("unknown-command-shape:$($current.Id)");continue}
            if(-not $definitionsByName.ContainsKey($callee)){
                if($callee -cnotin $AllowedLeafCommandNames){$violations.Add("unknown-callee:$($current.Id):$callee")}
                continue
            }
            $matches=@($definitionsByName[$callee]);$owned=@($matches|Where-Object{$_.Owned});$outside=@($matches|Where-Object{-not $_.Owned})
            if($owned.Count -gt 1 -or ($owned.Count -eq 1 -and $outside.Count -gt 0)){$violations.Add("ambiguous-helper:$callee");continue}
            if($owned.Count -eq 1){$null=$edges.Add("$($current.Id)->$($owned[0].Id)");$queue.Enqueue($owned[0]);continue}
            if($outside.Count -ne 1){$violations.Add("ambiguous-boundary:$callee");continue}
            $boundaryId=[string]$outside[0].Id;$null=$boundaries.Add($boundaryId)
            if($boundaryId -cnotin $AllowedBoundaryIds){$violations.Add("unapproved-boundary:$boundaryId")}
        }
    }
    $actualExceptions=[Collections.Generic.List[string]]::new()
    foreach($boundaryId in @($boundaries|Sort-Object)){
        if(-not $definitionsById.ContainsKey($boundaryId)){continue};$definition=$definitionsById[$boundaryId].Ast
        $nodes=@($definition.FindAll({param($node)
            ($node -is [Management.Automation.Language.ParameterAst] -and $node.StaticType -eq [scriptblock]) -or
            ($node -is [Management.Automation.Language.CommandAst] -and $node.InvocationOperator -in @([Management.Automation.Language.TokenKind]::Ampersand,[Management.Automation.Language.TokenKind]::Dot) -and
                $node.CommandElements.Count -gt 0 -and $node.CommandElements[0] -isnot [Management.Automation.Language.StringConstantExpressionAst])
        },$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$definition)})
        foreach($node in $nodes){$actualExceptions.Add("$boundaryId::$($node.GetType().Name)::$(Get-HardKillStructuralSha256 $node)")}
    }
    $expectedExceptions=@($ExceptionManifest|ForEach-Object{"$($_.RelativePath)::$($_.FunctionName)::$($_.NodeKind)::$($_.NodeDigest)"}|Sort-Object)
    if(@(Compare-Object $expectedExceptions @($actualExceptions|Sort-Object) -CaseSensitive).Count -ne 0){$violations.Add('exception-manifest-drift')}
    $functionIds=@($seen.Keys|Sort-Object);$edgeIds=@($edges|Sort-Object);$boundaryIds=@($boundaries|Sort-Object)
    $closureDigest=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes(($functionIds+$edgeIds+$boundaryIds -join "`n")))).ToLowerInvariant()
    if($closureDigest -cne $ExpectedClosureDigest){$violations.Add('closure-manifest-drift')}
    return [pscustomobject]@{
        Valid=$violations.Count -eq 0;FunctionIds=$functionIds;Edges=$edgeIds;BoundaryIds=$boundaryIds;ExceptionIds=@($actualExceptions|Sort-Object);Violations=@($violations)
        ClosureDigest=$closureDigest
    }
}
function Test-HardKillProductionClosureContract {
    param([Parameter(Mandatory)][string]$ScriptsRoot,[Parameter(Mandatory)][string[]]$Roots)
    $result=[ordered]@{
        Valid=$false;FunctionCount=0;EdgeCount=0;BoundaryCount=0;ClosureDigest='';AllScriptsCovered=$false;IdentifierSurfaceValid=$false
        ScriptBlockReject=$false;DynamicReject=$false;DuplicateReject=$false;UnknownReject=$false;NeutralHelperReject=$false;FifthMirrorReject=$false
        ApprovedControl=$false;SafeTreeControl=$false;ExceptionManifestValid=$false;Error=''
    }
    try{
        $owned=@('canonical-mutation-common.ps1','canonical-skill-adapter-common.ps1','canonical-transaction-common.ps1','canonical-recovery-common.ps1','transaction-journal-common.ps1','json-artifact-common.ps1')
        $scriptsFull=[IO.Path]::GetFullPath($ScriptsRoot)
        $scriptFiles=@(Microsoft.PowerShell.Management\Get-ChildItem -LiteralPath $scriptsFull -Recurse -Filter '*.ps1' -File|Sort-Object FullName)
        if($scriptFiles.Count -eq 0){throw 'production-closure-script-inventory-empty'}
        $sourceMap=[ordered]@{}
        foreach($file in $scriptFiles){
            $relative=[IO.Path]::GetRelativePath($scriptsFull,$file.FullName).Replace('\','/')
            if($relative.StartsWith('..',[StringComparison]::Ordinal) -or $sourceMap.Contains($relative)){throw 'production-closure-script-inventory-invalid'}
            $sourceMap[$relative]=[IO.File]::ReadAllText($file.FullName)
        }
        $allScriptsCovered=$sourceMap.Count -eq $scriptFiles.Count -and $sourceMap.Contains('internal/live-transaction-host.ps1') -and
            @($owned|Where-Object{-not $sourceMap.Contains($_)}).Count -eq 0
        if(-not $allScriptsCovered){throw 'production-closure-script-inventory-incomplete'}
        $boundaries=@(
            'safe-tree-walker.ps1::Test-SafePathInsideRoot','safe-tree-walker.ps1::Open-SafeDirectoryContainmentChain','safe-tree-walker.ps1::Open-SafeExistingDirectoryContainmentChain','safe-tree-walker.ps1::Close-SafeDirectoryContainmentChain',
            'safe-tree-walker.ps1::Get-NoFollowRootEntryMarker','safe-tree-walker.ps1::Get-SafeTreeSnapshotInternal','safe-tree-walker.ps1::Get-SafeTreeSnapshot','safe-tree-walker.ps1::Copy-SafeTree',
            'safe-tree-walker.ps1::Open-SafeTreeRetainedTraversal',
            'scan-input-common.ps1::Get-ProtectedReasonixRelativePaths','scan-input-common.ps1::Test-PathInsideRoot',
            'semantic-json.ps1::ConvertFrom-SemanticJson','semantic-json.ps1::ConvertTo-SemanticJsonBytes','semantic-json.ps1::Get-SemanticJsonHash'
        )
        $exceptions=@(
            [pscustomobject]@{RelativePath='safe-tree-walker.ps1';FunctionName='Copy-SafeTree';NodeKind='ParameterAst';NodeDigest='c341358ecef544310944b4f171dc99fc267da6b6e4a0ae20c926745fdbac95a3'},
            [pscustomobject]@{RelativePath='safe-tree-walker.ps1';FunctionName='Get-SafeTreeSnapshot';NodeKind='ParameterAst';NodeDigest='c341358ecef544310944b4f171dc99fc267da6b6e4a0ae20c926745fdbac95a3'},
            [pscustomobject]@{RelativePath='safe-tree-walker.ps1';FunctionName='Open-SafeTreeRetainedTraversal';NodeKind='ParameterAst';NodeDigest='c341358ecef544310944b4f171dc99fc267da6b6e4a0ae20c926745fdbac95a3'}
        )
        $allowedLeaves=@('Add-Member','Compare-Object','ForEach-Object','git','Join-Path','Out-Null','Resolve-Path','Select-Object','Sort-Object','Split-Path','Test-Path','Where-Object')
        $expectedDigest='a719c9cb940a98e091941ef079e317f0f28b6e4f66d7a9f513b5232933ab2d9c'
        function TestIdentifierSurface([Collections.IDictionary]$Map){
            $violations=[Collections.Generic.List[string]]::new()
            $forbidden=@('AiAgentDotfilesTests','SealedMutation','SealedCanonical','Invoke-SealedMutationReach','InvocationContext','SealedStageRootLease','SealedStageFileLease','SealedJobQpcDeadlines','StageCoordinator')
            foreach($relative in @($Map.Keys|Sort-Object)){
                $text=[string]$Map[$relative]
                foreach($identifier in $forbidden){if($text.IndexOf($identifier,[StringComparison]::OrdinalIgnoreCase) -ge 0){$violations.Add(('forbidden-production-test-identifier:{0}:{1}' -f $relative,$identifier))}}
            }
            return [pscustomobject]@{Valid=$violations.Count -eq 0;Violations=@($violations)}
        }
        function InvokeClosure([Collections.IDictionary]$Map){
            return Test-HardKillProductionClosureSourceMap -SourceByRelativePath $Map -OwnedRelativePaths $owned -Roots $Roots `
                -AllowedBoundaryIds $boundaries -ExceptionManifest $exceptions -AllowedLeafCommandNames $allowedLeaves -ExpectedClosureDigest $expectedDigest
        }
        $baseline=InvokeClosure $sourceMap
        $baselineIdentifiers=TestIdentifierSurface $sourceMap
        function NewClosureMutation([Collections.IDictionary]$Map,[string]$Path,[string]$Helper,[string]$Call,[switch]$DuplicateRoot){
            $clone=[ordered]@{};foreach($key in $Map.Keys){$clone[$key]=[string]$Map[$key]}
            if($DuplicateRoot){$clone[$Path]+="`nfunction Initialize-CanonicalRecoveryWorkspace {}`n";return $clone}
            $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($clone[$Path],[ref]$tokens,[ref]$errors);if(@($errors).Count -ne 0){throw 'closure-mutation-baseline-parse'}
            $root=Get-HardKillFunctionAst -Ast $ast -Name 'Initialize-CanonicalRecoveryWorkspace';if($null -eq $root){throw 'closure-mutation-root-missing'}
            $insert=$root.Body.ParamBlock.Extent.EndOffset;$clone[$Path]=$clone[$Path].Insert($insert,"`n$Call`n")+"`n$Helper`n";return $clone
        }
        $scriptBlockMap=NewClosureMutation $sourceMap 'canonical-mutation-common.ps1' 'function Invoke-NeutralClosureScriptBlock { param([scriptblock]$Action) }' 'Invoke-NeutralClosureScriptBlock'
        $dynamicMap=NewClosureMutation $sourceMap 'canonical-mutation-common.ps1' 'function Invoke-NeutralClosureDynamic { param($Action); & $Action }' 'Invoke-NeutralClosureDynamic -Action Get-Date'
        $unknownMap=NewClosureMutation $sourceMap 'canonical-mutation-common.ps1' '' 'Invoke-NeutralUnknownCallee'
        $neutralMap=NewClosureMutation $sourceMap 'canonical-mutation-common.ps1' 'function Invoke-NeutralClosureHelper { return 1 }' 'Invoke-NeutralClosureHelper'
        $duplicateMap=NewClosureMutation $sourceMap 'internal/live-transaction-host.ps1' '' '' -DuplicateRoot
        $approvedMap=[ordered]@{};foreach($key in $sourceMap.Keys){$approvedMap[$key]=[string]$sourceMap[$key]};$approvedMap['approved-runner-common.ps1']+="`nfunction Invoke-UnreachedApprovedControl { param([scriptblock]`$Action) }`n"
        $safeTreeMap=[ordered]@{};foreach($key in $sourceMap.Keys){$safeTreeMap[$key]=[string]$sourceMap[$key]};$safeTreeMap['safe-tree-walker.ps1']+="`nfunction Invoke-UnreachedSafeTreeControl { param(`$Action); & `$Action }`n"
        $fifthMirrorMap=[ordered]@{};foreach($key in $sourceMap.Keys){$fifthMirrorMap[$key]=[string]$sourceMap[$key]};$fifthMirrorMap['internal/live-transaction-host.ps1']+="`nfunction Invoke-SealedCanonicalNeutralMirror {}`n"
        $scriptBlock=InvokeClosure $scriptBlockMap
        $dynamic=InvokeClosure $dynamicMap
        $unknown=InvokeClosure $unknownMap
        $neutral=InvokeClosure $neutralMap
        $duplicate=InvokeClosure $duplicateMap
        $approved=InvokeClosure $approvedMap
        $safeTree=InvokeClosure $safeTreeMap
        $fifthMirrorIdentifiers=TestIdentifierSurface $fifthMirrorMap
        $result.FunctionCount=$baseline.FunctionIds.Count;$result.EdgeCount=$baseline.Edges.Count;$result.BoundaryCount=$baseline.BoundaryIds.Count;$result.ClosureDigest=$baseline.ClosureDigest
        $result.AllScriptsCovered=$allScriptsCovered
        $result.IdentifierSurfaceValid=$baselineIdentifiers.Valid
        $result.ScriptBlockReject=-not $scriptBlock.Valid -and @($scriptBlock.Violations|Where-Object{$_ -like 'scriptblock-parameter:*Invoke-NeutralClosureScriptBlock*'}).Count -eq 1
        $result.DynamicReject=-not $dynamic.Valid -and @($dynamic.Violations|Where-Object{$_ -like 'dynamic-command-invocation:*Invoke-NeutralClosureDynamic*'}).Count -eq 1
        $result.UnknownReject=-not $unknown.Valid -and @($unknown.Violations|Where-Object{$_ -like 'unknown-callee:*:Invoke-NeutralUnknownCallee'}).Count -eq 1
        $result.NeutralHelperReject=-not $neutral.Valid -and @($neutral.Violations|Where-Object{$_ -ceq 'closure-manifest-drift'}).Count -eq 1
        $result.DuplicateReject=-not $duplicate.Valid -and @($duplicate.Violations|Where-Object{$_ -like 'root-cardinality:Initialize-CanonicalRecoveryWorkspace'}).Count -eq 1
        $result.FifthMirrorReject=-not $fifthMirrorIdentifiers.Valid -and @($fifthMirrorIdentifiers.Violations|Where-Object{$_ -like 'forbidden-production-test-identifier:internal/live-transaction-host.ps1:SealedCanonical'}).Count -eq 1
        $result.ApprovedControl=$approved.Valid -and $approved.ClosureDigest -ceq $baseline.ClosureDigest
        $result.SafeTreeControl=$safeTree.Valid -and $safeTree.ClosureDigest -ceq $baseline.ClosureDigest
        $result.ExceptionManifestValid=$baseline.Valid -and $baseline.ExceptionIds.Count -eq $exceptions.Count -and $baseline.ClosureDigest -ceq $expectedDigest
        $result.Valid=$baseline.Valid -and $result.AllScriptsCovered -and $result.IdentifierSurfaceValid -and $result.ScriptBlockReject -and $result.DynamicReject -and
            $result.UnknownReject -and $result.NeutralHelperReject -and $result.DuplicateReject -and $result.FifthMirrorReject -and
            $result.ApprovedControl -and $result.SafeTreeControl -and $result.ExceptionManifestValid
    }catch{$result.Error=$_.Exception.Message}
    return [pscustomobject]$result
}
function Test-HardKillFourMirrorContract {
    param([Parameter(Mandatory)][string]$EngineSource,[Parameter(Mandatory)]$ProductionAst,[Parameter(Mandatory)][Collections.IDictionary]$FunctionMap,[Parameter(Mandatory)][Collections.IDictionary]$ManifestMap)
    $errors=[Collections.Generic.List[string]]::new();$tokens=$null;$parseErrors=$null;$engineAst=[Management.Automation.Language.Parser]::ParseInput($EngineSource,[ref]$tokens,[ref]$parseErrors)
    if(@($parseErrors).Count -ne 0){return [pscustomobject]@{Valid=$false;ErrorCodes=@('engine-parse');EngineAst=$engineAst}}
    $sealedDefinitions=@($engineAst.FindAll({param($node)$node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -match 'SealedCanonical'},$true))
    if($sealedDefinitions.Count -ne 4 -or @(Compare-Object @($FunctionMap.Keys) @($sealedDefinitions|ForEach-Object{$_.Name}) -CaseSensitive).Count -ne 0){$errors.Add('definition-set')}
    foreach($sealedName in $FunctionMap.Keys){
        $sealed=Get-HardKillFunctionAst -Ast $engineAst -Name $sealedName;$production=Get-HardKillFunctionAst -Ast $ProductionAst -Name ([string]$FunctionMap[$sealedName])
        if($null -eq $sealed -or $null -eq $production){$errors.Add("missing:$sealedName");continue}
        $manifestResult=Get-HardKillReachManifestResult -FunctionAst $sealed -Manifest @($ManifestMap[$sealedName])
        if(-not $manifestResult.Valid){$errors.Add(('manifest:{0}:{1}' -f $sealedName,$manifestResult.ErrorCode));continue}
        $projection=Get-HardKillSealedParityProjection $sealed
        if(-not $projection.Valid -or $projection.ReachCount -ne @($ManifestMap[$sealedName]).Count){$errors.Add(('projection:{0}:{1}' -f $sealedName,$projection.Error));continue}
        if($projection.Projection -cne (Get-HardKillStructuralProjection $production.Body)){$errors.Add("parity:$sealedName")}
    }
    return [pscustomobject]@{Valid=$errors.Count -eq 0;ErrorCodes=@($errors);EngineAst=$engineAst}
}
function Set-HardKillFunctionTextMutation {
    param([Parameter(Mandatory)][string]$EngineSource,[Parameter(Mandatory)][string]$FunctionName,[Parameter(Mandatory)][string]$Kind)
    $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($EngineSource,[ref]$tokens,[ref]$errors);if(@($errors).Count -ne 0){return $null}
    $functionAst=Get-HardKillFunctionAst -Ast $ast -Name $FunctionName;if($null -eq $functionAst){return $null}
    $functionText=[string]$functionAst.Extent.Text;$base=[int]$functionAst.Extent.StartOffset
    function ApplyChanges([object[]]$Changes){
        if(@($Changes).Count -eq 0 -or @($Changes|Where-Object{$null -eq $_}).Count -ne 0){return $null}
        $result=$functionText;$nextStart=$functionText.Length+1
        foreach($change in @($Changes|Sort-Object Start -Descending)){
            $start=[int]$change.Start;$end=[int]$change.End
            if($start -lt 0 -or $end -le $start -or $end -gt $functionText.Length -or $end -gt $nextStart){return $null}
            $result=$result.Remove($start,$end-$start).Insert($start,[string]$change.Replacement);$nextStart=$start
        }
        return $result
    }
    function ChangeNode($Node,[string]$Replacement){
        if($null -eq $Node){return $null}
        return [pscustomobject]@{Start=([int]$Node.Extent.StartOffset-$base);End=([int]$Node.Extent.EndOffset-$base);Replacement=$Replacement}
    }
    function GetUnique([scriptblock]$Predicate){
        $matches=@($functionAst.FindAll($Predicate,$true)|Where-Object{[object]::ReferenceEquals((Get-NearestHardKillFunction $_),$functionAst)})
        if($matches.Count -ne 1){return $null};return $matches[0]
    }
    function GetReach([string]$Checkpoint){
        $expected="([AiAgentDotfilesTests.SealedMutationCheckpoint]::$Checkpoint)"
        return GetUnique {param($node)
            if($node -isnot [Management.Automation.Language.CommandAst] -or $node.GetCommandName() -cne 'Invoke-SealedMutationReach'){return $false}
            $parsed=Get-HardKillCommandArguments $node
            return $parsed.Valid -and $parsed.Arguments.ContainsKey('Checkpoint') -and
                (Get-HardKillAstTextCompact $parsed.Arguments.Checkpoint) -ceq $expected
        }
    }
    switch($Kind){
        'renamed-phase'{
            $add=GetUnique {param($candidate)
                if($candidate -isnot [Management.Automation.Language.CommandAst] -or $candidate.GetCommandName() -cne 'Add-CanonicalJournalRecord'){return $false}
                $arguments=Get-HardKillCommandArguments $candidate
                return $arguments.Valid -and $arguments.Arguments.ContainsKey('Phase') -and $arguments.Arguments.ContainsKey('Data') -and
                    (Get-HardKillAstTextCompact $arguments.Arguments.Phase) -ceq 'WORKSPACE_CREATE_INTENT' -and
                    (Get-HardKillAstTextCompact $arguments.Arguments.Data) -ceq '([ordered]@{WorkspacePath=$path;WorkspaceRole=$role;WorkspaceState=$before})'
            }
            $phase=if($add){(Get-HardKillCommandArguments $add).Arguments.Phase}else{$null}
            $changed=ApplyChanges @((ChangeNode $phase 'WORKSPACE_CREATED'))
        }
        'swapped-target-swap-path'{
            $target=GetUnique {param($candidate)$candidate -is [Management.Automation.Language.ConvertExpressionAst] -and $candidate.Extent.Text -ceq '[string]$Target.TargetPath' -and $candidate.Parent -is [Management.Automation.Language.ArrayLiteralAst]}
            $swap=GetUnique {param($candidate)$candidate -is [Management.Automation.Language.ConvertExpressionAst] -and $candidate.Extent.Text -ceq '[string]$Target.SwapOldPath' -and $candidate.Parent -is [Management.Automation.Language.ArrayLiteralAst]}
            $changed=ApplyChanges @((ChangeNode $target '[string]$Target.SwapOldPath'),(ChangeNode $swap '[string]$Target.TargetPath'))
        }
        'applied-record-moved-early'{
            $assignment=GetUnique {param($candidate)$candidate -is [Management.Automation.Language.AssignmentStatementAst] -and $candidate.Left.Extent.Text -ceq '$installedData'}
            $add=GetUnique {param($candidate)
                if($candidate -isnot [Management.Automation.Language.CommandAst] -or $candidate.GetCommandName() -cne 'Add-CanonicalJournalRecord'){return $false}
                $arguments=Get-HardKillCommandArguments $candidate
                return $arguments.Valid -and $arguments.Arguments.ContainsKey('Phase') -and $arguments.Arguments.ContainsKey('Data') -and
                    (Get-HardKillAstTextCompact $arguments.Arguments.Phase) -ceq 'NEW_INSTALLED' -and
                    (Get-HardKillAstTextCompact $arguments.Arguments.Data) -ceq '$installedData'
            }
            $addStatement=if($add -and $add.Parent -is [Management.Automation.Language.PipelineAst]){$add.Parent}else{$null}
            $changed=ApplyChanges @((ChangeNode $addStatement ''),(ChangeNode $assignment ($addStatement.Extent.Text+"`r`n"+$assignment.Extent.Text)))
        }
        'deleted-lease-finally'{
            $close=GetUnique {param($candidate)$candidate -is [Management.Automation.Language.CommandAst] -and $candidate.GetCommandName() -ceq 'Close-CanonicalMutationParentLease'}
            $statement=if($close -and $close.Parent -is [Management.Automation.Language.PipelineAst]){$close.Parent}else{$null}
            $changed=ApplyChanges @((ChangeNode $statement '$null=$lease'))
        }
        'wrong-physical-edge'{
            $reach=GetReach 'AfterDirectoryOldMove';$statement=if($reach){$reach.Parent}else{$null}
            $assignment=GetUnique {param($candidate)$candidate -is [Management.Automation.Language.AssignmentStatementAst] -and $candidate.Left.Extent.Text -ceq '$oldMoved'}
            $changed=ApplyChanges @((ChangeNode $statement ''),(ChangeNode $assignment ($statement.Extent.Text+"`r`n"+$assignment.Extent.Text)))
        }
        'wrong-declared-variant'{
            $reach=GetReach 'BeforeDirectoryOldMove';$argument=if($reach){(Get-HardKillCommandArguments $reach).Arguments.DeclaredVariant}else{$null}
            $changed=ApplyChanges @((ChangeNode $argument '([AiAgentDotfilesTests.SealedMutationPrimitiveVariant]::DirectoryNewMovePresent)'))
        }
        'wrong-actual-discriminator'{
            $reach=GetReach 'AfterDirectoryOldMove';$argument=if($reach){(Get-HardKillCommandArguments $reach).Arguments.ActualBranchState}else{$null}
            $changed=ApplyChanges @((ChangeNode $argument '$Target.Candidate.State'))
        }
        'hidden-io-reach-argument'{
            $reach=GetReach 'BeforeDirectoryOldMove';$argument=if($reach){(Get-HardKillCommandArguments $reach).Arguments.ActualBranchState}else{$null}
            $changed=ApplyChanges @((ChangeNode $argument '(Get-CanonicalObservedPathState -Path $Target.TargetPath)'))
        }
        'adjacent-extra-command'{
            $reach=GetReach 'BeforeParentCreate';$statement=if($reach){$reach.Parent}else{$null}
            $changed=ApplyChanges @((ChangeNode $statement (('$null=Get-Date'+"`r`n")+$statement.Extent.Text)))
        }
        'wrong-nested-callee'{
            $callee=GetUnique {param($candidate)$candidate -is [Management.Automation.Language.CommandAst] -and $candidate.GetCommandName() -ceq 'Initialize-CanonicalTargetPreimage'}
            $nameElement=if($callee){$callee.CommandElements[0]}else{$null}
            $changed=ApplyChanges @((ChangeNode $nameElement 'Initialize-CanonicalTargetPreimageWrong'))
        }
        default{return $null}
    }
    if($null -eq $changed -or $changed -ceq $functionText){return $null}
    return $EngineSource.Substring(0,$functionAst.Extent.StartOffset)+$changed+$EngineSource.Substring($functionAst.Extent.EndOffset)
}
function Invoke-HardKillParityMutationCorpus {
    param([Parameter(Mandatory)][string]$EngineSource,[Parameter(Mandatory)]$ProductionAst,[Parameter(Mandatory)][Collections.IDictionary]$FunctionMap,[Parameter(Mandatory)][Collections.IDictionary]$ManifestMap)
    $specs=@(
        [pscustomobject]@{Name='renamed-phase';Function='Initialize-SealedCanonicalRecoveryWorkspace';ErrorPattern='manifest:Initialize-SealedCanonicalRecoveryWorkspace:reach-physical-edge'},
        [pscustomobject]@{Name='swapped-target-swap-path';Function='Invoke-SealedCanonicalDirectoryReplacement';ErrorPattern='parity:Invoke-SealedCanonicalDirectoryReplacement'},
        [pscustomobject]@{Name='applied-record-moved-early';Function='Invoke-SealedCanonicalDirectoryReplacement';ErrorPattern='manifest:Invoke-SealedCanonicalDirectoryReplacement:reach-physical-edge'},
        [pscustomobject]@{Name='deleted-lease-finally';Function='Invoke-SealedCanonicalParentDirectoryCreate';ErrorPattern='parity:Invoke-SealedCanonicalParentDirectoryCreate'},
        [pscustomobject]@{Name='wrong-physical-edge';Function='Invoke-SealedCanonicalDirectoryReplacement';ErrorPattern='manifest:Invoke-SealedCanonicalDirectoryReplacement:reach-physical-edge'},
        [pscustomobject]@{Name='wrong-declared-variant';Function='Invoke-SealedCanonicalDirectoryReplacement';ErrorPattern='manifest:Invoke-SealedCanonicalDirectoryReplacement:reach-DeclaredVariant'},
        [pscustomobject]@{Name='wrong-actual-discriminator';Function='Invoke-SealedCanonicalDirectoryReplacement';ErrorPattern='manifest:Invoke-SealedCanonicalDirectoryReplacement:reach-ActualBranchState'},
        [pscustomobject]@{Name='hidden-io-reach-argument';Function='Invoke-SealedCanonicalDirectoryReplacement';ErrorPattern='manifest:Invoke-SealedCanonicalDirectoryReplacement:reach-argument-impure'},
        [pscustomobject]@{Name='adjacent-extra-command';Function='Invoke-SealedCanonicalParentDirectoryCreate';ErrorPattern='manifest:Invoke-SealedCanonicalParentDirectoryCreate:reach-physical-edge'},
        [pscustomobject]@{Name='wrong-nested-callee';Function='Invoke-SealedCanonicalDirectoryReplacement';ErrorPattern='parity:Invoke-SealedCanonicalDirectoryReplacement'},
        [pscustomobject]@{Name='neutral-fifth-mirror';Function='';ErrorPattern='definition-set'}
    )
    $baseline=Test-HardKillFourMirrorContract -EngineSource $EngineSource -ProductionAst $ProductionAst -FunctionMap $FunctionMap -ManifestMap $ManifestMap
    if(-not $baseline.Valid){return [pscustomobject]@{BaselineValid=$false;Cases=@();ExpectedNames=@($specs.Name)}}
    $results=[Collections.Generic.List[object]]::new()
    foreach($spec in $specs){
        $mutant=if($spec.Name -ceq 'neutral-fifth-mirror'){
            $EngineSource+"`nfunction Invoke-SealedCanonicalNeutralMirror {}`n"
        }else{
            Set-HardKillFunctionTextMutation -EngineSource $EngineSource -FunctionName $spec.Function -Kind $spec.Name
        }
        $changed=$null -ne $mutant -and $mutant -cne $EngineSource
        $tokens=$null;$errors=$null;if($changed){$null=[Management.Automation.Language.Parser]::ParseInput($mutant,[ref]$tokens,[ref]$errors)}
        $parseValid=$changed -and @($errors).Count -eq 0
        $contract=if($parseValid){Test-HardKillFourMirrorContract -EngineSource $mutant -ProductionAst $ProductionAst -FunctionMap $FunctionMap -ManifestMap $ManifestMap}else{$null}
        $errorCodes=if($contract){@($contract.ErrorCodes)}else{@()};$expectedReason=$parseValid -and -not $contract.Valid -and @($errorCodes|Where-Object{$_ -ceq [string]$spec.ErrorPattern}).Count -eq 1
        $results.Add([pscustomobject]@{Name=$spec.Name;Changed=$changed;ParseValid=$parseValid;Rejected=$parseValid -and -not $contract.Valid;RejectedForExpectedReason=$expectedReason;ErrorCodes=$errorCodes})
    }
    return [pscustomobject]@{BaselineValid=$true;Cases=@($results);ExpectedNames=@($specs.Name)}
}
function Set-TestProgress{param([string]$Name)if($ProgressPath){[IO.File]::WriteAllText([IO.Path]::GetFullPath($ProgressPath),$Name,[Text.UTF8Encoding]::new($false))}}
function Start-HardKillRegisteredProcess{
    param(
        [Parameter(Mandatory)][string]$FilePath,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$ArgumentList,
        [string]$RedirectStandardOutputPath,
        [string]$RedirectStandardErrorPath
    )
    $jobProcess=$null
    try{
        $jobProcess=Start-HardKillJobProcess -FilePath $FilePath -ArgumentList $ArgumentList `
            -RedirectStandardOutputPath $RedirectStandardOutputPath -RedirectStandardErrorPath $RedirectStandardErrorPath
        $process=$jobProcess.Process
        $process|Add-Member -NotePropertyName HardKillStartTimeUtcTicks -NotePropertyValue ([long]$jobProcess.RootCreationFileTimeTicks) -Force
        $process|Add-Member -NotePropertyName HardKillJobProcess -NotePropertyValue $jobProcess -Force
        $script:spawnedProcesses.Add($process)
        return $process
    }catch{
        if($null -ne $jobProcess){Close-HardKillJobProcess -JobProcess $jobProcess}
        throw
    }
}
function Confirm-HardKillRegisteredProcessReaped {
    param([Parameter(Mandatory)]$Process,[string]$Label='registered hard-kill process',[int]$TimeoutMilliseconds=5000)
    $leaseProperty=$Process.PSObject.Properties['HardKillJobProcess']
    if($null -eq $leaseProperty -or $null -eq $leaseProperty.Value){throw "$Label has no registered Job lease"}
    $jobProcess=[AiAgentDotfilesTests.HardKillJobProcess]$leaseProperty.Value
    if(-not $jobProcess.Reaped){
        $jobReapReceipt=Confirm-HardKillJobProcessReaped -JobProcess $jobProcess -TimeoutMilliseconds $TimeoutMilliseconds
        if($jobReapReceipt -isnot [bool] -or -not $jobReapReceipt){throw "$Label job-reap-receipt-invalid"}
    }
    if(-not $jobProcess.Reaped){throw "$Label Job did not report Reaped after confirmation"}
    Close-HardKillJobProcess -JobProcess $jobProcess
    return $true
}
function Invoke-SealedRecoveryFailureAfterIntent {
    param([Parameter(Mandatory)]$Document,[Parameter(Mandatory)]$State,[Parameter(Mandatory)][string]$RepoRoot)
    $null=Assert-CanonicalRecoveryStateContext -State $State -RepoRoot $RepoRoot
    $action=[string]$Document.PlanPayload.PlannedAction;$classification=Get-CanonicalTransactionRecoveryClassification -State $State -RepoRoot $RepoRoot
    if([string]$classification.AllowedAction -cne $action){throw 'canonical-recovery-action-mismatch'}
    if([string]$Document.DocumentHash -in @($State.ConsumedDocumentHashes)){throw 'reviewed-plan-consumed'}
    $null=Add-CanonicalJournalRecord -TransactionNamespace $State.TransactionNamespace -Phase RECOVERY_ACTION_INTENT -Data ([ordered]@{
        PlanKind=[string]$Document.PlanPayload.PlanKind;DocumentHash=[string]$Document.DocumentHash;PriorHeadHash=[string]$State.DerivedJournalHeadHash;ExpectedOutcome=[string]$Document.PlanPayload.ExpectedOutcome;ExpectedTerminalProjectionHash=[string]$Document.PlanPayload.ExpectedTerminalProjectionHash
    })
    throw 'injected-recovery-failure'
}
function Write-Utf8{param([string]$Path,[string]$Value)$parent=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};[IO.File]::WriteAllText($Path,$Value,[Text.UTF8Encoding]::new($false))}
function Initialize-TestRepo{
    param([string]$Path)
    [IO.Directory]::CreateDirectory($Path)|Out-Null;Write-Utf8 (Join-Path $Path 'README.md') 'fixture'
    & git -C $Path init --quiet;& git -C $Path config user.email hard-kill@example.invalid;& git -C $Path config user.name hard-kill
    & git -C $Path add -- README.md;& git -C $Path commit --quiet -m baseline
    if($LASTEXITCODE -ne 0){throw 'Unable to initialize hard-kill fixture repository.'}
}
function New-TestTarget{
    param([string]$Root,[string]$Name,[ValidateSet('directory','file','parent-directory')][string]$Kind,[string]$TargetPath,[string]$StagedPath,$Current,$Candidate,[int]$Order=0)
    $role=if($Kind -eq 'file'){'manifest'}elseif($Kind -eq 'parent-directory'){'parent'}else{'canonical'};$platform=if($Kind -eq 'file'){'Union'}else{$null};$id=Get-CanonicalJournalTargetId -Order $Order -TargetKind $Kind -Role $role -Platform $platform -TargetPath $TargetPath
    $row=[ordered]@{
        TargetId=$id;Order=$Order;TargetKind=$Kind;Role=$role
        TargetPath=[IO.Path]::GetFullPath($TargetPath);PreimagePath=Join-Path $Root ("preimage/$id");SwapOldPath=Join-Path $Root ("swap-old/$id")
        StagedPath=if($StagedPath){[IO.Path]::GetFullPath($StagedPath)}else{Join-Path $Root ("staged/$id")};Current=$Current;Candidate=$Candidate;TargetContextHash=[string](Resolve-TargetContext -Path $TargetPath -Mode MetadataOnly).RequestedInitialRootContextHash
    }
    if($platform){$row.Platform=$platform}
    return $row
}
function New-TestJournal{
    param([string]$Namespace,[string]$RecoveryRoot,[object[]]$Targets)
    $id=[IO.Path]::GetFileName($Namespace)
    $header=[ordered]@{
        SchemaVersion=1;ArtifactKind='canonical-journal-header';TransactionId=$id;CanonicalOperationKind='normalize';OriginalDocumentHash=('1'*64)
        OriginalPlanHash=('2'*64);RepoId=('3'*64);GitCommonDirHash=('4'*64);WorktreeId=('5'*64);TransactionNamespace=[IO.Path]::GetFullPath($Namespace)
        RecoveryTransactionRoot=[IO.Path]::GetFullPath($RecoveryRoot);ExpectedPostconditionsHash=('6'*64);Targets=@($Targets)
    }
    $null=New-CanonicalJournalHeader -Document $header -TransactionNamespace $Namespace
}

function Get-HardKillJournalDocuments {
    param([Parameter(Mandatory)][string]$TransactionNamespace)
    if(-not(Test-Path -LiteralPath $TransactionNamespace -PathType Container)){return @()}
    $documents=[Collections.Generic.List[object]]::new()
    foreach($file in @(Get-ChildItem -LiteralPath $TransactionNamespace -Filter '*.json' -File -ErrorAction SilentlyContinue)){
        try{$documents.Add(([IO.File]::ReadAllText($file.FullName)|ConvertFrom-Json -AsHashtable))}catch{}
    }
    return @($documents)
}
function Test-HardKillJournalPhase {
    param([object[]]$Documents,[Parameter(Mandatory)][string]$Phase,[string]$TargetId,[string]$WorkspaceRole)
    foreach($document in @($Documents)){
        if(-not($document -is [Collections.IDictionary]) -or -not $document.Contains('Phase') -or [string]$document.Phase -cne $Phase){continue}
        if($TargetId -and (-not $document.Contains('Data') -or [string]$document.Data.TargetId -cne $TargetId)){continue}
        if($WorkspaceRole -and (-not $document.Contains('Data') -or [string]$document.Data.WorkspaceRole -cne $WorkspaceRole)){continue}
        return $true
    }
    return $false
}
function Test-HardKillPendingInventoryEmpty {
    param([Parameter(Mandatory)][string]$TransactionNamespace)
    $namespaceHandles=$null;$pendingHandle=$null
    try{
        $namespaceHandlesReceiver=[AiAgentDotfiles.SealedOwnershipTransferReceiver]::new()
        Open-SafeDirectoryContainmentChain -Path ([IO.Path]::GetFullPath($TransactionNamespace)) -OwnershipReceiver $namespaceHandlesReceiver
        $namespaceHandles = $namespaceHandlesReceiver.GetDeliveredExact()
        $pendingHandle=[AiAgentDotfiles.NoFollowFile]::HoldChildDirectory($namespaceHandles[$namespaceHandles.Count-1],'_pending')
        return @([AiAgentDotfiles.NoFollowFile]::GetChildNames($pendingHandle)).Count -eq 0
    }finally{
        if($pendingHandle){$pendingHandle.Dispose()}
        if($namespaceHandles){Close-SafeDirectoryContainmentChain -Handles $namespaceHandles}
    }
}
function Test-HardKillMutationCheckpointName {
    param([Parameter(Mandatory)][string]$Name)
    return $Name -in @(
        'before-workspace-mkdir:preimage','after-workspace-mkdir:preimage','before-workspace-mkdir:swap-old','after-workspace-mkdir:swap-old',
        'before-preimage-copy','during-preimage-copy','after-preimage-copy','before-parent-mkdir','after-parent-mkdir',
        'before-directory-move-old','after-directory-move-old','before-directory-move-new','after-directory-move-new',
        'before-file-replace','after-file-replace','before-directory-new-installed-record','after-directory-new-installed-record',
        'before-parent-remove','after-parent-remove','before-rollback-directory-new-to-staged','after-rollback-directory-new-to-staged',
        'before-rollback-directory-old-to-target','after-rollback-directory-old-to-target','before-rollback-file-replace','after-rollback-file-replace',
        'before-rollback-file-new-to-staged','after-rollback-file-new-to-staged'
    )
}
function Test-HardKillMutationParentLease {
    param([Parameter(Mandatory)][string]$LeafPath)
    $parent=Split-Path -Parent ([IO.Path]::GetFullPath($LeafPath))
    return [AiAgentDotfiles.HardKillLeaseProbe]::IsDeleteOpenBlocked($parent)
}
function Test-HardKillHeldFileDeleteSharing {
    param([Parameter(Mandatory)][string]$Path)
    return [AiAgentDotfiles.HardKillLeaseProbe]::IsDeleteOpenBlocked([IO.Path]::GetFullPath($Path))
}
function Test-HardKillDependentRollbackTuple {
    param([Parameter(Mandatory)]$Header,[object[]]$Documents)
    $targets=@($Header.Targets|Sort-Object{[long]$_.Order})
    if($targets.Count -lt 2){return $false}
    $dependent=$targets[-1]
    if($Documents){
        if(Test-HardKillJournalPhase -Documents $Documents -Phase NEW_INSTALLED -TargetId ([string]$dependent.TargetId)){return $false}
        $reconciliation=Get-CanonicalTargetReconciliation -Target $dependent -Records @($Documents|Where-Object{$_ -is [Collections.IDictionary] -and $_.Contains('Phase')})
        if([string]$reconciliation.State -cne 'PRE_PRIMITIVE' -or [bool]$reconciliation.PrimitiveOccurred){return $false}
    }
    $tuple=Get-CanonicalTargetTuple -Target $dependent
    return [string]$tuple.Target.State -ceq 'MISSING' -and
        [string]$tuple.Preimage.State -ceq 'MISSING' -and
        [string]$tuple.SwapOld.State -ceq 'MISSING' -and
        (Test-CanonicalObservedMatchesContractState -Actual $tuple.Staged -Contract $dependent.Candidate)
}
function Get-HardKillMutationCheckpointState {
    param([Parameter(Mandatory)][string]$Name,[Parameter(Mandatory)][string]$TransactionNamespace)
    $documents=@(Get-HardKillJournalDocuments -TransactionNamespace $TransactionNamespace)
    $header=@($documents|Where-Object{$_ -is [Collections.IDictionary] -and $_.Contains('ArtifactKind') -and [string]$_.ArtifactKind -ceq 'canonical-journal-header'})|Select-Object -First 1
    if($null -eq $header -or @($header.Targets).Count -eq 0){return $false}
    $target=@($header.Targets|Sort-Object{[long]$_.Order})[0]
    $targetId=[string]$target.TargetId;$targetPath=[string]$target.TargetPath;$preimagePath=[string]$target.PreimagePath;$swapPath=[string]$target.SwapOldPath;$stagedPath=[string]$target.StagedPath
    $recoveryRoot=[string]$header.RecoveryTransactionRoot
    $hasRecoveryIntent=Test-HardKillJournalPhase -Documents $documents -Phase RECOVERY_ACTION_INTENT
    $hasRecoveryApplied=Test-HardKillJournalPhase -Documents $documents -Phase RECOVERY_ACTION_APPLIED
    switch($Name){
        'before-workspace-mkdir:preimage'{return (Test-HardKillJournalPhase $documents WORKSPACE_CREATE_INTENT -WorkspaceRole preimage) -and -not(Test-Path -LiteralPath (Join-Path $recoveryRoot 'preimage')) -and (Test-HardKillMutationParentLease (Join-Path $recoveryRoot 'preimage'))}
        'after-workspace-mkdir:preimage'{return (Test-HardKillJournalPhase $documents WORKSPACE_CREATE_INTENT -WorkspaceRole preimage) -and (Test-Path -LiteralPath (Join-Path $recoveryRoot 'preimage') -PathType Container) -and -not(Test-HardKillJournalPhase $documents WORKSPACE_CREATED -WorkspaceRole preimage) -and (Test-HardKillMutationParentLease (Join-Path $recoveryRoot 'preimage'))}
        'before-workspace-mkdir:swap-old'{return (Test-HardKillJournalPhase $documents WORKSPACE_CREATE_INTENT -WorkspaceRole 'swap-old') -and -not(Test-Path -LiteralPath (Join-Path $recoveryRoot 'swap-old')) -and (Test-HardKillMutationParentLease (Join-Path $recoveryRoot 'swap-old'))}
        'after-workspace-mkdir:swap-old'{return (Test-HardKillJournalPhase $documents WORKSPACE_CREATE_INTENT -WorkspaceRole 'swap-old') -and (Test-Path -LiteralPath (Join-Path $recoveryRoot 'swap-old') -PathType Container) -and -not(Test-HardKillJournalPhase $documents WORKSPACE_CREATED -WorkspaceRole 'swap-old') -and (Test-HardKillMutationParentLease (Join-Path $recoveryRoot 'swap-old'))}
        'before-preimage-copy'{return (Test-HardKillJournalPhase $documents PREIMAGE_COPY_INTENT -TargetId $targetId) -and -not(Test-Path -LiteralPath $preimagePath) -and (Test-HardKillMutationParentLease $preimagePath)}
        'during-preimage-copy'{
            if(-not(Test-HardKillJournalPhase $documents PREIMAGE_COPY_INTENT -TargetId $targetId) -or -not(Test-Path -LiteralPath $preimagePath -PathType Leaf)){return $false}
            try{$sourceLength=[IO.FileInfo]::new($targetPath).Length;$partialLength=[IO.FileInfo]::new($preimagePath).Length;return $partialLength -gt 0 -and $partialLength -lt $sourceLength -and (Test-HardKillMutationParentLease $preimagePath)}catch{return $false}
        }
        'after-preimage-copy'{
            if(-not(Test-HardKillJournalPhase $documents PREIMAGE_COPY_INTENT -TargetId $targetId) -or (Test-HardKillJournalPhase $documents FILE_PREPARED -TargetId $targetId) -or -not(Test-Path -LiteralPath $preimagePath -PathType Leaf)){return $false}
            try{$copy=[AiAgentDotfiles.NoFollowFile]::HashRegularFile($preimagePath);return [string]$copy.Sha256 -ceq [string]$target.Current.Hash -and (Test-HardKillMutationParentLease $preimagePath) -and (Test-HardKillPendingInventoryEmpty -TransactionNamespace $TransactionNamespace)}catch{return $false}
        }
        'before-parent-mkdir'{return (Test-HardKillJournalPhase $documents DIR_CREATE_INTENT -TargetId $targetId) -and -not(Test-Path -LiteralPath $targetPath) -and (Test-HardKillMutationParentLease $targetPath)}
        'after-parent-mkdir'{return (Test-HardKillJournalPhase $documents DIR_CREATE_INTENT -TargetId $targetId) -and (Test-Path -LiteralPath $targetPath -PathType Container) -and -not(Test-HardKillJournalPhase $documents DIR_CREATED -TargetId $targetId) -and (Test-HardKillMutationParentLease $targetPath)}
        'before-directory-move-old'{return (Test-HardKillJournalPhase $documents MOVE_OLD_INTENT -TargetId $targetId) -and (Test-Path -LiteralPath $targetPath -PathType Container) -and -not(Test-Path -LiteralPath $swapPath) -and (Test-HardKillMutationParentLease $targetPath)}
        'after-directory-move-old'{return (Test-HardKillJournalPhase $documents MOVE_OLD_INTENT -TargetId $targetId) -and -not(Test-Path -LiteralPath $targetPath) -and (Test-Path -LiteralPath $swapPath -PathType Container) -and -not(Test-HardKillJournalPhase $documents OLD_MOVED -TargetId $targetId) -and (Test-HardKillMutationParentLease $targetPath)}
        'before-directory-move-new'{return (Test-HardKillJournalPhase $documents MOVE_NEW_INTENT -TargetId $targetId) -and -not(Test-Path -LiteralPath $targetPath) -and (([string]$target.Candidate.State -ceq 'MISSING') -or (Test-Path -LiteralPath $stagedPath -PathType Container)) -and (Test-HardKillMutationParentLease $targetPath)}
        'after-directory-move-new'{return (Test-HardKillJournalPhase $documents MOVE_NEW_INTENT -TargetId $targetId) -and (Test-Path -LiteralPath $targetPath -PathType Container) -and -not(Test-Path -LiteralPath $stagedPath) -and -not(Test-HardKillJournalPhase $documents NEW_INSTALLED -TargetId $targetId) -and (Test-HardKillMutationParentLease $targetPath)}
        'before-directory-new-installed-record'{return (Test-HardKillJournalPhase $documents MOVE_NEW_INTENT -TargetId $targetId) -and -not(Test-Path -LiteralPath $targetPath) -and -not(Test-Path -LiteralPath $stagedPath) -and -not(Test-HardKillJournalPhase $documents NEW_INSTALLED -TargetId $targetId) -and (Test-HardKillMutationParentLease $targetPath)}
        'after-directory-new-installed-record'{return (Test-HardKillJournalPhase $documents NEW_INSTALLED -TargetId $targetId) -and (Test-HardKillMutationParentLease $targetPath)}
        'before-file-replace'{return (Test-HardKillJournalPhase $documents FILE_REPLACE_INTENT -TargetId $targetId) -and (Test-Path -LiteralPath $stagedPath -PathType Leaf) -and -not(Test-Path -LiteralPath $swapPath) -and (Test-HardKillMutationParentLease $targetPath)}
        'after-file-replace'{return (Test-HardKillJournalPhase $documents FILE_REPLACE_INTENT -TargetId $targetId) -and (Test-Path -LiteralPath $targetPath -PathType Leaf) -and -not(Test-Path -LiteralPath $stagedPath) -and -not(Test-HardKillJournalPhase $documents FILE_REPLACED -TargetId $targetId) -and (Test-HardKillMutationParentLease $targetPath)}
        'after-parent-remove'{return $hasRecoveryIntent -and (Test-HardKillDependentRollbackTuple -Header $header -Documents $documents) -and -not(Test-Path -LiteralPath $targetPath) -and -not $hasRecoveryApplied}
        'before-rollback-directory-new-to-staged'{return $hasRecoveryIntent -and (Test-Path -LiteralPath $targetPath -PathType Container) -and -not(Test-Path -LiteralPath $stagedPath)}
        'after-rollback-directory-new-to-staged'{return $hasRecoveryIntent -and -not(Test-Path -LiteralPath $targetPath) -and (Test-Path -LiteralPath $stagedPath -PathType Container) -and -not $hasRecoveryApplied}
        'before-rollback-directory-old-to-target'{return $hasRecoveryIntent -and -not(Test-Path -LiteralPath $targetPath) -and (Test-Path -LiteralPath $swapPath -PathType Container)}
        'after-rollback-directory-old-to-target'{return $hasRecoveryIntent -and (Test-Path -LiteralPath $targetPath -PathType Container) -and -not(Test-Path -LiteralPath $swapPath) -and (Test-Path -LiteralPath $stagedPath -PathType Container) -and -not $hasRecoveryApplied}
        'before-rollback-file-replace'{return $hasRecoveryIntent -and (Test-Path -LiteralPath $targetPath -PathType Leaf) -and (Test-Path -LiteralPath $swapPath -PathType Leaf) -and -not(Test-Path -LiteralPath $stagedPath)}
        'after-rollback-file-replace'{return $hasRecoveryIntent -and (Test-Path -LiteralPath $targetPath -PathType Leaf) -and -not(Test-Path -LiteralPath $swapPath) -and (Test-Path -LiteralPath $stagedPath -PathType Leaf) -and -not $hasRecoveryApplied}
        'before-rollback-file-new-to-staged'{return $hasRecoveryIntent -and (Test-Path -LiteralPath $targetPath -PathType Leaf) -and -not(Test-Path -LiteralPath $stagedPath)}
        'after-rollback-file-new-to-staged'{return $hasRecoveryIntent -and -not(Test-Path -LiteralPath $targetPath) -and (Test-Path -LiteralPath $stagedPath -PathType Leaf) -and -not $hasRecoveryApplied}
    }
    return $false
}
function Wait-HardKillExternalMutationJournalState {
    param([Parameter(Mandatory)]$Process,[Parameter(Mandatory)][string]$Name,[Parameter(Mandatory)][string]$TransactionNamespace,[int]$TimeoutSeconds=300)
    $deadline=[DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
    while([DateTime]::UtcNow -lt $deadline){
        $Process.Refresh();if($Process.HasExited){return $false}
        if(Get-HardKillMutationCheckpointState -Name $Name -TransactionNamespace $TransactionNamespace){
            $null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label 'hard-kill mutation checkpoint'
            return $true
        }
        Start-Sleep -Milliseconds 50
    }
    $null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label 'hard-kill mutation checkpoint cleanup'
    return $false
}
function Read-HardKillAfterPreimageStartStage {
    param(
        [Parameter(Mandatory)][string]$StagePath,
        [Parameter(Mandatory)][string]$TransactionId,
        [Parameter(Mandatory)][string]$TransactionNamespace
    )
    if(-not(Test-Path -LiteralPath $StagePath -PathType Leaf)){return $null}
    $stage=[IO.File]::ReadAllText([IO.Path]::GetFullPath($StagePath),[Text.UTF8Encoding]::new($false,$true))|ConvertFrom-Json -AsHashtable
    $keys=@($stage.Keys|Sort-Object);$expectedKeys=@('ArtifactKind','SchemaVersion','Stage','TargetHash','TargetId','TargetIdentity','TargetPath','TransactionId','TransactionNamespace')|Sort-Object
    if(([string]::Join("`n",$keys)) -cne ([string]::Join("`n",$expectedKeys)) -or [long]$stage.SchemaVersion -ne 1 -or
        [string]$stage.ArtifactKind -cne 'sealed-after-preimage-stage' -or [string]$stage.Stage -cne 'preimage-start' -or
        [string]$stage.TransactionId -cne $TransactionId -or
        -not [IO.Path]::GetFullPath([string]$stage.TransactionNamespace).Equals([IO.Path]::GetFullPath($TransactionNamespace),[StringComparison]::OrdinalIgnoreCase) -or
        [string]$stage.TargetId -cnotmatch '^[0-9a-f]{64}$' -or [string]$stage.TargetIdentity -cnotmatch '^[0-9a-f]+:[0-9a-f]+$' -or
        [string]$stage.TargetHash -cnotmatch '^[0-9a-f]{64}$'){
        throw 'sealed after-preimage start stage differs from its exact contract'
    }
    return $stage
}
function Open-HardKillAfterPreimageIntentEvidence {
    param([Parameter(Mandatory)][string]$TransactionNamespace,[Parameter(Mandatory)]$Stage)
    $snapshot=$null
    try{
        $snapshot=Open-CanonicalJournalSnapshot -TransactionNamespace $TransactionNamespace -AllowUnfinished
        $state=$snapshot.State
        if(@($state.PendingEntries).Count -ne 0){throw 'after-preimage intent snapshot contains pending artifacts'}
        $target=@($state.Header.Targets|Where-Object{[string]$_.TargetId -ceq [string]$Stage.TargetId})|Select-Object -First 1
        if($null -eq $target -or [string]$target.TargetKind -cne 'file' -or [string]$target.Current.State -cne 'PRESENT' -or
            [string]$target.Current.Hash -cne [string]$Stage.TargetHash -or
            -not [IO.Path]::GetFullPath([string]$target.TargetPath).Equals([IO.Path]::GetFullPath([string]$Stage.TargetPath),[StringComparison]::OrdinalIgnoreCase)){
            throw 'after-preimage intent target differs from the typed start stage'
        }
        $intents=@($state.Records|Where-Object{[string]$_.Phase -ceq 'PREIMAGE_COPY_INTENT' -and [string]$_.Data.TargetId -ceq [string]$target.TargetId}|Sort-Object{[long]$_.Sequence})
        $prepared=@($state.Records|Where-Object{[string]$_.Phase -ceq 'FILE_PREPARED' -and [string]$_.Data.TargetId -ceq [string]$target.TargetId})
        if($intents.Count -ne 1 -or $prepared.Count -ne 0){throw 'after-preimage intent snapshot is not the exact pre-copy boundary'}
        $intentName=('{0:d6}.json' -f [long]$intents[0].Sequence)
        if(-not $snapshot.ArtifactHandles.Contains($intentName)){throw 'after-preimage intent handle is missing from the held snapshot'}
        return [pscustomobject][ordered]@{
            Target=$target;IntentPath=[IO.Path]::GetFullPath((Join-Path $state.TransactionNamespace $intentName))
            IntentIdentity=[string]$snapshot.ArtifactHandles[$intentName].ReadResult.Identity
        }
    }finally{if($snapshot){Close-CanonicalJournalSnapshot -Snapshot $snapshot}}
}
function Test-HardKillAfterPreimagePostReapState {
    param(
        [Parameter(Mandatory)][string]$TransactionNamespace,
        [Parameter(Mandatory)][string]$RepoRoot,
        [Parameter(Mandatory)]$ArmEvidence
    )
    $state=Read-CanonicalJournalDirectory -TransactionNamespace $TransactionNamespace -AllowUnfinished
    if(@($state.PendingEntries).Count -ne 0){return $false}
    $target=@($state.Header.Targets|Where-Object{[string]$_.TargetId -ceq [string]$ArmEvidence.Target.TargetId})|Select-Object -First 1
    if($null -eq $target){return $false}
    $intentCount=@($state.Records|Where-Object{[string]$_.Phase -ceq 'PREIMAGE_COPY_INTENT' -and [string]$_.Data.TargetId -ceq [string]$target.TargetId}).Count
    $preparedCount=@($state.Records|Where-Object{[string]$_.Phase -ceq 'FILE_PREPARED' -and [string]$_.Data.TargetId -ceq [string]$target.TargetId}).Count
    if($intentCount -ne 1 -or $preparedCount -ne 0){return $false}
    $tuple=Get-CanonicalTargetTuple -Target $target
    $reconciliation=Get-CanonicalTargetReconciliation -Target $target -Records @($state.Records)
    $classification=Get-CanonicalTransactionRecoveryClassification -State $state -RepoRoot $RepoRoot
    $leasesReleased=$true
    foreach($leaf in @([string]$target.TargetPath,[string]$target.PreimagePath,[string]$target.SwapOldPath,[string]$target.StagedPath)){
        if(Test-HardKillMutationParentLease -LeafPath $leaf){$leasesReleased=$false;break}
    }
    return [string]$tuple.Preimage.State -ceq 'PRESENT' -and [string]$tuple.Preimage.Type -ceq 'File' -and
        [string]$tuple.Preimage.Hash -ceq [string]$target.Current.Hash -and [string]$tuple.Preimage.Identity -ceq [string]$ArmEvidence.PreimageIdentity -and
        [string]$reconciliation.State -ceq 'PRE_PRIMITIVE' -and -not [bool]$reconciliation.PrimitiveOccurred -and
        [string]$classification.AllowedAction -ceq 'abandon' -and [string]$classification.ExpectedOutcome -ceq 'abandoned' -and $leasesReleased
}
function Wait-HardKillAfterPreimageCheckpoint {
    param(
        [Parameter(Mandatory)]$Process,
        [Parameter(Mandatory)][string]$TransactionNamespace,
        [Parameter(Mandatory)][string]$RepoRoot,
        [Parameter(Mandatory)][string]$TransactionId,
        [Parameter(Mandatory)][string]$StagePath,
        [Parameter(Mandatory)]$StageEvent,
        [int]$TimeoutSeconds=300
    )
    $deadline=[DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
    $stage=$null;$sourceFirst=$null;$headerGate=$null;$sourceCopy=$null;$intentGate=$null;$armEvidence=$null;$released=$false
    try{
        while([DateTime]::UtcNow -lt $deadline -and $null -eq $stage){$Process.Refresh();if($Process.HasExited){return $false};$stage=Read-HardKillAfterPreimageStartStage -StagePath $StagePath -TransactionId $TransactionId -TransactionNamespace $TransactionNamespace;if($null -eq $stage){Start-Sleep -Milliseconds 20}}
        if($null -eq $stage){return $false}
        $sourceFirst=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetPath)
        if([string]$sourceFirst.Identity -cne [string]$stage.TargetIdentity){throw 'after-preimage first source R|W oplock identity differs from the typed stage'}
        $null=$StageEvent.Set();$released=$true
        if(-not $sourceFirst.WaitForBreak(300000) -or -not $sourceFirst.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage source observation did not reach its exact first R|W break'}
        $headerPath=Join-Path $TransactionNamespace 'header.json';$headerIdentity=[string][AiAgentDotfiles.NoFollowFile]::Inspect($headerPath).Identity
        $headerGate=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile($headerPath)
        if([string]$headerGate.Identity -cne $headerIdentity){throw 'after-preimage header gate identity changed before its R|W oplock was armed'}
        $sourceFirst.Dispose();$sourceFirst=$null
        if(-not $headerGate.WaitForBreak(300000) -or -not $headerGate.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage PREIMAGE_COPY_INTENT append did not reach its held header read'}
        $sourceCopy=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$stage.TargetPath)
        if([string]$sourceCopy.Identity -cne [string]$stage.TargetIdentity){throw 'after-preimage copy source identity changed before its second R|W oplock was armed'}
        $headerGate.Dispose();$headerGate=$null
        if(-not $sourceCopy.WaitForBreak(300000) -or -not $sourceCopy.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage real preimage copy did not reach its exact source R|W break'}
        $armEvidence=Open-HardKillAfterPreimageIntentEvidence -TransactionNamespace $TransactionNamespace -Stage $stage
        $intentGate=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile([string]$armEvidence.IntentPath)
        if([string]$intentGate.Identity -cne [string]$armEvidence.IntentIdentity){throw 'after-preimage intent identity changed before its R|W oplock was armed'}
        $sourceCopy.Dispose();$sourceCopy=$null
        if(-not $intentGate.WaitForBreak(300000) -or -not $intentGate.IsAcknowledgedSelfMutationBreak()){throw 'after-preimage FILE_PREPARED append did not reach its exact held intent read'}
        $null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label 'hard-kill after-preimage requester'
        $intentGate.Dispose();$intentGate=$null
        $preimageInfo=[AiAgentDotfiles.NoFollowFile]::Inspect([IO.Path]::GetFullPath([string]$armEvidence.Target.PreimagePath));$armEvidence|Add-Member -NotePropertyName PreimageIdentity -NotePropertyValue ([string]$preimageInfo.Identity)
        if(-not(Test-HardKillAfterPreimagePostReapState -TransactionNamespace $TransactionNamespace -RepoRoot $RepoRoot -ArmEvidence $armEvidence)){throw 'hard-kill after-preimage post-reap tuple differs from its exact abandon boundary'}
        return $true
    }finally{
        $cleanupFailure=$null
        try{$null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label 'hard-kill after-preimage cleanup'}catch{$cleanupFailure=$_}
        if($null -eq $cleanupFailure){
            foreach($held in @($intentGate,$sourceCopy,$headerGate,$sourceFirst)){if($held){try{$held.Dispose()}catch{if($null -eq $cleanupFailure){$cleanupFailure=$_}}}}
            if(-not $released){try{$null=$StageEvent.Set()}catch{if($null -eq $cleanupFailure){$cleanupFailure=$_}}}
        }
        if($cleanupFailure){throw $cleanupFailure}
    }
}
function Read-HardKillExternalCheckpointProof {
    param([Parameter(Mandatory)][string]$MarkerPath)
    if(-not(Test-Path -LiteralPath $MarkerPath -PathType Leaf)){return $null}
    try{
        $proof=[IO.File]::ReadAllText([IO.Path]::GetFullPath($MarkerPath))|ConvertFrom-Json -AsHashtable
        $keys=@('Checkpoint','Gated','Reaped','Validated')
        if($proof -isnot [Collections.IDictionary] -or @($proof.Keys).Count -ne $keys.Count -or
            @($keys|Where-Object{-not $proof.Contains($_)}).Count -ne 0 -or
            [string]::IsNullOrWhiteSpace([string]$proof.Checkpoint) -or -not [bool]$proof.Gated -or -not [bool]$proof.Reaped -or -not [bool]$proof.Validated){return $null}
        return $proof
    }catch{return $null}
}
function Write-HardKillAtomicJson {
    param([Parameter(Mandatory)][string]$Path,[Parameter(Mandatory)]$Document)
    $finalPath=[IO.Path]::GetFullPath($Path)
    $tempPath=Join-Path (Split-Path -Parent $finalPath) ('.'+[IO.Path]::GetFileName($finalPath)+'.'+[Guid]::NewGuid().ToString('N')+'.tmp')
    $bytes=[Text.UTF8Encoding]::new($false,$true).GetBytes(($Document|ConvertTo-Json -Compress -Depth 10))
    $published=$false
    try{
        $stream=[IO.File]::Open($tempPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
        try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}
        [IO.File]::Move($tempPath,$finalPath,$false)
        $published=$true
    }finally{if(-not $published -and (Test-Path -LiteralPath $tempPath -PathType Leaf)){[IO.File]::Delete($tempPath)}}
}
function Write-HardKillExternalCheckpointProof {
    param([Parameter(Mandatory)][string]$Path,[Parameter(Mandatory)][string]$Checkpoint)
    Write-HardKillAtomicJson -Path $Path -Document ([ordered]@{Checkpoint=$Checkpoint;Gated=$true;Reaped=$true;Validated=$true})
}
function Read-HardKillRecoveryVisitedStages {
    param([Parameter(Mandatory)][string]$StageRoot)
    $rootPath=[IO.Path]::GetFullPath($StageRoot)
    $files=@([IO.Directory]::EnumerateFiles($rootPath)|Sort-Object)
    $publicationTempPattern='^\.(?:entering|visited)-[0-9]{6}\.json\.[0-9a-f]{32}\.tmp$'
    $publishedStagePattern='^(?:entering|visited)-[0-9]{6}\.json$'
    $regexOptions=[Text.RegularExpressions.RegexOptions]::CultureInvariant
    $publicationInProgress=$false
    for($index=0;$index -lt $files.Count;$index++){
        $leaf=[IO.Path]::GetFileName($files[$index])
        if([Text.RegularExpressions.Regex]::IsMatch($leaf,$publicationTempPattern,$regexOptions)){
            $publicationInProgress=$true
            continue
        }
        if(-not[Text.RegularExpressions.Regex]::IsMatch($leaf,$publishedStagePattern,$regexOptions)){
            throw ('sealed recovery stage inventory contains an unexpected entry: '+$leaf)
        }
    }
    if($publicationInProgress){throw 'sealed-recovery-stage-publication-in-progress'}
    $stages=[Collections.Generic.List[object]]::new()
    for($index=0;$index -lt $files.Count;$index++){
        $file=$files[$index];$leaf=[IO.Path]::GetFileName($file)
        $stage=[IO.File]::ReadAllText($file)|ConvertFrom-Json -AsHashtable
        $expectedLeaf=('{0}-{1:D6}.json' -f [string]$stage.Stage,($index+1))
        if($leaf -cne $expectedLeaf){throw ('sealed recovery stage inventory contains an unexpected entry: '+$leaf)}
        $keys=@($stage.Keys|Sort-Object);$expectedKeys=@('ArtifactKind','Order','SchemaVersion','Sequence','Stage','TargetId','TargetKind')|Sort-Object
        if(([string]::Join("`n",$keys)) -cne ([string]::Join("`n",$expectedKeys)) -or
            [long]$stage.SchemaVersion -ne 1 -or [string]$stage.ArtifactKind -cne 'sealed-recovery-target-stage' -or
            [string]$stage.Stage -cnotmatch '^(?:entering|visited)$' -or
            [long]$stage.Sequence -ne ($index+1) -or [string]$stage.TargetId -cnotmatch '^[0-9a-f]{64}$' -or
            [long]$stage.Order -lt 0 -or [string]$stage.TargetKind -cnotmatch '^(?:file|directory|parent-directory)$'){
            throw ('sealed recovery stage document is invalid: '+$leaf)
        }
        $stages.Add($stage)
    }
    return @($stages)
}
function Wait-HardKillRecoveryVisitedStages {
    param([Parameter(Mandatory)]$Process,[Parameter(Mandatory)][string]$StageRoot,[Parameter(Mandatory)][int]$Count,[int]$TimeoutSeconds=300)
    $deadline=[DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
    $lastReadError=$null
    while([DateTime]::UtcNow -lt $deadline){
        $Process.Refresh();if($Process.HasExited){return @()}
        try{$stages=@(Read-HardKillRecoveryVisitedStages -StageRoot $StageRoot);$lastReadError=$null;if($stages.Count -eq $Count){return $stages}}catch{$lastReadError=$_}
        Start-Sleep -Milliseconds 50
    }
    if($lastReadError){throw $lastReadError}
    return @()
}
function Test-HardKillRepoLockBusy {
    param([Parameter(Mandatory)][string]$LockPath)
    $probe=$null
    try{$probe=Enter-CanonicalRepoLock -LockPath $LockPath;return $false}
    catch{return $_.Exception.Message -match 'operation-lock-busy'}
    finally{if($probe){Exit-CanonicalRepoLock -LockHandle $probe}}
}
function Test-HardKillAllMutationParentLeases {
    param([Parameter(Mandatory)]$Target)
    foreach($leaf in @([string]$Target.TargetPath,[string]$Target.PreimagePath,[string]$Target.SwapOldPath,[string]$Target.StagedPath)){
        if(-not(Test-HardKillMutationParentLease -LeafPath $leaf)){return $false}
    }
    return $true
}
function Test-HardKillExactRollbackTuple {
    param(
        [Parameter(Mandatory)]$Target,
        [Parameter(Mandatory)]$InitialReconciliation,
        [Parameter(Mandatory)][ValidateSet('entering','directory-middle','visited')][string]$Boundary
    )
    $actual=Get-CanonicalTargetTuple -Target $Target
    $initial=$InitialReconciliation.Tuple
    if($Boundary -ceq 'entering'){
        return Test-CanonicalTargetTupleEqual -Actual $actual -Expected $initial
    }
    $missing=[ordered]@{State='MISSING'}
    if($Boundary -ceq 'directory-middle'){
        $expected=[ordered]@{Target=$missing;Preimage=$initial.Preimage;SwapOld=$initial.SwapOld;Staged=$initial.Target}
        return Test-CanonicalTargetTupleEqual -Actual $actual -Expected $expected
    }
    $expectedTarget=if([string]$Target.Current.State -ceq 'PRESENT'){$initial.SwapOld}else{$missing}
    $expectedStaged=if([string]$InitialReconciliation.State -ceq 'NEW_INSTALLED'){$initial.Target}else{$initial.Staged}
    return (Test-CanonicalObservedStateEqual -Actual $actual.Target -Expected $expectedTarget) -and
        (Test-CanonicalObservedStateEqual -Actual $actual.Preimage -Expected $initial.Preimage) -and
        (Test-CanonicalObservedStateEqual -Actual $actual.SwapOld -Expected $missing) -and
        (Test-CanonicalObservedStateEqual -Actual $actual.Staged -Expected $expectedStaged -IgnoreIdentity:([string]$Target.TargetKind -ceq 'file'))
}
function Test-HardKillExactSetupJson {
    param([Parameter(Mandatory)][string]$Path,[Parameter(Mandatory)][string]$SchemaName,[Parameter(Mandatory)]$ExpectedDocument)
    if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){return $false}
    try{
        $document=Read-CanonicalJsonContractFile -Path $Path -SchemaPath (Join-Path $script:CanonicalToolchainRoot ("schemas/{0}" -f $SchemaName))
        return (Get-SemanticJsonHash -InputObject $document) -ceq (Get-SemanticJsonHash -InputObject $ExpectedDocument)
    }catch{return $false}
}
function Get-HardKillExpectedSetupState {
    param([Parameter(Mandatory)]$Header,[Parameter(Mandatory)][string]$RepoRoot)
    $projection=$Header.SetupRecovery.ExpectedStateProjection
    $bootstrap=[ordered]@{
        OwnerSid=[string]$projection.OwnerSid;SecurityResolverVersion=[string]$projection.SecurityResolverVersion;SecurityTemplateHash=[string]$projection.SecurityTemplateHash
        CanonicalRecoveryRootIntent=$projection.CanonicalRecoveryRootIntent;CanonicalRecoveryRootIntentHash=[string]$projection.CanonicalRecoveryRootIntentHash
        ControlBaseIntent=$projection.ControlBaseIntent;ControlBaseIntentHash=[string]$projection.ControlBaseIntentHash
        BackupRootIntent=$projection.BackupRootIntent;BackupRootIntentHash=[string]$projection.BackupRootIntentHash
    }
    $planPayload=[ordered]@{
        OperationKind='setup';ExpectedSetupStateProjection=$projection;ExpectedSetupStateProjectionHash=[string]$Header.SetupRecovery.ExpectedStateProjectionHash
        PrivateRootBootstrapIntent=$bootstrap;SetupIntentHash=[string]$projection.SetupIntentHash;ExpectedRootClaim=$Header.SetupRecovery.ExpectedClaim;ExpectedRootClaimHash=[string]$Header.SetupRecovery.ExpectedClaimHash
    }
    return New-CanonicalFinalSetupState -PlanPayload $planPayload -RepoRoot $RepoRoot
}
function Test-HardKillSetupCheckpointState {
    param([Parameter(Mandatory)][string]$Name,[Parameter(Mandatory)][string]$TransactionNamespace,[Parameter(Mandatory)][string]$RepoRoot,[switch]$RequireHeldPreparedArtifact)
    $documents=@(Get-HardKillJournalDocuments -TransactionNamespace $TransactionNamespace)
    $headers=@($documents|Where-Object{$_ -is [Collections.IDictionary] -and $_.Contains('ArtifactKind') -and [string]$_.ArtifactKind -ceq 'canonical-journal-header'})
    if($headers.Count -ne 1){return $false}
    $header=$headers[0];$records=@($documents|Where-Object{$_ -is [Collections.IDictionary] -and $_.Contains('Phase')}|Sort-Object{[long]$_.Sequence})
    $phases=@($records|ForEach-Object{[string]$_.Phase})
    $pendingRoot=Join-Path $TransactionNamespace '_pending'
    $pending=@(if(Test-Path -LiteralPath $pendingRoot -PathType Container){[IO.Directory]::EnumerateFiles([IO.Path]::GetFullPath($pendingRoot))})
    $claimPath=[string]$header.SetupRecovery.ClaimPath;$statePath=[string]$header.SetupRecovery.StatePath
    $claimExact=Test-HardKillExactSetupJson -Path $claimPath -SchemaName 'canonical-root-claim.schema.json' -ExpectedDocument $header.SetupRecovery.ExpectedClaim
    $expectedState=Get-HardKillExpectedSetupState -Header $header -RepoRoot $RepoRoot
    $stateExact=Test-HardKillExactSetupJson -Path $statePath -SchemaName 'canonical-setup-state.schema.json' -ExpectedDocument $expectedState
    switch($Name){
        'before-setup-claim-publish'{return $phases.Count -eq 0 -and $pending.Count -eq 0 -and -not(Test-Path -LiteralPath $claimPath) -and -not(Test-Path -LiteralPath $statePath)}
        'after-setup-claim-temp-flush'{
            $temp=@($pending|Where-Object{[IO.Path]::GetFileName($_) -cmatch '^setup-claim-[0-9a-f]{32}\.tmp$'})
            return $phases.Count -eq 1 -and $phases[0] -ceq 'SETUP_CLAIM_INTENT' -and [string]$records[0].Data.ClaimHash -ceq [string]$header.SetupRecovery.ExpectedClaimHash -and
                $pending.Count -eq 1 -and $temp.Count -eq 1 -and (-not $RequireHeldPreparedArtifact -or (Test-HardKillHeldFileDeleteSharing $temp[0])) -and -not(Test-Path -LiteralPath $claimPath) -and -not(Test-Path -LiteralPath $statePath)
        }
        'after-setup-claim-publish'{return $phases.Count -eq 2 -and $phases[0] -ceq 'SETUP_CLAIM_INTENT' -and $phases[1] -ceq 'SETUP_CLAIM_PUBLISHED' -and $pending.Count -eq 0 -and $claimExact -and -not(Test-Path -LiteralPath $statePath)}
        'before-setup-state-publish'{return $phases.Count -eq 0 -and $pending.Count -eq 0 -and $claimExact -and -not(Test-Path -LiteralPath $statePath)}
        'after-setup-state-temp-flush'{
            $temp=@($pending|Where-Object{[IO.Path]::GetFileName($_) -cmatch '^setup-state-[0-9a-f]{32}\.tmp$'})
            $expectedHash=Get-SemanticJsonHash -InputObject $expectedState
            return $phases.Count -eq 1 -and $phases[0] -ceq 'SETUP_STATE_INTENT' -and [string]$records[0].Data.StateHash -ceq $expectedHash -and
                $pending.Count -eq 1 -and $temp.Count -eq 1 -and (-not $RequireHeldPreparedArtifact -or (Test-HardKillHeldFileDeleteSharing $temp[0])) -and $claimExact -and -not(Test-Path -LiteralPath $statePath)
        }
        'after-setup-state-publish'{
            $expectedHash=Get-SemanticJsonHash -InputObject $expectedState
            return $phases.Count -eq 2 -and $phases[0] -ceq 'SETUP_STATE_INTENT' -and $phases[1] -ceq 'SETUP_STATE_PUBLISHED' -and
                [string]$records[0].Data.StateHash -ceq $expectedHash -and [string]$records[1].Data.StateHash -ceq $expectedHash -and $pending.Count -eq 0 -and $claimExact -and $stateExact
        }
    }
    return $false
}
function Read-HardKillSetupBoundaryEvidence {
    param([Parameter(Mandatory)][string]$MarkerPath,[Parameter(Mandatory)][string]$Name)
    if(-not(Test-Path -LiteralPath $MarkerPath -PathType Leaf)){return $null}
    $text=[IO.File]::ReadAllText([IO.Path]::GetFullPath($MarkerPath),[Text.UTF8Encoding]::new($false,$true))
    try{$marker=$text|ConvertFrom-Json -AsHashtable}catch{return $null}
    if($marker -isnot [Collections.IDictionary]){return $null}
    $outerKeys=@('SchemaVersion','ArtifactKind','Checkpoint','PreparedArtifact')
    if(@($marker.Keys).Count -ne $outerKeys.Count -or @($outerKeys|Where-Object{-not $marker.Contains($_)}).Count -ne 0 -or
        [long]$marker.SchemaVersion -ne 1 -or [string]$marker.ArtifactKind -cne 'sealed-setup-checkpoint' -or [string]$marker.Checkpoint -cne $Name){return $null}
    if($Name -notin @('after-setup-claim-temp-flush','after-setup-state-temp-flush')){
        if($null -ne $marker.PreparedArtifact){return $null}
        return $marker
    }
    $evidence=$marker.PreparedArtifact
    if($evidence -isnot [Collections.IDictionary]){return $null}
    $preparedKeys=@('TempPath','PendingName','Identity','Length','Sha256','SemanticHash','SchemaValidated','FlushCompleted')
    if(@($evidence.Keys).Count -ne $preparedKeys.Count -or @($preparedKeys|Where-Object{-not $evidence.Contains($_)}).Count -ne 0){return $null}
    return $marker
}
function Test-HardKillSetupPreparedEvidence {
    param([Parameter(Mandatory)][Collections.IDictionary]$Marker,[Parameter(Mandatory)][string]$Name,[Parameter(Mandatory)][string]$TransactionNamespace,[Parameter(Mandatory)][string]$RepoRoot,[switch]$RequireHeldPreparedArtifact)
    $evidence=$Marker.PreparedArtifact
    if([string]$Marker.Checkpoint -cne $Name -or -not [bool]$evidence.SchemaValidated -or -not [bool]$evidence.FlushCompleted){return $false}
    $documents=@(Get-HardKillJournalDocuments -TransactionNamespace $TransactionNamespace)
    $headers=@($documents|Where-Object{$_ -is [Collections.IDictionary] -and $_.Contains('ArtifactKind') -and [string]$_.ArtifactKind -ceq 'canonical-journal-header'})
    if($headers.Count -ne 1){return $false}
    $header=$headers[0]
    if($Name -ceq 'after-setup-claim-temp-flush'){
        $expectedDocument=$header.SetupRecovery.ExpectedClaim;$namePattern='^setup-claim-[0-9a-f]{32}\.tmp$'
    }else{
        $expectedDocument=Get-HardKillExpectedSetupState -Header $header -RepoRoot $RepoRoot;$namePattern='^setup-state-[0-9a-f]{32}\.tmp$'
    }
    $tempName=[string]$evidence.PendingName
    if($tempName -cnotmatch $namePattern -or [IO.Path]::GetFileName($tempName) -cne $tempName){return $false}
    $expectedBytes=ConvertTo-SemanticJsonBytes -InputObject $expectedDocument
    $expectedSha=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($expectedBytes)).ToLowerInvariant()
    $expectedHash=Get-SemanticJsonHash -InputObject $expectedDocument
    if([long]$evidence.Length -ne [long]$expectedBytes.LongLength -or [string]$evidence.Sha256 -cne $expectedSha -or [string]$evidence.SemanticHash -cne $expectedHash){return $false}
    $tempPath=Join-Path (Join-Path $TransactionNamespace '_pending') $tempName
    if(-not [IO.Path]::GetFullPath([string]$evidence.TempPath).Equals([IO.Path]::GetFullPath($tempPath),[StringComparison]::OrdinalIgnoreCase)){return $false}
    try{$info=[AiAgentDotfiles.NoFollowFile]::Inspect($tempPath)}catch{return $false}
    return -not [bool]$info.IsDirectory -and -not [bool]$info.IsReparsePoint -and [long]$info.LinkCount -eq 1 -and
        [string]$info.Identity -ceq [string]$evidence.Identity -and [long]$info.Length -eq [long]$evidence.Length -and
        (-not $RequireHeldPreparedArtifact -or (Test-HardKillHeldFileDeleteSharing $tempPath))
}
function Wait-HardKillExternalSetupCheckpoint {
    param([Parameter(Mandatory)]$Process,[Parameter(Mandatory)][string]$Name,[Parameter(Mandatory)][string]$TransactionNamespace,[Parameter(Mandatory)][string]$RepoRoot,[Parameter(Mandatory)][string]$MarkerPath,[int]$TimeoutSeconds=300)
    $Watcher=$null
    $deadline=[DateTime]::UtcNow.AddSeconds($TimeoutSeconds);$suspended=$false;$primaryFailure=$null
    try{
        while([DateTime]::UtcNow -lt $deadline){
            $Process.Refresh();if($Process.HasExited){return $false}
            if(-not(Test-Path -LiteralPath $MarkerPath -PathType Leaf)){Start-Sleep -Milliseconds 50;continue}
            $marker=Read-HardKillSetupBoundaryEvidence -MarkerPath $MarkerPath -Name $Name
            if($null -eq $marker){throw 'sealed setup host marker differs from the requested checkpoint contract'}
            [AiAgentDotfiles.HardKillLeaseProbe]::Suspend($Process);$suspended=$true
            if(-not(Test-HardKillSetupCheckpointState -Name $Name -TransactionNamespace $TransactionNamespace -RepoRoot $RepoRoot -RequireHeldPreparedArtifact)){throw 'sealed setup checkpoint tuple differs from its durable boundary contract'}
            if($Name -in @('after-setup-claim-temp-flush','after-setup-state-temp-flush') -and -not(Test-HardKillSetupPreparedEvidence -Marker $marker -Name $Name -TransactionNamespace $TransactionNamespace -RepoRoot $RepoRoot -RequireHeldPreparedArtifact)){throw 'sealed setup prepared artifact evidence differs from its exact held bytes contract'}
            $null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label 'sealed setup checkpoint host';$suspended=$false
            if($Watcher){$Watcher.Dispose();$Watcher=$null}
            if(-not(Test-HardKillSetupCheckpointState -Name $Name -TransactionNamespace $TransactionNamespace -RepoRoot $RepoRoot)){throw 'sealed setup checkpoint tuple changed after Job reap'}
            if($Name -in @('after-setup-claim-temp-flush','after-setup-state-temp-flush') -and -not(Test-HardKillSetupPreparedEvidence -Marker $marker -Name $Name -TransactionNamespace $TransactionNamespace -RepoRoot $RepoRoot)){throw 'sealed setup prepared artifact evidence changed after Job reap'}
            return $true
        }
        return $false
    }catch{$primaryFailure=$_.Exception}
    finally{
        $cleanupFailure=$null
        try{
            $jobLeaseProperty=$Process.PSObject.Properties['HardKillJobProcess']
            if($null -eq $jobLeaseProperty -or $null -eq $jobLeaseProperty.Value){throw 'sealed setup checkpoint cleanup has no registered Job lease'}
            $jobProcess=[AiAgentDotfilesTests.HardKillJobProcess]$jobLeaseProperty.Value
            if(-not $jobProcess.Reaped){$null=Confirm-HardKillRegisteredProcessReaped -Process $Process -Label 'sealed setup checkpoint cleanup'}
            $suspended=$false
        }catch{$cleanupFailure=$_.Exception}
        if($primaryFailure -and $cleanupFailure){throw [AggregateException]::new('sealed setup checkpoint primary/cleanup failure',[Exception[]]@($primaryFailure,$cleanupFailure))}
        if($primaryFailure){throw $primaryFailure}
        if($cleanupFailure){throw $cleanupFailure}
    }
}

$root=Microsoft.PowerShell.Management\Join-Path ([IO.Path]::GetTempPath()) ('ai-agent-dotfiles-canonical-hard-kill-'+[Guid]::NewGuid().ToString('N'))
[IO.Directory]::CreateDirectory($root)|Out-Null
try{
    $oplockSource=[IO.File]::ReadAllText($PSCommandPath)
