        'selector-nonmatch-no-io','selector-first-match-single-use-ticket','selector-prehandoff-failure-ownership','selector-posthandoff-timeout-ownership',
        'context-sealed-call-failure-cleanup','context-match-assertion-failure-cleanup','native-layout-x86-x64','native-secured-root-containment',
        'native-forbidden-read-delete-bridge','native-reviewed-writer-bridge-seal','native-seal-blocks-write-delete-rebind','native-failure-matrix-zero-residue',
        'qpc-late-entry-no-refresh','qpc-overflow-and-natural-exit-race','partial-preseal-rebind-fail-closed','partial-postseal-mutation-blocked',
        'differential-role-swap-rejected','differential-stable-parent-recreate-rejected','rollback-stage-cleanup-failure-no-proof','preimage-stage-cleanup-failure-no-proof'
    )
    $legacyProbeValidatorStaticSelfTest=Test-HardKillBehaviorProbeValidatorMutations
    $behaviorProbeValidatorStaticSelfTest=[pscustomobject]@{Valid=$legacyProbeValidatorStaticSelfTest.Valid -and $hostCaseFlowStaticSatisfied -and
        $childPrimitiveAuthorityStaticSatisfied -and $childCapabilityStaticSatisfied -and $oracleDriverStaticSatisfied -and
        $oracleDispatcherStaticSatisfied -and $parentOracleAuthorityStaticSatisfied -and $parentOracleRuntimePreflightStaticSatisfied -and
        $preimageProvenanceStaticSatisfied -and $preimageTransportStaticSatisfied -and $transportAuthorityDefinitionStaticSatisfied -and $transportAuthorityRuntimeStaticSatisfied -and $afterPreimageLadderStaticSatisfied}
    $behaviorLaunchStaticGate=$behaviorProbeValidatorStaticSelfTest.Valid -and $hardKillHostExists -and $mutationEngineReady -and $childPrimitiveAuthority.Valid -and $childCapability.Valid -and $hostCaseFlow.Valid -and
        $oracleDispatcherContract.Valid -and $parentOracleAuthority.Valid -and $behaviorCleanupStaticContractSatisfied -and
        $behaviorCleanupAuthorityWiring.Valid -and $behaviorCleanupAuthority.Valid -and $transportAuthorityDefinitionStaticSatisfied -and $transportAuthorityRuntimeStaticSatisfied -and $transportAuthority.Valid -and $preimageTransport.Valid -and $realPreimageAuthorityPresent -and
        $workspaceIntentPrimitiveCreatedOrder
    $heldEngineValidationProbe=[pscustomobject]@{Valid=$false;FailedCases=@($behaviorExpectedCases);Residue=0;RootAbsent=$true;LaunchAttempted=$false;LaunchedPid=0;CleanupErrors=@();ForensicRoot='';Error='behavior-held-engine-validation-not-run'}
    $heldHostValidationProbe=[pscustomobject]@{Valid=$false;FailedCases=@($behaviorExpectedCases);Residue=0;RootAbsent=$true;LaunchAttempted=$false;LaunchedPid=0;CleanupErrors=@();ForensicRoot='';Error='behavior-held-host-validation-not-run'}
    $heldEngineRegistryStable=$false;$heldHostRegistryStable=$false;$heldEngineSpawnedStable=$false;$heldHostSpawnedStable=$false
    $heldEngineScratchStable=$false;$heldHostScratchStable=$false;$heldEngineExclusiveReopen=$false;$heldHostExclusiveReopen=$false
    $heldEnginePreCleanupAccepted=$false;$heldHostPreCleanupAccepted=$false;$heldEngineFailedCasesExact=$false;$heldHostFailedCasesExact=$false
    $heldValidationFixtureDeleted=$false;$heldValidationFixtureCleanupErrors=[Collections.Generic.List[string]]::new()
    [object[]]$behaviorRegistryBefore=@($script:forensicRoots);[object[]]$behaviorProcessesBefore=$script:spawnedProcesses.ToArray()
    [string[]]$behaviorRootInventoryBefore=@(Microsoft.PowerShell.Management\Get-ChildItem -LiteralPath $root -Force|Sort-Object Name|ForEach-Object{[string]$_.Name})
    if($behaviorLaunchStaticGate){
        $heldValidationParentHandles=$null;$heldValidationRootHandle=$null;$heldValidationCaseHandle=$null
        $heldValidationCleanupSession=[AiAgentDotfilesTests.HardKillBehaviorCleanupSession]::Begin()
        $heldValidationRootLeaf='held-source-validation-'+[Guid]::NewGuid().ToString('N');$heldValidationRootPath=Join-Path $root $heldValidationRootLeaf
        $heldValidationCleanupJournal=[pscustomobject]@{MutationRows=[Collections.Generic.List[object]]::new();DeletedRelativePaths=[Collections.Generic.List[string]]::new()}
        $heldValidationCases=[Collections.Generic.List[object]]::new()
        try{
            $heldValidationParentHandlesReceiver=[AiAgentDotfiles.SealedOwnershipTransferReceiver]::new()
            Open-SafeDirectoryContainmentChain -Path $root -OwnershipReceiver $heldValidationParentHandlesReceiver
            $heldValidationParentHandles = $heldValidationParentHandlesReceiver.GetDeliveredExact()
            $heldValidationParentHandle=$heldValidationParentHandles[$heldValidationParentHandles.Count-1]
            $heldValidationRootHandle=[AiAgentDotfiles.NoFollowFile]::CreateChildDirectory($heldValidationParentHandle,$heldValidationRootLeaf)
            $heldValidationRootInfo=[pscustomobject]@{Identity=[string]$heldValidationRootHandle.Info.Identity;LinkCount=[uint32]$heldValidationRootHandle.Info.LinkCount;Length=[long]$heldValidationRootHandle.Info.Length;Attributes=[int]$heldValidationRootHandle.Info.Attributes}
            $validEngineBytes=[IO.File]::ReadAllBytes($mutationEnginePath);$validHostBytes=[IO.File]::ReadAllBytes($hardKillHostPath)
            $invalidEngineBytes=[Text.UTF8Encoding]::new($false).GetBytes("function Invoke-SealedMutationBehaviorCase { return 'canned' }`n")
            $invalidHostBytes=[Text.UTF8Encoding]::new($false).GetBytes("#requires -Version 7.0`n")
            foreach($definition in @(
                [pscustomobject]@{Kind='engine';DirectoryLeaf='engine-invalid';EngineBytes=$invalidEngineBytes;HostBytes=$validHostBytes},
                [pscustomobject]@{Kind='host';DirectoryLeaf='host-invalid';EngineBytes=$validEngineBytes;HostBytes=$invalidHostBytes}
            )){
                $casePath=Join-Path $heldValidationRootPath $definition.DirectoryLeaf
                $heldValidationCaseHandle=[AiAgentDotfiles.NoFollowFile]::CreateChildDirectory($heldValidationRootHandle,$definition.DirectoryLeaf)
                $caseInfo=[pscustomobject]@{Identity=[string]$heldValidationCaseHandle.Info.Identity;LinkCount=[uint32]$heldValidationCaseHandle.Info.LinkCount;Length=[long]$heldValidationCaseHandle.Info.Length;Attributes=[int]$heldValidationCaseHandle.Info.Attributes}
                $enginePath=Join-Path $casePath 'engine.ps1';$hostPath=Join-Path $casePath 'host.ps1'
                Write-HardKillCreateNewBytes -Path $enginePath -Bytes ([byte[]]$definition.EngineBytes);Write-HardKillCreateNewBytes -Path $hostPath -Bytes ([byte[]]$definition.HostBytes)
                $fileRows=[Collections.Generic.List[object]]::new()
                foreach($leaf in @('engine.ps1','host.ps1')){
                    $capture=[AiAgentDotfiles.NoFollowFile]::OpenAndHashChildRegularFile($heldValidationCaseHandle,$leaf)
                    try{$fileRows.Add([pscustomobject]@{Leaf=$leaf;Path=Join-Path $casePath $leaf;Identity=[string]$capture.ReadResult.Identity;LinkCount=[uint32]$capture.ReadResult.LinkCount;Length=[long]$capture.ReadResult.Length;Attributes=[int]$capture.Info.Attributes;Sha256=[string]$capture.ReadResult.Sha256})}finally{$capture.Dispose()}
                }
                $heldValidationCases.Add([pscustomobject]@{Kind=$definition.Kind;DirectoryLeaf=$definition.DirectoryLeaf;Path=$casePath;DirectoryInfo=$caseInfo;Files=@($fileRows);RegistryStable=$false;SpawnedStable=$false;ScratchStable=$false;ExclusiveReopen=$false})
                $heldValidationCaseHandle.Dispose();$heldValidationCaseHandle=$null
            }
            $heldValidationRootHandle.Dispose();$heldValidationRootHandle=$null

            foreach($case in $heldValidationCases){
                [object[]]$registryBefore=@($script:forensicRoots);[object[]]$spawnedBefore=$script:spawnedProcesses.ToArray()
                try{
                    if($case.Kind -ceq 'engine'){$heldEngineValidationProbe=Invoke-HardKillBehaviorProbe -EnginePath (Join-Path $case.Path 'engine.ps1') -ProbeHostPath (Join-Path $case.Path 'host.ps1') -ExpectedCases $behaviorExpectedCases -ScratchParent $case.Path -ControllerSource $oplockSource}
                    else{$heldHostValidationProbe=Invoke-HardKillBehaviorProbe -EnginePath (Join-Path $case.Path 'engine.ps1') -ProbeHostPath (Join-Path $case.Path 'host.ps1') -ExpectedCases $behaviorExpectedCases -ScratchParent $case.Path -ControllerSource $oplockSource}
                }catch{
                    $failure=[pscustomobject]@{Valid=$false;FailedCases=@($behaviorExpectedCases);Residue=-1;RootAbsent=$true;LaunchAttempted=$false;LaunchedPid=0;CleanupErrors=@($_.Exception.Message);ForensicRoot='';Error=("behavior-held-$($case.Kind)-validation-threw: "+$_.Exception.Message)}
                    if($case.Kind -ceq 'engine'){$heldEngineValidationProbe=$failure}else{$heldHostValidationProbe=$failure}
                }
                [object[]]$registryAfter=@($script:forensicRoots);$case.RegistryStable=$registryBefore.Length -eq $registryAfter.Length
                for($index=0;$case.RegistryStable -and $index -lt $registryBefore.Length;$index++){$case.RegistryStable=[object]::ReferenceEquals($registryBefore[$index],$registryAfter[$index])}
                [object[]]$spawnedAfter=$script:spawnedProcesses.ToArray();$case.SpawnedStable=$spawnedBefore.Length -eq $spawnedAfter.Length
                for($index=0;$case.SpawnedStable -and $index -lt $spawnedBefore.Length;$index++){$case.SpawnedStable=[object]::ReferenceEquals($spawnedBefore[$index],$spawnedAfter[$index])}
                $challengeRoot=$null;$challengeCase=$null
                try{
                    $challengeRoot=[AiAgentDotfiles.NoFollowFile]::HoldChildDirectory($heldValidationParentHandle,$heldValidationRootLeaf)
                    $challengeCase=[AiAgentDotfiles.NoFollowFile]::HoldChildDirectory($challengeRoot,$case.DirectoryLeaf)
                    $case.ScratchStable=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($challengeCase)|Sort-Object).Count -eq 2 -and
                        @(Compare-Object @('engine.ps1','host.ps1') @([AiAgentDotfiles.NoFollowFile]::GetChildNames($challengeCase)|Sort-Object) -CaseSensitive).Count -eq 0
                }finally{if($challengeCase){$challengeCase.Dispose()};if($challengeRoot){$challengeRoot.Dispose()}}
                $case.ExclusiveReopen=$true
                foreach($file in $case.Files){$exclusive=$null;try{$exclusive=[IO.File]::Open([string]$file.Path,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}catch{$case.ExclusiveReopen=$false}finally{if($exclusive){$exclusive.Dispose()}}}
                if($case.Kind -ceq 'engine'){$heldEngineRegistryStable=$case.RegistryStable;$heldEngineSpawnedStable=$case.SpawnedStable;$heldEngineScratchStable=$case.ScratchStable;$heldEngineExclusiveReopen=$case.ExclusiveReopen}
                else{$heldHostRegistryStable=$case.RegistryStable;$heldHostSpawnedStable=$case.SpawnedStable;$heldHostScratchStable=$case.ScratchStable;$heldHostExclusiveReopen=$case.ExclusiveReopen}
            }

            $heldEngineFailures=@($heldEngineValidationProbe.FailedCases);$heldEngineFailedCasesExact=$heldEngineFailures.Count -eq $behaviorExpectedCases.Count
            for($index=0;$heldEngineFailedCasesExact -and $index -lt $behaviorExpectedCases.Count;$index++){$heldEngineFailedCasesExact=[string]$heldEngineFailures[$index] -ceq [string]$behaviorExpectedCases[$index]}
            $heldHostFailures=@($heldHostValidationProbe.FailedCases);$heldHostFailedCasesExact=$heldHostFailures.Count -eq $behaviorExpectedCases.Count
            for($index=0;$heldHostFailedCasesExact -and $index -lt $behaviorExpectedCases.Count;$index++){$heldHostFailedCasesExact=[string]$heldHostFailures[$index] -ceq [string]$behaviorExpectedCases[$index]}
            $heldEnginePreCleanupAccepted=-not $heldEngineValidationProbe.Valid -and -not $heldEngineValidationProbe.LaunchAttempted -and
                [int]$heldEngineValidationProbe.LaunchedPid -eq 0 -and $heldEngineValidationProbe.RootAbsent -and [int]$heldEngineValidationProbe.Residue -eq 0 -and
                [string]::IsNullOrEmpty([string]$heldEngineValidationProbe.ForensicRoot) -and @($heldEngineValidationProbe.CleanupErrors).Count -eq 0 -and
                $heldEngineFailedCasesExact -and [string]$heldEngineValidationProbe.Error -like 'behavior-child-primitive-authority:*' -and
                $heldEngineRegistryStable -and $heldEngineSpawnedStable -and $heldEngineScratchStable -and $heldEngineExclusiveReopen
            $heldHostPreCleanupAccepted=-not $heldHostValidationProbe.Valid -and -not $heldHostValidationProbe.LaunchAttempted -and
                [int]$heldHostValidationProbe.LaunchedPid -eq 0 -and $heldHostValidationProbe.RootAbsent -and [int]$heldHostValidationProbe.Residue -eq 0 -and
                [string]::IsNullOrEmpty([string]$heldHostValidationProbe.ForensicRoot) -and @($heldHostValidationProbe.CleanupErrors).Count -eq 0 -and
                $heldHostFailedCasesExact -and [string]$heldHostValidationProbe.Error -like 'behavior-probe-contract:*' -and
                $heldHostRegistryStable -and $heldHostSpawnedStable -and $heldHostScratchStable -and $heldHostExclusiveReopen
            if(-not $heldEnginePreCleanupAccepted -or -not $heldHostPreCleanupAccepted){throw 'held-source validation failed before fixture teardown'}

            $heldValidationRootHandle=[AiAgentDotfiles.NoFollowFile]::HoldChildDirectory($heldValidationParentHandle,$heldValidationRootLeaf)
            if([string]$heldValidationRootHandle.Info.Identity -cne [string]$heldValidationRootInfo.Identity -or
                [uint32]$heldValidationRootHandle.Info.LinkCount -ne [uint32]$heldValidationRootInfo.LinkCount -or
                [long]$heldValidationRootHandle.Info.Length -ne [long]$heldValidationRootInfo.Length -or
                [int]$heldValidationRootHandle.Info.Attributes -ne [int]$heldValidationRootInfo.Attributes){throw 'held-validation-root-identity-drift'}
            $expectedCaseLeaves=@($heldValidationCases|ForEach-Object{[string]$_.DirectoryLeaf}|Sort-Object)
            $actualCaseLeaves=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($heldValidationRootHandle)|Sort-Object)
            if(@(Compare-Object $expectedCaseLeaves $actualCaseLeaves -CaseSensitive).Count -ne 0){throw 'held-validation-root-inventory-drift'}
            foreach($case in $heldValidationCases){
                $heldValidationCaseHandle=[AiAgentDotfiles.NoFollowFile]::HoldChildDirectory($heldValidationRootHandle,$case.DirectoryLeaf)
                if([string]$heldValidationCaseHandle.Info.Identity -cne [string]$case.DirectoryInfo.Identity -or
                    [uint32]$heldValidationCaseHandle.Info.LinkCount -ne [uint32]$case.DirectoryInfo.LinkCount -or
                    [long]$heldValidationCaseHandle.Info.Length -ne [long]$case.DirectoryInfo.Length -or
                    [int]$heldValidationCaseHandle.Info.Attributes -ne [int]$case.DirectoryInfo.Attributes){throw "held-validation-case-identity-drift:$($case.Kind)"}
                $expectedFileLeaves=@($case.Files|ForEach-Object{[string]$_.Leaf}|Sort-Object)
                $actualFileLeaves=@([AiAgentDotfiles.NoFollowFile]::GetChildNames($heldValidationCaseHandle)|Sort-Object)
                if(@(Compare-Object $expectedFileLeaves $actualFileLeaves -CaseSensitive).Count -ne 0){throw "held-validation-case-inventory-drift:$($case.Kind)"}
                foreach($file in $case.Files){
                    $capture=[AiAgentDotfiles.NoFollowFile]::OpenAndHashChildRegularFile($heldValidationCaseHandle,[string]$file.Leaf)
                    try{if([string]$capture.ReadResult.Identity -cne [string]$file.Identity -or [uint32]$capture.ReadResult.LinkCount -ne [uint32]$file.LinkCount -or [long]$capture.ReadResult.Length -ne [long]$file.Length -or [int]$capture.Info.Attributes -ne [int]$file.Attributes -or [string]$capture.ReadResult.Sha256 -cne [string]$file.Sha256){throw "held-validation-fixture-drift:$($case.Kind):$($file.Leaf)"}}finally{$capture.Dispose()}
                }
                $heldValidationCaseHandle.Dispose();$heldValidationCaseHandle=$null
            }
            foreach($case in $heldValidationCases){
                $heldValidationCaseHandle=[AiAgentDotfiles.NoFollowFile]::HoldChildDirectory($heldValidationRootHandle,$case.DirectoryLeaf)
                foreach($file in $case.Files){
                    Remove-HardKillBehaviorRegularFileExact -Parent $heldValidationCaseHandle -Leaf ([string]$file.Leaf) -ExpectedIdentity ([string]$file.Identity) -ExpectedLinkCount ([uint32]$file.LinkCount) -ExpectedLength ([long]$file.Length) -ExpectedAttributes ([int]$file.Attributes) -RelativePath ("$($case.DirectoryLeaf)/$($file.Leaf)") -CleanupJournal $heldValidationCleanupJournal -CleanupSession $heldValidationCleanupSession
                }
                $heldValidationCaseHandle.Dispose();$heldValidationCaseHandle=$null
                Remove-HardKillBehaviorEmptyDirectoryExact -Parent $heldValidationRootHandle -Leaf ([string]$case.DirectoryLeaf) -ExpectedIdentity ([string]$case.DirectoryInfo.Identity) -ExpectedLinkCount ([uint32]$case.DirectoryInfo.LinkCount) -ExpectedLength ([long]$case.DirectoryInfo.Length) -ExpectedAttributes ([int]$case.DirectoryInfo.Attributes) -RelativePath ([string]$case.DirectoryLeaf) -CleanupJournal $heldValidationCleanupJournal -CleanupSession $heldValidationCleanupSession
            }
            $heldValidationRootHandle.Dispose();$heldValidationRootHandle=$null
            Remove-HardKillBehaviorEmptyDirectoryExact -Parent $heldValidationParentHandle -Leaf $heldValidationRootLeaf -ExpectedIdentity ([string]$heldValidationRootInfo.Identity) -ExpectedLinkCount ([uint32]$heldValidationRootInfo.LinkCount) -ExpectedLength ([long]$heldValidationRootInfo.Length) -ExpectedAttributes ([int]$heldValidationRootInfo.Attributes) -RelativePath '.' -CleanupJournal $heldValidationCleanupJournal -CleanupSession $heldValidationCleanupSession
            $expectedDeleted=@('engine-invalid/engine.ps1','engine-invalid/host.ps1','engine-invalid','host-invalid/engine.ps1','host-invalid/host.ps1','host-invalid','.')
            $heldValidationFixtureDeleted=@(Compare-Object $expectedDeleted @($heldValidationCleanupJournal.DeletedRelativePaths) -CaseSensitive).Count -eq 0
        }catch{
            $heldValidationFixtureCleanupErrors.Add($_.Exception.Message)
            $script:cleanupFailures.Add([InvalidOperationException]::new('held-source validation fixture cleanup failed',$_.Exception))
        }finally{
            try{if($heldValidationCaseHandle){$heldValidationCaseHandle.Dispose();$heldValidationCaseHandle=$null}}catch{$heldValidationFixtureCleanupErrors.Add($_.Exception.Message);$script:cleanupFailures.Add($_.Exception)}
            try{if($heldValidationRootHandle){$heldValidationRootHandle.Dispose();$heldValidationRootHandle=$null}}catch{$heldValidationFixtureCleanupErrors.Add($_.Exception.Message);$script:cleanupFailures.Add($_.Exception)}
            try{if($heldValidationParentHandles){Close-SafeDirectoryContainmentChain -Handles $heldValidationParentHandles;$heldValidationParentHandles=$null}}catch{$heldValidationFixtureCleanupErrors.Add($_.Exception.Message);$script:cleanupFailures.Add($_.Exception)}
        }
    }
    $heldEngineValidationSatisfied=$behaviorLaunchStaticGate -and $heldEnginePreCleanupAccepted -and
        $heldValidationFixtureDeleted -and $heldValidationFixtureCleanupErrors.Count -eq 0
    $heldHostValidationSatisfied=$behaviorLaunchStaticGate -and $heldHostPreCleanupAccepted -and
        $heldValidationFixtureDeleted -and $heldValidationFixtureCleanupErrors.Count -eq 0
    Assert $heldEngineValidationSatisfied `
        'held invalid engine validation aborts before scratch or child launch, releases both copied leaves and containment owners, and leaves exact zero residue'
    Assert $heldHostValidationSatisfied `
        'held invalid host validation preserves exact registry references, releases both copied leaves and containment owners, and leaves exact zero residue'
    $behaviorRunGate=$behaviorLaunchStaticGate -and $heldEngineValidationSatisfied -and $heldHostValidationSatisfied
    if($behaviorRunGate){
        $behaviorProbe=Invoke-HardKillBehaviorProbe -EnginePath $mutationEnginePath -ProbeHostPath $hardKillHostPath -ExpectedCases $behaviorExpectedCases -ScratchParent $root -ControllerSource $oplockSource
    }else{
        $launchError=if(-not $mutationEngineReady){'behavior-engine-missing'}elseif(-not $childPrimitiveAuthority.Valid){[string]$childPrimitiveAuthority.Error}elseif(-not $childCapability.Valid){[string]$childCapability.ErrorCodes[0]}elseif(-not $hardKillHostExists){'behavior-probe-host-missing'}elseif(-not $hostCaseFlow.Valid){[string]$hostCaseFlow.ErrorCodes[0]}elseif(-not $parentOracleAuthority.Valid){[string]$parentOracleAuthority.Error}elseif(-not $oracleDispatcherContract.Valid){[string]$oracleDispatcherContract.ErrorCodes[0]}elseif(-not $behaviorCleanupAuthority.Valid){[string]$behaviorCleanupAuthority.Error}elseif(-not $heldEngineValidationSatisfied -or -not $heldHostValidationSatisfied){'behavior-held-source-validation-contract'}else{'behavior-prelaunch-static-contract'}
        $behaviorProbe=[pscustomobject]@{
            Valid=$false;CaseNames=@();PassedCases=@();FailedCases=@($behaviorExpectedCases);ParentObservations=@();Residue=0;RootAbsent=$true
            ProbeContractValid=$false;ValidatorSelfTest=$behaviorProbeValidatorStaticSelfTest.Valid;ParentOracleAuthority=$parentOracleAuthority.Valid
            AuthorityBackedCleanup=$behaviorCleanupAuthority.Valid;LaunchAttempted=$false;LaunchedPid=0;CleanupErrors=@();ForensicRoot='';Error=$launchError
        }
    }
    [object[]]$behaviorRegistryAfter=@($script:forensicRoots);$behaviorNoLaunchRegistryStable=$behaviorRegistryBefore.Length -eq $behaviorRegistryAfter.Length
    for($index=0;$behaviorNoLaunchRegistryStable -and $index -lt $behaviorRegistryBefore.Length;$index++){$behaviorNoLaunchRegistryStable=[object]::ReferenceEquals($behaviorRegistryBefore[$index],$behaviorRegistryAfter[$index])}
    [object[]]$behaviorProcessesAfter=$script:spawnedProcesses.ToArray();$behaviorNoLaunchProcessesStable=$behaviorProcessesBefore.Length -eq $behaviorProcessesAfter.Length
    for($index=0;$behaviorNoLaunchProcessesStable -and $index -lt $behaviorProcessesBefore.Length;$index++){$behaviorNoLaunchProcessesStable=[object]::ReferenceEquals($behaviorProcessesBefore[$index],$behaviorProcessesAfter[$index])}
    [string[]]$behaviorRootInventoryAfter=@(Microsoft.PowerShell.Management\Get-ChildItem -LiteralPath $root -Force|Sort-Object Name|ForEach-Object{[string]$_.Name})
    $behaviorNoLaunchRootStable=@(Compare-Object $behaviorRootInventoryBefore $behaviorRootInventoryAfter -CaseSensitive).Count -eq 0
    $behaviorFailedCases=@($behaviorProbe.FailedCases);$behaviorFailedCasesExact=$behaviorFailedCases.Count -eq $behaviorExpectedCases.Count
    for($index=0;$behaviorFailedCasesExact -and $index -lt $behaviorExpectedCases.Count;$index++){$behaviorFailedCasesExact=[string]$behaviorFailedCases[$index] -ceq [string]$behaviorExpectedCases[$index]}
    $behaviorPassed=@($behaviorProbe.PassedCases)
    Assert ($behaviorRunGate -or (-not $behaviorProbe.LaunchAttempted -and [int]$behaviorProbe.LaunchedPid -eq 0 -and
        $behaviorProbe.RootAbsent -and [int]$behaviorProbe.Residue -eq 0 -and [string]::IsNullOrEmpty([string]$behaviorProbe.ForensicRoot) -and
        $behaviorFailedCasesExact -and $behaviorNoLaunchRegistryStable -and $behaviorNoLaunchProcessesStable -and $behaviorNoLaunchRootStable)) `
        'behavior-probe static rejection occurs before scratch acquisition or child launch and leaves zero residue'
    Assert $behaviorProbe.ValidatorSelfTest `
        'behavior-probe validators bind the hash-held engine, reviewed child primitive authority, exact twenty-case host loop, and closed action-to-case-to-response lifecycle before launch'

    $checkpointNames=@(
        'BeforeWorkspaceCreate','AfterWorkspaceCreate','BeforeParentCreate','AfterParentCreate',
        'BeforeDirectoryOldMove','AfterDirectoryOldMove','BeforeDirectoryNewMove','AfterDirectoryNewMove',
        'BeforeDirectoryDeletionRecord','AfterDirectoryDeletionRecord','BeforeFileReplaceMove','AfterFileReplaceMove',
        'PreimageReady','RetainedPartialPreimage'
    )
    $primitiveVariantNames=@(
        'WorkspacePreimageCreate','WorkspaceSwapOldCreate','ParentCreate','DirectoryOldMovePresent','DirectoryNewMovePresent',
        'DirectoryDeletionRecordMissing','FileReplacePresent','FileMoveMissing','RealPreimageFile','RetainedPartialPreimageFile'
    )
    $enumMatch=[regex]::Match($mutationEngineSource,'(?s)public\s+enum\s+SealedMutationCheckpoint\s*\{(?<body>.*?)\}')
    $actualCheckpointNames=if($enumMatch.Success){@($enumMatch.Groups['body'].Value -split ','|ForEach-Object{($_ -split '=')[0].Trim()}|Where-Object{$_})}else{@()}
    $variantMatch=[regex]::Match($mutationEngineSource,'(?s)public\s+enum\s+SealedMutationPrimitiveVariant\s*\{(?<body>.*?)\}')
    $actualPrimitiveVariantNames=if($variantMatch.Success){@($variantMatch.Groups['body'].Value -split ','|ForEach-Object{($_ -split '=')[0].Trim()}|Where-Object{$_})}else{@()}
    $requiredTypeNames=@('SealedMutationStageSelector','SealedMutationPublicationTicket','SealedMutationStageCoordinator','SealedMutationInvocationContext','SealedStageRootLease','SealedStageFileLease','SealedJobQpcDeadlines')
    $typedContractPresent=$mutationEngineReady -and $enumMatch.Success -and
        @(Compare-Object $checkpointNames $actualCheckpointNames -CaseSensitive).Count -eq 0 -and $variantMatch.Success -and
        @(Compare-Object $primitiveVariantNames $actualPrimitiveVariantNames -CaseSensitive).Count -eq 0
    foreach($typeName in $requiredTypeNames){$typedContractPresent=$typedContractPresent -and ([regex]::Matches($mutationEngineSource,"(?m)\b(?:class|struct)\s+$typeName\b").Count -eq 1)}
    Assert $typedContractPresent `
        'sealed mutation engine declares the exact closed checkpoint, selector, ticket, invocation-context, deadline, and native lease types'

    $reachFunctionAst=if($mutationEngineReady){Get-HardKillFunctionAst -Ast $mutationEngineAst -Name 'Invoke-SealedMutationReach'}else{$null}
    $reachParameters=if($reachFunctionAst){@($reachFunctionAst.Body.ParamBlock.Parameters)}else{@()}
    $reachContextParameters=@($reachParameters|Where-Object{$_.Name.VariablePath.UserPath -ceq 'InvocationContext' -and @($_.Attributes|Where-Object{$_ -is [Management.Automation.Language.TypeConstraintAst] -and $_.TypeName.FullName -ceq 'AiAgentDotfilesTests.SealedMutationInvocationContext'}).Count -eq 1})
    Assert ($null -ne $reachFunctionAst -and $reachContextParameters.Count -eq 1 -and
        @($reachParameters|Where-Object{$_.Name.VariablePath.UserPath -match 'Coordinator|StageRootLease'}).Count -eq 0 -and
        $mutationEngineSource.IndexOf('$global:',[StringComparison]::OrdinalIgnoreCase) -lt 0 -and
        $mutationEngineSource.IndexOf('$script:SealedMutationStageCoordinator',[StringComparison]::OrdinalIgnoreCase) -lt 0 -and
        $mutationEngineSource.IndexOf('$script:SealedStageRootLease',[StringComparison]::OrdinalIgnoreCase) -lt 0 -and
        $mutationEngineSource.IndexOf('$env:',[StringComparison]::OrdinalIgnoreCase) -lt 0) `
        'the mandatory InvocationContext is the sole child owner and reach has no ambient coordinator or stage-root locator'

    $selectorBehaviorCases=@('selector-nonmatch-no-io','selector-first-match-single-use-ticket')
    $selectorContractPresent=$mutationEngineSource.IndexOf('TryAcceptMatch',[StringComparison]::Ordinal) -ge 0 -and
        $mutationEngineSource.IndexOf('SealedMutationPublicationTicket',[StringComparison]::Ordinal) -ge 0 -and
        $mutationEngineSource.IndexOf('StageReady',[StringComparison]::Ordinal) -ge 0 -and
        $mutationEngineSource.IndexOf('Continue',[StringComparison]::Ordinal) -ge 0 -and
        $mutationEngineSource.IndexOf('IntentArtifactRawSha256',[StringComparison]::Ordinal) -ge 0 -and
        $mutationEngineSource.IndexOf('TailArtifactRawSha256',[StringComparison]::Ordinal) -ge 0 -and
        $mutationEngineSource.IndexOf('DerivedJournalHeadHash',[StringComparison]::Ordinal) -ge 0 -and
        $mutationEngineSource.IndexOf('AssertMatchedExactlyOnce',[StringComparison]::Ordinal) -ge 0 -and
        @($selectorBehaviorCases|Where-Object{$_ -cnotin $behaviorPassed}).Count -eq 0
    Assert $selectorContractPresent `
