    $setupCallerReap=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle ($checkedReapCall+'$process -Label ("setup kill') -StartIndex $setupWait
    $setupStateRead=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$state=Read-CanonicalJournalDirectory' -StartIndex $setupWait
    $setupProofPublish=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle 'Write-HardKillExternalCheckpointProof -Path $proofPath' -StartIndex $setupStateRead
    Assert ($setupControllerReap -ge 0 -and $setupControllerDispose -gt $setupControllerReap -and
        $setupWait -ge 0 -and $setupCallerReap -gt $setupWait -and $setupStateRead -gt $setupCallerReap -and $setupProofPublish -gt $setupStateRead) `
        'setup proof and recovery tuple are reachable only after checked tree reap and exact process identity'
    $processCasesNeedle='$ca'+'ses=@('
    $processMatrixStart=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle $processCasesNeedle -StartIndex $setupMatrixStart
    $initialCheckpoint=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$externalCheckpointGated=$false' -StartIndex $processMatrixStart
    $mainReap=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle ($checkedReapCall+'$process -Label ("hard-kill {0} mutation host') -StartIndex $initialCheckpoint
    $mainStateRead=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$state=Read-CanonicalJournalDirectory' -StartIndex $mainReap
    $mainPostReapTupleInit=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$postReapTupleValid=$true' -StartIndex $mainStateRead
    $mainDependentTuple=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$dependentRollbackTupleValid=' -StartIndex $mainPostReapTupleInit
    $mainParentTuple=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$parentRollbackTupleValid=' -StartIndex $mainDependentTuple
    $mainManualPrefix=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$manualPrefixMatches=' -StartIndex $mainParentTuple
    $mainProofGateNeedle='if($externalMutationCheckpoint -and $initialReached -and $checkpointClassificationValid -and $postReap'+'TupleValid)'
    $mainProofGate=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle $mainProofGateNeedle -StartIndex $mainManualPrefix
    $mainProofPublish=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle 'Write-HardKillExternalCheckpointProof -Path $marker' -StartIndex $mainProofGate
    Assert ($initialCheckpoint -ge 0 -and $mainReap -gt $initialCheckpoint -and $mainStateRead -gt $mainReap -and
        $mainPostReapTupleInit -gt $mainStateRead -and $mainDependentTuple -gt $mainPostReapTupleInit -and
        $mainParentTuple -gt $mainDependentTuple -and $mainManualPrefix -gt $mainParentTuple -and
        $mainProofGate -gt $mainManualPrefix -and $mainProofPublish -gt $mainProofGate) `
        'main proof is reachable only after checked tree reap and every exact post-reap tuple predicate'
    $typedRecoveryReap=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle ($checkedReapCall+'$recoveryProcess -Label ("hard-kill {0} typed recovery"') -StartIndex $processMatrixStart
    $recoveryCleanupEnd=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle 'if($cleanupFailure){throw $cleanupFailure}' -StartIndex $typedRecoveryReap
    $recoveryStateRead=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$afterFailure=Read-CanonicalJournalDirectory' -StartIndex $recoveryCleanupEnd
    $recoveryClassification=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$nextClassification=Get-CanonicalTransactionRecoveryClassification' -StartIndex $recoveryStateRead
    $recoveryProofPublish=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle 'Write-HardKillExternalCheckpointProof -Path $recoveryMarker' -StartIndex $recoveryClassification
    $recoveryCallerReap=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle ($checkedReapCall+'$recoveryProcess -Label ("hard-kill {0} recovery host"') -StartIndex $recoveryProofPublish
    $recoveryProofRead=Find-HardKillSourceIndexAfter -Text $oplockSource -Needle '$externalRecoveryProof=Read-HardKillExternalCheckpointProof' -StartIndex $recoveryCallerReap
    Assert ($typedRecoveryReap -ge 0 -and $recoveryCleanupEnd -gt $typedRecoveryReap -and
        $recoveryStateRead -gt $recoveryCleanupEnd -and $recoveryClassification -gt $recoveryStateRead -and $recoveryProofPublish -gt $recoveryClassification -and
        $recoveryCallerReap -gt $recoveryProofPublish -and $recoveryProofRead -gt $recoveryCallerReap) `
        'recovery proof, tuple, and classification are reachable only after checked tree reap and exact process identity'
    $liveChildRoot=$null;$liveChild=$null;$liveChildEvidence=$null;$jobTreeProofValid=$false
    try{
        $liveChildRootPath=Join-Path $root 'root-exit-live-child';[IO.Directory]::CreateDirectory($liveChildRootPath)|Out-Null
        $liveChildMarker=Join-Path $liveChildRootPath 'child-alive.marker';$liveChildEvidencePath=Join-Path $liveChildRootPath 'child-evidence.json'
        $liveChildRoot=Start-HardKillRegisteredProcess -FilePath (Get-Command pwsh).Source -ArgumentList @(
            '-NoProfile','-File',(Join-Path $RepoRoot 'tests/helpers/canonical-root-exit-live-child-host.ps1'),
            '-Mode','root','-ChildMarkerPath',$liveChildMarker,'-ChildEvidencePath',$liveChildEvidencePath
        )
        if(-not $liveChildRoot.WaitForExit(15000)){throw 'root-exit live-child fixture root did not exit'}
        if(-not(Test-Path -LiteralPath $liveChildEvidencePath -PathType Leaf)){throw 'root-exit live-child fixture did not publish child evidence'}
        $liveChildEvidence=[IO.File]::ReadAllText($liveChildEvidencePath)|ConvertFrom-Json -AsHashtable
        $liveChild=[Diagnostics.Process]::GetProcessById([int]$liveChildEvidence.ProcessId)
        if([long]$liveChild.StartTime.ToUniversalTime().Ticks -ne [long]$liveChildEvidence.StartTimeUtcTicks){throw 'root-exit live-child fixture child identity changed'}
        $jobLease=[AiAgentDotfilesTests.HardKillJobProcess]$liveChildRoot.HardKillJobProcess
        $retainedDescendantObserved=$liveChildRoot.HasExited -and -not $liveChild.HasExited -and $jobLease.ActiveProcesses -gt 0
        $liveChild.Dispose();$liveChild=$null
        $null=Confirm-HardKillRegisteredProcessReaped -Process $liveChildRoot -Label 'root-exit live-child Job fixture'
        $jobTreeProofValid=$retainedDescendantObserved -and $jobLease.Reaped -and
            (Test-HardKillProcessIdentityGone -ProcessId ([int]$liveChildEvidence.ProcessId) -StartTimeUtcTicks ([long]$liveChildEvidence.StartTimeUtcTicks))
    }finally{
        if($liveChild){$liveChild.Dispose()}
        if($liveChildRoot){$null=Confirm-HardKillRegisteredProcessReaped -Process $liveChildRoot -Label 'root-exit live-child Job fixture cleanup'}
    }
    Assert $jobTreeProofValid 'retained Job observes a live descendant after root exit and proves the entire Job empty before returning'
    $jobHelperPath=Join-Path $RepoRoot 'tests/helpers/canonical-hard-kill-job-process.ps1'
    $jobHelperText=if(Test-Path -LiteralPath $jobHelperPath -PathType Leaf){[IO.File]::ReadAllText($jobHelperPath)}else{''}
    Assert ($jobHelperText.IndexOf('PROC_THREAD_ATTRIBUTE_JOB_LIST',[StringComparison]::Ordinal) -ge 0 -and
        $jobHelperText.IndexOf('CREATE_SUSPENDED',[StringComparison]::Ordinal) -ge 0 -and
        $jobHelperText.IndexOf('ActiveProcesses',[StringComparison]::Ordinal) -ge 0 -and
        $oplockSource.IndexOf('Register-HardKillProcess (Start-'+'Process',[StringComparison]::Ordinal) -lt 0 -and
        $oplockSource.IndexOf('Start-'+'Process -FilePath',[StringComparison]::Ordinal) -lt 0) `
        'every hard-kill host is atomically created suspended inside one retained tests-only Job'
    $startFailureCleanup=$jobHelperText.IndexOf('if (!success && processCreated)',[StringComparison]::Ordinal)
    $startFailureTerminate=$jobHelperText.IndexOf('TerminateJobObject(job, 1)', $startFailureCleanup, [StringComparison]::Ordinal)
    $startFailureThreadClose=if($startFailureTerminate -ge 0){$jobHelperText.IndexOf('if (threadHandle != IntPtr.Zero)', $startFailureTerminate, [StringComparison]::Ordinal)}else{-1}
    $startFailureProcessClose=if($startFailureThreadClose -ge 0){$jobHelperText.IndexOf('if (processHandle != IntPtr.Zero)', $startFailureThreadClose, [StringComparison]::Ordinal)}else{-1}
    $startFailureManagedClose=if($startFailureProcessClose -ge 0){$jobHelperText.IndexOf('if (managedProcess != null)', $startFailureProcessClose, [StringComparison]::Ordinal)}else{-1}
    $startFailureJobEmpty=if($startFailureManagedClose -ge 0){$jobHelperText.IndexOf('WaitForJobEmpty(job', $startFailureManagedClose, [StringComparison]::Ordinal)}else{-1}
    $startFailureTimeoutAggregate=Find-HardKillSourceIndexAfter -Text $jobHelperText -Needle 'CombineStartAndCleanupFailure(failure, new TimeoutException(' -StartIndex $startFailureJobEmpty
    $startFailureCatchAggregate=Find-HardKillSourceIndexAfter -Text $jobHelperText -Needle 'CombineStartAndCleanupFailure(failure, cleanupError)' -StartIndex $startFailureTimeoutAggregate
    $startFailureAggregateOrder=$jobHelperText.IndexOf('new Exception[] { primary, cleanup }', [StringComparison]::Ordinal)
    Assert ($startFailureCleanup -ge 0 -and $startFailureTerminate -gt $startFailureCleanup -and
        $startFailureThreadClose -gt $startFailureTerminate -and $startFailureProcessClose -gt $startFailureThreadClose -and
        $startFailureManagedClose -gt $startFailureProcessClose -and $startFailureJobEmpty -gt $startFailureManagedClose -and
        $startFailureTimeoutAggregate -gt $startFailureJobEmpty -and $startFailureCatchAggregate -gt $startFailureTimeoutAggregate -and
        $startFailureAggregateOrder -ge 0) `
        'atomic Job launch failure closes references before ActiveProcesses zero and preserves primary then cleanup causes'
    $rwProbeTryAst=$controllerAst.FindAll({param($node)
        $node -is [Management.Automation.Language.TryStatementAst] -and
        $null -ne $node.Finally -and $node.Extent.Text.IndexOf('$rwOpenBreakValid',[StringComparison]::Ordinal) -ge 0
    },$true)|Sort-Object{$_.Extent.Text.Length}|Select-Object -First 1
    $rwCleanupGuardAst=if($rwProbeTryAst){$rwProbeTryAst.Finally.Find({param($node)
        $node -is [Management.Automation.Language.IfStatementAst] -and
        $node.Extent.Text.IndexOf('$null -eq $rwCleanupFailure',[StringComparison]::Ordinal) -ge 0 -and
        $node.Extent.Text.IndexOf('$rwOplock.Dispose()',[StringComparison]::Ordinal) -ge 0
    },$true)}else{$null}
    $rwCleanupDisposeCount=if($rwProbeTryAst){@($rwProbeTryAst.Finally.FindAll({param($node)
        $node -is [Management.Automation.Language.InvokeMemberExpressionAst] -and
        $node.Extent.Text -ceq '$rwOplock.Dispose()'
    },$true)).Count}else{0}
    Assert ($null -ne $rwCleanupGuardAst -and $rwCleanupDisposeCount -eq 1) `
        'RW cleanup preserves its unacknowledged oplock when checked reap fails'
    $rwOplockMethod=[AiAgentDotfiles.HardKillDirectoryOplock].GetMethod('BeginReadWriteFile',[Reflection.BindingFlags]::Public -bor [Reflection.BindingFlags]::Static)
    Assert ($null -ne $rwOplockMethod -and $oplockSource.IndexOf('OPLOCK_LEVEL_CACHE_WRITE',[StringComparison]::Ordinal) -ge 0) 'hard-kill oplock exposes an exact file R|W grant distinct from the legacy R|H lease'
    $rwOpenBreakValid=$false
    if($rwOplockMethod){
        $rwProbeRoot=Join-Path $root 'rw-oplock-probe';[IO.Directory]::CreateDirectory($rwProbeRoot)|Out-Null
        $rwProbeFile=Join-Path $rwProbeRoot 'header.json';$rwOpenedMarker=Join-Path $rwProbeRoot 'opened.marker';Write-Utf8 $rwProbeFile '{}'
        $rwOplock=$null;$rwReader=$null
        try{
            $expectedIdentity=[string][AiAgentDotfiles.NoFollowFile]::Inspect($rwProbeFile).Identity
            $rwOplock=[AiAgentDotfiles.HardKillDirectoryOplock]::BeginReadWriteFile($rwProbeFile)
            $identityExact=[string]$rwOplock.Identity -ceq $expectedIdentity
            $rwParent=[Diagnostics.Process]::GetCurrentProcess();$rwDeadlineTicks=[DateTime]::UtcNow.AddSeconds(30).Ticks
            $rwReader=Start-HardKillRegisteredProcess -FilePath (Get-Command pwsh).Source -ArgumentList @(
                '-NoProfile','-File',(Join-Path $RepoRoot 'tests/helpers/canonical-held-file-read-attempt-host.ps1'),
                '-Path',$rwProbeFile,'-OpenedMarkerPath',$rwOpenedMarker,
                '-ParentProcessId',$PID,'-ParentStartTimeUtcTicks',$rwParent.StartTime.ToUniversalTime().Ticks,
                '-DeadlineUtcTicks',$rwDeadlineTicks
            )
            $rwReaderStartTicks=$rwReader.StartTime.ToUniversalTime().Ticks
            $breakObserved=$rwOplock.WaitForBreak(10000)
            $breakRequiresAck=$breakObserved -and $rwOplock.IsAcknowledgedSelfMutationBreak()
            $readerPending=$breakRequiresAck -and -not $rwReader.HasExited -and -not(Test-Path -LiteralPath $rwOpenedMarker)
            $rwOplock.Dispose();$rwOplock=$null
            $openDeadline=[DateTime]::UtcNow.AddSeconds(10)
            while(-not(Test-Path -LiteralPath $rwOpenedMarker -PathType Leaf) -and -not $rwReader.HasExited -and [DateTime]::UtcNow -lt $openDeadline){Start-Sleep -Milliseconds 20}
            $readerCompletedOpen=Test-Path -LiteralPath $rwOpenedMarker -PathType Leaf
            $readerReaped=Confirm-HardKillRegisteredProcessReaped -Process $rwReader -Label 'held-file read-attempt helper'
            if(-not $readerReaped){throw 'held-file read-attempt helper cleanup was not confirmed'}
            $rwOpenBreakValid=$identityExact -and $breakRequiresAck -and $readerPending -and $readerCompletedOpen
        }finally{
            $rwCleanupFailure=$null
            if($rwReader){
                try{$null=Confirm-HardKillRegisteredProcessReaped -Process $rwReader -Label 'held-file read-attempt helper cleanup'}catch{$rwCleanupFailure=$_}
            }
            if($null -eq $rwCleanupFailure -and $rwOplock){$rwOplock.Dispose()}
            if($rwCleanupFailure){throw $rwCleanupFailure}
        }
    }
    Assert $rwOpenBreakValid 'file R|W oplock holds a different-key real read open pending until the requester is reaped'

    $lifecycleRoot=Join-Path $root 'held-reader-lifecycle';[IO.Directory]::CreateDirectory($lifecycleRoot)|Out-Null
    $lifecycleFile=Join-Path $lifecycleRoot 'source.json';Write-Utf8 $lifecycleFile '{}'
    $deadlineMarker=Join-Path $lifecycleRoot 'deadline-opened.marker';$deadlineReader=$null
    try{
        $lifecycleParent=[Diagnostics.Process]::GetCurrentProcess();$deadlineClock=[Diagnostics.Stopwatch]::StartNew();$deadlineTicks=[DateTime]::UtcNow.AddSeconds(5).Ticks
        $deadlineReader=Start-HardKillRegisteredProcess -FilePath (Get-Command pwsh).Source -ArgumentList @(
            '-NoProfile','-File',(Join-Path $RepoRoot 'tests/helpers/canonical-held-file-read-attempt-host.ps1'),
            '-Path',$lifecycleFile,'-OpenedMarkerPath',$deadlineMarker,
            '-ParentProcessId',$PID,'-ParentStartTimeUtcTicks',$lifecycleParent.StartTime.ToUniversalTime().Ticks,
            '-DeadlineUtcTicks',$deadlineTicks
        )
        $deadlineReaderId=[int]$deadlineReader.Id;$deadlineReaderStart=$deadlineReader.StartTime.ToUniversalTime().Ticks
        $deadlineExited=$deadlineReader.WaitForExit(10000);$deadlineClock.Stop()
        $deadlineExitCode=if($deadlineExited){[int]$deadlineReader.HardKillJobProcess.RootExitCode}else{$null}
        $null=Confirm-HardKillRegisteredProcessReaped -Process $deadlineReader -Label 'deadline-bound held-file read-attempt helper'
        $deadlineLifecycleValid=$deadlineExited -and (Test-Path -LiteralPath $deadlineMarker -PathType Leaf) -and
            $deadlineExitCode -eq 124 -and $deadlineClock.Elapsed.TotalSeconds -lt 8 -and
            (Test-HardKillProcessIdentityGone -ProcessId $deadlineReaderId -StartTimeUtcTicks $deadlineReaderStart)
    }finally{
        if($deadlineReader){$null=Confirm-HardKillRegisteredProcessReaped -Process $deadlineReader -Label 'deadline-bound held-file read-attempt helper cleanup'}
    }
    Assert $deadlineLifecycleValid 'held-file read-attempt helper exits at its absolute deadline and leaves no exact PID instance'

    $parentMarker=Join-Path $lifecycleRoot 'parent-opened.marker';$childEvidence=Join-Path $lifecycleRoot 'child-evidence.json';$parentHost=$null;$orphanEvidence=$null
    try{
        $parentHost=Start-HardKillRegisteredProcess -FilePath (Get-Command pwsh).Source -ArgumentList @(
            '-NoProfile','-File',(Join-Path $RepoRoot 'tests/helpers/canonical-held-file-read-attempt-parent-host.ps1'),
            '-HelperPath',(Join-Path $RepoRoot 'tests/helpers/canonical-held-file-read-attempt-host.ps1'),
            '-Path',$lifecycleFile,'-OpenedMarkerPath',$parentMarker,'-ChildEvidencePath',$childEvidence,
            '-DeadlineUtcTicks',([DateTime]::UtcNow.AddSeconds(30).Ticks)
        )
        $parentId=[int]$parentHost.Id;$parentStart=$parentHost.StartTime.ToUniversalTime().Ticks
        if(-not $parentHost.WaitForExit(15000)){throw 'held-file read-attempt parent host did not exit at its test boundary'}
        if(-not(Test-Path -LiteralPath $childEvidence -PathType Leaf)){throw 'held-file read-attempt parent host did not publish child identity evidence'}
        $orphanEvidence=[IO.File]::ReadAllText($childEvidence)|ConvertFrom-Json -AsHashtable
        $orphanDeadline=[DateTime]::UtcNow.AddSeconds(10)
        while(-not(Test-HardKillProcessIdentityGone -ProcessId ([int]$orphanEvidence.ProcessId) -StartTimeUtcTicks ([long]$orphanEvidence.StartTimeUtcTicks)) -and [DateTime]::UtcNow -lt $orphanDeadline){Start-Sleep -Milliseconds 20}
        $null=Confirm-HardKillRegisteredProcessReaped -Process $parentHost -Label 'held-file read-attempt parent host'
        $parentDeathLifecycleValid=(Test-Path -LiteralPath $parentMarker -PathType Leaf) -and
            (Test-HardKillProcessIdentityGone -ProcessId ([int]$orphanEvidence.ProcessId) -StartTimeUtcTicks ([long]$orphanEvidence.StartTimeUtcTicks)) -and
            (Test-HardKillProcessIdentityGone -ProcessId $parentId -StartTimeUtcTicks $parentStart)
    }finally{
        if($parentHost){$null=Confirm-HardKillRegisteredProcessReaped -Process $parentHost -Label 'held-file read-attempt parent host cleanup'}
        if($orphanEvidence -and -not(Test-HardKillProcessIdentityGone -ProcessId ([int]$orphanEvidence.ProcessId) -StartTimeUtcTicks ([long]$orphanEvidence.StartTimeUtcTicks))){throw 'held-file child escaped inherited Job containment'}
    }
    Assert $parentDeathLifecycleValid 'held-file read-attempt helper exits when its exact parent process dies'

    $pendingRecovery=Join-Path $root 'after-preimage-pending-recovery'
    foreach($path in @($pendingRecovery,(Join-Path $pendingRecovery 'staged'))){[IO.Directory]::CreateDirectory($path)|Out-Null}
    $pendingTarget=Join-Path $root 'after-preimage-pending-target.txt';$pendingStaged=Join-Path $pendingRecovery 'staged/new.txt';Write-Utf8 $pendingTarget 'old-pending-window';Write-Utf8 $pendingStaged 'new-pending-window'
    $pendingCurrent=Get-CanonicalObservedPathState -Path $pendingTarget -ExpectedKind file;$pendingCandidate=Get-CanonicalObservedPathState -Path $pendingStaged -ExpectedKind file
    $pendingRow=New-TestTarget -Root $pendingRecovery -Name after-preimage-pending -Kind file -TargetPath $pendingTarget -StagedPath $pendingStaged -Current ([ordered]@{State='PRESENT';Hash=[string]$pendingCurrent.Hash}) -Candidate ([ordered]@{State='PRESENT';Hash=[string]$pendingCandidate.Hash})
    $pendingNs=Join-Path $root ([Guid]::NewGuid().ToString('D').ToLowerInvariant());New-TestJournal -Namespace $pendingNs -RecoveryRoot $pendingRecovery -Targets @($pendingRow);Initialize-CanonicalRecoveryWorkspace -TransactionNamespace $pendingNs
    $pendingMissing=[ordered]@{State='MISSING'}
    $pendingIntent=New-CanonicalTargetRecordData -Target $pendingRow -TargetState $pendingCurrent -PreimageState $pendingMissing -SwapOldState $pendingMissing -StagedState $pendingCandidate
    $null=Add-CanonicalJournalRecord -TransactionNamespace $pendingNs -Phase PREIMAGE_COPY_INTENT -Data $pendingIntent
    $null=Copy-CanonicalFileCreateNew -Source $pendingTarget -Destination ([string]$pendingRow.PreimagePath)
    $pendingLeaf=('record-000006-'+[Guid]::NewGuid().ToString('N')+'.tmp');Write-Utf8 (Join-Path (Join-Path $pendingNs '_pending') $pendingLeaf) '{}'
    $pendingLease=$null
    try{
        $pendingLease=Open-CanonicalMutationParentLease -RequireLeafParentsExist -LeafPaths @([string]$pendingRow.PreimagePath)
        $pendingPredicate=Get-HardKillMutationCheckpointState -Name 'after-preimage-copy' -TransactionNamespace $pendingNs
    }finally{Close-CanonicalMutationParentLease -Lease $pendingLease}
    $pendingState=Read-CanonicalJournalDirectory -TransactionNamespace $pendingNs -AllowUnfinished
    $pendingClassification=Get-CanonicalTransactionRecoveryClassification -State $pendingState -RepoRoot $root
    Assert (-not $pendingPredicate -and @($pendingState.PendingEntries).Count -eq 1 -and [string]$pendingClassification.Reason -ceq 'pending-artifact-requires-manual-reconciliation') 'after-preimage predicate rejects an exact copied preimage while a pending journal artifact exists'

    Write-Host "`n[immutable preimage and directory state machine]" -ForegroundColor Cyan
    $dRecovery=Join-Path $root 'dir-recovery';[IO.Directory]::CreateDirectory($dRecovery)|Out-Null
    $dTarget=Join-Path $root 'directory-target';$dStaged=Join-Path $dRecovery 'staged/new-directory'
    [IO.Directory]::CreateDirectory($dTarget)|Out-Null;Write-Utf8 (Join-Path $dTarget 'old.txt') 'old-directory'
    [IO.Directory]::CreateDirectory($dStaged)|Out-Null;Write-Utf8 (Join-Path $dStaged 'new.txt') 'new-directory'
    $dCurrent=[ordered]@{State='PRESENT';Hash=(Get-SafeTreeSnapshot -Root $dTarget).TreeHash};$dCandidate=[ordered]@{State='PRESENT';Hash=(Get-SafeTreeSnapshot -Root $dStaged).TreeHash}
    $dTargetRow=New-TestTarget -Root $dRecovery -Name directory -Kind directory -TargetPath $dTarget -StagedPath $dStaged -Current $dCurrent -Candidate $dCandidate
    $dNs=Join-Path $root ([Guid]::NewGuid().ToString('D').ToLowerInvariant());New-TestJournal -Namespace $dNs -RecoveryRoot $dRecovery -Targets @($dTargetRow)
    $null=Invoke-CanonicalDirectoryReplacement -TransactionNamespace $dNs -Target $dTargetRow
    $dState=Read-CanonicalJournalDirectory -TransactionNamespace $dNs -AllowUnfinished
    $dRecon=Get-CanonicalTargetReconciliation -Target $dTargetRow -Records $dState.Records
    Assert ([string]$dRecon.State -ceq 'NEW_INSTALLED') 'directory: reconciler recognizes the exact installed post-tuple'
    Assert ((Get-CanonicalObservedPathState $dTargetRow.PreimagePath).Hash -ceq $dCurrent.Hash -and (Get-CanonicalObservedPathState $dTargetRow.SwapOldPath).Hash -ceq $dCurrent.Hash) 'directory: immutable preimage and swap-old are distinct old-byte copies'
    Restore-CanonicalMutationTarget -Target $dTargetRow -Reconciliation $dRecon
    Assert ((Get-CanonicalObservedPathState $dTarget).Hash -ceq $dCurrent.Hash -and (Get-CanonicalObservedPathState $dTargetRow.StagedPath).Hash -ceq $dCandidate.Hash) 'directory: rollback restores old target and preserves new bytes in staged'
    Assert ((Get-CanonicalObservedPathState $dTargetRow.PreimagePath).Hash -ceq $dCurrent.Hash) 'directory: rollback never consumes immutable preimage'

    Write-Host "`n[file replace and race capture]" -ForegroundColor Cyan
    $fRecovery=Join-Path $root 'file-recovery';[IO.Directory]::CreateDirectory($fRecovery)|Out-Null
    $fTarget=Join-Path $root 'manifest.txt';$fStaged=Join-Path $fRecovery 'staged/new-manifest.txt';Write-Utf8 $fTarget 'old-file';Write-Utf8 $fStaged 'new-file'
    $fCurrent=[ordered]@{State='PRESENT';Hash=(Get-CanonicalObservedPathState $fTarget).Hash};$fCandidate=[ordered]@{State='PRESENT';Hash=(Get-CanonicalObservedPathState $fStaged).Hash}
    $fTargetRow=New-TestTarget -Root $fRecovery -Name file -Kind file -TargetPath $fTarget -StagedPath $fStaged -Current $fCurrent -Candidate $fCandidate
    $fNs=Join-Path $root ([Guid]::NewGuid().ToString('D').ToLowerInvariant());New-TestJournal -Namespace $fNs -RecoveryRoot $fRecovery -Targets @($fTargetRow)
    $null=Invoke-CanonicalFileReplacement -TransactionNamespace $fNs -Target $fTargetRow
    $fState=Read-CanonicalJournalDirectory -TransactionNamespace $fNs -AllowUnfinished;$fRecon=Get-CanonicalTargetReconciliation -Target $fTargetRow -Records $fState.Records
    Assert ([string]$fRecon.State -ceq 'NEW_INSTALLED') 'file: reconciler recognizes atomic replace post-tuple'
    Restore-CanonicalMutationTarget -Target $fTargetRow -Reconciliation $fRecon
    Assert ((Get-CanonicalObservedPathState $fTarget).Hash -ceq $fCurrent.Hash -and (Get-CanonicalObservedPathState $fTargetRow.StagedPath).Hash -ceq $fCandidate.Hash) 'file: rollback atomically restores old and preserves replaced new bytes'

    $rRecovery=Join-Path $root 'race-recovery';[IO.Directory]::CreateDirectory($rRecovery)|Out-Null
    $rTarget=Join-Path $root 'race.txt';$rStaged=Join-Path $rRecovery 'staged/new.txt';Write-Utf8 $rTarget 'reviewed-old';Write-Utf8 $rStaged 'reviewed-new'
    $rCurrent=[ordered]@{State='PRESENT';Hash=(Get-CanonicalObservedPathState $rTarget).Hash};$rCandidate=[ordered]@{State='PRESENT';Hash=(Get-CanonicalObservedPathState $rStaged).Hash}
    $rRow=New-TestTarget -Root $rRecovery -Name race -Kind file -TargetPath $rTarget -StagedPath $rStaged -Current $rCurrent -Candidate $rCandidate
    $rNs=Join-Path $root ([Guid]::NewGuid().ToString('D').ToLowerInvariant());New-TestJournal -Namespace $rNs -RecoveryRoot $rRecovery -Targets @($rRow)
    $null=Initialize-CanonicalTargetPreimage -TransactionNamespace $rNs -Target $rRow;Write-Utf8 $rTarget 'external-raced-bytes'
    Assert-Throws {Invoke-CanonicalFileReplacement -TransactionNamespace $rNs -Target $rRow} 'manual-recovery-required|prepared target no longer matches' 'file race: drift after durable preimage is rejected before the primitive'
    Assert ((Get-CanonicalObservedPathState $rRow.SwapOldPath).State -ceq 'MISSING' -and [Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($rTarget)) -ceq 'external-raced-bytes') 'file race: rejected pre-primitive drift preserves external bytes without creating swap-old'
    Assert ((Get-CanonicalObservedPathState $rRow.PreimagePath).Hash -ceq $rCurrent.Hash) 'file race: immutable reviewed preimage remains separate and unchanged'

    Write-Host "`n[add/delete state-machine branches]" -ForegroundColor Cyan
    $missing=[ordered]@{State='MISSING'}
    $fdRecovery=Join-Path $root 'file-add-recovery';[IO.Directory]::CreateDirectory((Join-Path $fdRecovery 'staged'))|Out-Null;$fdTarget=Join-Path $root 'new-manifest.txt';$fdStaged=Join-Path $fdRecovery 'staged/new-manifest.txt';Write-Utf8 $fdStaged 'new-only'
