                Assert ([string]$noIntentClass.Status -ceq 'manual' -and (Test-Path -LiteralPath ([string]$pending[0].Path))) 'setup kill claim-temp: a pending claim without the exact durable claim intent is manual and preserved';[IO.File]::WriteAllBytes($intentPath,$intentBytes);$state=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished;$classification=Get-CanonicalTransactionRecoveryClassification -State $state -RepoRoot $caseRepo
                $dualStatePath=Join-Path (Split-Path -Parent ([string]$pending[0].Path)) ('setup-state-'+[Guid]::NewGuid().ToString('N')+'.tmp');[IO.File]::WriteAllBytes($dualStatePath,(ConvertTo-SemanticJsonBytes -InputObject $classification.SetupState.ExpectedFinalState));$dualState=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished;$dualClass=Get-CanonicalTransactionRecoveryClassification -State $dualState -RepoRoot $caseRepo
                Assert ([string]$dualClass.Status -ceq 'manual' -and (Test-Path -LiteralPath $dualStatePath)) 'setup kill claim-temp: simultaneous claim and state temps are impossible/manual and preserved';Remove-Item -LiteralPath $dualStatePath -Force
                [IO.File]::WriteAllText([string]$pending[0].Path,'{}',[Text.UTF8Encoding]::new($false));$corruptState=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished;$corruptClass=Get-CanonicalTransactionRecoveryClassification -State $corruptState -RepoRoot $caseRepo
                Assert ([string]$corruptClass.Status -ceq 'manual' -and [Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes([string]$pending[0].Path)) -ceq '{}') 'setup kill claim-temp: corrupt temp is manual and retained'
                [IO.File]::WriteAllBytes([string]$pending[0].Path,$validBytes);$duplicate=Join-Path (Split-Path -Parent ([string]$pending[0].Path)) ('setup-claim-'+[Guid]::NewGuid().ToString('N')+'.tmp');[IO.File]::WriteAllBytes($duplicate,$validBytes);$multipleState=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished;$multipleClass=Get-CanonicalTransactionRecoveryClassification -State $multipleState -RepoRoot $caseRepo
                Assert ([string]$multipleClass.Status -ceq 'manual' -and (Test-Path -LiteralPath $duplicate)) 'setup kill claim-temp: multiple valid temps are manual and preserved';Remove-Item -LiteralPath $duplicate -Force;$state=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished
            }
