            $pending=@($state.PendingEntries|Where-Object{[string]$_.Name -like 'setup-state-*'});Assert ($pending.Count -eq 1 -and @($state.PendingEntries|Where-Object{[string]$_.Name -like 'result-*'}).Count -eq 0) 'setup kill state-temp: dedicated flushed temp is not treated as result pending'
            $validBytes=[IO.File]::ReadAllBytes([string]$pending[0].Path);[IO.File]::WriteAllText([string]$pending[0].Path,'{}',[Text.UTF8Encoding]::new($false));$corruptState=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished;$corruptClass=Get-CanonicalTransactionRecoveryClassification -State $corruptState -RepoRoot $caseRepo
            Assert ([string]$corruptClass.Status -ceq 'manual' -and [Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes([string]$pending[0].Path)) -ceq '{}') 'setup kill state-temp: corrupt temp is manual and retained'
