            Assert ([string]$multipleClass.Status -ceq 'manual' -and (Test-Path -LiteralPath $duplicate)) 'setup kill state-temp: multiple valid temps are manual and preserved';Remove-Item -LiteralPath $duplicate -Force;$state=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished
        }
