        $lock=Enter-CanonicalRepoLock -LockPath $casePaths.LockPath;try{$terminal=Invoke-SealedCanonicalReviewedRecovery -Document $document -State $state -RepoRoot $caseRepo}finally{Exit-CanonicalRepoLock $lock}
