    $hardKillControllerText=[IO.File]::ReadAllText($PSCommandPath)
    $hardKillJobText=[IO.File]::ReadAllText((Join-Path $RepoRoot 'tests/helpers/canonical-hard-kill-job-process.ps1'))
    $recoveryKillHostText=[IO.File]::ReadAllText((Join-Path $RepoRoot 'tests/helpers/canonical-recovery-kill-host.ps1'))
