            }
            $sealedMutationSeedHeadHash=[string]$sealedMutationSeedPostState.DerivedJournalHeadHash
            $externalMutationCheckpoint=$false;$process=$null;$processState='job-reaped';$initialReached=$true
            $checkpointWait=[Diagnostics.Stopwatch]::StartNew();$checkpointWait.Stop()
        }else{
        $sealedMutationRecoverySeed=$false
        Set-TestProgress ("process:{0}" -f [string]$case.Name)
        $caseRoot=Join-Path $root ("kill-"+[string]$case.Name);[IO.Directory]::CreateDirectory($caseRoot)|Out-Null
        $caseRepo=Join-Path $caseRoot 'repo';Initialize-TestRepo $caseRepo
        $transactionId=[Guid]::NewGuid().ToString('D').ToLowerInvariant();$marker=Join-Path $caseRoot 'checkpoint.marker'
        $afterPreimageStage=$null;$afterPreimageStageEvent=$null;$afterPreimageStageEventName=$null
        $stdout=Join-Path $caseRoot 'host.out';$stderr=Join-Path $caseRoot 'host.err'
        $hostArguments=@('-NoProfile','-File',$hostScript,'-ToolchainRoot',$RepoRoot,'-FixtureRoot',$caseRoot,'-TransactionId',$transactionId,'-Kind',[string]$case.Kind,'-Checkpoint',[string]$case.Checkpoint,'-MarkerPath',$marker)
        if([string]$case.Name -ceq 'after-preimage'){
            $afterPreimageStage=Join-Path $caseRoot 'after-preimage-start.json'
            $afterPreimageStageEventName='AiAgentDotfilesTests-AfterPreimage-'+[Guid]::NewGuid().ToString('N');$afterPreimageStageEventCreated=$false
            $afterPreimageStageEvent=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$afterPreimageStageEventName,[ref]$afterPreimageStageEventCreated)
            if(-not $afterPreimageStageEventCreated){throw 'after-preimage typed stage event name was not newly created'}
            $hostArguments+=@('-AfterPreimageStagePath',$afterPreimageStage,'-AfterPreimageStageEventName',$afterPreimageStageEventName)
        }
        if($case.Contains('Outcome') -and [string]$case.Outcome -ceq 'failed-restored'){$hostArguments+=@('-TerminalOutcome','failed-restored')}
        $caseGit=Get-CanonicalGitContext -RepoRoot $caseRepo;$casePaths=Get-CanonicalTransactionContractPaths -GitContext $caseGit;$namespace=Join-Path $casePaths.TransactionsRoot (Join-Path $caseGit.WorktreeId $transactionId)
        $externalMutationCheckpoint=Test-HardKillMutationCheckpointName -Name ([string]$case.Checkpoint)
        $process=$null
        $externalCheckpointGated=$false
        $checkpointWait=[Diagnostics.Stopwatch]::StartNew()
        $process=script:Start-HardKillRegisteredProcess -FilePath (Microsoft.PowerShell.Core\Get-Command pwsh).Source -ArgumentList $hostArguments -RedirectStandardOutputPath $stdout -RedirectStandardErrorPath $stderr
        if($externalMutationCheckpoint){
            if([string]$case.Name -ceq 'after-preimage'){
                try{$externalCheckpointGated=Wait-HardKillAfterPreimageCheckpoint -Process $process -TransactionNamespace $namespace -RepoRoot $caseRepo -TransactionId $transactionId -StagePath $afterPreimageStage -StageEvent $afterPreimageStageEvent}
                finally{if($afterPreimageStageEvent){$afterPreimageStageEvent.Dispose();$afterPreimageStageEvent=$null}}
            }else{
                $externalCheckpointGated=Wait-HardKillExternalMutationJournalState -Process $process -Name ([string]$case.Checkpoint) -TransactionNamespace $namespace
            }
        }else{
            $deadline=[DateTime]::UtcNow.AddSeconds(300)
            while(-not(Test-Path -LiteralPath $marker -PathType Leaf) -and -not $process.HasExited -and [DateTime]::UtcNow -lt $deadline){Start-Sleep -Milliseconds 50}
        }
        $checkpointWait.Stop()
        if($externalMutationCheckpoint){$processState='job-reaped';$initialReached=[bool]$externalCheckpointGated}
        else{$process.Refresh();$processState=if($process.HasExited){'exited'}else{'running'};$initialReached=(Test-Path -LiteralPath $marker -PathType Leaf) -and -not $process.HasExited}
        if($null -ne $process){$null=Confirm-HardKillRegisteredProcessReaped -Process $process -Label ("hard-kill {0} mutation host" -f [string]$case.Name)}
        }
        if(-not $initialReached){throw ("sealed mutation host did not reach checkpoint for {0}" -f $case.Name)}
        $state=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished
        $postReapTupleValid=$true
        $multiParentParentTarget=$null;$multiParentDependentTarget=$null;$multiParentParentIdentity=$null
        if([string]$case.Name -like 'rollback-multi-parent-*'){
            $dependentTargets=@($state.Header.Targets|Where-Object{[string]$_.TargetKind -ne 'parent-directory'}|Sort-Object{[long]$_.Order})
            $parentTargets=@($state.Header.Targets|Where-Object{[string]$_.TargetKind -ceq 'parent-directory'}|Sort-Object{[long]$_.Order})
            Assert ($dependentTargets.Count -eq 1 -and $parentTargets.Count -eq 1) ("hard-kill {0}: multi-parent fixture has one parent and one dependent target" -f $case.Name)
            if($dependentTargets.Count -ne 1 -or $parentTargets.Count -ne 1){throw 'hard-kill multi-parent fixture target cardinality is invalid'}
            $multiParentParentTarget=$parentTargets[0];$multiParentDependentTarget=$dependentTargets[0]
            $dependentReconciliation=Get-CanonicalTargetReconciliation -Target $multiParentDependentTarget -Records @($state.Records)
            $parentReconciliation=Get-CanonicalTargetReconciliation -Target $multiParentParentTarget -Records @($state.Records)
            $parentTuple=Get-CanonicalTargetTuple -Target $multiParentParentTarget
            $parentSnapshot=Get-SafeTreeSnapshot -Root ([string]$multiParentParentTarget.TargetPath)
            $multiParentParentIdentity=[string]$parentTuple.Target.Identity
            $dependentRollbackTupleValid=[string]$dependentReconciliation.State -ceq 'PRE_PRIMITIVE' -and -not [bool]$dependentReconciliation.PrimitiveOccurred -and
                (Test-HardKillDependentRollbackTuple -Header $state.Header -Documents (@($state.Header)+@($state.Records)))
            $parentRollbackTupleValid=[string]$parentReconciliation.State -ceq 'PARENT_CREATED' -and [bool]$parentReconciliation.PrimitiveOccurred -and
                -not [string]::IsNullOrWhiteSpace($multiParentParentIdentity) -and @($parentSnapshot.ContentTreeRows).Count -eq 1
            $postReapTupleValid=$postReapTupleValid -and $dependentRollbackTupleValid -and $parentRollbackTupleValid
            Assert $dependentRollbackTupleValid `
                ("hard-kill {0}: later dependent is an exact PRE_PRIMITIVE target with no primitive history" -f $case.Name)
            Assert $parentRollbackTupleValid `
                ("hard-kill {0}: created parent is the same exact empty directory before descending recovery" -f $case.Name)
        }
