        if($sealedMutationRecoverySeed -and ([string]$state.DerivedJournalHeadHash -cne $sealedMutationSeedHeadHash -or @($state.PendingEntries).Count -ne 0 -or
            $state.IsTerminal -or [string]$classification.Status -cne 'recovery' -or [string]$classification.AllowedAction -cne 'rollback' -or
            [string]$classification.ExpectedOutcome -cne 'rolled-back')){
            throw 'sealed mutation recovery seed journal head or recomputed classification differs from its proof'
        }
        $checkpointClassificationValid=if([string]$case.Action -ceq 'terminal'){
            $state.IsTerminal -and [string]$classification.Status -ceq 'terminal' -and [string]$state.Outcome -ceq [string]$case.Outcome
        }elseif([string]$case.Action -ceq 'manual'){
            -not $state.IsTerminal -and [string]$classification.Status -ceq 'manual'
        }else{
            -not $state.IsTerminal -and [string]$classification.AllowedAction -ceq [string]$case.Action
        }
        $manualPrefixMatches=$true
        if([string]$case.Action -ceq 'manual'){
            $partialTarget=$state.Header.Targets|Select-Object -First 1
            $partialBytes=[IO.File]::ReadAllBytes([string]$partialTarget.PreimagePath);$sourceBytes=[IO.File]::ReadAllBytes([string]$partialTarget.TargetPath);$manualPrefixMatches=$partialBytes.Length -gt 0 -and $partialBytes.Length -lt $sourceBytes.Length
            if($manualPrefixMatches){for($byteIndex=0;$byteIndex -lt $partialBytes.Length;$byteIndex++){if($partialBytes[$byteIndex] -ne $sourceBytes[$byteIndex]){$manualPrefixMatches=$false;break}}}
            $postReapTupleValid=$postReapTupleValid -and $manualPrefixMatches
        }
        if($externalMutationCheckpoint -and $initialReached -and $checkpointClassificationValid -and $postReapTupleValid){Write-HardKillExternalCheckpointProof -Path $marker -Checkpoint ([string]$case.Checkpoint)}
        $externalProof=if($externalMutationCheckpoint){Read-HardKillExternalCheckpointProof -MarkerPath $marker}else{$null}
        $externalProofValid=-not $externalMutationCheckpoint -or ($null -ne $externalProof -and [bool]$externalProof.Gated -and [bool]$externalProof.Reaped -and [bool]$externalProof.Validated -and [string]$externalProof.Checkpoint -ceq [string]$case.Checkpoint)
        $proofDetail=if($externalMutationCheckpoint){"gated=$externalProofValid; reaped=$externalProofValid; validated=$externalProofValid; "}else{''}
        $detail=("{0}; elapsed={1:N1}s; {2}" -f $processState,$checkpointWait.Elapsed.TotalSeconds,$proofDetail)+$(if(Test-Path $stdout){Get-Content $stdout -Raw}else{''})+$(if(Test-Path $stderr){Get-Content $stderr -Raw}else{''})
        Assert ($initialReached -and $externalProofValid) ("hard-kill {0}: sealed host reached exact checkpoint ({1})" -f $case.Name,$detail)
        if(-not $externalProofValid){throw ("sealed mutation checkpoint proof was not published for {0}" -f $case.Name)}
        if([string]$case.Action -ceq 'terminal'){
            Assert ($state.IsTerminal -and [string]$classification.Status -ceq 'terminal' -and [string]$state.Outcome -ceq [string]$case.Outcome) ("hard-kill {0}: published COMPLETE is already clean and auditable" -f $case.Name)
            continue
        }
        if([string]$case.Action -ceq 'manual'){
            Assert ($checkpointClassificationValid -and $postReapTupleValid -and $manualPrefixMatches) ("hard-kill {0}: partial copy is manual and retained byte-for-byte" -f $case.Name)
            continue
        }
        Assert (-not $state.IsTerminal -and [string]$classification.AllowedAction -ceq [string]$case.Action) ("hard-kill {0}: disk tuple permits only {1}" -f $case.Name,$case.Action)
        Set-TestProgress ("process:{0}:initial-killed" -f [string]$case.Name)
        $git=Get-CanonicalGitContext -RepoRoot $caseRepo;$paths=Get-CanonicalTransactionContractPaths -GitContext $git;$lock=Enter-CanonicalRepoLock -LockPath $paths.LockPath -AllowCreate
        if($case.Contains('RecoveryCheckpoint')){
            $plans=Join-Path $caseRoot 'plans';[IO.Directory]::CreateDirectory($plans)|Out-Null
            try{
                $firstPayload=Get-CanonicalRecoveryEvidencePayload -State $state -RepoRoot $caseRepo -Action ([string]$case.Action)
                $firstDocument=Write-CanonicalRecoveryPlan -PlanPayload $firstPayload -PlanPath (Join-Path $plans 'first.json') -RepoRoot $caseRepo
            }finally{Exit-CanonicalRepoLock -LockHandle $lock}
            Set-TestProgress ("process:{0}:recovery-host" -f [string]$case.Name)
            $recoveryMarker=Join-Path $caseRoot 'recovery-checkpoint.marker';$recoveryOut=Join-Path $caseRoot 'recovery-host.out';$recoveryErr=Join-Path $caseRoot 'recovery-host.err';$recoveryHost=Join-Path $RepoRoot 'tests/helpers/canonical-recovery-kill-host.ps1'
            $typedParentRecoveryCheckpoint=[string]$case.Name -like 'rollback-multi-parent-*'
            $recoveryTarget=if($typedParentRecoveryCheckpoint){$null}else{@($state.Header.Targets|Sort-Object{[long]$_.Order} -Descending)[0]}
            $initialRecoveryReconciliation=if($recoveryTarget){Get-CanonicalTargetReconciliation -Target $recoveryTarget -Records @($state.Records)}else{$null}
            $typedRecoveryMode=if($typedParentRecoveryCheckpoint){
                if([string]$case.RecoveryCheckpoint -ceq 'before-parent-remove'){'parent-before'}else{'parent-after'}
            }else{
                switch([string]$case.RecoveryCheckpoint){
                    'before-rollback-directory-new-to-staged'{'entering'}
                    'after-rollback-directory-new-to-staged'{if([string]$recoveryTarget.Current.State -ceq 'MISSING'){'visited'}else{'directory-middle'}}
                    'before-rollback-directory-old-to-target'{'directory-middle'}
                    'after-rollback-directory-old-to-target'{'visited'}
                    'before-rollback-file-replace'{'entering'}
                    'after-rollback-file-replace'{'visited'}
                    'before-rollback-file-new-to-staged'{'entering'}
                    'after-rollback-file-new-to-staged'{'visited'}
                    default{throw ('unsupported typed rollback checkpoint: '+[string]$case.RecoveryCheckpoint)}
                }
            }
            $stageRoot=$null;$stageEvent=$null;$stageEventName=$null;$directoryOplock=$null;$typedSuspended=$false;$typedRecoveryValid=$false;$postReapTupleBoundary=$null;$publishRecoveryProof=$false
            if($typedParentRecoveryCheckpoint -and ($null -eq $multiParentParentTarget -or $null -eq $multiParentDependentTarget)){throw 'hard-kill typed parent recovery requires its exact parent and dependent targets'}
            if(-not $typedParentRecoveryCheckpoint -and $null -eq $recoveryTarget){throw 'hard-kill typed recovery requires its exact mutation target'}
            $stageRoot=Join-Path $caseRoot 'recovery-stages';[IO.Directory]::CreateDirectory($stageRoot)|Out-Null
            $stageEventName='AiAgentDotfilesTests-SealedRecovery-'+[Guid]::NewGuid().ToString('N');$eventCreated=$false
            $stageEvent=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$stageEventName,[ref]$eventCreated)
            if(-not $eventCreated){throw 'hard-kill typed recovery event name was not newly created'}
            $stagePosition=if($typedRecoveryMode -in @('entering','directory-middle')){'entering'}else{'visited'}
            $stopTargetId=if($typedRecoveryMode -ceq 'parent-before'){[string]$multiParentDependentTarget.TargetId}elseif($typedRecoveryMode -ceq 'parent-after'){[string]$multiParentParentTarget.TargetId}else{[string]$recoveryTarget.TargetId}
            $recoveryArguments=@('-NoProfile','-File',$recoveryHost,'-ToolchainRoot',$RepoRoot,'-RepoRoot',$caseRepo,'-PlanPath',(Join-Path $plans 'first.json'),'-TransactionId',$transactionId,'-StageRoot',$stageRoot,'-StageEventName',$stageEventName,'-StagePosition',$stagePosition,'-StopTargetId',$stopTargetId,'-StageTimeoutSeconds','300')
            $recoveryProcess=$null
            try{
                $recoveryProcess=script:Start-HardKillRegisteredProcess -FilePath (Microsoft.PowerShell.Core\Get-Command pwsh).Source -ArgumentList $recoveryArguments -RedirectStandardOutputPath $recoveryOut -RedirectStandardErrorPath $recoveryErr
                $expectedStageCount=if($typedRecoveryMode -ceq 'parent-after'){2}else{1}
                $visitedStages=@(Wait-HardKillRecoveryVisitedStages -Process $recoveryProcess -StageRoot $stageRoot -Count $expectedStageCount)
                    if($typedParentRecoveryCheckpoint){
                        $visitedShape=$visitedStages.Count -eq $expectedStageCount -and [string]$visitedStages[0].Stage -ceq 'visited' -and
                            [long]$visitedStages[0].Sequence -eq 1 -and [string]$visitedStages[0].TargetId -ceq [string]$multiParentDependentTarget.TargetId -and
                            [long]$visitedStages[0].Order -eq [long]$multiParentDependentTarget.Order -and [string]$visitedStages[0].TargetKind -ceq [string]$multiParentDependentTarget.TargetKind
                        if($expectedStageCount -eq 2){
                            $visitedShape=$visitedShape -and [string]$visitedStages[1].Stage -ceq 'visited' -and [long]$visitedStages[1].Sequence -eq 2 -and
                                [string]$visitedStages[1].TargetId -ceq [string]$multiParentParentTarget.TargetId -and
                                [long]$visitedStages[1].Order -eq [long]$multiParentParentTarget.Order -and [string]$visitedStages[1].TargetKind -ceq 'parent-directory'
                        }
                    }else{
                        $visitedShape=$visitedStages.Count -eq 1 -and [string]$visitedStages[0].Stage -ceq $stagePosition -and
                            [long]$visitedStages[0].Sequence -eq 1 -and [string]$visitedStages[0].TargetId -ceq [string]$recoveryTarget.TargetId -and
                            [long]$visitedStages[0].Order -eq [long]$recoveryTarget.Order -and [string]$visitedStages[0].TargetKind -ceq [string]$recoveryTarget.TargetKind
                    }
                    Assert $visitedShape ("hard-kill {0}: typed coordinator publishes the exact target stage sequence" -f $case.Name)
                    $stageState=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished
                    $stageDocuments=@($stageState.Header)+@($stageState.Records)
                    $intentCount=@($stageState.Records|Where-Object{[string]$_.Phase -ceq 'RECOVERY_ACTION_INTENT'}).Count
                    $stageJournalValid=$intentCount -eq 1 -and -not(Test-HardKillJournalPhase -Documents $stageDocuments -Phase RECOVERY_ACTION_APPLIED) -and
                        -not(Test-HardKillJournalPhase -Documents $stageDocuments -Phase COMPLETE)
                    if($typedParentRecoveryCheckpoint){$stageJournalValid=$stageJournalValid -and (Test-HardKillDependentRollbackTuple -Header $stageState.Header -Documents $stageDocuments)}
                    Assert $stageJournalValid ("hard-kill {0}: typed stage retains one durable intent and no applied or complete record" -f $case.Name)
                    $repoLockBusy=Test-HardKillRepoLockBusy -LockPath $paths.LockPath
                    Assert $repoLockBusy ("hard-kill {0}: sealed recovery still owns the exact repo lock at the typed stage" -f $case.Name)

                    switch($typedRecoveryMode){
                        'parent-before'{
                            $stageParentTuple=Get-CanonicalTargetTuple -Target $multiParentParentTarget
                            $stageParentSnapshot=Get-SafeTreeSnapshot -Root ([string]$multiParentParentTarget.TargetPath)
                            $parentStillExact=[string]$stageParentTuple.Target.State -ceq 'PRESENT' -and
                                [string]$stageParentTuple.Target.Identity -ceq $multiParentParentIdentity -and @($stageParentSnapshot.ContentTreeRows).Count -eq 1
                            Assert $parentStillExact ("hard-kill {0}: dependent no-op returns before the same empty parent is touched" -f $case.Name)
                            if($visitedShape -and $stageJournalValid -and $repoLockBusy -and $parentStillExact){
                                $directoryOplock=[AiAgentDotfiles.HardKillDirectoryOplock]::Begin([IO.Path]::GetFullPath([string]$multiParentParentTarget.TargetPath))
                                $parentOplockIdentityExact=[string]$directoryOplock.Identity -ceq $multiParentParentIdentity
                                $null=$stageEvent.Set()
                                if($directoryOplock.WaitForBreak(300000) -and $directoryOplock.IsAcknowledgedSelfMutationBreak()){
                                    [AiAgentDotfiles.HardKillLeaseProbe]::Suspend($recoveryProcess);$typedSuspended=$true
                                    $typedRecoveryValid=$parentOplockIdentityExact -and (Test-HardKillMutationParentLease -LeafPath ([string]$multiParentParentTarget.TargetPath))
                                }
                            }
                        }
                        'parent-after'{
                            if($visitedShape -and $stageJournalValid -and $repoLockBusy){
                                [AiAgentDotfiles.HardKillLeaseProbe]::Suspend($recoveryProcess);$typedSuspended=$true
                                $typedRecoveryValid=Get-HardKillMutationCheckpointState -Name 'after-parent-remove' -TransactionNamespace $namespace
                            }
                        }
                        'directory-middle'{
                            if($visitedShape -and $stageJournalValid -and $repoLockBusy){
                                $enteringTupleExact=Test-HardKillExactRollbackTuple -Target $recoveryTarget -InitialReconciliation $initialRecoveryReconciliation -Boundary entering
                                if(-not $enteringTupleExact){throw 'hard-kill directory-middle entering tuple differs from its exact reviewed state'}
                                $expectedSwapOldIdentity=[string]$initialRecoveryReconciliation.Tuple.SwapOld.Identity
                                if([string]::IsNullOrWhiteSpace($expectedSwapOldIdentity)){throw 'hard-kill directory-middle reviewed swap-old identity is missing'}
                                $directoryOplock=[AiAgentDotfiles.HardKillDirectoryOplock]::Begin([IO.Path]::GetFullPath([string]$recoveryTarget.SwapOldPath))
                                $oplockIdentityExact=[string]$directoryOplock.Identity -ceq $expectedSwapOldIdentity
                                $null=$stageEvent.Set()
                                if($directoryOplock.WaitForBreak(300000) -and $directoryOplock.IsAcknowledgedSelfMutationBreak()){
                                    [AiAgentDotfiles.HardKillLeaseProbe]::Suspend($recoveryProcess);$typedSuspended=$true
                                    $typedRecoveryValid=$oplockIdentityExact -and (Test-HardKillAllMutationParentLeases -Target $recoveryTarget)
                                    $postReapTupleBoundary='directory-middle'
                                }
                            }
                        }
                        'entering'{
                            if($visitedShape -and $stageJournalValid -and $repoLockBusy){
                                $prePrimitiveValid=Test-HardKillExactRollbackTuple -Target $recoveryTarget -InitialReconciliation $initialRecoveryReconciliation -Boundary entering
                                if($prePrimitiveValid){
                                    $targetFullPath=[IO.Path]::GetFullPath([string]$recoveryTarget.TargetPath)
                                    $expectedTargetIdentity=[string]$initialRecoveryReconciliation.Tuple.Target.Identity
                                    if([string]::IsNullOrWhiteSpace($expectedTargetIdentity)){throw 'hard-kill entering reviewed target identity is missing'}
                                    $directoryOplock=if([string]$recoveryTarget.TargetKind -ceq 'file'){
                                        [AiAgentDotfiles.HardKillDirectoryOplock]::BeginFile($targetFullPath)
                                    }else{[AiAgentDotfiles.HardKillDirectoryOplock]::Begin($targetFullPath)}
                                    $oplockIdentityExact=[string]$directoryOplock.Identity -ceq $expectedTargetIdentity
                                    $null=$stageEvent.Set()
                                    if($directoryOplock.WaitForBreak(300000) -and $directoryOplock.IsAcknowledgedSelfMutationBreak()){
                                        [AiAgentDotfiles.HardKillLeaseProbe]::Suspend($recoveryProcess);$typedSuspended=$true
                                        $typedRecoveryValid=$oplockIdentityExact -and (Test-HardKillAllMutationParentLeases -Target $recoveryTarget)
                                        $postReapTupleBoundary='entering'
                                    }
                                }
                            }
                        }
                        default{
                            if($visitedShape -and $stageJournalValid -and $repoLockBusy){
                                [AiAgentDotfiles.HardKillLeaseProbe]::Suspend($recoveryProcess);$typedSuspended=$true
                                $typedRecoveryValid=Test-HardKillExactRollbackTuple -Target $recoveryTarget -InitialReconciliation $initialRecoveryReconciliation -Boundary visited
                                $postReapTupleBoundary='visited'
                            }
                        }
                    }
                    $null=Confirm-HardKillRegisteredProcessReaped -Process $recoveryProcess -Label ("hard-kill {0} typed recovery" -f [string]$case.Name)
                    $killConfirmed=$true;$typedSuspended=$false
                    Assert $killConfirmed ("hard-kill {0}: sealed recovery process is fully reaped before proof publication" -f $case.Name)
                    if($killConfirmed -and $directoryOplock){$directoryOplock.Dispose();$directoryOplock=$null}
                    if($typedRecoveryValid -and $killConfirmed -and $postReapTupleBoundary){
                        $typedRecoveryValid=Test-HardKillExactRollbackTuple -Target $recoveryTarget -InitialReconciliation $initialRecoveryReconciliation -Boundary $postReapTupleBoundary
                    }elseif($typedRecoveryValid -and $killConfirmed -and $typedRecoveryMode -ceq 'parent-before'){
                        $postKillParentTuple=Get-CanonicalTargetTuple -Target $multiParentParentTarget
                        $postKillParentSnapshot=Get-SafeTreeSnapshot -Root ([string]$multiParentParentTarget.TargetPath)
                        $typedRecoveryValid=[string]$postKillParentTuple.Target.State -ceq 'PRESENT' -and
                            [string]$postKillParentTuple.Target.Identity -ceq $multiParentParentIdentity -and @($postKillParentSnapshot.ContentTreeRows).Count -eq 1
                    }elseif($typedRecoveryValid -and $killConfirmed -and $typedRecoveryMode -ceq 'parent-after'){
                        $typedRecoveryValid=Get-HardKillMutationCheckpointState -Name 'after-parent-remove' -TransactionNamespace $namespace
                    }
                    Assert $typedRecoveryValid ("hard-kill {0}: typed rollback boundary matches the exact target tuple before ACTION_APPLIED" -f $case.Name)
                    $publishRecoveryProof=$typedRecoveryValid -and $killConfirmed
            }finally{
                $cleanupFailure=$null
                if($recoveryProcess){try{$null=Confirm-HardKillRegisteredProcessReaped -Process $recoveryProcess -Label ("hard-kill {0} typed recovery cleanup" -f [string]$case.Name);$typedSuspended=$false}catch{$cleanupFailure=$_}}
                if($null -eq $cleanupFailure){
                    if($directoryOplock){try{$directoryOplock.Dispose()}catch{if($null -eq $cleanupFailure){$cleanupFailure=$_}}}
                    if($stageEvent){try{$stageEvent.Dispose()}catch{if($null -eq $cleanupFailure){$cleanupFailure=$_}}}
                }
                if($cleanupFailure){throw $cleanupFailure}
            }
            Set-TestProgress ("process:{0}:read-after-kill" -f [string]$case.Name)
            $afterFailure=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished
            $recoveryPlanConsumed=[string]$firstDocument.DocumentHash -in @($afterFailure.ConsumedDocumentHashes)
            Set-TestProgress ("process:{0}:classify-after-kill" -f [string]$case.Name)
            $nextClassification=Get-CanonicalTransactionRecoveryClassification -State $afterFailure -RepoRoot $caseRepo;$nextAction=[string]$nextClassification.AllowedAction
            $recoveryContinuationValid=$nextAction -in @('rollback','finalize')
            if($publishRecoveryProof -and $recoveryPlanConsumed -and $recoveryContinuationValid){Write-HardKillExternalCheckpointProof -Path $recoveryMarker -Checkpoint ([string]$case.RecoveryCheckpoint)}
            $null=Confirm-HardKillRegisteredProcessReaped -Process $recoveryProcess -Label ("hard-kill {0} recovery host" -f [string]$case.Name)
            $externalRecoveryProof=Read-HardKillExternalCheckpointProof -MarkerPath $recoveryMarker
            $externalRecoveryProofValid=$null -ne $externalRecoveryProof -and [bool]$externalRecoveryProof.Gated -and [bool]$externalRecoveryProof.Reaped -and [bool]$externalRecoveryProof.Validated -and [string]$externalRecoveryProof.Checkpoint -ceq [string]$case.RecoveryCheckpoint
            $recoveryProofDetail="gated=$externalRecoveryProofValid; reaped=$externalRecoveryProofValid; validated=$externalRecoveryProofValid; "
            $recoveryDetail=$recoveryProofDetail+$(if(Test-Path $recoveryOut){Get-Content $recoveryOut -Raw}else{''})+$(if(Test-Path $recoveryErr){Get-Content $recoveryErr -Raw}else{''})
            $recoveryReached=(Test-Path -LiteralPath $recoveryMarker -PathType Leaf) -and $externalRecoveryProofValid
            Assert $recoveryReached ("hard-kill {0}: recovery host reached exact rollback checkpoint ({1})" -f $case.Name,$recoveryDetail)
            if(-not $recoveryReached){throw ("sealed recovery host did not reach checkpoint for {0}" -f $case.Name)}
            Set-TestProgress ("process:{0}:rollback-killed" -f [string]$case.Name)
            Assert $recoveryPlanConsumed ("hard-kill {0}: killed rollback plan remains consumed" -f $case.Name)
            Assert $recoveryContinuationValid ("hard-kill {0}: reconciled rollback window has one safe continuation" -f $case.Name)
            Set-TestProgress ("process:{0}:enter-second-lock" -f [string]$case.Name)
            $lock=Enter-CanonicalRepoLock -LockPath $paths.LockPath
            try{
                Set-TestProgress ("process:{0}:second-evidence" -f [string]$case.Name)
                $secondPayload=Get-CanonicalRecoveryEvidencePayload -State $afterFailure -RepoRoot $caseRepo -Action $nextAction
                Set-TestProgress ("process:{0}:second-plan" -f [string]$case.Name)
                $secondDocument=Write-CanonicalRecoveryPlan -PlanPayload $secondPayload -PlanPath (Join-Path $plans 'second.json') -RepoRoot $caseRepo
                Set-TestProgress ("process:{0}:invoke-second-recovery" -f [string]$case.Name)
                $terminal=Invoke-SealedCanonicalReviewedRecovery -Document $secondDocument -State $afterFailure -RepoRoot $caseRepo
                Set-TestProgress ("process:{0}:second-terminal" -f [string]$case.Name)
            }finally{Exit-CanonicalRepoLock -LockHandle $lock}
            Assert ($terminal.IsTerminal -and [string]$terminal.Outcome -ceq [string]$case.Outcome) ("hard-kill {0}: fresh reviewed recovery reaches the unique terminal outcome" -f $case.Name)
            if([string]$case.Name -like 'rollback-multi-parent-*'){
                $later=$terminal.Header.Targets|Sort-Object{[long]$_.Order}|Select-Object -Last 1;$laterTarget=Get-CanonicalObservedPathState -Path ([string]$later.TargetPath);$laterStaged=Get-CanonicalObservedPathState -Path ([string]$later.StagedPath)
                Assert ([string]$laterTarget.State -ceq 'MISSING' -and [string]$laterStaged.Hash -ceq [string]$later.Candidate.Hash) ("hard-kill {0}: later PRE_PRIMITIVE target is a byte-preserving descending rollback no-op" -f $case.Name)
            }
            continue
        }
        try{
            $plans=Join-Path $caseRoot 'plans';[IO.Directory]::CreateDirectory($plans)|Out-Null
            $firstPayload=Get-CanonicalRecoveryEvidencePayload -State $state -RepoRoot $caseRepo -Action ([string]$case.Action)
            $firstDocument=Write-CanonicalRecoveryPlan -PlanPayload $firstPayload -PlanPath (Join-Path $plans 'first.json') -RepoRoot $caseRepo
            Assert-Throws {Invoke-SealedRecoveryFailureAfterIntent -Document $firstDocument -State $state -RepoRoot $caseRepo} 'injected-recovery-failure' ("hard-kill {0}: test-only orchestrator failure after recovery intent retains an unfinished journal" -f $case.Name)
            $afterFailure=Read-CanonicalJournalDirectory -TransactionNamespace $namespace -AllowUnfinished
            Assert ([string]$firstDocument.DocumentHash -in @($afterFailure.ConsumedDocumentHashes)) ("hard-kill {0}: failed recovery attempt is consumed before action" -f $case.Name)
            $nextClassification=Get-CanonicalTransactionRecoveryClassification -State $afterFailure -RepoRoot $caseRepo
            $nextAction=[string]$nextClassification.AllowedAction
            if([string]::IsNullOrWhiteSpace($nextAction)){throw ("missing next recovery action: "+($nextClassification|ConvertTo-Json -Compress -Depth 20))}
            if($nextAction -ceq [string]$case.Action){Assert-Throws {Assert-CanonicalRecoveryPlanCurrent -Document $firstDocument -State $afterFailure -RepoRoot $caseRepo} 'plan-stale' ("hard-kill {0}: journal-head drift makes the prior recovery plan stale" -f $case.Name)}
            $secondPayload=Get-CanonicalRecoveryEvidencePayload -State $afterFailure -RepoRoot $caseRepo -Action $nextAction
            $secondDocument=Write-CanonicalRecoveryPlan -PlanPayload $secondPayload -PlanPath (Join-Path $plans 'second.json') -RepoRoot $caseRepo
            $terminal=Invoke-SealedCanonicalReviewedRecovery -Document $secondDocument -State $afterFailure -RepoRoot $caseRepo
        }finally{Exit-CanonicalRepoLock -LockHandle $lock}
        Assert ($terminal.IsTerminal -and [string]$terminal.Outcome -ceq [string]$case.Outcome) ("hard-kill {0}: fresh reviewed recovery reaches the unique terminal outcome" -f $case.Name)
        Assert ([string]$firstDocument.DocumentHash -in @($terminal.ConsumedDocumentHashes)) ("hard-kill {0}: prior recovery attempt remains permanently consumed" -f $case.Name)
    }
    }
}
catch{
    $script:fail++
    if($null -eq $script:unhandledPrimaryException){$script:unhandledPrimaryException=$_.Exception}
    Write-Host "  FAIL  unhandled test error: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host $_.ScriptStackTrace -ForegroundColor DarkYellow
}
finally{
    foreach($spawned in @($script:spawnedProcesses)){
        try{
            $outerReapReceipt=Confirm-HardKillRegisteredProcessReaped -Process $spawned -Label 'outer hard-kill cleanup'
            if($outerReapReceipt -isnot [bool] -or -not $outerReapReceipt){throw 'outer-hard-kill-reap-receipt-invalid'}
        }catch{$script:cleanupFailures.Add($_.Exception)}
    }
    if($script:hardKillReviewedLoadLease){
        try{$script:hardKillReviewedLoadLease.Dispose()}
        catch{$script:cleanupFailures.Add($_.Exception)}
        finally{$script:hardKillReviewedLoadLease=$null}
    }
    if($script:cleanupFailures.Count -ne 0){
        $script:fail+=$script:cleanupFailures.Count
        foreach($cleanupFailure in $script:cleanupFailures){Write-Host "  FAIL  hard-kill cleanup failures: $($cleanupFailure.Message)" -ForegroundColor Red}
    }
    Write-Host '';Write-Host ("Results: {0} passed, {1} failed" -f $script:pass,$script:fail) -ForegroundColor Cyan
    if($script:cleanupFailures.Count -eq 0 -and $script:forensicRoots.Count -eq 0 -and $null -eq $script:unhandledPrimaryException -and (Microsoft.PowerShell.Management\Test-Path -LiteralPath $root)){
        Microsoft.PowerShell.Management\Remove-Item -LiteralPath $root -Recurse -Force
    }
}
$script:terminalFailures=[Collections.Generic.List[Exception]]::new()
if($null -ne $script:unhandledPrimaryException){$script:terminalFailures.Add($script:unhandledPrimaryException)}
foreach($cleanupFailure in $script:cleanupFailures){$script:terminalFailures.Add($cleanupFailure)}
if($script:terminalFailures.Count -ne 0){throw [AggregateException]::new('hard-kill primary/cleanup failures',[Exception[]]$script:terminalFailures.ToArray())}
if($script:fail -ne 0){exit 1}
